local function lib_exists(name)
	local base = getWorkingDirectory() .. '/lib/'
	if doesFileExist(base .. name) then return true end
	local stem = name:gsub('%.[^%.]+$', '')
	if doesFileExist(base .. stem .. '.lua') then return true end
	if doesFileExist(base .. stem .. '.dll') then return true end
	if doesFileExist(base .. stem .. '/init.lua') then return true end
	return false
end

