--> [SH-Guard] Track inverse operations, including FFI exports, in each draw callback.
do
 local g = {active = false, busy = false, ops = {}, raw = {}, errors = {}}
 local function callable(fn) return type(fn) == 'function' or type(fn) == 'cdata' end
 local function forget(kind, count)
  for _ = 1, count or 1 do
   for i = #g.ops, 1, -1 do
    if g.ops[i].kind == kind then table.remove(g.ops, i); break end
   end
  end
 end
 local function wrap(name, after)
  local orig = imgui[name]
  if not callable(orig) then return end
  g.raw[name] = orig
  imgui[name] = function(...)
   if not g.active or g.busy then return orig(...) end
   g.busy = true
   local result = {pcall(orig, ...)}
   g.busy = false
   if not result[1] then error(result[2], 0) end
   after(result[2], ...)
   return unpack(result, 2, #result)
  end
 end
 local function pair(open, close, kind, conditional, counted)
  local undo = imgui[close]
  if not callable(undo) then return end
  wrap(open, function(ok)
   if not conditional or ok then g.ops[#g.ops + 1] = {kind = kind, undo = undo} end
  end)
  -- Different overloads can share the same closing function.
  if not g.raw[close] then
   wrap(close, function(_, n) forget(kind, counted and (tonumber(n) or 1) or 1) end)
  end
 end
 pair('Begin', 'End', 'window')
 pair('BeginChild', 'EndChild', 'child')
 pair('BeginChildID', 'EndChild', 'child')
 pair('BeginPopup', 'EndPopup', 'popup', true)
 pair('BeginPopupModal', 'EndPopup', 'popup', true)
 pair('BeginTooltip', 'EndTooltip', 'tooltip')
 pair('BeginGroup', 'EndGroup', 'group')
 pair('BeginCombo', 'EndCombo', 'combo', true)
 pair('BeginMenu', 'EndMenu', 'menu', true)
 pair('BeginMenuBar', 'EndMenuBar', 'menubar', true)
 pair('BeginTabBar', 'EndTabBar', 'tabbar', true)
 pair('BeginTabItem', 'EndTabItem', 'tabitem', true)
 pair('PushFont', 'PopFont', 'font')
 pair('PushStyleColor', 'PopStyleColor', 'color', false, true)
 pair('PushStyleColorU32', 'PopStyleColor', 'color', false, true)
 pair('PushStyleVar', 'PopStyleVar', 'style', false, true)
 pair('PushStyleVarFloat', 'PopStyleVar', 'style', false, true)
 pair('PushStyleVarVec2', 'PopStyleVar', 'style', false, true)
 pair('PushID', 'PopID', 'id')
 pair('PushItemWidth', 'PopItemWidth', 'width')
 pair('PushTextWrapPos', 'PopTextWrapPos', 'wrap')
 pair('PushClipRect', 'PopClipRect', 'clip')
 local function repair()
  local failures = {}
  g.busy = true
  for i = #g.ops, 1, -1 do
   local op = g.ops[i]
   local ok, err = pcall(op.undo)
   if not ok then failures[#failures + 1] = tostring(err) end
  end
  g.ops, g.busy = {}, false
  return #failures == 0, table.concat(failures, '; ')
 end
 local function guard(draw)
  return function(...)
   g.ops, g.active = {}, true
   local args = {n = select('#', ...), ...}
   local ok, err = xpcall(function() return draw(unpack(args, 1, args.n)) end, debug.traceback)
   local balanced = #g.ops == 0
   local restored, repair_error = true, ''
   if not balanced then restored, repair_error = repair() end
   g.active = false
   if not ok or not balanced then
    local message = ok and 'unbalanced draw callback' or tostring(err)
    local now = os.clock()
    if not g.errors[message] or now - g.errors[message] > 5 then
     g.errors[message] = now
     local n = 0; for _ in pairs(g.errors) do n = n + 1 end
     if n > 60 then g.errors = {[message] = now} end
     print('[SH-Guard] ' .. (restored and 'tracked stacks restored: ' or 'stack recovery failed: ') .. message .. (repair_error ~= '' and ('; ' .. repair_error) or ''))
    end
   end
  end
 end
 local onframe = imgui.OnFrame
 imgui.OnFrame = function(cond, ...)
  local n, args = select('#', ...), {...}
  if type(args[n]) == 'function' then args[n] = guard(args[n]) end
  return onframe(function(...)
   return sh_resource and sh_resource.fonts_ready() and cond(...)
  end, unpack(args, 1, n))
 end
end
