local default_tab_order = deep_copy(setting.tab)
local valid_tabs = {}
for _, name in ipairs(default_tab_order) do valid_tabs[name] = true end

local function normalize_tab_order(order)
	local tabs, seen, issues = {}, {}, {}
	if type(order) == 'table' then
		for i = 1, #order do
			local value = order[i]
			local name = value == 'browser' and 'help' or value
			if type(name) == 'string' and valid_tabs[name] and not seen[name] then
				tabs[#tabs + 1] = name
				seen[name] = true
				if name ~= value then issues[#issues + 1] = 'browser -> help' end
			else
				issues[#issues + 1] = 'removed ' .. tostring(value) .. ' (' .. type(value) .. ')'
			end
		end
	else
		issues[#issues + 1] = 'invalid list ' .. tostring(order) .. ' (' .. type(order) .. ')'
	end
	if #tabs == 0 then
		tabs = deep_copy(default_tab_order)
		issues[#issues + 1] = 'restored defaults'
	end
	if #issues > 0 then
		setting.tab = tabs
		print('[SH] Tab list repaired: ' .. table.concat(issues, '; '))
		return tabs
	end
	return order
end

local original_os_date = os.date
os.date = function(format, time)
	local adjusted_time = time
	if adjusted_time == nil then adjusted_time = os.time() + ((tonumber(setting.time_offset) or 0) * 3600) end
	return original_os_date(format, adjusted_time)
end

local last_saved_json = nil

local function replace_file(new_path, path)
	local ok = ffi.load('kernel32').MoveFileExA(new_path, path, 9) ~= 0
	return ok, not ok and 'MoveFileExA failed' or nil
end

local function write_file(path, data)
	local tmp = path .. '.tmp'
	local f, err = io.open(tmp, 'wb')
	if not f then return false, err end
	local written, write_err = f:write(data)
	local flushed, flush_err = f:flush()
	local closed, close_err = f:close()
	if not written or not flushed or not closed then
		os.remove(tmp)
		return false, write_err or flush_err or close_err
	end
	return replace_file(tmp, path)
end
settings_reset_pending = false
-- Shared validation for imported commands and the command executor.
sh_audit = {}
function sh_audit.command(value)
	if type(value) ~= 'table' or type(value.cmd) ~= 'string' or not value.cmd:match('^[A-Za-z0-9_]*$') then return false, 'неверное имя команды' end
	if type(value.act) ~= 'table' or #value.act > 10000 then return false, 'нет корректного списка действий' end
	if type(value.delay) ~= 'number' or value.delay ~= value.delay or value.delay < 0 or value.delay > 3600 then return false, 'неверная задержка' end
	if type(value.folder) ~= 'number' or value.folder < 1 or value.folder ~= math.floor(value.folder) then return false, 'неверная папка' end
	if type(value.rank) ~= 'number' or value.rank < 0 or value.rank > 100 then return false, 'неверный ранг' end
	for _, field in ipairs({'arg', 'var', 'key'}) do if type(value[field]) ~= 'table' then return false, 'неверное поле ' .. field end end
	if type(value.key[1]) ~= 'string' or type(value.key[2]) ~= 'table' then return false, 'неверная клавиша' end
	for _, key in ipairs(value.key[2]) do if type(key) ~= 'number' then return false, 'неверный код клавиши' end end
	for _, arg in ipairs(value.arg) do if type(arg) ~= 'table' or type(arg.name) ~= 'string' or type(arg.desc) ~= 'string' or (arg.type ~= 1 and arg.type ~= 2) then return false, 'неверный аргумент' end end
	for _, var in ipairs(value.var) do if type(var) ~= 'table' or type(var.name) ~= 'string' or type(var.value) ~= 'string' then return false, 'неверная переменная' end end
	local allowed = {SEND=true,SEND_CMD=true,OPEN_INPUT=true,SEND_ME=true,DELAY=true,NEW_VAR=true,DIALOG=true,IF=true,ELSE=true,END=true,STOP=true,WAIT_ENTER=true,SEND_DIALOG=true,SELECT_DIALOG_ROW=true}
	local stack = {}
	for _, action in ipairs(value.act) do
		if type(action) ~= 'table' or not allowed[action[1]] then return false, 'неизвестное действие' end
		local kind = action[1]
		if kind == 'IF' then
			if type(action[2]) ~= 'number' or action[2] < 2 or action[2] > 4 or type(action[3]) ~= 'table' or action[3][1] == nil or action[3][2] == nil or type(action[4]) ~= 'number' then return false, 'неверное условие' end
			stack[#stack + 1] = {id = action[4], otherwise = false}
		elseif kind == 'ELSE' or kind == 'END' then
			local top = stack[#stack]
			if not top or top.id ~= action[2] or (kind == 'ELSE' and top.otherwise) then return false, 'нарушена структура условий' end
			if kind == 'END' then table.remove(stack) else top.otherwise = true end
		elseif kind == 'DIALOG' then
			if type(action[2]) ~= 'string' or type(action[3]) ~= 'table' or #action[3] > 10 then return false, 'неверный диалог' end
			for _, label in ipairs(action[3]) do if type(label) ~= 'string' then return false, 'неверный пункт диалога' end end
		elseif kind == 'DELAY' then
			if type(action[2]) ~= 'number' or action[2] < 0 or action[2] > 3600 then return false, 'неверная пауза' end
		elseif kind == 'NEW_VAR' then
			if type(action[2]) ~= 'string' or type(action[3]) ~= 'string' then return false, 'неверное присвоение переменной' end
		elseif kind ~= 'STOP' and kind ~= 'WAIT_ENTER' and type(action[2]) ~= 'string' then return false, 'неверный текст действия' end
	end
	if #stack > 0 then return false, 'незакрытое условие' end
	return true
end
function sh_audit.audio_release()
	local handle = play and play.stream
	if play then play.stream = nil end
	if handle and handle ~= 0 then pcall(bass.BASS_StreamFree, handle) end
end
sh_reminders = {displaying = false}
function sh_reminders.push(reminder)
	if type(setting.pending_reminders) ~= 'table' then setting.pending_reminders = {} end
	setting.pending_reminders[#setting.pending_reminders + 1] = {text = reminder.text, sound = reminder.sound == true}
end
function sh_reminders.tick()
	local queue = setting.pending_reminders
	if type(queue) ~= 'table' then setting.pending_reminders = {}; return end
	if sh_reminders.displaying and not windows.reminder[0] then
		table.remove(queue, 1); sh_reminders.displaying = false; save()
	end
	if not sh_reminders.displaying and not windows.reminder[0] and #queue > 0 then
		local item = queue[1]
		if type(item) ~= 'table' or type(item.text) ~= 'string' then table.remove(queue, 1); save(); return end
		text_reminder, reminder_sound_pending = item.text, item.sound == true
		sh_reminders.displaying, windows.reminder[0] = true, true
	end
end

function sh_audit.categories(value)
	if type(value) ~= 'table' or #value == 0 or #value > 1000 then return false end
	local seen = {}
	for _, item in ipairs(value) do
		local name = type(item) == 'table' and item[1]
		if type(name) ~= 'string' or name == '' or name == '.' or name == '..' or name:find('[<>:"/\\|?*]') or seen[name] then return false end
		seen[name] = true
	end
	return true
end
function sh_audit.io_error(message, detail)
	local now = os.clock()
	print('[SH Save] ' .. message .. ' ' .. tostring(detail or ''))
	if not sh_audit.last_io_error or now - sh_audit.last_io_error > 10 then
		sh_audit.last_io_error = now
		pcall(sampAddChatMessage, '[SH]{FFFFFF} ' .. message, 0xFF5345)
	end
end
function sh_audit.split_show(command)
	if command.cmd ~= 'show' then return end
	local dialog = command.act[1]
	if type(dialog) ~= 'table' or dialog[1] ~= 'DIALOG' or type(dialog[3]) ~= 'table' or #dialog[3] ~= 4 then return end
	local branches, depth, active, otherwise = {}, 0, nil, false
	for i = 2, #command.act do
		local action = command.act[i]
		if action[1] == 'IF' then
			if depth == 0 then
				if action[2] ~= 2 or action[3][1] ~= dialog[2] then return end
				active = tonumber(action[3][2]); if not active or active < 1 or active > 4 or branches[active] then return end
				branches[active], otherwise = {}, false
			else branches[active][#branches[active] + 1] = deep_copy(action) end
			depth = depth + 1
		elseif action[1] == 'END' then
			depth = depth - 1
			if depth < 0 then return end
			if depth > 0 then branches[active][#branches[active] + 1] = deep_copy(action) end
		elseif depth == 1 and action[1] == 'ELSE' then otherwise = true
		elseif depth > 0 and not otherwise then branches[active][#branches[active] + 1] = deep_copy(action)
		else return end
	end
	if depth ~= 0 then return end
	local names = {'showpassrp','showmcrp','showlicrp','showworkrp'}
	local labels = {'Показать паспорт','Показать медкарту','Показать лицензии','Показать трудовую'}
	local result = {}
	for i = 1, 4 do
		if not branches[i] or #branches[i] == 0 then return end
		local variant = deep_copy(command)
		variant.cmd, variant.desc, variant.act = names[i], u8(labels[i]), branches[i]
		variant.id_element = i == 1 and 19 or (9600 + i - 1)
		if i > 1 then variant.key, variant.UID = {'', {}}, nil end
		result[i] = variant
	end
	return result
end
function sh_audit.migrate_commands()
	if setting.first_start then return end
	local names, uids = {}, {}
	for _, c in ipairs(cmd[1]) do names[c.cmd] = true; if c.UID then uids[c.UID] = true end end
	local result, changed = {}, false
	local document_labels = {
		showpassrp = {'Показать паспорт с РП', 'Показать паспорт'},
		showmcrp = {'Показать медицинскую карту с РП', 'Показать медкарту'},
		showlicrp = {'Показать лицензии с РП', 'Показать лицензии'},
		showworkrp = {'Показать трудовую книжку с РП', 'Показать трудовую'},
	}
	local function identity(c)
		if not c.UID then repeat c.UID = math.random(20,95000000) until not uids[c.UID] end
		uids[c.UID], names[c.cmd] = true, true
	end
	for _, c in ipairs(cmd[1]) do
		local variants = sh_audit.split_show(c)
		if variants then for _, v in ipairs(variants) do if names[v.cmd] then variants = nil; break end end end
		if variants then for _, v in ipairs(variants) do identity(v); result[#result + 1] = v end; changed = true
		else
			local label = document_labels[c.cmd]
			if label and c.desc == u8(label[1]) then
				c = deep_copy(c)
				c.desc = u8(label[2])
				changed = true
			end
			local first = c.act and c.act[1]
			if c.newbie_license_template == true and first and first[1] == 'SEND'
				and first[2] == u8'/me снял{sex[][а]} со спины сумку, после чего открыл{sex[][а]} её' then
				c = deep_copy(c)
				c.act[1][2] = u8'/me достал{sex[][а]} из под стола пустой бланк для выдачи лицензии '
				changed = true
			end
			result[#result + 1] = c
		end
	end
	local added_newbie = false
	if setting.org == 5 and not setting.newbie_variant_migrated then
		local present = names.licnewbie
		for _, c in ipairs(result) do if c.newbie_license_template then present = true end end
		if not present then
			for _, c in ipairs(cmd_defoult.driving_school or {}) do
				if c.newbie_license_template then local copy = deep_copy(c); copy.UID = nil; identity(copy); result[#result + 1] = copy; changed, added_newbie = true, true; break end
			end
		end
	end
	if changed then
		local previous = cmd[1]; cmd[1] = result
		if not save_cmd() then cmd[1] = previous; return false end
	end
	if setting.org == 5 and (names.licnewbie or added_newbie) then setting.newbie_variant_migrated = true; save() end
	return changed
end

sh_audit.private_root = dir .. '/StateHelper passwords'
sh_audit.private_fields = {ym_token = true, ym_uid = true, vk_cookie = true, vk_uid = true}
sh_audit.settings_backups = {'.last-good', '.old'}

function sh_audit.ensure_private_storage()
	if not doesDirectoryExist(sh_audit.private_root) then lfs.mkdir(sh_audit.private_root) end
	return doesDirectoryExist(sh_audit.private_root)
end

function sh_audit.move_private_file(from, to)
	if not doesFileExist(from) and not doesDirectoryExist(from) then return true end
	local target, index = to, 1
	while doesFileExist(target) or doesDirectoryExist(target) do
		index = index + 1
		target = to .. '.legacy-' .. index
	end
	return os.rename(from, target)
end

function sh_audit.save_private_music()
	local token, uid = setting.ym_token or '', setting.ym_uid or ''
	if sh_audit.saved_ym_token == token and sh_audit.saved_ym_uid == uid then return true end
	if not sh_audit.ensure_private_storage() then return false, sh_audit.private_root end
	local ok, data = pcall(encodeJson, {ym_token = token, ym_uid = uid})
	if not ok then return false, data end
	local written, problem = write_file(sh_audit.private_root .. '/yandex-music.json', data)
	if written then sh_audit.saved_ym_token, sh_audit.saved_ym_uid = token, uid end
	return written, problem
end

function sh_audit.migrate_private_storage()
	if not sh_audit.ensure_private_storage() then
		sh_audit.io_error('Не удалось создать папку личных данных StateHelper.')
		return false
	end
	local base = dir .. '/State Helper/'
	local function read_json(path)
		local file = io.open(path, 'rb')
		if not file then return end
		local data = file:read('*a')
		file:close()
		if not data then return end
		local ok, value = pcall(decodeJson, (data:gsub('^\239\187\191', '')))
		if ok and type(value) == 'table' then return value, data end
		return nil, data
	end
	local private_file = sh_audit.private_root .. '/yandex-music.json'
	local saved = read_json(private_file)
	if saved and type(saved.ym_token) == 'string' then
		setting.ym_token = saved.ym_token
		setting.ym_uid = type(saved.ym_uid) == 'string' and saved.ym_uid or ''
		sh_audit.saved_ym_token, sh_audit.saved_ym_uid = setting.ym_token, setting.ym_uid
	elseif doesFileExist(private_file) then
		if not sh_audit.move_private_file(private_file, private_file .. '.invalid') then
			sh_audit.io_error('Не удалось сохранить повреждённую копию данных входа.', private_file)
			return false
		end
	elseif setting.ym_token == '' and setting.ym_uid == '' then
		sh_audit.saved_ym_token, sh_audit.saved_ym_uid = '', ''
	end
	local ok, problem = sh_audit.save_private_music()
	if not ok then
		sh_audit.io_error('Не удалось перенести данные входа в Яндекс Музыку.', problem)
		return false
	end

	local function strip_credentials(folder)
		for name in lfs.dir(folder) do
			if name:sub(1, 14) == 'Настройки.json' then
				local path = folder .. '/' .. name
				local config, raw = read_json(path)
				if config then
					local changed = false
					for key in pairs(sh_audit.private_fields) do
						if config[key] ~= nil then config[key], changed = nil, true end
					end
					if changed then
						local encoded, data = pcall(encodeJson, config)
						if not encoded or not write_file(path, data) then
							sh_audit.io_error('Не удалось очистить старую копию настроек от данных входа.', path)
						end
					end
				elseif raw then
					for key in pairs(sh_audit.private_fields) do
						if raw:find('"' .. key .. '"', 1, true) then
							local moved = sh_audit.move_private_file(path, sh_audit.private_root .. '/invalid-' .. name)
							if not moved then sh_audit.io_error('Не удалось перенести повреждённую копию настроек.', path) end
							break
						end
					end
				end
			end
		end
	end
	if doesDirectoryExist(base) then strip_credentials(base) end
	local archive = base .. 'Archive'
	if doesDirectoryExist(archive) then
		for name in lfs.dir(archive) do
			local folder = archive .. '/' .. name
			if name:match('^settings%-reset%-') and doesDirectoryExist(folder) then strip_credentials(folder) end
		end
	end
	for _, name in ipairs({'debug.log', 'debug.log.old', 'sign-trace.log', 'license-trace.log', 'crashlog.log'}) do
		local moved = sh_audit.move_private_file(base .. name, sh_audit.private_root .. '/' .. name)
		if not moved then sh_audit.io_error('Не удалось перенести личный журнал.', name) end
	end
	return true
end

function sh_audit.prepare_private_browser()
	if not sh_audit.ensure_private_storage() then return false end
	local target = sh_audit.private_root .. '/Browser'
	if not doesDirectoryExist(target) then lfs.mkdir(target) end
	if not doesDirectoryExist(target) then return false end
	local legacy = dir .. '/State Helper/Browser/'
	for _, name in ipairs({'Profile', 'PrivateProfile', 'control.json', 'status.json', 'host-error.json', 'sites.json',
		'control.json.lua.tmp', 'status.json.tmp', 'host-error.json.tmp', 'sites.json.lua.tmp'}) do
		local moved = sh_audit.move_private_file(legacy .. name, target .. '/' .. name)
		if not moved then return false, name end
	end
	if doesDirectoryExist(legacy) then
		for name in lfs.dir(legacy) do
			if name:match('^status%.json%.tmp%-%d+$') or name:match('^host%-error%.json%.tmp%-%d+$') then
				local moved = sh_audit.move_private_file(legacy .. name, target .. '/' .. name)
				if not moved then return false, name end
			end
		end
	end
	return true
end

function sh_audit.archive_settings_for_reset()
	local base = dir .. '/State Helper/'
	if not sh_audit.ensure_private_storage() then return false, sh_audit.private_root end
	local archive = sh_audit.private_root .. '/Archive'
	if not doesDirectoryExist(archive) then lfs.mkdir(archive) end
	if not doesDirectoryExist(archive) then return false, archive end

	local prefix = archive .. '/settings-reset-' .. os.time()
	local destination, index = prefix, 1
	while doesDirectoryExist(destination) or doesFileExist(destination) do
		index = index + 1
		destination = prefix .. '-' .. index
	end
	local created, create_error = lfs.mkdir(destination)
	if not created then return false, destination .. ': ' .. tostring(create_error) end

	local names = {'Настройки.json', 'Отыгровки', 'Отыгровки-last-good.json', 'yandex-music.json'}
	local function active_path(name)
		if name == 'yandex-music.json' then return sh_audit.private_root .. '/' .. name end
		return base .. name
	end
	for _, suffix in ipairs(sh_audit.settings_backups) do
		names[#names + 1] = 'Настройки.json' .. suffix
	end
	local moved = {}
	for _, name in ipairs(names) do
		local path = active_path(name)
		if doesFileExist(path) or doesDirectoryExist(path) then
			local ok, problem = os.rename(path, destination .. '/' .. name)
			if not ok then
				local failure = name .. ': ' .. tostring(problem)
				for i = #moved, 1, -1 do
					local item = moved[i]
					local restored, restore_error = os.rename(destination .. '/' .. item, active_path(item))
					if not restored then failure = failure .. ' | ' .. item .. ': ' .. tostring(restore_error) end
				end
				return false, failure .. ' | ' .. destination
			end
			moved[#moved + 1] = name
		end
	end
	return true, destination
end

function save(force)
	if settings_reset_pending then return false end
	if not force and setting.first_start then return false end
	local private_saved, private_error = sh_audit.save_private_music()
	if not private_saved then
		sh_audit.io_error('Не удалось сохранить данные входа в Яндекс Музыку.', private_error)
		return false
	end
	local public = {}
	for key, value in pairs(setting) do
		if not sh_audit.private_fields[key] then public[key] = value end
	end
	local ok, data = pcall(encodeJson, public)
	if not ok then sh_audit.io_error('Не удалось подготовить настройки к сохранению.'); return false end
	if not force and data == last_saved_json then return true end
	local written, problem = write_file(dir .. '/State Helper/Настройки.json', data)
	if written then
		last_saved_json = data
		local backup_ok, backup_error = write_file(dir .. '/State Helper/Настройки.json.last-good', data)
		if not backup_ok then sh_audit.io_error('Настройки сохранены, но резервная копия не обновилась.', backup_error) end
		return true
	end
	sh_audit.io_error('Не удалось сохранить настройки. Проверьте свободное место и доступ к папке.', problem)
	return false
end

local debug_start_time = os.time()
local debug_file = nil
local debug_writes = 0
local debug_beat = 0
local debug_frames = 0
local debug_last_time = 0
local debug_last_min = nil

local function debug_call(name)
	local fn = _G[name]
	if type(fn) ~= 'function' then return '?' end
	local ok, res = pcall(fn)
	if not ok then return 'err' end
	return tostring(res)
end

local function debug_write(msg)
	debug_writes = debug_writes + 1
	if debug_writes % 5000 == 0 and debug_file then
		pcall(function() debug_file:close() end)
		debug_file = nil
	end
	if not debug_file then
		local path = sh_audit.private_root .. '/debug.log'
		local old = io.open(path, 'r')
		if old then
			local size = old:seek('end') or 0
			old:close()
			if size > 8 * 1024 * 1024 then
				os.remove(path .. '.old')
				os.rename(path, path .. '.old')
			end
		end
		debug_file = io.open(path, 'a')
		if not debug_file then return end
	end
	if not pcall(function() debug_file:write(msg .. '\n'); debug_file:flush() end) then
		debug_file = nil
	end
end

function debug_log(fmt, ...)
	if not setting or not setting.debug_mode then return end
	local ok, msg = pcall(string.format, fmt, ...)
	debug_write(string.format('[%s +%d] %s', os.date('%H:%M:%S'), os.time() - debug_start_time, ok and msg or tostring(fmt)))
end

function debug_init()
	if not setting.debug_mode then return end
	debug_log('start source=%s token=%s mini=%s time_hud=%s', tostring(setting.music_source), setting.ym_token ~= '' and 'yes' or 'no', tostring(setting.mini_player), tostring(setting.time_hud))
	local crash_dir = getGameDirectory() .. '/crashlog'
	if doesDirectoryExist(crash_dir) then
		local newest, newest_time = nil, 0
		for name in lfs.dir(crash_dir) do
			if name:find('^addr%..+%.log$') then
				local full = crash_dir .. '/' .. name
				local attr = lfs.attributes(full)
				if attr and attr.modification > newest_time then
					newest, newest_time = full, attr.modification
				end
			end
		end
		if newest then
			local f = io.open(newest, 'r')
			if f then
				local data = f:read('*a') or ''
				f:close()
				debug_log('crash %s: %s', newest:match('[^/\\]+$'), data:gsub('%s+', ' '):sub(1, 1500))
			end
		end
	end
end

function debug_frame()
	if not setting.debug_mode then return end
	debug_frames = debug_frames + 1
	local fg = debug_call('isGameWindowForeground')
	if fg ~= debug_last_min then
		debug_last_min = fg
		debug_log('FG=%s play=%s/%s/%s stream=%s img=%s ym=%s', fg, tostring(play.status), tostring(play.tab), tostring(play.i), tostring(play.stream), tostring(play.image_label), tostring(mus.ym_status))
	end
	local now = os.time()
	if now == debug_last_time then return end
	local elapsed = now - debug_last_time
	debug_last_time = now
	debug_beat = debug_beat + 1
	local fps = debug_frames / math.max(elapsed, 1)
	debug_frames = 0
	debug_log('beat %d fps=%.1f fg=%s gt=%s pause=%s chat=%s src=%s ym=%s play=%s/%s/%s stream=%s act=%s pos=%s/%s img=%s mp=%s tracks=%d mem=%.0f', debug_beat, fps, fg, debug_call('getGameTimer'), debug_call('isGamePaused'), debug_call('sampIsChatInputActive'), tostring(setting.music_source), tostring(mus.ym_status), tostring(play.status), tostring(play.tab), tostring(play.i), tostring(play.stream), tostring(get_status_potok_song()), tostring(play.pos_time), tostring(play.len_time), tostring(play.image_label), windows.player and tostring(windows.player[0]) or '?', tracks and #tracks or 0, collectgarbage('count'))
end

local debug_thread_create = lua_thread.create
lua_thread.create = function(fn, ...)
	if type(fn) ~= 'function' then return debug_thread_create(fn, ...) end
	-- LuaThreadInterface освобождает ссылки через lua_State создателя: он должен пережить дочерний объект.
	local context = {run = fn, owner = coroutine.running()}
	if not setting.debug_mode then
		return debug_thread_create(function(...) return context.run(...) end, ...)
	end
	local info = debug.getinfo(fn, 'Sl')
	local name = '?'
	if info then
		name = tostring((info.short_src or '?'):match('[^/\\]+$') or '?') .. ':' .. tostring(info.linedefined)
	end
	local args = {n = select('#', ...), ...}
	debug_log('thread > %s', name)
	return debug_thread_create(function()
		local ok, err = pcall(context.run, unpack(args, 1, args.n))
		if ok then
			debug_log('thread < %s', name)
		else
			debug_log('thread ! %s: %s', name, tostring(err))
		end
	end)
end

local cmd_loaded_files = {}

function save_cmd()
	if settings_reset_pending or setting.first_start then return false end
	local base = dir .. '/State Helper/Отыгровки/'
	if not doesDirectoryExist(base) then createDirectory(base) end
	local plan, current, before, staged = {}, {}, {}, {}
	local function fail(detail)
		sh_audit.io_error('Не удалось сохранить команды. Изменения остались в памяти; повторите сохранение.', detail)
		for _, temp in ipairs(staged) do os.remove(temp) end
		return false
	end
	for _, c in ipairs(cmd[1]) do
		local valid, problem = sh_audit.command(c)
		if not valid then return fail(problem) end
		local category = cmd[2][c.folder]
		local folder = category and category[1]
		if type(folder) ~= 'string' or folder == '' or folder == '.' or folder == '..' or folder:find('[<>:"/\\|?*]') then return fail('invalid folder') end
		local directory = base .. folder .. '/'
		if not doesDirectoryExist(directory) then createDirectory(directory) end
		local name = c.cmd ~= '' and c.cmd or tostring(c.UID)
		local path, duplicate = directory .. name .. '.json', 2
		while current[path] do path = directory .. name .. ' (' .. duplicate .. ').json'; duplicate = duplicate + 1 end
		local ok, data = pcall(encodeJson, c); if not ok then return fail(data) end
		current[path], plan[path] = true, data
	end
	local ok, categories = pcall(encodeJson, cmd[2]); if not ok then return fail(categories) end
	plan[base .. 'categories.json'] = categories
	for path in pairs(cmd_loaded_files) do if not current[path] then plan[path] = false end end
	for path in pairs(plan) do
		local file = io.open(path, 'rb')
		if file then before[path] = file:read('*a'); file:close()
		elseif doesFileExist(path) then return fail('cannot read old file: ' .. path)
		else before[path] = false end
	end
	-- Keep a complete rollback snapshot outside the folders scanned by the loader.
	local encoded, recovery = pcall(encodeJson, before)
	if not encoded or not write_file(dir .. '/State Helper/Отыгровки-last-good.json', recovery) then return fail('cannot write recovery snapshot') end
	for path, data in pairs(plan) do
		if data then
			local temp = path .. '.pending'
			if not write_file(temp, data) then return fail('cannot stage: ' .. path) end
			staged[#staged + 1] = temp
		end
	end
	local applied, problem = {}, nil
	for path, data in pairs(plan) do
		local success
		if data then success = replace_file(path .. '.pending', path) else success = not doesFileExist(path) or os.remove(path) end
		applied[#applied + 1] = path
		if not success then problem = path; break end
	end
	if problem then
		for _, path in ipairs(applied) do if before[path] then write_file(path, before[path]) else os.remove(path) end end
		return fail('rollback snapshot: State Helper/Отыгровки-last-good.json; failed: ' .. problem)
	end
	cmd_loaded_files = {}
	for path in pairs(current) do cmd_loaded_files[path] = true end
	return true
end
	
