local sign_trace_active = false
local sign_trace_path = sh_audit.private_root .. '/sign-trace.log'

local function sign_trace_write(direction, text)
	if not sign_trace_active then return end
	local file = io.open(sign_trace_path, 'ab')
	if not file then return end
	file:write(os.date('[%H:%M:%S] '), direction, '\r\n', text, '\r\n\r\n')
	file:close()
end

function sign_trace_start()
	if sign_trace_active then
		sign_trace_active = false
		sampAddChatMessage('[SH]{FFFFFF} CEF trace stopped: StateHelper passwords/sign-trace.log', 0xFF5345)
		return
	end
	local file = io.open(sign_trace_path, 'wb')
	if file then file:close() end
	sign_trace_active = true
	sampAddChatMessage('[SH]{FFFFFF} CEF trace started. Open the sign menu, select one sign, then run /shsigntrace again.', 0xFF5345)
end

local function sign_trace_stream(label, bs)
	if not sign_trace_active then return end
	local offset = raknetBitStreamGetReadOffset(bs)
	local size = raknetBitStreamGetNumberOfBytesUsed(bs)
	raknetBitStreamSetReadOffset(bs, 0)
	local bytes = {}
	for i = 1, math.min(size, 64) do
		bytes[i] = string.format('%02X', raknetBitStreamReadInt8(bs) % 256)
	end
	raknetBitStreamSetReadOffset(bs, offset)
	sign_trace_write(label, 'bytes=' .. size .. ' hex=' .. table.concat(bytes, ' '))
end

function CefDialog()
	local document_opened = false
	addEventHandler('onSendRpc', function(id, bs)
		if id == 62 then
			sign_trace_stream('RAW_DIALOG_RESPONSE', bs)
		elseif sign_trace_active then
			sign_trace_write('OUT_RPC#' .. tostring(id), '')
		end
	end)
	addEventHandler('onReceivePacket', function(id, bs)
		if id == 220 then
			raknetBitStreamIgnoreBits(bs, 8)
			local cef_subtype = raknetBitStreamReadInt8(bs)
			if sign_trace_active and cef_subtype ~= 17 then
				sign_trace_write('IN#' .. cef_subtype, '')
			end
			if cef_subtype == 17 then
				raknetBitStreamIgnoreBits(bs, 32)
				local length = raknetBitStreamReadInt16(bs)
				local encoded = raknetBitStreamReadInt8(bs)
				if length > 0 then
					local text = (encoded ~= 0) and raknetBitStreamDecodeString(bs, length + encoded) or raknetBitStreamReadString(bs, length)
					sign_trace_write('IN', text)
					local event, body = text:match("window%.executeEvent%('(.+)',%s*`%[(.+)%]`%);")

					if event == 'event.setActiveView' and body and body:find('InteractiveMenu') and bodycam_wait then
						bodycam_wait = false
						sendCef('radialMenu.useAction|280')
					end

					if run_sob then
						if setting.sob.hide_doc and setting.sob.close_doc and not isCefScript then
							sendJav(cef_script)
							isCefScript = true
						end
						if event == 'event.documents.inititalizeData' then
							local ok, data = pcall(json.decode, body)
							if not ok or type(data) ~= 'table' then return end
							local document_type = data['type']

							if document_type == 1 then --> Паспорт
								if data['name'] ~= sob_info.nick then
									if setting.sob.hide_doc and setting.sob.close_doc then
										if not setting.cef_notif then
											sampAddChatMessage('[SH]{FFFFFF} Нельзя просматривать чужие документы при включенной функции \'Скрывать документы\'', 0xFF5345)
										else
											cefnotig('{FF5345}[SH]{FFFFFF} Нельзя просматривать чужие документы при включенной функции \'Скрывать документы\'', 4000)
										end
										sendCef('documents.close')
										sendJav("if(typeof window.cleanupCefHider === 'function') { window.cleanupCefHider(); }")
										isCefScript = false
									end
									sendJav("if(typeof window.cleanupCefHider === 'function') { window.cleanupCefHider(); }")
									isCefScript = false
									return
								end
								sob_info.valid = true
								local sex = data['sex']
								local birthday = data['birthday']
								local zakono = tonumber(tostring(data['zakono']):match("%d+")) or -2
								local level = tonumber(tostring(data['level']):match("%d+")) or -2
								local agenda = tostring(data['agenda'] or "Нет")
								local charity_info = data['charity']
								if agenda:find("Имеется", 1, true) then
									sob_info.ticket = 1
								else
									sob_info.ticket = 2
								end
								if charity_info ~= 'Нет' then
									sob_info.warn = 0
								else
									sob_info.warn = 1
								end
								sob_info.law = zakono
								sob_info.exp = level
							if setting.sob.close_doc then
								lua_thread.create(function()
									wait(200)
									sendCef('documents.changePage|2')
								end)
							end
							elseif sob_info.valid then
								if document_type == 2 then --> Лицензии
									local licenses = data['info']

									sob_info.car = 2
									sob_info.moto = 2
									sob_info.gun = 2

									for _, v in pairs(licenses) do
										local license = v['license']
										local date_text = v['date_text'] or ""
										local is_active = (date_text:find("Действует", 1, true) or date_text:find("Бессрочная", 1, true)) and 1 or 2

										if license == "car" then
											sob_info.car = is_active
										elseif license == "bike" then
											sob_info.moto = is_active
										elseif license == "gun" then
											sob_info.gun = is_active
										end
									end
									if setting.sob.close_doc then
										lua_thread.create(function()
											wait(200)
											sendCef('documents.changePage|4')
										end)
									end
								elseif document_type == 4 then --> Мед.карта
									local zavisimost = tonumber(data['zavisimost']) or 0
									local state = data['state'] or ""
									 local sub_text = (data['demorgan'] and data['demorgan']['sub_text']) or ""

									local med_status_m = {
										["Полностью здоров"] = 1,
										["Псих. отклонени"] = 2,
										["Псих. нездоров"] = 3,
										["Не определён"] = 4
									}

									local med_status = 4
									local found_status = false
									for key, value in pairs(med_status_m) do
										if state:find(key, 1, true) then
											med_status = value
											found_status = true
											break
										end
									end
									
									if sub_text == "Обновите мед. карту" then
										sob_info.org = 2
									else
										sob_info.org = 1
									end

									if not found_status then
										med_status = 5
										sob_info.org = 3
									end

									sob_info.narko = zavisimost
									sob_info.med = med_status
									if setting.sob.close_doc then
										lua_thread.create(function()
											wait(200)
											sendCef('documents.changePage|8')
