local function fast_action_name(name)
	local text = u8:decode(name):match('^%s*(.-)%s*$')
	text = fast_action_names[text] or text
	local first_byte = text:byte(1)
	if first_byte and first_byte >= 224 and first_byte <= 255 then
		text = string.char(first_byte - 32) .. text:sub(2)
	elseif first_byte == 184 then
		text = string.char(168) .. text:sub(2)
	else
		text = text:sub(1, 1):upper() .. text:sub(2)
	end
	return u8(text)
end

--> [SH-Lectures] Specialize each menu choice into an independent command.
do
 local legacy_names = {lekmz = true, lekcl = true, lekgov = true, lekarmy = true, lekfd = true, lekzeks = true, lektsr = true}
 local groups = {'hospital', 'driving_school', 'government', 'army', 'fire_department', 'jail'}
 local function split_lecture(command)
  if not legacy_names[command.cmd] or type(command.act) ~= 'table' then return nil end
  local dialog
  for _, action in ipairs(command.act) do
   if action[1] == 'DIALOG' then dialog = action; break end
  end
  if not dialog or type(dialog[3]) ~= 'table' then return nil end
  local dialog_id = tostring(dialog[2])
  local choices, seen = {}, {}
  for _, action in ipairs(command.act) do
   if action[1] == 'IF' and action[2] == 2 and type(action[3]) == 'table' and tostring(action[3][1]) == dialog_id then
    local choice = tonumber(action[3][2])
    if choice and choice >= 1 and choice == math.floor(choice) and not seen[choice] then
     choices[#choices + 1], seen[choice] = choice, true
    end
   end
  end
  table.sort(choices)
  local function specialize(first, last, selected)
   local out, i = {}, first
   while i <= last do
    local action = command.act[i]
    if action == dialog then
     i = i + 1
    elseif action[1] == 'IF' and action[2] == 2 and type(action[3]) == 'table' and tostring(action[3][1]) == dialog_id then
     local depth, ending, alternate = 1, i + 1, nil
     while ending <= last do
      local kind = command.act[ending][1]
      if kind == 'IF' then depth = depth + 1 end
      if kind == 'END' then depth = depth - 1; if depth == 0 then break end end
      if kind == 'ELSE' and depth == 1 then alternate = ending end
      ending = ending + 1
     end
     if depth ~= 0 then error('Unclosed IF in lecture ' .. tostring(command.cmd)) end
     local match = tonumber(action[3][2]) == selected
     local body_first = match and (i + 1) or (alternate and alternate + 1 or ending)
     local body_last = match and ((alternate or ending) - 1) or (ending - 1)
     for _, child in ipairs(specialize(body_first, body_last, selected)) do out[#out + 1] = child end
     i = ending + 1
    else
     out[#out + 1] = deep_copy(action)
     i = i + 1
    end
   end
   return out
  end
  local result = {}
  for _, choice in ipairs(choices) do
   local title = dialog[3][choice]
   if not title or title == '' then
    title = command.cmd == 'lekmz' and choice == 5 and u8'ОПП при утоплении' or (u8'Тема ' .. choice)
   end
   local variant = deep_copy(command)
   variant.cmd = command.cmd .. choice
   variant.desc = (command.cmd == 'lekzeks' and u8'Лекция для заключённых: ' or u8'Лекция: ') .. title
   variant.act = specialize(1, #command.act, choice)
   variant.id_element = #variant.act
   if #result > 0 then variant.key, variant.UID = {'', {}}, nil end
   result[#result + 1] = variant
  end
  return #result > 0 and result or nil
 end
 local function remap_fast(fast, mapping)
  local changed, visited = false, {}
  local function list(items)
   if type(items) ~= 'table' or visited[items] then return end
   visited[items] = true
   local present = {}
   for _, item in ipairs(items) do
    if type(item) == 'table' and type(item.cmd) == 'string' then present[item.cmd:gsub('^/', '')] = true end
   end
   for i = #items, 1, -1 do
    local item = items[i]
    if type(item) == 'table' then
     if item.items then list(item.items) end
     local name = type(item.cmd) == 'string' and item.cmd:match('^/?([%w_]+)$')
     local variants = name and mapping[name]
     if variants then
      table.remove(items, i)
      for j = #variants, 1, -1 do
       local variant = variants[j]
       if not present[variant.cmd] then
        local entry = deep_copy(item)
        entry.cmd, entry.name, entry.id = variant.cmd, variant.desc, #(variant.arg or {}) > 0
        table.insert(items, i, entry)
        present[variant.cmd] = true
       end
      end
      changed = true
     end
    end
   end
  end
  for _, key in ipairs({'one_win', 'two_win', 'wheel', 'custom'}) do list(fast[key]) end
  for _, items in pairs(type(fast.by_org) == 'table' and fast.by_org or {}) do list(items) end
  for _, pref in pairs(type(fast.menu) == 'table' and fast.menu or {}) do
   if type(pref) == 'table' and type(pref.off) == 'table' then
    for old, variants in pairs(mapping) do
     if pref.off[old] ~= nil then
      for _, variant in ipairs(variants) do
       if pref.off[variant.cmd] == nil then pref.off[variant.cmd] = pref.off[old] end
      end
      pref.off[old], changed = nil, true
     end
    end
   end
  end
  return changed
 end
 function migrate_lecture_commands()
  if setting.first_start then return false end
  local mapping = {}
  for old in pairs(legacy_names) do
   local variants = {}
   for _, group in ipairs(groups) do
    for _, command in ipairs(cmd_defoult[group] or {}) do
     if command.cmd:match('^' .. old .. '%d+$') then variants[#variants + 1] = command end
    end
   end
   table.sort(variants, function(a, b) return tonumber(a.cmd:match('(%d+)$')) < tonumber(b.cmd:match('(%d+)$')) end)
   if #variants > 0 then mapping[old] = variants end
  end
  local names, uids = {}, {}
  for _, command in ipairs(cmd[1]) do names[command.cmd] = true; if command.UID then uids[command.UID] = true end end
  local replacement, changed = {}, false
  for _, command in ipairs(cmd[1]) do
   local ok, variants = pcall(split_lecture, command)
   if not ok then print('[SH Lectures] ' .. tostring(variants)); variants = nil end
   if variants then
    for _, variant in ipairs(variants) do
     if names[variant.cmd] then
      print('[SH Lectures] Command name already exists: ' .. variant.cmd .. '; original menu preserved.')
      variants = nil; break
     end
    end
   end
   if variants then
    for _, variant in ipairs(variants) do
     if not variant.UID then
      repeat variant.UID = math.random(20, 95000000) until not uids[variant.UID]
     end
     uids[variant.UID], names[variant.cmd] = true, true
     replacement[#replacement + 1] = variant
    end
    mapping[command.cmd], changed = variants, true
   else
    if legacy_names[command.cmd] then mapping[command.cmd] = nil end
    replacement[#replacement + 1] = command
   end
  end
  local next_fast = deep_copy(setting.fast)
  local fast_changed = remap_fast(next_fast, mapping)
  if not changed and not fast_changed then return false end
  local backup = dir .. '/State Helper/Лекции-до-разделения-' .. os.time() .. '.json'
  local suffix = 1
  while doesFileExist(backup) do suffix = suffix + 1; backup = dir .. '/State Helper/Лекции-до-разделения-' .. os.time() .. '-' .. suffix .. '.json' end
  if not write_file(backup, encodeJson({commands = cmd[1], fast = setting.fast})) then
   print('[SH Lectures] Backup failed; migration canceled.'); return false
  end
  local previous = cmd[1]
  cmd[1] = replacement
  if changed and not save_cmd() then
   cmd[1] = previous
   print('[SH Lectures] Save failed; original commands retained in memory. Backup: ' .. backup)
   return false
  end
  if fast_changed then setting.fast = next_fast; save() end
  print('[SH Lectures] Separate lecture commands installed. Backup: ' .. backup)
  return true
 end
end
--> [SH-Lectures-End]

function main()
	repeat wait(300) until isSampAvailable()
	reset_state()
	injNotif()
	create_folder('Police', 'для полиции')

	local function loadTenCodes()
		tenCodes = {}
		local tencode_path = dir .. '/State Helper/Police/tencode.json'
		if doesFileExist(tencode_path) then
			local file = io.open(tencode_path, 'r')
			if file then
				local data = file:read('*a')
				file:close()
				local success, all_codes = pcall(decodeJson, data)
				if success and type(all_codes) == 'table' then
					local server_key_found = nil
					local best_score = 0
					if s_na ~= '' then
						if type(all_codes[s_na]) == 'table' then
							server_key_found = s_na
							best_score = 100
						end
						for key, codes in pairs(all_codes) do
							if type(key) == 'string' and type(codes) == 'table' then
								local score = 0
								if key == s_na then
									score = 100
								elseif key:find('^' .. s_na .. '[_-]', 1) then
									score = 50
								elseif key:find(s_na, 1, true) then
									score = 10
								end
								if score > best_score then
									best_score = score
									server_key_found = key
								end
							end
						end
					end
					if server_key_found and all_codes[server_key_found] then
						tenCodes = all_codes[server_key_found]
					else
						local default = all_codes["Default_Winslow_Scottdale_SaintRose_QueenCreek"]
						tenCodes = type(default) == 'table' and default or {}
					end
				end
			end
		end
	end

