				cmd[1][i].UID = math.random(20, 95000000)
				bool_uid_save = true
			end
			
			for h, v in ipairs(cmd[1][i].act) do
				if v[1] == 'IF' then
					if v[5] == nil then
						v[5] = 1
					end
				end
			end

