					sampRegisterChatCommand(_cname, function(arg) cmd_start(arg, _uid .. _cname) end)
				end
				
				if cmd[1][i].cmd == 'licdig' then
					for u = 1, #cmd[1][i].act do
						if cmd[1][i].act[u][1] == 'DIALOG' then
							if cmd[1][i].act[u][2] == '' then
								cmd[1][i].act[u][2] = '1'
