afind_warn = false
afind_run = false
afind_gen = 0
afind_bound = false
afind_q = {}
afind_worker = false
afind_bypass = false

function afind_halt()
	afind_gen = afind_gen + 1
	afind_run = false
end

function afind_sleep(ms)
	local until_t = os.clock() + ms / 1000
	while os.clock() < until_t do
		wait(50)
	end
end

function afind_take_cmd(argument, cmd_name)
	afind_q[#afind_q + 1] = { argument, cmd_name }
	if afind_worker then return end
	afind_worker = true
	lua_thread.create(function()
		local primed = true
		while true do
			if #afind_q > 0 then
				local job = table.remove(afind_q, 1)
				while thread and thread:status() ~= 'dead' do wait(50) end
				if primed then afind_sleep(math.random(1000, 2000)) end
				primed = true
				while thread and thread:status() ~= 'dead' do wait(50) end
				afind_bypass = true
				pcall(cmd_start, job[1], job[2])
				afind_bypass = false
				while thread and thread:status() ~= 'dead' do wait(50) end
			else
				local until_t = os.clock() + math.random(1000, 2000) / 1000
				while os.clock() < until_t and #afind_q == 0 do
					wait(50)
				end
				while os.clock() < until_t do wait(50) end
				if #afind_q == 0 then
					afind_worker = false
					if #afind_q == 0 then break end
					afind_worker = true
				end
				primed = false
			end
		end
	end)
end

function afind_bind(on)
	if afind_bound then
		sampUnregisterChatCommand('afind')
		afind_bound = false
	end
	afind_halt()
	if on and setting.org >= 11 and setting.org <= 15 then
		sampRegisterChatCommand('afind', afind_cmd)
		afind_bound = true
	end
end

function afind_cmd(arg)
	if not setting.police_settings.afind or setting.org < 11 or setting.org > 15 then return end
	if afind_run then
		afind_halt()
		sampAddChatMessage('[SH]{FFFFFF} /afind выключен.', 0xFF5345)
		return
	end
	local id = tonumber((arg or ''):match('^%s*(%d+)%s*$'))
	if not id or id < 0 or id > 999 then
		sampAddChatMessage('[SH]{FFFFFF} Использование: /afind [id 0-999]', 0xFF5345)
		return
	end
	afind_gen = afind_gen + 1
	local gen = afind_gen
	afind_run = true
	lua_thread.create(function()
		local function still()
			return afind_run and afind_gen == gen and setting.police_settings.afind and setting.org >= 11 and setting.org <= 15
		end
		while still() do
			while still() and (afind_worker or #afind_q > 0) do
				wait(50)
			end
			if not still() then break end
			sampSendChat('/find ' .. id)
			local slice = math.random(1500, 2200)
			local t0 = os.clock()
			while still() and (os.clock() - t0) * 1000 < slice do
				if afind_worker or #afind_q > 0 then break end
				wait(50)
			end
		end
		if afind_gen == gen then afind_run = false end
	end)
	sampAddChatMessage('[SH]{FFFFFF} /afind ' .. id .. ' включен. Ещё раз /afind остановит его.', 0xFF5345)
end

