function music_match(hay, needle) --> Поиск без учёта регистра (кириллица и латиница)
	local function lower(s)
		return (s:lower():gsub('[' .. string.char(192) .. '-' .. string.char(223) .. ']', function(c)
			return string.char(c:byte() + 32)
		end):gsub(string.char(168), string.char(184)))
	end
	return lower(hay):find(lower(needle), 1, true) ~= nil
end

function find_track_link(search_text, page) --> Поиск песни в интернете
	mus.search_token = (mus.search_token or 0) + 1
	local search_token = mus.search_token
	debug_log('search hitmotop q=%s page=%s', tostring(search_text), tostring(page))
	local tracks_repsone = {
		link = {},
		artist = {},
		name = {},
		time = {},
		image = {}
	}
	local page_ssl = ''
	local all_page_num = 1
	local page_table = {'1'}
	current_page = page
	local function remove_duplicates(array)
		local seen = {}
		local result = {}

		for _, value in ipairs(array) do
			if not seen[value] then
				table.insert(result, value)
				seen[value] = true
			end
		end

		return result
	end
	if page == 2 then
		page_ssl = '/start/48'
	elseif page == 3 then
		page_ssl = '/start/96'
	elseif page == 4 then
		page_ssl = '/start/144'
	end
	
	asyncHttpRequest('GET', 'https://' .. site_link .. '/search' .. page_ssl .. '?q=' .. urlencode(mus.search), {
		headers = {
			['User-Agent'] = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36',
			['Accept-Language'] = 'ru-RU,ru;q=0.9',
			['Referer'] = 'https://' .. site_link .. '/'
		},
		timeout = 15
	},
		function(response)
			if search_token ~= mus.search_token then return end
			if page == 1 then
				for link in string.gmatch(u8:decode(response.text), '/search/start/48') do
					table.insert(page_table, '48')
				end
				for link in string.gmatch(u8:decode(response.text), '/search/start/96') do
					table.insert(page_table, '96')
				end
				for link in string.gmatch(u8:decode(response.text), '/search/start/144') do
					table.insert(page_table, '144')
				end
				local new_arr = remove_duplicates(page_table)
				qua_page = #new_arr
			end
			for link in string.gmatch(u8:decode(response.text), 'По вашему запросу ничего не найдено') do
				tracks_repsone.link[1] = 'Ошибка404'
				tracks_repsone.artist[1] = 'Ошибка404'
			end
			for link in string.gmatch(u8:decode(response.text), 'href="(.-)" class=') do
				if link:find('/get/music/') then
					if link:sub(1, 1) == '/' then
						link = 'https://' .. site_link .. link
					end
					track = link:match('(.+).mp3')
					table.insert(tracks_repsone.link, track .. '.mp3')
				end
			end
			for link in string.gmatch(u8:decode(response.text), '"track%_%_title"%>(.-)%</div') do
				local nametrack = link:match('(.+)')
				nametrack = nametrack and nametrack:gsub('^%s*(.-)%s*$', '%1') or 'Неизвестно'
				table.insert(tracks_repsone.name, nametrack)
			end

			for link in string.gmatch(u8:decode(response.text), '"track%_%_desc"%>(.-)%</div') do
				local artist = link:match('(.+)')
				artist = artist and artist:gsub('^%s*(.-)%s*$', '%1') or 'Неизвестно'
				table.insert(tracks_repsone.artist, artist)
			end
			for link in string.gmatch(u8:decode(response.text), '"track%_%_fulltime"%>(.-)%</div') do
				if link:find('(.+)') then
					table.insert(tracks_repsone.time, link:match('(.+)'))
				end
			end
			for link in string.gmatch(u8:decode(response.text), '"track%_%_img" style="background%-image: url%(\'(.-)\'%)%;"%>%</div%>') do
				if link:find('(.+)') then
					table.insert(tracks_repsone.image, link:match('(.+)'))
				end
			end
			
			local track_list = {}
			local count = math.max(#tracks_repsone.link, #tracks_repsone.artist, #tracks_repsone.name, #tracks_repsone.time, #tracks_repsone.image)

			for i = 1, count do
				track_list[i] = {
					link = tracks_repsone.link[i] or '',
					artist = tracks_repsone.artist[i] or '',
					name = tracks_repsone.name[i] or '',
					time = tracks_repsone.time[i] or '',
					image = tracks_repsone.image[i] or ''
				}
			end
			
			tracks = track_list
			debug_log('search hitmotop tracks=%d', #track_list)
		end,
		function(err)
		print(err)
	end)
end

-- Яндекс Музыка: вход по Device Flow, поиск и подписанные ссылки на mp3
-- CLIENT_ID / CLIENT_SECRET — публичные credentials официального Android-клиента Яндекс.Музыки
-- (используются в https://github.com/MarshalX/yandex-music-api и множестве open-source проектов).
-- Это не приватный секрет приложения; ротация не требуется. Токен пользователя храните в setting.ym_token.
local YM_CLIENT_ID = '23cabbbdc6cd418abb4b39c32c41195d'
local YM_CLIENT_SECRET = '53bc75238f0c4d08a118e51fe9203300'
local YM_API = 'https://api.music.yandex.net'
local ym_device_id = (function()
	local chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
	local t = {}
	for i = 1, 10 do
		local n = math.random(#chars)
		t[i] = chars:sub(n, n)
	end
	return table.concat(t)
end)()

function ym_request(url, resolve, reject)
	debug_log('http > %s', tostring(url))
	asyncHttpRequest('GET', url, {
		headers = {
			['X-Yandex-Music-Client'] = 'YandexMusicAndroid/24023621',
			['Authorization'] = 'OAuth ' .. setting.ym_token,
			['Accept-Language'] = 'ru'
		},
		timeout = 15
	}, function(response)
		debug_log('http < %s code=%s len=%s', tostring(url), tostring(response and response.status_code), tostring(response and response.text and #response.text))
		if response and tonumber(response.status_code) == 401 and setting.ym_token ~= '' then
			setting.ym_token = ''
			setting.ym_uid = ''
			ym_playlists = nil
			save()
			sampAddChatMessage('[SH] {FFFFFF}Токен Яндекс Музыки недействителен, войдите заново.', 0xFF5345)
		end
		if resolve then resolve(response) end
	end, function(err)
		debug_log('http ! %s %s', tostring(url), tostring(err))
		if reject then reject(err) end
	end)
end

function ym_auth_start()
	debug_log('ym auth start')
	mus.ym_status = 'requesting'
	mus.ym_auth = nil
	asyncHttpRequest('POST', 'https://oauth.yandex.ru/device/code', {
		data = 'client_id=' .. YM_CLIENT_ID .. '&device_id=' .. ym_device_id .. '&device_name=StateHelper',
		headers = {['Content-Type'] = 'application/x-www-form-urlencoded'},
		timeout = 15
	}, function(response)
		local ok, data = pcall(json.decode, response.text)
		if not ok or not data or not data.device_code then
			mus.ym_status = 'error'
			sampAddChatMessage('[SH] {FFFFFF}Не удалось начать вход в Яндекс Музыку.', 0xFF5345)
			return
		end
		mus.ym_status = 'pending'
		debug_log('ym device code received; interval=%s', tostring(data.interval))
		mus.ym_user_code = data.user_code
		mus.ym_interval = tonumber(data.interval) or 5
		local url = data.verification_url or 'https://ya.ru/device'
		if type(url) ~= 'string' or not url:match('^https://') then url = 'https://ya.ru/device' end
		setClipboardText(tostring(data.user_code))
		shell32.ShellExecuteA(nil, 'open', url, nil, nil, 1)
		sampAddChatMessage('[SH] {FFFFFF}Код входа: {FFD700}' .. tostring(data.user_code) .. '{FFFFFF} скопирован в буфер. Открыт ' .. url, 0xFF5345)
		ym_auth_wait(data.device_code, tonumber(data.expires_in) or 300)
	end, function(err)
		print(err)
		mus.ym_status = 'error'
		sampAddChatMessage('[SH] {FFFFFF}Не удалось начать вход в Яндекс Музыку.', 0xFF5345)
	end)
end

function ym_auth_wait(device_code, expires_in)
	mus.ym_auth = {
		code = device_code,
		until_time = os.time() + expires_in,
		next_time = os.time() + (mus.ym_interval or 5)
	}
end

function ym_auth_poll()
	local auth = mus.ym_auth
	if not auth or auth.busy or os.time() < auth.next_time then return end
	if os.time() > auth.until_time then
		mus.ym_auth = nil
		mus.ym_status = 'expired'
		sampAddChatMessage('[SH] {FFFFFF}Код истёк, нажмите «Войти» ещё раз.', 0xFF5345)
		return
	end
	auth.busy = true
	asyncHttpRequest('POST', 'https://oauth.yandex.ru/token', {
		data = 'grant_type=device_code&code=' .. auth.code .. '&client_id=' .. YM_CLIENT_ID .. '&client_secret=' .. YM_CLIENT_SECRET,
		headers = {['Content-Type'] = 'application/x-www-form-urlencoded'},
		timeout = 15
	}, function(response)
		if mus.ym_auth ~= auth then return end
		auth.busy = false
		auth.next_time = os.time() + (mus.ym_interval or 5)
		local ok, data = pcall(json.decode, response.text)
		if not ok or type(data) ~= 'table' then return end
		debug_log('ym poll err=%s', tostring(data.error))
		if data.access_token then
			mus.ym_auth = nil
			setting.ym_token = data.access_token
			setting.ym_uid = ''
			ym_playlists = nil
			mus.ym_status = 'ok'
			save()
			sampAddChatMessage('[SH] {FFFFFF}Вход в Яндекс Музыку выполнен.', 0xFF5345)
		elseif data.error == 'slow_down' then
			mus.ym_interval = (mus.ym_interval or 5) + 5
		elseif data.error and data.error ~= 'authorization_pending' then
			mus.ym_auth = nil
			mus.ym_status = 'error'
			sampAddChatMessage('{FF6347}[SH] {FFFFFF}Не удалось войти в Яндекс Музыку.', -1)
		end
	end, function(err)
		if mus.ym_auth ~= auth then return end
		auth.busy = false
		auth.next_time = os.time() + (mus.ym_interval or 5)
		debug_log('ym poll ! %s', tostring(err))
	end)
end

