function sefon_http(url, resolve, reject)
	debug_log('sefon > %s', tostring(url))
	local th = effil.thread(function(url, ua)
		local ffi = require 'ffi'
		ffi.cdef[[
			typedef void* HINTERNET;
			HINTERNET InternetOpenA(const char*, unsigned long, const char*, const char*, unsigned long);
			HINTERNET InternetOpenUrlA(HINTERNET, const char*, const char*, unsigned long, unsigned long, uintptr_t);
			int InternetReadFile(HINTERNET, void*, unsigned long, unsigned long*);
			int InternetCloseHandle(HINTERNET);
			int InternetSetOptionA(HINTERNET, unsigned long, void*, unsigned long);
			int HttpQueryInfoA(HINTERNET, unsigned long, void*, unsigned long*, unsigned long*);
			unsigned long GetLastError(void);
		]]
		local wi = ffi.load('wininet')
		local session = wi.InternetOpenA(ua, 0, nil, nil, 0)
		if session == nil then return false, 'InternetOpen error ' .. tostring(ffi.C.GetLastError()) end
		local tmo = ffi.new('unsigned long[1]', 20000)
		wi.InternetSetOptionA(session, 2, tmo, 4)
		wi.InternetSetOptionA(session, 5, tmo, 4)
		wi.InternetSetOptionA(session, 6, tmo, 4)
		local hdr = 'Accept: text/html,application/xhtml+xml,image/*,*/*;q=0.8\r\nAccept-Language: ru,uk;q=0.9,en;q=0.8\r\nReferer: https://sefon.pro/\r\n'
		local h = wi.InternetOpenUrlA(session, url, hdr, #hdr, 0x80000000 + 0x04000000, 0)
		if h == nil then
			local e = tonumber(ffi.C.GetLastError())
			wi.InternetCloseHandle(session)
			return false, 'WinINet error ' .. tostring(e)
		end
		local code = ffi.new('unsigned long[1]')
		local clen = ffi.new('unsigned long[1]', 4)
		wi.HttpQueryInfoA(h, 19 + 0x20000000, code, clen, nil)
		local buf, got = ffi.new('char[65536]'), ffi.new('unsigned long[1]')
		local parts, total = {}, 0
		while wi.InternetReadFile(h, buf, 65536, got) ~= 0 and got[0] > 0 do
			parts[#parts + 1] = ffi.string(buf, got[0])
			total = total + got[0]
			if total > 8 * 1024 * 1024 then break end
		end
		wi.InternetCloseHandle(h)
		wi.InternetCloseHandle(session)
		return true, {status_code = tonumber(code[0]), text = table.concat(parts)}
	end)(url, SEFON_UA)
	table.insert(http_pending, {runner = th, resolve = resolve or function() end, reject = reject or function() end, url = url})
end

sefon_probed = setmetatable({}, {__mode = 'k'})

function sefon_content_length(url, callback)
	local th = effil.thread(function(url, ua)
		local ffi = require 'ffi'
		ffi.cdef[[
			typedef void* HINTERNET;
			HINTERNET InternetOpenA(const char*, unsigned long, const char*, const char*, unsigned long);
			HINTERNET InternetOpenUrlA(HINTERNET, const char*, const char*, unsigned long, unsigned long, uintptr_t);
			int InternetCloseHandle(HINTERNET);
			int InternetSetOptionA(HINTERNET, unsigned long, void*, unsigned long);
			int HttpQueryInfoA(HINTERNET, unsigned long, void*, unsigned long*, unsigned long*);
		]]
		local wi = ffi.load('wininet')
		local session = wi.InternetOpenA(ua, 0, nil, nil, 0)
		if session == nil then return false, 'open' end
		local tmo = ffi.new('unsigned long[1]', 8000)
		wi.InternetSetOptionA(session, 2, tmo, 4)
		wi.InternetSetOptionA(session, 5, tmo, 4)
		wi.InternetSetOptionA(session, 6, tmo, 4)
		local hdr = 'Referer: https://sefon.pro/\r\n'
		local h = wi.InternetOpenUrlA(session, url, hdr, #hdr, 0x80000000 + 0x04000000, 0)
		if h == nil then
			wi.InternetCloseHandle(session)
			return false, 'url'
		end
		local len = ffi.new('unsigned long[1]')
		local size = ffi.new('unsigned long[1]', 4)
		local ok = wi.HttpQueryInfoA(h, 5 + 0x20000000, len, size, nil)
		wi.InternetCloseHandle(h)
		wi.InternetCloseHandle(session)
		if ok == 0 then return false, 'no length' end
		return true, {bytes = tonumber(len[0])}
	end)(url, SEFON_UA)
	table.insert(http_pending, {runner = th, resolve = function(r) callback(r and r.bytes) end, reject = function() callback(nil) end, url = url})
end

function sefon_fill_times(list)
	local n = 0
	for i = 1, #list do
		local tr = list[i]
		if tr.time == '0:00' and tr.url and not sefon_probed[tr] and n < 12 then
			n = n + 1
			sefon_probed[tr] = true
			sefon_content_length(tr.url, function(bytes)
				if not bytes or bytes < 200000 then return end
				local u = tostring(tr.url)
				local kbps = tonumber(u:match('%%28(%d+)kbps') or u:match('%((%d+)kbps')) or 192
				if kbps < 32 or kbps > 320 then kbps = 192 end
				local sec = math.floor(bytes * 8 / (kbps * 1000) + 0.5)
				if sec > 0 and sec < 36000 and tr.time == '0:00' then
					tr.time = string.format('%d:%02d', math.floor(sec / 60), sec % 60)
					debug_log('sefon time probe %s -> %s (%d bytes)', tostring(tr.link), tr.time, bytes)
				end
			end)
		end
	end
end

function sefon_urlencode(s)
	s = tostring(s or ''):gsub('^%s+', ''):gsub('%s+$', ''):gsub('%s+', ' ')
	s = s:gsub('[^%w%-%._~ ]', function(c) return string.format('%%%02X', c:byte()) end)
	return (s:gsub(' ', '+'))
end

function sefon_utf8_char(cp)
	if cp < 0x80 then return string.char(cp)
	elseif cp < 0x800 then return string.char(0xC0 + math.floor(cp / 64), 0x80 + cp % 64)
	elseif cp < 0x10000 then return string.char(0xE0 + math.floor(cp / 4096), 0x80 + math.floor(cp / 64) % 64, 0x80 + cp % 64)
	end
	return '?'
end

function sefon_unescape(s)
	s = tostring(s or ''):gsub('<[^>]+>', '')
	s = s:gsub('&#x(%x+);', function(h) return sefon_utf8_char(tonumber(h, 16)) end)
	s = s:gsub('&#(%d+);', function(d) return sefon_utf8_char(tonumber(d)) end)
	s = s:gsub('&quot;', '"'):gsub('&#039;', "'"):gsub('&apos;', "'"):gsub('&lt;', '<'):gsub('&gt;', '>'):gsub('&nbsp;', ' '):gsub('&amp;', '&')
	return (s:gsub('^%s+', ''):gsub('%s+$', ''))
end

SEFON_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
function sefon_b64_decode(data)
	data = data:gsub('[^' .. SEFON_B64 .. '=]', '')
	local out, buffer, bits = {}, 0, 0
	for i = 1, #data do
		local c = data:sub(i, i)
		if c == '=' then break end
		local v = SEFON_B64:find(c, 1, true)
		if v then
			buffer = buffer * 64 + v - 1
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				out[#out + 1] = string.char(math.floor(buffer / (2 ^ bits)) % 256)
				buffer = buffer % (2 ^ bits)
			end
		end
	end
	return table.concat(out)
end

function sefon_reverse_segments(s, ch)
	local parts, start = {}, 1
	while true do
		local p = s:find(ch, start, true)
		if not p then parts[#parts + 1] = s:sub(start) break end
		parts[#parts + 1] = s:sub(start, p - 1)
		start = p + 1
	end
	local out = {}
	for i = #parts, 1, -1 do
		out[#out + 1] = parts[i]
		if i > 1 then out[#out + 1] = ch end
	end
	return table.concat(out)
end

function sefon_decode_url(encoded, key)
	if not encoded or not key then return nil end
	if encoded:sub(1, 1) == '#' then encoded = encoded:sub(2) end
	for i = #key, 1, -1 do encoded = sefon_reverse_segments(encoded, key:sub(i, i)) end
	local url = sefon_b64_decode(encoded)
	if url:match('^https?://') then return url end
end

function sefon_image_url(url)
	if type(url) ~= 'string' then return nil end
	url = sefon_unescape(url)
	if url == '' or url:find('^data:') then return nil end
	local low = url:lower()
	if low:find('logo', 1, true) or low:find('favicon', 1, true) or low:find('sprite', 1, true)
		or low:find('noimage', 1, true) or low:find('no%-image') or low:find('no%-cover') or low:find('placeholder', 1, true)
		or low:find('blank', 1, true) or low:find('%.svg') or low:find('%.gif') then
		return nil
	end
	if url:sub(1, 2) == '//' then return 'https:' .. url end
	if url:sub(1, 1) == '/' then return SEFON_URL .. url end
	if url:find('^https?://') then return url end
end

function sefon_page_cover(html)
	local function meta(prop)
		return html:match('<meta[^>]-property="' .. prop .. '"[^>]-content="([^"]+)"')
			or html:match('<meta[^>]-content="([^"]+)"[^>]-property="' .. prop .. '"')
			or html:match('<meta[^>]-name="' .. prop .. '"[^>]-content="([^"]+)"')
			or html:match('<meta[^>]-content="([^"]+)"[^>]-name="' .. prop .. '"')
	end
	local candidates = {
		meta('og:image'),
		meta('og:image:secure_url'),
		meta('twitter:image'),
		html:match('<link[^>]-rel="image_src"[^>]-href="([^"]+)"'),
		html:match('<[^>]-itemprop="image"[^>]-content="([^"]+)"'),
		html:match('<img[^>]-itemprop="image"[^>]-src="([^"]+)"'),
		html:match('<img[^>]-class="[^"]*artist[^"]*"[^>]-src="([^"]+)"'),
		html:match('<img[^>]-src="([^"]+)"[^>]-class="[^"]*artist[^"]*"'),
		html:match('<img[^>]-src="([^"]*/artist[^"]+)"'),
		html:match('<img[^>]-src="([^"]*cover[^"]+)"'),
		html:match('<img[^>]-src="([^"]*poster[^"]+)"')
	}
	for i = 1, 11 do
		local url = sefon_image_url(candidates[i])
		if url then return url end
	end
end

function sefon_block_thumb(block)
	local candidates = {
		block:match('<img[^>]-data%-src="([^"]+)"'),
		block:match('<img[^>]-data%-original="([^"]+)"'),
		block:match('<img[^>]-src="([^"]+)"'),
		block:match("background%-image:%s*url%(['\"]?([^'\")]+)")
	}
	for i = 1, 4 do
		local url = sefon_image_url(candidates[i])
		if url then return url end
	end
end

function sefon_block_seconds(block)
	local h, m, s = block:match('datetime="PT(%d+)H(%d+)M(%d+)S"')
	if h then return tonumber(h) * 3600 + tonumber(m) * 60 + tonumber(s) end
	m, s = block:match('datetime="PT(%d+)M(%d+)S"')
	local sec = m and (tonumber(m) * 60 + tonumber(s)) or 0
	if sec > 0 then return sec end
	m, s = block:match('itemprop="duration"[^>]*>%s*(%d+):(%d+)')
	if not m then m, s = block:match('class="value"[^>]*>%s*(%d+):(%d+)') end
	if m then return tonumber(m) * 60 + tonumber(s) end
	return 0
end

function sefon_parse(html, only_id)
	local starts, p = {}, 1
	while true do
		local a = html:find('<div[^>]-class="mp3[ "][^>]*>', p)
		if not a then break end
		starts[#starts + 1] = a
		p = a + 1
	end
	if #starts == 0 then
		p = 1
		while true do
			local a = html:find('data%-mp3_id="%d+"', p)
			if not a then break end
			starts[#starts + 1] = a
			p = a + 1
		end
	end
	local list, seen, stat = {}, {}, {blocks = #starts, no_id = 0, no_title = 0, no_url = 0, bad_decode = 0}
	for n = 1, #starts do
		local block = html:sub(starts[n], (starts[n + 1] or (#html + 1)) - 1)
		local id = block:match('data%-mp3_id="(%d+)"')
		local title = block:match('class="song_name"[^>]*>.-<a[^>]*>(.-)</a>') or block:match('class="song_name"[^>]*>(.-)</')
		local encoded = block:match('class="url_protected"[^>]-data%-url="([^"]+)"') or block:match('data%-url="([^"]+)"')
		local key = block:match('class="url_protected"[^>]-data%-key="([^"]+)"') or block:match('data%-key="([^"]+)"')
		local artist = block:match('class="artist_name"[^>]*>.-<a[^>]*>(.-)</a>') or block:match('class="artist_name"[^>]*>(.-)</')
		local artist_href = block:match('class="artist_name"[^>]*>.-<a[^>]-href="([^"]+)"')
		if not id then stat.no_id = stat.no_id + 1
		elseif not title then stat.no_title = stat.no_title + 1
		elseif not (encoded and key) then stat.no_url = stat.no_url + 1
		elseif not seen[id] and (not only_id or only_id == id) then
			local url = sefon_decode_url(encoded, key)
			if url then
				seen[id] = true
				artist = artist and sefon_unescape(artist) or ''
				local sec = sefon_block_seconds(block)
				list[#list + 1] = {
					link = 'sefon:' .. id,
					artist = artist ~= '' and u8:decode(artist) or 'Неизвестно',
					name = u8:decode(sefon_unescape(title)),
					time = string.format('%d:%02d', math.floor(sec / 60), sec % 60),
					image = '',
					thumb = sefon_block_thumb(block),
					artist_url = artist_href,
					url = url,
					url_time = os.time()
				}
			else
				stat.bad_decode = stat.bad_decode + 1
			end
		end
	end
	return list, stat
end

sefon_artist_cache = {}

function sefon_artist_photo(href, callback)
	if type(href) ~= 'string' then return callback(nil) end
	local id, slug = href:match('/artist/(%d+)%-([^/#?]+)')
	if not id then return callback(nil) end
	if sefon_artist_cache[id] ~= nil then return callback(sefon_artist_cache[id] or nil) end
	sefon_http(SEFON_URL .. '/artist/' .. id .. '-' .. slug .. '/', function(response)
		local photo
		if tonumber(response.status_code) == 200 then
			local html = tostring(response.text)
			photo = html:match('itemprop="image"[^>]-content="([^"]+)"')
				or html:match('content="([^"]+)"[^>]-itemprop="image"')
			photo = sefon_image_url(photo)
		end
		sefon_artist_cache[id] = photo or false
		callback(photo)
	end, function(err)
		debug_log('artist photo ! %s', tostring(err))
		callback(nil)
	end)
end

function sefon_page(id, callback)
	if not id or id == '' then return callback(nil) end
	local c = sefon_page_cache[id]
	if c and os.time() - c.time < 120 then return callback(c) end
	if sefon_page_wait[id] then
		table.insert(sefon_page_wait[id], callback)
		return
	end
	sefon_page_wait[id] = {callback}
	local function finish(res)
		local waiting = sefon_page_wait[id]
		sefon_page_wait[id] = nil
		if res then sefon_page_cache[id] = res end
		for i = 1, #waiting do waiting[i](res) end
	end
	sefon_http(SEFON_URL .. '/mp3/' .. id .. '/', function(response)
		local code = tonumber(response.status_code)
		local html = tostring(response.text)
		if code ~= 200 or #html < 500 then
			debug_log('sefon page %s code=%s len=%d', id, tostring(code), #html)
			return finish(nil)
		end
		local list = sefon_parse(html, id)
		local res = {time = os.time(), track = list[1], cover = sefon_page_cover(html)}
		debug_log('sefon page %s track=%s cover=%s', id, tostring(res.track ~= nil), tostring(res.cover))
		finish(res)
	end, function(err)
		debug_log('sefon page ! %s', tostring(err))
		finish(nil)
	end)
end

function sefon_show(list, search_token)
	if search_token ~= mus.search_token then return end
	if #list == 0 then
		list[1] = {link = '', artist = 'Ошибка404', name = '', time = '', image = ''}
	end
	tracks = list
	tracks = list
	sefon_fill_times(list)
end

function sefon_search(search_text)
	mus.search_token = (mus.search_token or 0) + 1
	local search_token = mus.search_token
	mus.sefon_state = 'search'
	sefon_http(SEFON_URL .. '/search/' .. sefon_urlencode(search_text) .. '/', function(response)
		local list, stat = {}, nil
		if tonumber(response.status_code) == 200 then
			list, stat = sefon_parse(tostring(response.text))
			debug_log('search sefon tracks=%d blocks=%d no_id=%d no_title=%d no_url=%d bad=%d', #list, stat.blocks, stat.no_id, stat.no_title, stat.no_url, stat.bad_decode)
		else
			debug_log('search sefon code=%s', tostring(response.status_code))
		end
		sefon_show(list, search_token)
	end, function(err)
		debug_log('search sefon ! %s', tostring(err))
		sefon_show({}, search_token)
	end)
end

function sefon_top()
	mus.search_token = (mus.search_token or 0) + 1
	local search_token = mus.search_token
	mus.sefon_state = 'loading'
	sefon_http(SEFON_URL .. '/', function(response)
		if search_token ~= mus.search_token then return end
		local list = tonumber(response.status_code) == 200 and sefon_parse(tostring(response.text)) or {}
		while #list > 20 do table.remove(list) end
		mus.sefon_state = #list > 0 and 'shown' or 'failed'
		if #list > 0 then
			tracks = list
			sefon_fill_times(list)
		end
		debug_log('sefon top tracks=%d', #list)
	end, function(err)
		if search_token ~= mus.search_token then return end
		mus.sefon_state = 'failed'
		debug_log('sefon top ! %s', tostring(err))
	end)
end

function sefon_resolve_link(link, callback, track)
	local id = link:match('^sefon:(%d+)')
	if not id then return callback(nil) end
	local saved = type(track) == 'table' and type(track.url) == 'string' and track.url ~= '' and track.url or nil
	if saved and os.time() - (tonumber(track.url_time) or 0) < 600 then
		debug_log('sefon resolve: свежая ссылка из списка')
		return callback(saved)
	end
	sefon_page(id, function(page)
		local fresh = page and page.track and page.track.url
		if fresh then
			if type(track) == 'table' then
				track.url, track.url_time = fresh, os.time()
			end
			debug_log('sefon resolve: ссылка со страницы песни')
			return callback(fresh)
		end
		debug_log('sefon resolve: страница не дала ссылку, saved=%s', tostring(saved ~= nil))
		callback(saved)
	end)
end

cover_trash = {}

function cover_release()
	local tex = play.image_label
	if tex and tex ~= image_no_label then
		table.insert(cover_trash, {tex = tex, time = os.clock()})
	end
	play.image_label = nil
end

function cover_flush()
	for i = #cover_trash, 1, -1 do
		if os.clock() - cover_trash[i].time > 3 then
			pcall(imgui.DestroyTexture, cover_trash[i].tex)
			table.remove(cover_trash, i)
		end
	end
end

function cover_drop_pending()
	local p = play.cover_pending
	if p and p.tex and p.tex ~= image_no_label then
		pcall(imgui.DestroyTexture, p.tex)
	end
	play.cover_pending = nil
end

function cover_try_commit()
	local p = play.cover_pending
	if p and p.token == mus.play_token and play.loaded_token == p.token then
		cover_release()
		play.image_label = p.tex
		play.status_image = p.num_i
		play.cover_pending = nil
	end
end

function music_cover(info, num_i)
	local token = mus.play_token
	local function apply(tex)
		if token ~= mus.play_token then
			if tex and tex ~= image_no_label then pcall(imgui.DestroyTexture, tex) end
			return
		end
		play.cover_pending = {tex = tex or image_no_label, num_i = num_i, token = token}
		cover_try_commit()
	end
	local function load_image(url)
		local path = getWorkingDirectory() .. '/State Helper/Изображения/Label_' .. tostring(token) .. '.png'
		debug_log('cover > %s', tostring(url))
		local function got(response)
			if token ~= mus.play_token then return end
			if tonumber(response.status_code) ~= 200 or not response.text or not sh_resource.valid(response.text, 'image') then
				return apply(nil)
			end
			local file = io.open(path, 'wb')
			if not file then return apply(nil) end
			file:write(response.text)
			file:close()
			local ok, tex = pcall(imgui.CreateTextureFromFile, path)
			os.remove(path)
			apply(ok and tex or nil)
		end
		local function fail(err)
			debug_log('cover ! %s', tostring(err))
			apply(nil)
		end
		if url:find('sefon', 1, true) then
			sefon_http(url, got, fail)
		else
			asyncHttpRequest('GET', url, {headers = {['User-Agent'] = SEFON_UA, ['Accept'] = 'image/*,*/*'}, timeout = 10}, got, fail)
		end
	end
	if type(info.link) == 'string' and info.link:sub(1, 6) == 'sefon:' then
		if type(info.image) == 'string' and info.image ~= '' then return load_image(info.image) end
		local function by_artist(href)
			sefon_artist_photo(href, function(photo)
				if token ~= mus.play_token then return end
				if photo then
					info.image = photo
					return load_image(photo)
				end
				apply(nil)
			end)
		end
		sefon_page(info.link:match('^sefon:(%d+)'), function(page)
			if token ~= mus.play_token then return end
			if page and page.cover then
				info.image = page.cover
				return load_image(page.cover)
			end
			if type(info.thumb) == 'string' and info.thumb ~= '' then return load_image(info.thumb) end
			by_artist((page and page.track and page.track.artist_url) or info.artist_url)
		end)
		return
	end
	if info.image == '' or info.image:find('no%-cover%-150') then
		return apply(nil)
	end
	load_image(info.image)
end



function music_platform(source)
	mus.search_token = (mus.search_token or 0) + 1
	if source ~= '' and source ~= setting.tracks_owner then
		setting.tracks_store[setting.tracks_owner] = setting.tracks
		setting.tracks = setting.tracks_store[source] or {}
		setting.tracks_store[source] = nil
		setting.tracks_owner = source
	end
	if source ~= setting.music_source then
		set_song_status('STOP')
	end
	setting.music_source = source
	mus.search, mus.add_search, mus.sefon_state = '', '', nil
	tracks = {}
	playlist_view = nil
	tab_music = 1
	save()
end

function music_gate()
	local source = setting.music_source
	if source == 'sefon' or source == 'hitmoz' or (source == 'yandex' and setting.ym_token ~= '') then return false end
	local gray = imgui.ImVec4(0.50, 0.50, 0.50, 1.00)
	local function center(x, y, text, font_text)
		imgui.PushFont(font_text)
		local calc = imgui.CalcTextSize(u8(text))
		imgui.PopFont()
		gui.Text(x - calc.x / 2, y, text, font_text)
	end
	local function logo(x, y, name)
		local path = getWorkingDirectory() .. '/State Helper/Изображения/' .. name .. '.png'
		if not image_music[name] and doesFileExist(path) then
			image_music[name] = imgui.CreateTextureFromFile(path)
		end
		if image_music[name] then
			imgui.SetCursorPos(imgui.ImVec2(x - 44, y - 44))
