function find_track_yandex(search_text, page)
	mus.search_token = (mus.search_token or 0) + 1
	local search_token = mus.search_token
	ym_request(YM_API .. '/search?text=' .. urlencode(search_text) .. '&type=track&page=0', function(response)
		if search_token ~= mus.search_token then return end
		local ok, data = pcall(json.decode, response.text)
		local results = ok and data and data.result and data.result.tracks and data.result.tracks.results
		debug_log('search yandex q=%s', tostring(search_text))
		local track_list = {}
		if results then
			for i = 1, #results do
				track_list[i] = ym_track_item(results[i])
			end
		else
			track_list[1] = {link = '', artist = 'Ошибка404', name = '', time = '', image = ''}
		end
		tracks = track_list
		debug_log('search yandex tracks=%d', #track_list)
	end, function(err)
		print(err)
		if tostring(err):find('401', 1, true) then
			setting.ym_token = ''
			setting.ym_uid = ''
			ym_playlists = nil
			save()
			sampAddChatMessage('[SH] {FFFFFF}Токен Яндекс Музыки недействителен, войдите заново.', 0xFF5345)
		else
			sampAddChatMessage('{FF6347}[SH] {FFFFFF}Ошибка поиска Яндекс Музыки.', -1)
		end
	end)
end

function ym_resolve_link(link, callback)
	debug_log('ym resolve %s', tostring(link))
	local track_id = link:match('^yandex:(%d+):')
	if not track_id then
		callback(nil)
		return
	end
	ym_request(YM_API .. '/tracks/' .. track_id .. '/download-info', function(response)
		local ok, data = pcall(json.decode, response.text)
		local infos = ok and data and data.result
		local best
		if infos then
			for i = 1, #infos do
				local info = infos[i]
				if info.codec == 'mp3' and not info.preview then
					if not best or (tonumber(info.bitrateInKbps) or 0) > (tonumber(best.bitrateInKbps) or 0) then
						best = info
					end
				end
			end
			best = best or infos[1]
		end
		if not best or not best.downloadInfoUrl then
			debug_log('ym resolve no-info')
			callback(nil)
			return
		end
		ym_request(best.downloadInfoUrl, function(xml_response)
			local xml = xml_response.text
			local host = xml:match('<host>(.-)</host>')
			local path = xml:match('<path>(.-)</path>')
			local ts = xml:match('<ts>(.-)</ts>')
			local s = xml:match('<s>(.-)</s>')
			if not (host and path and ts and s) then
				debug_log('ym resolve bad-xml')
				callback(nil)
				return
			end
			local sign = md5.sumhexa('XGRlBW9FXlekgbPrRHuSiA' .. path:sub(2) .. s)
			debug_log('ym resolve ok')
			callback('https://' .. host .. '/get-mp3/' .. sign .. '/' .. ts .. path)
		end, function(err)
			print(err)
			callback(nil)
		end)
	end, function(err)
		print(err)
		callback(nil)
	end)
end

function play_song(table_track, loop_track, num_i, song_tab, stream_url)
	debug_log('play_song tab=%s i=%s link=%s resolved=%s', tostring(song_tab), tostring(num_i), tostring(type(table_track) == 'table' and table_track.link), tostring(stream_url ~= nil))
	if song_tab == 'PLAYLIST' and playlist_playing == ym_wave and num_i >= #ym_wave - 1 then
		ym_wave_more()
	end
	if not stream_url then
		mus.play_token = mus.play_token + 1
		cover_drop_pending()
	end
	local play_token = mus.play_token
	if not stream_url and song_tab ~= 'RECORD' and song_tab ~= 'RADIO' then
		music_cover(table_track, num_i)
	end
	local resolver = table_track.link and (table_track.link:sub(1, 7) == 'yandex:' and ym_resolve_link or table_track.link:sub(1, 6) == 'sefon:' and sefon_resolve_link)
	if not stream_url and resolver then
		if song_tab ~= 'RECORD' and song_tab ~= 'RADIO' then
			play.switching = true
			if get_status_potok_song() ~= 0 then
				bass.BASS_ChannelStop(play.stream)
			end
			resolver(table_track.link, function(url)
				if play_token ~= mus.play_token then return end
				if url then
					play_song(table_track, loop_track, num_i, song_tab, url)
				else
					play.switching = false
					play.status = 'STOP'
					sampAddChatMessage('[SH] {FFFFFF}Не удалось получить трек.', 0xFF5345)
				end
			end, table_track)
		end
		return
	end
	if song_tab ~= 'RECORD' and song_tab ~= 'RADIO' then
		local cp = play.cover_pending
		local cover_ready = cp and cp.token == play_token
		if not cover_ready and play.cover_wait_token ~= play_token then
			play.cover_wait_token = play_token
			play.switching = true
			local go_url = stream_url or table_track.link
			lua_thread.create(function()
				local t0 = os.clock()
				while play_token == mus.play_token and os.clock() - t0 < 3 do
					local p = play.cover_pending
					if p and p.token == play_token then break end
					wait(0)
				end
				if play_token ~= mus.play_token then return end
				play_song(table_track, loop_track, num_i, song_tab, go_url)
			end)
			return
		end
		play.i = num_i
		play.info = table_track
		play.time = 0
		play.seek_base = 0
		play.status = 'PLAY'
		play.switching = false
		play.len_time = get_track_length(play.info.time)
		play.tab = song_tab
		
		sh_audit.audio_release()
		
		local link = stream_url or play.info.link
				debug_log('play source=%s', tostring(play.info.link and play.info.link:match('^(%w+):') or 'file'))
		local flag = loop_track and BASS_SAMPLE_LOOP or BASS_STREAM_AUTOFREE
		if not link:find('^http') then
			flag = bit.bor(flag, 0x20000)
		end
		if link:find('^http') then
			local stream_link = link
			if link:find('hitmoz.org', 1, true) then
				stream_link = link .. '\r\nUser-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36\r\nAccept-Language: ru-RU,ru;q=0.9\r\nReferer: https://ru.hitmoz.org/\r\n'
			end
			play.stream = bass.BASS_StreamCreateURL(stream_link, 0, flag, nil, nil)
			if (not play.stream or play.stream == 0) and tostring(play.info.link):sub(1, 6) == 'sefon:' then
				play.stream = bass.BASS_StreamCreateURL(link .. '\r\nReferer: https://sefon.pro/\r\n', 0, flag, nil, nil)
			end

		else
			play.stream = bass.BASS_StreamCreateFile(0, ffi.cast('const char*', link), 0, 0, flag)
		end
		if not play.stream or play.stream == 0 then
			play.status = 'STOP'
			play.switching = false
			sampAddChatMessage('[SH] {FFFFFF}Не удалось открыть поток трека.', 0xFF5345)
			return
		end
		bass.BASS_ChannelPlay(play.stream, false)
		debug_log('bass stream=%s act=%s err=%s', tostring(play.stream), tostring(get_status_potok_song()), tostring(bass.BASS_ErrorGetCode()))
		bass.BASS_ChannelSetAttribute(play.stream, BASS_ATTRIB_VOL, play.volume)
		if not play.len_time or play.len_time <= 0 or play.len_time == 999 then
			local okl, sec = pcall(function()
				return tonumber(bass.BASS_ChannelBytes2Seconds(play.stream, bass.BASS_ChannelGetLength(play.stream, BASS_POS_BYTE)))
			end)
			debug_log('len из потока ok=%s sec=%s', tostring(okl), tostring(sec))
			if okl and sec and sec > 0 and sec < 36000 then
				play.len_time = math.floor(sec + 0.5)
				play.info.time = string.format('%d:%02d', math.floor(play.len_time / 60), play.len_time % 60)
			end
		end
		play.loaded_token = play_token
		cover_try_commit()
	else
		play.i = num_i
		play.info = {}
		play.time = 0
		play.status = 'PLAY'
		play.len_time = 0
		play.tab = song_tab
		
		sh_audit.audio_release()
		
		play.stream = bass.BASS_StreamCreateURL(table_track, 0, BASS_SAMPLE_LOOP, nil, nil)
		if not play.stream or play.stream == 0 then
			play.status = 'STOP'
			sampAddChatMessage('[SH] {FFFFFF}Не удалось открыть поток радио.', 0xFF5345)
			return
		end
		bass.BASS_ChannelPlay(play.stream, false)
		bass.BASS_ChannelSetAttribute(play.stream, BASS_ATTRIB_VOL, play.volume)
		
		play.image_label = image_no_label
	end
end

function get_status_potok_song() --> Получить статус потока
	if play.stream ~= nil then
		return tonumber(bass.BASS_ChannelIsActive(play.stream))
	else
		return 0
	end
	
	--[[
	[0] - Ничего не воспроизводится
	[1] - Играет
	[2] - Блок
	[3] - Пауза
	--]]
end

function rewind_song(time_position)
	if play.status ~= 'NULL' and get_status_potok_song() ~= 0 then
		local length = tonumber((tostring(bass.BASS_ChannelGetLength(play.stream, BASS_POS_BYTE)):gsub('%D', '')))
		if not length or length <= 0 or length > 1e15 or not play.len_time or play.len_time <= 0 then
			debug_log('seek: длина потока неизвестна (%s)', tostring(length))
			return
		end
		local pos = math.floor(math.max(0, math.min((length / play.len_time) * time_position - 100, length - 1)))
		local ok = bass.BASS_ChannelSetPosition(play.stream, pos, BASS_POS_BYTE)
		debug_log('seek t=%s len=%s pos=%s ok=%s err=%s', tostring(time_position), tostring(length), tostring(pos), tostring(ok), tostring(bass.BASS_ErrorGetCode()))
	end
end

function time_song_position(song_length)
	local posByte = bass.BASS_ChannelGetPosition(play.stream, BASS_POS_BYTE)
	posByte = tostring(posByte)
	posByte = posByte:gsub('(%D+)', '')
	posByte = tonumber(posByte)
	local length = bass.BASS_ChannelGetLength(play.stream, BASS_POS_BYTE)
	length = tostring(length)
	length = length:gsub('(%D+)', '')
	length = tonumber(length)
	local postrack = posByte / (length / song_length)
	
	return postrack
end

function get_track_length(track_length)
	local minutes, seconds = track_length:match('^(%d+):(%d+)$')
	
	if minutes and seconds then
		minutes = tonumber(minutes)
		seconds = tonumber(seconds)
		
		return minutes * 60 + seconds
	else
		return 999
	end
end

function set_song_status(action_music)
	if action_music == 'STOP' then
		mus.play_token = mus.play_token + 1
		cover_drop_pending()
		cover_release()
		sh_audit.audio_release()
		play = {
			i = 0,
			info = {},
			len_time = 0,
			pos_time = 0,
			status = 'NULL',
			stream = nil,
			volume = play.volume,
			status_image = 0,
			image_label = nil,
			tab = '',
			switching = false,
			repeat_track = play.repeat_track
		}
		windows.player[0] = false
		return
	end
	if play.stream ~= nil and get_status_potok_song() ~= 0 then
		debug_log('song_status %s status=%s', tostring(action_music), tostring(play.status))
		if action_music == 'PLAY_OR_PAUSE' then
			if play.status == 'PLAY' then
				play.status = 'PAUSE'
				bass.BASS_ChannelPause(play.stream)
			elseif play.status == 'PAUSE' then
				play.status = 'PLAY'
				bass.BASS_ChannelPlay(play.stream, false)
			end
		elseif action_music == 'PLAY' then
			play.status = 'PAUSE'
			bass.BASS_ChannelPause(play.stream)
		end
	end
end

local last_windows_notification = 0
local function windows_notification_command()
	local image = (dir .. '/State Helper/Изображения/notification.png'):gsub("'", "''")
	local script = [=[$ProgressPreference='SilentlyContinue';[Windows.UI.Notifications.ToastNotificationManager,Windows.UI.Notifications,ContentType=WindowsRuntime]>$null;[Windows.Data.Xml.Dom.XmlDocument,Windows.Data.Xml.Dom.XmlDocument,ContentType=WindowsRuntime]>$null;$img=([System.Uri]::new('__SH_NOTIFICATION_PATH__')).AbsoluteUri;$xml='<toast duration="short"><visual><binding template="ToastGeneric"><text>Новое событие</text><text>В StateHelper сработало звуковое уведомление. Вернитесь в игру, чтобы проверить.</text><image placement="appLogoOverride" hint-crop="circle" src="'+$img+'"/></binding></visual><audio silent="true"/></toast>';$doc=New-Object Windows.Data.Xml.Dom.XmlDocument;$doc.LoadXml($xml);$toast=New-Object Windows.UI.Notifications.ToastNotification $doc;[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier('com.statehelper.installer').Show($toast)]=]
	script = script:gsub('__SH_NOTIFICATION_PATH__', function() return image end)
	local converter = iconv.new('UTF-16LE', 'CP1251')
	local data = converter:iconv(script)
	if not data then return nil end
	local alphabet, result = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', {}
	for i = 1, #data, 3 do
		local a,b,c = data:byte(i,i+2); local n = a * 65536 + (b or 0) * 256 + (c or 0)
		local function char(shift) local index = math.floor(n / 2^shift) % 64; return alphabet:sub(index+1,index+1) end
		result[#result+1] = char(18)..char(12)..(b and char(6) or '=')..(c and char(0) or '=')
	end
	return '-NoProfile -WindowStyle Hidden -EncodedCommand ' .. table.concat(result)
end

function play_beep()
	local now = os.time()
	if not isGameWindowForeground() and now - last_windows_notification >= 5 then
		last_windows_notification = now
		local command = windows_notification_command()
		if command then shell32.ShellExecuteA(nil, 'open', 'powershell.exe', command, nil, 0) end
	end
	local path = getWorkingDirectory() .. '/State Helper/Звуки/beep.wav'
	if not doesFileExist(path) then
		playMissionPassedTune(1)
		return
	end
	if bass.BASS_GetDevice() == -1 then
		bass.BASS_Init(-1, 44100, 0, nil, nil)
	end
	local stream = bass.BASS_StreamCreateFile(0, ffi.cast('const char*', path), 0, 0, BASS_STREAM_AUTOFREE)
	if not stream or stream == 0 then
		playMissionPassedTune(1)
		return
	end
	bass.BASS_ChannelSetAttribute(stream, BASS_ATTRIB_VOL, 0.6)
	bass.BASS_ChannelPlay(stream, false)
end

function volume_song(volume_music)
	if play.stream ~= nil and get_status_potok_song() ~= 0 then
		bass.BASS_ChannelSetAttribute(play.stream, BASS_ATTRIB_VOL, volume_music)
	end
end

function back_track()
	if play.tab == 'PLAYLIST' and playlist_playing and #playlist_playing > 0 then
		local i = play.i
		if i > 1 then
			play_song(playlist_playing[i - 1], play.repeat_track == 2, i - 1, 'PLAYLIST')
		elseif play.repeat_track == 1 then
			play_song(playlist_playing[#playlist_playing], play.repeat_track == 2, #playlist_playing, 'PLAYLIST')
		end
		return
	end
	if play.tab == 'SEARCH' and #tracks > 0 then
		for i = 1, #tracks do
			if tracks[i].link == play.info.link then
				if i ~= 1 then
					play_song(tracks[i - 1], play.repeat_track == 2, i - 1, 'SEARCH')
				elseif play.repeat_track == 1 then
					play_song(tracks[#tracks], play.repeat_track == 2, #tracks, 'SEARCH')
				end
				break
			end
		end
	elseif play.tab == 'ADD' and #setting.tracks > 0 then
		for i = 1, #setting.tracks do
			if setting.tracks[i].link == play.info.link then
				if i ~= 1 then
					play_song(setting.tracks[i - 1], play.repeat_track == 2, i - 1, 'ADD')
				elseif play.repeat_track == 1 then
					play_song(setting.tracks[#setting.tracks], play.repeat_track == 2, #setting.tracks, 'ADD')
				end
				break
			end
		end
	end
end

function next_track(repeat_param)
	if play.tab == 'PLAYLIST' and playlist_playing and #playlist_playing > 0 then
		local i = play.i
		if i < #playlist_playing then
			play_song(playlist_playing[i + 1], play.repeat_track == 2, i + 1, 'PLAYLIST')
			return true
		elseif repeat_param then
			play_song(playlist_playing[1], play.repeat_track == 2, 1, 'PLAYLIST')
			return true
		end
		return false
	end
	if play.tab == 'SEARCH' and #tracks > 0 then
		for i = 1, #tracks do
			if tracks[i].link == play.info.link then
				if i ~= #tracks then
					play_song(tracks[i + 1], play.repeat_track == 2, i + 1, 'SEARCH')
					return true
				elseif repeat_param then
					play_song(tracks[1], play.repeat_track == 2, 1, 'SEARCH')
					return true
				end
			end
		end
	elseif play.tab == 'ADD' and #setting.tracks > 0 then
		for i = 1, #setting.tracks do
			if setting.tracks[i].link == play.info.link then
				if i ~= #setting.tracks then
					play_song(setting.tracks[i + 1], play.repeat_track == 2, i + 1, 'ADD')
					return true
				elseif repeat_param then
					play_song(setting.tracks[1], play.repeat_track == 2, 1, 'ADD')
					return true
				end
			end
		end
	end
	return false
end

function control_song_when_finished()
	local status = get_status_potok_song()
	if status == 3 and play.status == 'PLAY' then
		bass.BASS_ChannelPlay(play.stream, false)
	elseif status == 0 and play.status == 'PLAY' and not play.switching then
		play.switching = true
		if play.repeat_track == 2 then
			play_song(play.info, play.repeat_track == 2, play.i, play.tab)
		elseif not next_track(play.repeat_track == 1) then
			play.switching = false
			if play.tab ~= 'RECORD' and play.tab ~= 'RADIO' then
				play.status = 'STOP'
			end
		end
	end
end

