local hall = {}
local settings_reveal = {}
function gui.RevealProgress(id, enabled)
	local progress = settings_reveal[id]
	if progress == nil then progress = enabled and 1 or 0 end
	progress = math.max(0, math.min(1, progress + (enabled and 1 or -1) * anim * 6))
	settings_reveal[id] = progress
	return progress
end

function gui.BeginReveal(progress, top, height, width)
	if progress <= 0 then return false end
	-- Keep the original window/IDs so keybinding popups and drag scrolling continue to work.
	imgui.SetCursorPos(imgui.ImVec2(0, 0))
	local origin = imgui.GetCursorScreenPos()
	imgui.PushClipRect(imgui.ImVec2(origin.x, origin.y + top), imgui.ImVec2(origin.x + (width or 618), origin.y + top + height * progress), true)
	imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, imgui.GetStyle().Alpha * progress)
	return true
end

function gui.EndReveal()
	imgui.PopStyleVar(1)
	imgui.PopClipRect()
end

