local action_move = {positions = {}, progress = 1}
function gui.ActionMoveFrame(actions)
	if action_move.actions ~= actions then
		action_move = {actions = actions, positions = {}, progress = 1}
	end
	action_move.progress = math.min(1, action_move.progress + anim / 0.22)
	if action_move.progress == 1 then action_move.from = nil end
end

function gui.StartActionMove()
	action_move.from = {}
	for action, y in pairs(action_move.positions) do action_move.from[action] = y end
	action_move.progress = 0
end

function gui.ActionMoveOffset(action, target)
	local from = action_move.from and action_move.from[action]
	local offset = from and (from - target) * (1 - action_move.progress) ^ 3 or 0
	action_move.positions[action] = target + offset
	return offset
end

function hall.cmd()
	local to_delete = nil
	local color_ItemActive = imgui.ImVec4(0.20, 0.20, 0.20, 1.00)
