				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.40, 0.40, 0.40, 1.00))
			else
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 1.00))
			end
			gui.Text(375, 165, 'Пусто', bold_font[3])
			imgui.PopStyleColor(1)
		else
			local function format_date_time(day, month, year, hour, minute)
				day = tonumber(day)
				month = tonumber(month)
				year = tonumber(year)
				hour = tonumber(hour)
				minute = tonumber(minute)
				local months = {
					'Января', 'Февраля', 'Марта', 'Апреля', 'Мая', 'Июня',
					'Июля', 'Августа', 'Сентября', 'Октября', 'Ноября', 'Декабря'
				}
				
				return string.format('%d %s %d г. в %02d:%02d', day, months[month], year, hour, minute)
			end
			
			local function get_repeats(repeats)
				local daysOfWeek = {'ПН', 'ВТ', 'СР', 'ЧТ', 'ПТ', 'СБ', 'ВС'}
				local result = {}
				
				for i, isRepeat in ipairs(repeats) do
					if isRepeat then
						table.insert(result, daysOfWeek[i])
					end
				end
				
				if #result == 0 then
					return 'Без повторений'
				elseif #result == 7 then
					return 'Повтор каждый день'
				elseif #result == 5 and table.concat(result, ', ') == 'ПН, ВТ, СР, ЧТ, ПТ' then
					return 'Повтор в будние дни'
				else
					return 'Повтор в ' .. table.concat(result, ', ')
				end
			end
			
			if reminder_move ~= 0 then
				reminder_anim_index = reminder_move
				reminder_anim = reminder_anim + (anim * 6)
				if reminder_anim > 1 then reminder_anim = 1 end
			elseif reminder_anim > 0 then
				reminder_anim = reminder_anim - (anim * 6)
				if reminder_anim < 0 then reminder_anim = 0 end
			end
			for i = 1, #setting.reminder do
				local pos_y_pl = (i - 1) * 85
				local rep_rem = get_repeats(setting.reminder[i].repeats)
				local wrapped_text, newline_count = wrapText(u8:decode(setting.reminder[i].text), 95, 95)
				local opened = reminder_move == i
				local sliding = reminder_anim_index == i and reminder_anim > 0
				local card_w = sliding and (808 - (88 * reminder_anim)) or 808
				imgui.SetCursorPos(imgui.ImVec2(16, 16 + pos_y_pl))
				if imgui.InvisibleButton(u8'##Напоминание' .. i, imgui.ImVec2(card_w, 75)) then
					reminder_move = opened and 0 or i
				end
				local card_hovered = imgui.IsItemHovered()
				if setting.cl == 'Black' then
					if imgui.IsItemActive() or opened or sliding then
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, imgui.ImVec4(0.12, 0.12, 0.12, 1.00), 7, 15)
					elseif card_hovered then
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, imgui.ImVec4(0.15, 0.15, 0.15, 1.00), 7, 15)
					else
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, cl.tab, 7, 15)
					end
				else
					if imgui.IsItemActive() or opened or sliding then
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, imgui.ImVec4(0.88, 0.86, 0.84, 1.00), 7, 15)
					elseif card_hovered then
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, imgui.ImVec4(0.92, 0.90, 0.88, 1.00), 7, 15)
					else
						gui.Draw({16, 16 + pos_y_pl}, {808, 75}, cl.tab, 7, 15)
					end
				end
				gui.DrawLine({16, 53 + pos_y_pl}, {824, 53 + pos_y_pl}, cl.line)
				if setting.reminder[i].text ~= '' then
					gui.Text(26, 26 + pos_y_pl,wrapped_text, font[3])
				else
					gui.Text(26, 26 + pos_y_pl, 'Без названия', font[3])
				end
				gui.Draw({26, 63 + pos_y_pl}, {6, 19}, imgui.ImVec4(1.00, 0.58, 0.00, 1.00))
				gui.Text(40, 64 + pos_y_pl, format_date_time(setting.reminder[i].day, setting.reminder[i].mon, setting.reminder[i].year, setting.reminder[i].hour, setting.reminder[i].min), font[3])
				if not sliding then
					imgui.PushFont(font[3])
					local calc_rep = imgui.CalcTextSize(u8(rep_rem))
					imgui.PopFont()
					gui.Text(814 - calc_rep.x, 64 + pos_y_pl, rep_rem, font[3])
					if setting.reminder[i].sound then
						imgui.PushFont(fa_font[3])
						local calc_vol = imgui.CalcTextSize(fa.VOLUME_HIGH)
						imgui.PopFont()
						gui.FaText(814 - calc_vol.x, 26 + pos_y_pl, fa.VOLUME_HIGH, fa_font[3], imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
					end
				else
					local anim_w = 44 * reminder_anim
					local edit_x = 824 - (88 * reminder_anim)
					local del_x = 824 - (44 * reminder_anim)
					imgui.SetCursorPos(imgui.ImVec2(edit_x, 16 + pos_y_pl))
					if imgui.InvisibleButton(u8'##Редактировать напоминание' .. i, imgui.ImVec2(anim_w, 75)) then
						local src = setting.reminder[i]
						new_reminder = true
						edit_rem = i
						reminder_move = 0
						reminder_anim = 0
						new_rem = {
							text = src.text,
							year = src.year,
							mon = src.mon,
							day = src.day,
							hour = src.hour,
							min = src.min,
							repeats = {},
							sound = src.sound,
							last_triggered_day = src.last_triggered_day
						}
						for k = 1, 7 do
							new_rem.repeats[k] = src.repeats[k] and true or false
						end
						last_child_y = {tonumber(src.hour) * 60, tonumber(src.min) * 60}
						start_child = {true, true}
					end
					local edit_hovered = imgui.IsItemHovered()
					gui.Draw({edit_x, 16 + pos_y_pl}, {anim_w, 75}, edit_hovered and imgui.ImVec4(1.00, 0.70, 0.15, 1.00) or imgui.ImVec4(0.95, 0.63, 0.05, 1.00), 0, 0)
					gui.FaText(edit_x + (anim_w / 2) - 11, 42 + pos_y_pl, fa.PEN_RULER, fa_font[3], imgui.ImVec4(1.00, 1.00, 1.00, reminder_anim))
					
					imgui.SetCursorPos(imgui.ImVec2(del_x, 16 + pos_y_pl))
					if imgui.InvisibleButton(u8'##Удалить напоминание' .. i, imgui.ImVec2(anim_w, 75)) then
						del_rem = i
						reminder_move = 0
						reminder_anim = 0
						imgui.OpenPopup(u8'Подтверждение удаления напоминания')
					end
					local del_hovered = imgui.IsItemHovered()
					gui.Draw({del_x, 16 + pos_y_pl}, {anim_w, 75}, del_hovered and imgui.ImVec4(1.00, 0.38, 0.35, 1.00) or imgui.ImVec4(0.94, 0.29, 0.27, 1.00), 7, 10)
					gui.FaText(del_x + (anim_w / 2) - 11, 42 + pos_y_pl, fa.TRASH, fa_font[3], imgui.ImVec4(1.00, 1.00, 1.00, reminder_anim))
				end
			end
			
			if imgui.BeginPopupModal(u8'Подтверждение удаления напоминания', null, imgui.WindowFlags.AlwaysAutoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoTitleBar) then
				if imgui.IsKeyPressed(27, false) then imgui.CloseCurrentPopup() end
				imgui.SetCursorPos(imgui.ImVec2(10, 10))
				if imgui.InvisibleButton(u8'##Закрыть окно удаления напоминания', imgui.ImVec2(16, 16)) then
					imgui.CloseCurrentPopup()
				end
				imgui.SetCursorPos(imgui.ImVec2(16, 16))
				local p = imgui.GetCursorScreenPos()
				if imgui.IsItemHovered() then
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.32, 0.38 ,1.00)), 60)
				else
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.42, 0.38 ,1.00)), 60)
				end
				gui.DrawLine({10, 31}, {346, 31}, cl.line)
				imgui.PushFont(bold_font[1])
				local calc_confirm = imgui.CalcTextSize(u8('Подтверждение'))
				imgui.PopFont()
				gui.Text(136 - (calc_confirm.x / 2), (31 - calc_confirm.y) / 2, 'Подтверждение', bold_font[1])
				imgui.SetCursorPos(imgui.ImVec2(6, 40))
				imgui.BeginChild(u8'Подтверждение удаления напоминания ', imgui.ImVec2(261, 90), false, imgui.WindowFlags.NoScrollbar)
				
				gui.Text(25, 5, 'Вы уверены, что хотите удалить \n				 напоминание?', font[3])
				if gui.Button(u8'Удалить', {24, 50}, {90, 27}) then
					table.remove(setting.reminder, del_rem)
					imgui.CloseCurrentPopup()
					save()
				end
				if gui.Button(u8'Отмена', {141, 50}, {90, 27}) then
					imgui.CloseCurrentPopup()
				end
				imgui.EndChild()
				imgui.EndPopup()
			end
			
			imgui.Dummy(imgui.ImVec2(0, 23))
		end
	end
	
	imgui.EndChild()
end


function hall.stat()
	local color_ItemActive = imgui.ImVec4(0.20, 0.20, 0.20, 1.00)
	local color_ItemHovered = imgui.ImVec4(0.24, 0.24, 0.24, 1.00)
	if setting.cl == 'White' then
		color_ItemActive = imgui.ImVec4(0.78, 0.78, 0.78, 1.00)
		color_ItemHovered = imgui.ImVec4(0.83, 0.83, 0.83, 1.00)
	end
	
	local function format_time(seconds)
		local days = math.floor(seconds / 86400)
		local hours = math.floor((seconds % 86400) / 3600)
		local minutes = math.floor((seconds % 3600) / 60)
		local secs = seconds % 60

		if days > 0 then
			return string.format('%02d д. %02d ч. %02d мин. %02d сек.', days, hours, minutes, secs)
		else
			return string.format('%02d ч. %02d мин. %02d сек.', hours, minutes, secs)
		end
	end
	
	local function is_yesterday(date_string)
		local day, month, year = date_string:match('(%d%d)%.(%d%d)%.(%d%d)')
		
		if not (day and month and year) then
			error('Неправильный формат даты. Ожидается формат "DD.MM.YY".')
		end
		
		day, month, year = tonumber(day), tonumber(month), tonumber(year)
		
		year = year + 2000
		
		local current_time = os.time()
		local current_date = os.date("*t", current_time)
		local input_date_time = os.time({year = year, month = month, day = day, hour = 0})
		local yesterday_time = os.time({
			year = current_date.year,
			month = current_date.month,
			day = current_date.day - 1,
			hour = 0
		})
		
		return input_date_time == yesterday_time
	end
	
	imgui.SetCursorPos(imgui.ImVec2(4, 39))
	imgui.BeginChild(u8'Статистика онлайна', imgui.ImVec2(840, 369), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller(u8'Статистика онлайна', img_step[1][0], img_duration[1][0], imgui.HoveredFlags.AllowWhenBlockedByActiveItem)
	
	gui.Draw({16, 16}, {808, 118}, cl.tab, 7, 15)
	gui.DrawLine({420, 66}, {420, 134}, cl.line)
	gui.Text(26, 26, tostring(setting.stat.date_week[1] .. ', сегодня'), bold_font[1])
	imgui.PushFont(bold_font[1])
	local calc_date = imgui.CalcTextSize(tostring(setting.stat.date_week[1]) .. u8', сегодня')
	imgui.PopFont()
	gui.Draw({24, 47}, {calc_date.x + 4, 5}, imgui.ImVec4(1.00, 0.58, 0.00, 1.00), 7, 15)
	gui.Text(26, 66, 'Чистый онлайн за день:', font[3])
	gui.Text(26, 86, 'АФК за день:', font[3])
	gui.Text(26, 106, 'Всего за день:', font[3])
	gui.Text(431, 66, 'Чистый онлайн за сессию:', font[3])
	gui.Text(431, 86, 'АФК за сессию:', font[3])
	gui.Text(431, 106, 'Всего за сессию:', font[3])
	
	imgui.PushFont(font[3])
	imgui.SetCursorPos(imgui.ImVec2(186, 66))
	imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.cl[1]))
	imgui.SetCursorPos(imgui.ImVec2(116, 86))
	imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.afk[1]))
	imgui.SetCursorPos(imgui.ImVec2(125, 106))
	imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.day[1]))
	
	imgui.SetCursorPos(imgui.ImVec2(609, 66))
	imgui.TextColoredRGB('{279643}' .. format_time(stat_ses.cl))
	imgui.SetCursorPos(imgui.ImVec2(539, 86))
	imgui.TextColoredRGB('{279643}' .. format_time(stat_ses.afk))
	imgui.SetCursorPos(imgui.ImVec2(546, 106))
	imgui.TextColoredRGB('{279643}' .. format_time(stat_ses.all))
	imgui.PopFont()
	
	local y_pl = 0
	local online_week = setting.stat.cl[1]
	for i = 2, 10 do
		if setting.stat.date_week[i] ~= '' then
			local form_date = setting.stat.date_week[i]
			
			if is_yesterday(setting.stat.date_week[i]) then
				form_date = form_date .. u8', вчера'
			end
			imgui.PushFont(bold_font[1])
			local calc_dat = imgui.CalcTextSize(form_date)
			imgui.PopFont()
			gui.Draw({16, 142 + y_pl}, {808, 118}, cl.tab, 7, 15)
			gui.Draw({24, 173 + y_pl}, {calc_dat.x + 4, 5}, imgui.ImVec4(1.00, 0.58, 0.00, 1.00), 7, 15)
			gui.Text(26, 152 + y_pl, u8:decode(form_date), bold_font[1])
			gui.Text(26, 192 + y_pl, 'Чистый онлайн за день:', font[3])
			gui.Text(26, 212 + y_pl, 'АФК за день:', font[3])
			gui.Text(26, 232 + y_pl, 'Всего за день:', font[3])
			imgui.PushFont(font[3])
			imgui.SetCursorPos(imgui.ImVec2(186, 192 + y_pl))
			imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.cl[i]))
			imgui.SetCursorPos(imgui.ImVec2(116, 212 + y_pl))
			imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.afk[i]))
			imgui.SetCursorPos(imgui.ImVec2(125, 232 + y_pl))
			imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.day[i]))
			imgui.PopFont()
			
			online_week = online_week + setting.stat.cl[i]
			y_pl = y_pl + 128
		end
	end
	gui.Draw({16, 142 + y_pl}, {808, 57}, cl.tab, 7, 15)
	gui.Text(26, 152 + y_pl, 'Чистый онлайн за 10 дней:', font[3])
	gui.Text(26, 172 + y_pl, 'Чистый онлайн за всё время:', font[3])
	imgui.PushFont(font[3])
	imgui.SetCursorPos(imgui.ImVec2(205, 152 + y_pl))
	imgui.TextColoredRGB('{279643}' .. format_time(online_week))
	imgui.SetCursorPos(imgui.ImVec2(223, 172 + y_pl))
	imgui.TextColoredRGB('{279643}' .. format_time(setting.stat.all))
	imgui.PopFont()
	
	imgui.Dummy(imgui.ImVec2(0, 23))

	imgui.EndChild()
end

local wave_ui = {show_tracks = false}
function wave_ui.draw(height)
	imgui.SetCursorPos(imgui.ImVec2(0, 0))
	local origin = imgui.GetCursorScreenPos()
	local dl = imgui.GetWindowDrawList()
	local offset = (height - 314) * 0.5
	local light = setting.cl == 'White'
	local ink = light and 0.10 or 1
	local function point(x, y) return imgui.ImVec2(origin.x + x, origin.y + y) end
	local function color(r, g, b, a) return imgui.GetColorU32Vec4(imgui.ImVec4(r, g, b, a)) end
	imgui.PushClipRect(point(144, 0), point(838, height), true)
	dl:AddRectFilled(point(144, 0), point(838, height), light and color(0.97, 0.97, 0.98, 1) or color(0.015, 0.015, 0.02, 1), 0, 15)
	local time = os.clock() * 0.35
	local function glow(x, y, radius, r, g, b)
		for layer = 14, 1, -1 do
			dl:AddCircleFilled(point(x, y), radius * (0.35 + layer / 14 * 0.65), color(r, g, b, light and 0.022 or 0.045), 48)
		end
	end
	glow(490 + math.sin(time) * 22, 122 + offset, 151, 0.95, 0.02, 0.38)
	glow(540 + math.cos(time) * 18, 112 + offset, 125, 1, 0.48, 0.02)
	glow(458 + math.sin(time + 1) * 25, 100 + offset, 120, 1, 0.92, 0)
	local function label(text, y, text_font, max_width)
		text = text:gsub('[\r\n]', ' ')
		imgui.PushFont(text_font)
		if max_width and imgui.CalcTextSize(u8(text)).x > max_width then
			repeat text = text:sub(1, -2) until text == '' or imgui.CalcTextSize(u8(text .. '...')).x <= max_width
			text = text .. '...'
		end
		local width = imgui.CalcTextSize(u8(text)).x
		imgui.PopFont()
		imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(ink, ink, ink, 1))
		gui.Text(491 - width / 2, y, text, text_font)
		imgui.PopStyleColor(1)
	end
	label('Моя волна', 27 + offset, bold_font[2])
	local active = playlist_playing == ym_wave and play.tab == 'PLAYLIST'
		and ym_wave[play.i] and play.info.link == ym_wave[play.i].link
	local index = active and play.i or 1
	local track = ym_wave[index]
	local cover = active and play.image_label or image_no_label
	if cover then
		dl:AddImageRounded(cover, point(457, 111 + offset), point(525, 179 + offset), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), color(1, 1, 1, 1), 9, 15)
	end
	local length = tonumber(play.len_time) or 0
	local seekable = active and not play.switching and length > 0 and length < math.huge
		and (play.status == 'PLAY' or play.status == 'PAUSE')
	local position = tonumber(play.pos_time) or 0
	position = seekable and position >= 0 and math.min(position, length) or 0
	if wave_ui.seek and (not seekable or wave_ui.seek.link ~= track.link or wave_ui.seek.token ~= mus.play_token) then
		wave_ui.seek = nil
	end
	local seek_hovered, seeking = false, false
	if seekable then
		imgui.SetCursorPos(imgui.ImVec2(260, 192 + offset))
		local pressed = imgui.InvisibleButton('##wave_seek', imgui.ImVec2(462, 40))
		seeking = imgui.IsItemActive()
		seek_hovered = imgui.IsItemHovered()
		if seeking or pressed or (imgui.IsItemDeactivated() and wave_ui.seek) then
			position = math.max(0, math.min(1, (imgui.GetMousePos().x - origin.x - 260) / 462)) * length
			wave_ui.seek = {link = track.link, token = mus.play_token, position = position}
			if not seeking then
				rewind_song(position)
				wave_ui.seek = nil
			end
		else
			wave_ui.seek = nil
		end
	end
	dl:AddRectFilled(point(260, 192 + offset), point(722, 232 + offset), light and color(1, 1, 1, 0.85) or color(0.11, 0.11, 0.12, 0.86), 20, 15)
	if seekable and position > 0 then
		imgui.PushClipRect(point(260, 192 + offset), point(260 + 462 * position / length, 232 + offset), true)
		dl:AddRectFilled(point(260, 192 + offset), point(722, 232 + offset), light and color(0.2, 0.16, 0.3, 0.12) or color(1, 1, 1, 0.17), 20, 15)
		imgui.PopClipRect()
	end
	local title = track and ((track.artist or '') .. ' — ' .. (track.name or ''))
		or (ym_wave_failed and 'Не удалось загрузить волну. Нажмите «Обновить».' or 'Подбираем музыку для вас...')
	if play.switching and playlist_playing == ym_wave then title = 'Загрузка трека...' end
	if seekable and (seek_hovered or seeking) then
		local function clock(seconds)
			seconds = math.floor(seconds)
			return string.format('%02d:%02d', math.floor(seconds / 60), seconds % 60)
		end
		title = clock(position) .. ' / ' .. clock(length)
	end
	label(title, 203 + offset, bold_font[1], 430)
	local function button(id, x, y, size, icon, enabled, yellow)
		imgui.SetCursorPos(imgui.ImVec2(x, y))
		local pressed = imgui.InvisibleButton(id, imgui.ImVec2(size, size))
		local hovered = imgui.IsItemHovered() and enabled
		local radius = size / 2
		dl:AddCircleFilled(point(x + radius, y + radius), radius, yellow and color(1, 0.96, 0, enabled and (hovered and 1 or 0.94) or 0.25)
			or color(ink, ink, ink, hovered and 0.15 or 0.06), 48)
		imgui.PushFont(size > 45 and fa_font[5] or fa_font[4])
		local measured = imgui.CalcTextSize(icon)
		imgui.SetCursorPos(imgui.ImVec2(x + (size - measured.x) / 2, y + (size - measured.y) / 2))
		imgui.TextColored(yellow and imgui.ImVec4(0.02, 0.02, 0.02, enabled and 1 or 0.5)
			or imgui.ImVec4(ink, ink, ink, enabled and 0.82 or 0.22), icon)
		imgui.PopFont()
		return pressed and enabled
	end
	if button('##wave_mute', 212, 194 + offset, 36, play.volume > 0 and fa.VOLUME_LOW or fa.VOLUME_SLASH, true) then
		if play.volume > 0 then
			play.last_volume_before_mute = play.volume
			play.volume = 0
		else
			play.volume = (play.last_volume_before_mute and play.last_volume_before_mute > 0) and play.last_volume_before_mute or 0.5
		end
		volume_song(play.volume)
	end
	local favorite
	if track then
		for i, saved in ipairs(setting.tracks) do
			if saved.link == track.link then favorite = i break end
		end
	end
	if button('##wave_favorite', 734, 194 + offset, 36, favorite and fa.HEART_CRACK or fa.HEART, track ~= nil) then
		if favorite then table.remove(setting.tracks, favorite) else table.insert(setting.tracks, track) end
		save()
	end
	if button('##wave_playlist', 780, 194 + offset, 36, fa.CIRCLE_PLUS, track ~= nil) then
		playlist_add_track = track
		imgui.OpenPopup(u8'Добавить в плейлист')
	end
	if button('##wave_previous', 405, 252 + offset, 36, fa.BACKWARD_STEP, active and play.i > 1 and not play.switching) then back_track() end
	local paused = active and play.status == 'PLAY'
	if button('##wave_play', 465, 244 + offset, 52, paused and fa.PAUSE or fa.PLAY, track ~= nil and not play.switching, true) then
		if active and (play.status == 'PLAY' or play.status == 'PAUSE') then
			set_song_status('PLAY_OR_PAUSE')
		else
			playlist_playing = ym_wave
			play_song(track, play.repeat_track == 2, index, 'PLAYLIST')
		end
	end
	if button('##wave_next', 541, 252 + offset, 36, fa.FORWARD_STEP, active and not play.switching) then next_track(true) end
	imgui.PopClipRect()
	playlist_add_popup()
end

function hall.music()
	local color_ItemActive = imgui.ImVec4(0.20, 0.20, 0.20, 1.00)
	local color_ItemHovered = imgui.ImVec4(0.24, 0.24, 0.24, 1.00)
	if setting.cl == 'White' then
		color_ItemActive = imgui.ImVec4(0.78, 0.78, 0.78, 1.00)
		color_ItemHovered = imgui.ImVec4(0.83, 0.83, 0.83, 1.00)
	end
	imgui.SetCursorPos(imgui.ImVec2(4, 39))
	imgui.BeginChild(u8'Музыка', imgui.ImVec2(840, 369), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller(u8'Музыка', img_step[1][0], img_duration[1][0], imgui.HoveredFlags.AllowWhenBlockedByActiveItem)
	
	local name_record = {'Record', 'Megamix', 'Party 24/7', 'Phonk', 'Гоп FM', 'Руки Вверх', 'Dupstep', 'Big Hits', 'Organic', 'Russian Hits'}
