				end
				local plus_hovered = imgui.IsItemHovered()
				gui.FaText(618, 16 + y_pos_tr, fa.CIRCLE_PLUS, fa_font[3], plus_hovered and imgui.ImVec4(0.85, 0.85, 0.85, 1.00) or imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
				if m <= 9 then
					imgui.SetCursorPos(imgui.ImVec2(17, 16 + y_pos_tr))
				else
					imgui.SetCursorPos(imgui.ImVec2(15, 16 + y_pos_tr))
				end
				imgui.PushFont(font[3])
				imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 0.50), tostring(m))
				imgui.PopFont()
				local artist_and_name, newline_count = wrapText(setting.tracks[m].artist .. ' - ' .. setting.tracks[m].name, 78, 78)
				gui.Text(43, 16 + y_pos_tr, artist_and_name, font[3])
				
				y_pos_tr = y_pos_tr + 40
			end
			if #list == 0 then
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
				gui.Text(250, 20, 'Ничего не найдено', font[3])
				imgui.PopStyleColor(1)
			end
			track_del_popup()
			playlist_add_popup()
			imgui.Dummy(imgui.ImVec2(0, 20))
			imgui.EndChild()
		else
			if setting.cl == 'White' then
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.40, 0.40, 0.40, 0.50))
			else
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
			end
			gui.Text(445, 164, 'Пусто', bold_font[3])
			imgui.PopStyleColor(1)
		end
	elseif tab_music == 3 then
		local height = (play.status == 'NULL') and 369 or 314
		if not playlist_view then
			playlist_search = InputTextForMusic({159, 17}, 627, playlist_search, u8'Поиск по плейлистам', 64, u8'Поиск по плейлистам')
			gui.DrawLine({156, 49}, {829, 49}, cl.line)
		end
		imgui.SetCursorPos(imgui.ImVec2(144, playlist_view and 0 or 50))
		imgui.BeginChild(u8'Плейлисты', imgui.ImVec2(694, playlist_view and height or height - 50), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
		imgui.Scroller(u8'Плейлисты', img_step[1][0], img_duration[1][0], imgui.HoveredFlags.AllowWhenBlockedByActiveItem)

		local card_w, card_h, card_gap, row_gap = 154, 120, 16, 14

		local function playlist_card(pos_x, pos_y, title, subtitle, color, id)
			imgui.SetCursorPos(imgui.ImVec2(0, 0))
			local origin = imgui.GetCursorScreenPos()
			local hovered = imgui.IsMouseHoveringRect(imgui.ImVec2(origin.x + pos_x, origin.y + pos_y), imgui.ImVec2(origin.x + pos_x + card_w, origin.y + pos_y + card_h))
			imgui.SetCursorPos(imgui.ImVec2(pos_x, pos_y))
			local clicked = imgui.InvisibleButton(u8'##плейлист ' .. id, imgui.ImVec2(card_w, card_h))
			imgui.SetItemAllowOverlap()
			gui.Draw({pos_x, pos_y}, {card_w, card_h}, imgui.ImVec4(color[1], color[2], color[3], hovered and 0.85 or 0.50), 7, 15)
			local card_title = wrapText(title, 16, 48)
			imgui.PushFont(bold_font[1])
			imgui.SetCursorPos(imgui.ImVec2(pos_x + 10, pos_y + 10))
			imgui.TextColored(imgui.ImVec4(0.97, 0.97, 0.97, 1.00), u8(card_title))
			imgui.PopFont()
			imgui.SetCursorPos(imgui.ImVec2(pos_x + 10, pos_y + card_h - 20))
			imgui.TextColored(imgui.ImVec4(0.95, 0.95, 0.95, 0.75), u8(subtitle))
			return clicked, hovered
		end

		if playlist_view then
			local view = playlist_view
			local pl = view
			if view.kind == 'local' then
				pl = setting.playlist[view.index]
				if not pl then playlist_view = nil end
			end
			if pl then
				local title = pl.name or view.title or ''
				imgui.SetCursorPos(imgui.ImVec2(6, 4))
				if imgui.InvisibleButton(u8'##назад к плейлистам', imgui.ImVec2(24, 24)) then
					playlist_view = nil
					playlist_search = ''
				end
				gui.FaText(12, 9, fa.ARROW_LEFT, fa_font[3])

				gui.Text(40, 8, title:sub(1, 34), bold_font[1])
				
				playlist_search = InputTextForMusic({15, 38}, 627, playlist_search, u8'Поиск по трекам', 64, u8'Поиск по трекам')
				gui.DrawLine({12, 70}, {685, 70}, cl.line)
				imgui.SetCursorPos(imgui.ImVec2(0, 76))
				imgui.BeginChild(u8'Треки плейлиста', imgui.ImVec2(694, height - 76), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
				imgui.Scroller(u8'Треки плейлиста', img_step[1][0], img_duration[1][0], imgui.HoveredFlags.AllowWhenBlockedByActiveItem)
				local y_tr = 0
				local query = u8:decode(playlist_search or '')
				local track_list = {}
				for m = 1, #pl.tracks do
					local track = pl.tracks[m]
					if query == '' or music_match((track.artist or '') .. ' - ' .. (track.name or ''), query) then
						track_list[#track_list + 1] = m
					end
				end
				local is_local = view.kind == 'local'
				for r = 1, #track_list do
					local m = track_list[r]
					local track = pl.tracks[m]
					local playing_now = play.status ~= 'NULL' and play.tab == 'PLAYLIST' and play.info and play.info.link == track.link
					local added_track = false
					for t = 1, #setting.tracks do
						if setting.tracks[t].link == track.link then
							added_track = true
							break
						end
					end
					imgui.SetCursorPos(imgui.ImVec2(8, 6 + y_tr))
					if imgui.InvisibleButton(u8'##трек плейлиста ' .. m, imgui.ImVec2(604, 37)) then
						if not playing_now then
							playlist_playing = pl.tracks
							play_song(track, play.repeat_track == 2, m, 'PLAYLIST')
						end
					end
					local row_hovered = imgui.IsItemHovered()
					if imgui.IsItemActive() and not playing_now then
						gui.Draw({8, 6 + y_tr}, {675, 37}, cl.bg2, 7, 15)
					elseif row_hovered and not playing_now then
						gui.Draw({8, 6 + y_tr}, {675, 37}, cl.tab, 7, 15)
					elseif playing_now then
						gui.Draw({8, 6 + y_tr}, {675, 37}, cl.bg2, 7, 15)
					end
					imgui.SetCursorPos(imgui.ImVec2(640, 6 + y_tr))
					if imgui.InvisibleButton(u8'##Действие с треком ' .. m, imgui.ImVec2(43, 37)) then
						if is_local then
							track_del = {kind = 'playlist', playlist = pl, index = m, name = (track.artist or '') .. ' - ' .. (track.name or '')}
							imgui.OpenPopup(u8'Подтверждение удаления трека')
							break
						end
						if added_track then
							for k = 1, #setting.tracks do
								if setting.tracks[k].link == track.link then
									table.remove(setting.tracks, k)
									break
								end
							end
						else
							table.insert(setting.tracks, track)
						end
						save()
					end
					local action_hovered = imgui.IsItemHovered()
					local action_active = imgui.IsItemActive()
					if not row_hovered and not action_hovered and not playing_now then
						imgui.PushFont(font[3])
						local calc_time = imgui.CalcTextSize(track.time)
						imgui.SetCursorPos(imgui.ImVec2(670 - calc_time.x, 16 + y_tr))
						imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 0.50), track.time)
						imgui.PopFont()
					end
					if row_hovered or action_hovered or playing_now then
						if playing_now then
							if action_hovered and not action_active then
								if an[22][4] < 1.00 then
									an[22][4] = an[22][4] + (anim * 3)
								end
							else
								if an[22][4] > 0 then
									an[22][4] = an[22][4] - (anim * 3)
								end
							end
						else
							if action_active or action_hovered then
								if an[22][5] < 1.00 then
									an[22][5] = an[22][5] + (anim * 3)
								end
							else
								if an[22][5] > 0 then
									an[22][5] = an[22][5] - (anim * 3)
								end
							end
						end
						local fa_action = is_local and fa.TRASH_XMARK or (added_track and fa.HEART_CRACK or fa.HEART)
						imgui.PushFont(fa_font[3])
						imgui.SetCursorPos(imgui.ImVec2(645, 16 + y_tr))
						imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 0.50), fa_action)
						imgui.SetCursorPos(imgui.ImVec2(645, 16 + y_tr))
						if playing_now then
							imgui.TextColored(imgui.ImVec4(1.00, 0.10, 0.00, an[22][4]), fa_action)
						else
							imgui.TextColored(imgui.ImVec4(1.00, 0.10, 0.00, an[22][5]), fa_action)
						end
						imgui.PopFont()
					end
					local can_add = (is_local and #setting.playlist >= 2) or (not is_local and #setting.playlist >= 1)
					if can_add then
						imgui.SetCursorPos(imgui.ImVec2(612, 6 + y_tr))
						if imgui.InvisibleButton(u8'##В плейлист из плейлиста ' .. m, imgui.ImVec2(28, 37)) then
							playlist_add_track = track
							playlist_add_from = is_local and pl or nil
							imgui.OpenPopup(u8'Добавить в плейлист')
						end
						local plus_hovered = imgui.IsItemHovered()
						gui.FaText(618, 16 + y_tr, fa.CIRCLE_PLUS, fa_font[3], plus_hovered and imgui.ImVec4(0.85, 0.85, 0.85, 1.00) or imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					end
					if m <= 9 then
						imgui.SetCursorPos(imgui.ImVec2(17, 16 + y_tr))
					else
						imgui.SetCursorPos(imgui.ImVec2(15, 16 + y_tr))
					end
					imgui.PushFont(font[3])
					imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 0.50), tostring(m))
					imgui.PopFont()
					gui.Text(43, 16 + y_tr, wrapText((track.artist or '') .. ' - ' .. (track.name or ''), 78, 78), font[3])
					y_tr = y_tr + 40
				end
				if #track_list == 0 then
					imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					local msg = query ~= '' and 'Ничего не найдено' or 'В плейлисте пока нет треков'
					imgui.PushFont(font[3])
					local msg_w = imgui.CalcTextSize(u8(msg)).x
					imgui.PopFont()
					gui.Text((694 - msg_w) / 2, 20, msg, font[3])
					imgui.PopStyleColor(1)
				end
				track_del_popup()
				playlist_add_popup()
				imgui.Dummy(imgui.ImVec2(0, 10))
				imgui.EndChild()
			end
		else
			gui.Text(8, 4, 'Свои плейлисты', bold_font[1])
			local query = u8:decode(playlist_search or '')
			local local_cards = {}
			for i = 1, #setting.playlist do
				if query == '' or music_match(setting.playlist[i].name or '', query) then
					local_cards[#local_cards + 1] = i
				end
			end
			for c = 1, #local_cards do
				local i = local_cards[c]
				local pl = setting.playlist[i]
				local x = 8 + ((c - 1) % 4) * (card_w + card_gap)
				local y = 28 + math.floor((c - 1) / 4) * (card_h + row_gap)
				local clicked, hovered = playlist_card(x, y, pl.name, #pl.tracks .. ' трек(ов)', playlist_colors[pl.color or 1] or playlist_colors[1], i)
				if hovered then
					imgui.SetCursorPos(imgui.ImVec2(x + card_w - 32, y + card_h - 30))
					if imgui.InvisibleButton(u8'##удалить плейлист ' .. i, imgui.ImVec2(22, 22)) then
						playlist_delete = i
						imgui.OpenPopup(u8'Удалить плейлист')
					end
					gui.FaText(x + card_w - 29, y + card_h - 26, fa.TRASH_XMARK, fa_font[2], imgui.ImVec4(1.00, 1.00, 1.00, 0.90))
					imgui.SetCursorPos(imgui.ImVec2(x + card_w - 58, y + card_h - 30))
					if imgui.InvisibleButton(u8'##редактировать плейлист ' .. i, imgui.ImVec2(22, 22)) then
						playlist_edit_index = i
						playlist_name_edit = u8(pl.name or '')
						playlist_color_edit = pl.color or 1
						playlist_rename_focus = true
						imgui.OpenPopup(u8'Редактировать плейлист')
					end
					gui.FaText(x + card_w - 55, y + card_h - 26, fa.PEN, fa_font[2], imgui.ImVec4(1.00, 1.00, 1.00, 0.90))
				end
				if clicked and not playlist_edit_index then
					playlist_view = {kind = 'local', index = i}
					playlist_search = ''
				end
			end

			local create_i = #local_cards + 1
			local cx = 8 + ((create_i - 1) % 4) * (card_w + card_gap)
			local cy = 28 + math.floor((create_i - 1) / 4) * (card_h + row_gap)
			imgui.SetCursorPos(imgui.ImVec2(cx, cy))
			local create_clicked = imgui.InvisibleButton(u8'##создать плейлист', imgui.ImVec2(card_w, card_h))
			local create_hovered = imgui.IsItemHovered()
			gui.Draw({cx, cy}, {card_w, card_h}, create_hovered and cl.bg2 or cl.tab, 7, 15)
			imgui.PushFont(fa_font[4])
			local calc_plus = imgui.CalcTextSize(fa.CIRCLE_PLUS)
			imgui.PopFont()
			imgui.PushFont(font[3])
			local calc_create = imgui.CalcTextSize(u8'Создать')
			imgui.PopFont()
			local y_create = cy + ((card_h - (calc_plus.y + 10 + calc_create.y)) / 2)
			gui.FaText(cx + ((card_w - calc_plus.x) / 2), y_create, fa.CIRCLE_PLUS, fa_font[4], imgui.ImVec4(0.55, 0.55, 0.55, 1.00))
			gui.Text(cx + ((card_w - calc_create.x) / 2), y_create + calc_plus.y + 10, 'Создать', font[3])
			if create_clicked then
				table.insert(setting.playlist, {name = 'Плейлист ' .. (#setting.playlist + 1), color = (#setting.playlist % 8) + 1, tracks = {}})
				playlist_search = ''
				save()
			end
			if setting.music_source == 'yandex' then
				local y_ym = 28 + math.ceil((#local_cards + 1) / 4) * (card_h + row_gap) + 6
				gui.Text(8, y_ym, 'Яндекс Музыка', bold_font[1])
				y_ym = y_ym + 24
				if setting.ym_token == '' then
					imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					gui.Text(8, y_ym + 6, 'Войдите в Яндекс Музыку в настройках', font[3])
					imgui.PopStyleColor(1)
				elseif ym_playlists == nil then
					ym_playlists_load()
					imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					gui.Text(8, y_ym + 6, 'Загрузка плейлистов...', font[3])
					imgui.PopStyleColor(1)
				elseif ym_playlists.status == 'loading' then
					imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					gui.Text(8, y_ym + 6, 'Загрузка плейлистов...', font[3])
					imgui.PopStyleColor(1)
				elseif ym_playlists.status == 'error' then
					imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50, 0.50, 0.50, 0.50))
					gui.Text(8, y_ym + 6, 'Не удалось загрузить плейлисты', font[3])
					imgui.PopStyleColor(1)
					if gui.Button(u8'Обновить##яндекс', {320, y_ym}, {100, 26}) then
						ym_playlists = nil
					end
				else
					local ym_cards = {}
					if query == '' or music_match('Мне нравится', query) then
						table.insert(ym_cards, {kind = 'likes', title = 'Мне нравится', count = ym_playlists.likes_count or 0})
					end
					for i = 1, #ym_playlists.list do
						if query == '' or music_match(ym_playlists.list[i].title or '', query) then
							table.insert(ym_cards, ym_playlists.list[i])
						end
					end
					for i = 1, #ym_cards do
						local card = ym_cards[i]
						local x = 8 + ((i - 1) % 4) * (card_w + card_gap)
						local y = y_ym + math.floor((i - 1) / 4) * (card_h + row_gap)
						local clicked = playlist_card(x, y, card.title, card.count .. ' трек(ов)', playlist_colors[((i - 1) % 8) + 1], 'ym' .. i)
						if clicked then
							playlist_search = ''
							ym_playlist_open(card.kind, card.title)
						end
					end
				end
			end
		end

		if playlist_delete then
			if imgui.BeginPopupModal(u8'Удалить плейлист', null, imgui.WindowFlags.AlwaysAutoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoTitleBar) then
				if imgui.IsKeyPressed(27, false) then imgui.CloseCurrentPopup() end
				imgui.SetCursorPos(imgui.ImVec2(10, 10))
				if imgui.InvisibleButton(u8'##Закрыть окно удаления плейлиста', imgui.ImVec2(16, 16)) then
					playlist_delete = nil
					imgui.CloseCurrentPopup()
				end
				imgui.SetCursorPos(imgui.ImVec2(16, 16))
				local p = imgui.GetCursorScreenPos()
				if imgui.IsItemHovered() then
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.32, 0.38, 1.00)), 60)
				else
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.42, 0.38, 1.00)), 60)
				end
				gui.DrawLine({10, 31}, {346, 31}, cl.line)
				imgui.PushFont(bold_font[1])
				local calc_confirm = imgui.CalcTextSize(u8('Подтверждение'))
				imgui.PopFont()
				gui.Text(136 - (calc_confirm.x / 2), (31 - calc_confirm.y) / 2, 'Подтверждение', bold_font[1])
				imgui.SetCursorPos(imgui.ImVec2(6, 40))
				imgui.BeginChild(u8'Удалить плейлист ', imgui.ImVec2(261, 90), false, imgui.WindowFlags.NoScrollbar)
				local pl = setting.playlist[playlist_delete]
				confirm_text('Вы уверены, что хотите удалить', 'плейлист «', pl and pl.name, '»?')
				if gui.Button(u8'Удалить##удалить плейлист', {24, 50}, {90, 27}) then
					table.remove(setting.playlist, playlist_delete)
						playlist_delete = nil
					save()
					imgui.CloseCurrentPopup()
				end
				if gui.Button(u8'Отмена##отмена удаления', {141, 50}, {90, 27}) then
					playlist_delete = nil
					imgui.CloseCurrentPopup()
				end
				imgui.EndChild()
				imgui.EndPopup()
			end
		end
		if playlist_delete and not imgui.IsPopupOpen(u8'Удалить плейлист') then
			playlist_delete = nil
		end

		if playlist_edit_index then
			if imgui.BeginPopupModal(u8'Редактировать плейлист', null, imgui.WindowFlags.AlwaysAutoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoTitleBar) then
				if imgui.IsKeyPressed(27, false) then imgui.CloseCurrentPopup() end
				imgui.SetCursorPos(imgui.ImVec2(10, 10))
				if imgui.InvisibleButton(u8'##Закрыть окно редактирования плейлиста', imgui.ImVec2(16, 16)) then
					playlist_edit_index = nil
					imgui.CloseCurrentPopup()
				end
				imgui.SetCursorPos(imgui.ImVec2(16, 16))
				local p = imgui.GetCursorScreenPos()
				if imgui.IsItemHovered() then
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.32, 0.38, 1.00)), 60)
				else
					imgui.GetWindowDrawList():AddCircleFilled(imgui.ImVec2(p.x - 0.4, p.y - 0.2), 7, imgui.GetColorU32Vec4(imgui.ImVec4(0.98, 0.42, 0.38, 1.00)), 60)
				end
				gui.DrawLine({10, 31}, {346, 31}, cl.line)
				imgui.SetCursorPos(imgui.ImVec2(6, 40))
				imgui.BeginChild(u8'Редактировать плейлист ', imgui.ImVec2(261, 112), false, imgui.WindowFlags.NoScrollbar)
					local pl = setting.playlist[playlist_edit_index]
					if pl then
						local function apply_edit()
							if playlist_name_edit ~= '' then pl.name = u8:decode(playlist_name_edit) end
							pl.color = playlist_color_edit
							playlist_edit_index = nil
							save()
							imgui.CloseCurrentPopup()
						end
						if playlist_rename_focus then
							imgui.SetKeyboardFocusHere()
							playlist_rename_focus = false
						end
						local name_text, name_done = gui.InputText({29, 10}, 193, playlist_name_edit, u8'##название плейлиста', 64)
						playlist_name_edit = name_text
						if name_done then apply_edit() end
						local color_gap = (207 - 22) / 7
						for i = 1, #playlist_colors do
							local c = playlist_colors[i]
							local cx = 24 + (i - 1) * color_gap
							imgui.SetCursorPos(imgui.ImVec2(cx + 11, 58))
							local pc = imgui.GetCursorScreenPos()
							imgui.SetCursorPos(imgui.ImVec2(cx, 47))
							if imgui.InvisibleButton(u8'##цвет плейлиста ' .. i, imgui.ImVec2(22, 22)) then
