			table.insert(bl_cmd.act, number_i_cmd + 1, {
				'IF',
				1, --> Условие
				{'', ''}, --> Входные данные,
				bl_cmd.id_element,
				1,
				false --> Свернутый блок
			})
			table.insert(bl_cmd.act, number_i_cmd + 2, {
				'ELSE',
