function tag_vis(tag_entry)
	if #tag_entry < 3 then return true end
	local groups = {
		[1] = {1, 2, 3, 4},
		[2] = {5},
		[3] = {6},
		[4] = {7, 8, 10},
		[5] = {11, 12, 13, 14, 15}
	}
	for i = 3, #tag_entry do
		local group = groups[tag_entry[i]]
		if group then
			for _, org_id in ipairs(group) do
				if setting.org == org_id then return true end
			end
		end
	end
	return false
end

