				afind_line('Внимание', 22, bold_font[1])
				afind_line('На сервере эта функция может быть запрещена.', 54, font[3], imgui.ImVec4(cl.text.x, cl.text.y, cl.text.z, 0.94))
				afind_line('Мы не несем ответственности за возможные блокировки.', 80, font[2], imgui.ImVec4(0.58, 0.58, 0.60, 0.88))
				dl:AddLine(imgui.ImVec2(c1.x + 22, c1.y + 108), imgui.ImVec2(c2.x - 22, c1.y + 108), imgui.GetColorU32Vec4(cl.line), 1)
