						local lift = hot and 0.16 or 0
						if down then lift = 0 end
						fill = imgui.ImVec4(cl.def.x + (1 - cl.def.x) * lift, cl.def.y + (1 - cl.def.y) * lift, cl.def.z + (1 - cl.def.z) * lift, 1)
						textc = imgui.ImVec4(0.98, 0.98, 0.98, 1)
						border = nil
					else
						fill = hot and cl.bg or cl.main
						textc = cl.text
						border = hot and cl.def or imgui.ImVec4(cl.line.x, cl.line.y, cl.line.z, 0.95)
					end
					imgui.SetCursorPos(imgui.ImVec2(0, 0))
					local p = imgui.GetCursorScreenPos()
					local x1, y1 = p.x + x, p.y + y
					dl:AddRectFilled(imgui.ImVec2(x1, y1 + 3), imgui.ImVec2(x1 + w, y1 + 41), imgui.GetColorU32Vec4(imgui.ImVec4(0, 0, 0, primary and 0.28 or 0.16)), 8)
					dl:AddRectFilled(imgui.ImVec2(x1, y1), imgui.ImVec2(x1 + w, y1 + 38), imgui.GetColorU32Vec4(fill), 8)
					if primary then
						dl:AddRectFilled(imgui.ImVec2(x1 + 10, y1 + 1), imgui.ImVec2(x1 + w - 10, y1 + 2), imgui.GetColorU32Vec4(imgui.ImVec4(1, 1, 1, hot and 0.35 or 0.18)), 1)
					end
					if border then
						dl:AddRect(imgui.ImVec2(x1, y1), imgui.ImVec2(x1 + w, y1 + 38), imgui.GetColorU32Vec4(border), 8, 15, 1)
					end
					local shown = label
					local mark = shown:find('##', 1, true)
					if mark then shown = shown:sub(1, mark - 1) end
					imgui.PushStyleColor(imgui.Col.Text, textc)
					imgui.PushFont(font[3])
					local calc = imgui.CalcTextSize(shown)
					imgui.SetCursorPos(imgui.ImVec2(x + (w - calc.x) / 2, y + (38 - calc.y) / 2))
					imgui.Text(shown)
					imgui.PopFont()
					imgui.PopStyleColor()
					return hit
				end
				local confirm_w, cancel_w, gap = 206, 140, 12
				local buttons_x = card_x + (card_w - confirm_w - gap - cancel_w) / 2
				local buttons_y = card_y + 128
				if afind_choice(u8'Всё равно подтвердить##afind_yes', buttons_x, buttons_y, confirm_w, true) then
					setting.police_settings.afind = true
					afind_bind(true)
					afind_warn = false
					save()
					imgui.CloseCurrentPopup()
				end
				if afind_choice(u8'Не включать##afind_no', buttons_x + confirm_w + gap, buttons_y, cancel_w, false) then
					afind_warn = false
					imgui.CloseCurrentPopup()
				end
			end
			imgui.EndPopup()
		end
		if afind_dim then
			imgui.PopStyleColor(3)
		end
	
		winter.finish()
		imgui.End()
	end
)

local suui = {
	LIMIT = 6,
	GOLD = {1.00, 0.78, 0.12},
	WARN = {1.00, 0.60, 0.20},
	hov = {},      -- плавное наведение: [ключ] = 0..1
	selv = {},     -- плавное выделение: [код] = 0..1
	chip = {},     -- появление чипов: [код] = 0..1
	chap = {},     -- раскрытие глав (для каскада): [index] = 0..1
	stars = {0, 0, 0, 0, 0, 0}, -- заливка звёзд в лотке
	pop = {0, 0, 0, 0, 0, 0},   -- «подпрыгивание» звезды при изменении
	last_used = 0,
	range_open = nil,           -- код статьи с открытой панелью выбора звёзд
	range_h = 0,                -- анимация высоты панели
	time = 0,
	warn_t = 0,                 -- вспышка бейджа при превышении лимита
	prev_total = 0,
	load_check = 0,
	t = 0,                      -- прогресс открытия окна 0..1
	fit_cache = {},
	hay = setmetatable({}, {__mode = 'k'}),
	init_done = false
}

-- ---------- математика / цвета ------------------------------------------------
function suui.clamp(v, a, b)
	if v < a then return a end
	if v > b then return b end
	return v
end

function suui.dt()
	local d = anim or 0.016
	if d > 0.05 then d = 0.05 end
	if d < 0 then d = 0 end
	return d
end

function suui.approach(tbl, key, target, speed)
	local v = tbl[key] or 0
	local step = suui.dt() * speed
	if v < target then
		v = math.min(target, v + step)
	elseif v > target then
		v = math.max(target, v - step)
	end
	tbl[key] = v
	return v
end

function suui.ease(t)
	t = suui.clamp(t, 0, 1)
	return 1 - (1 - t) * (1 - t) * (1 - t)
end

function suui.lerp(a, b, t)
	return a + (b - a) * t
end

function suui.mix(c1, c2, t)
	return imgui.ImVec4(
		suui.lerp(c1.x, c2.x, t),
		suui.lerp(c1.y, c2.y, t),
		suui.lerp(c1.z, c2.z, t),
		suui.lerp(c1.w, c2.w, t)
	)
end

function suui.alpha(c, a)
	return imgui.ImVec4(c.x, c.y, c.z, c.w * a)
end

function suui.u32(c, a)
	if a then
		c = suui.alpha(c, a)
	end
	return imgui.GetColorU32Vec4(c)
end

function suui.gold(a)
	return imgui.ImVec4(suui.GOLD[1], suui.GOLD[2], suui.GOLD[3], a or 1)
end

function suui.warn(a)
	return imgui.ImVec4(suui.WARN[1], suui.WARN[2], suui.WARN[3], a or 1)
end

function suui.muted(a)
	return imgui.ImVec4(0.50, 0.50, 0.50, a or 0.90)
end

-- мягкая карточка: скруглённая заливка + скруглённая рамка
function suui.box(x, y, w, h, bg, border, r)
	gui.Draw({x, y}, {w, h}, bg, r, 15)
	if border then
		gui.DrawEmp({x, y}, {w, h}, border, r, 15, 1.2)
	end
end

-- вторичный (приглушённый) текст из исходника (CP1251)
function suui.mtext(x, y, text, col)
	imgui.PushStyleColor(imgui.Col.Text, col or suui.muted(1))
	gui.Text(x, y, text)
	imgui.PopStyleColor(1)
end

-- сброс анимаций при каждом открытии окна
function suui.reset()
	suui.t = 0
	suui.hov = {}
	suui.selv = {}
	suui.chip = {}
	suui.chap = {}
	suui.stars = {0, 0, 0, 0, 0, 0}
	suui.pop = {0, 0, 0, 0, 0, 0}
	suui.last_used = 0
	suui.prev_total = 0
	suui.warn_t = 0
	suui.range_open = nil
	suui.fit_cache = {}
	suui.init_done = false
	suui.load_check = 0
end

-- ---------- работа с UTF-8 текстом из JSON -----------------------------------
-- нижний регистр для кириллицы в UTF-8 (string.lower её не трогает)
function suui.ulower(s)
	s = tostring(s or '')
	local out = {}
	local i, n = 1, #s
	while i <= n do
		local b = s:byte(i)
		if b == 208 and i < n then
			local c = s:byte(i + 1)
			if c >= 144 and c <= 159 then
				out[#out + 1] = string.char(208, c + 32)
			elseif c >= 160 and c <= 175 then
				out[#out + 1] = string.char(209, c - 32)
			elseif c == 129 then
				out[#out + 1] = string.char(209, 145)
			else
				out[#out + 1] = string.char(b, c)
			end
			i = i + 2
		elseif b < 128 then
			out[#out + 1] = string.char(b):lower()
			i = i + 1
		else
			out[#out + 1] = string.char(b)
			i = i + 1
		end
	end
	return table.concat(out)
end

-- обрезка UTF-8 строки по ширине с многоточием
function suui.fit(text, max_w)
	text = tostring(text or '')
	local key = text .. '\1' .. tostring(math.floor(max_w))
	local hit = suui.fit_cache[key]
	if hit then return hit[1], hit[2] end
	if imgui.CalcTextSize(text).x <= max_w then
		suui.fit_cache[key] = {text, false}
		return text, false
	end
	local ell = '...'
	local ell_w = imgui.CalcTextSize(ell).x
	local out = {}
	local w = 0
	local i, n = 1, #text
	while i <= n do
		local b = text:byte(i)
		local len = 1
		if b >= 240 then len = 4 elseif b >= 224 then len = 3 elseif b >= 192 then len = 2 end
		local ch = text:sub(i, i + len - 1)
		local cw = imgui.CalcTextSize(ch).x
		if w + cw + ell_w > max_w then break end
		out[#out + 1] = ch
		w = w + cw
		i = i + len
	end
	local res = table.concat(out) .. ell
	suui.fit_cache[key] = {res, true}
	return res, true
end

-- диапазон/число звёзд из поля penalty
function suui.parse_pen(p)
	local s = tostring(p or '')
	local a, b = s:match('(%d+)%s*%-%s*(%d+)')
	if a and b then
		a, b = tonumber(a), tonumber(b)
		if a > b then a, b = b, a end
		if a == b then return a, a, false end
		return a, b, true
	end
	local n = tonumber(s:match('%d+')) or 0
	return n, n, false
end

-- чистое название: без дублирующего кода в начале и без "(N)" в конце
function suui.title(article)
	local text = tostring(article.text or '')
	local code = tostring(article.code or '')
	local t = text
	if code ~= '' and t:sub(1, #code) == code then
		t = t:sub(#code + 1)
	end
	t = t:gsub('^%s+', '')
	t = t:gsub('%s*%(%s*%d+%s*%-?%s*%d*%s*%)%s*$', '')
	t = t:gsub('%s+$', '')
	if t == '' then t = text end
	return t
end

-- ---------- выбор статей ------------------------------------------------------
function suui.find_sel(code)
	for i, s in ipairs(smartSuState.selected) do
		if s.code == code then return s, i end
	end
	return nil, nil
end

function suui.recalc()
	local sum = 0
	for _, s in ipairs(smartSuState.selected) do
		sum = sum + s.stars
	end
	smartSuState.totalStars = sum
end

function suui.set_sel(article, stars)
	if stars < 1 then return end
	local s = suui.find_sel(article.code)
	if s then
		s.stars = stars
	else
		table.insert(smartSuState.selected, {
			code = article.code,
			text = article.text,
			stars = stars,
			penalty = article.penalty
		})
	end
	suui.recalc()
end

function suui.remove_sel(code)
	local _, i = suui.find_sel(code)
	if i then
		table.remove(smartSuState.selected, i)
		suui.recalc()
	end
end

function suui.notify(text)
	if not setting.cef_notif then
		sampAddChatMessage('[SH]{FFFFFF} ' .. text, 0xFF5345)
	else
		cefnotig('{FF5345}[SH]{FFFFFF} ' .. text, 2500)
	end
end

function suui.issue_stars()
	local n = smartSuState.totalStars
	if n > suui.LIMIT then n = suui.LIMIT end
	if n < 1 then n = 1 end
	return n
end

function suui.reason()
	local parts = {}
	for _, s in ipairs(smartSuState.selected) do
		parts[#parts + 1] = s.code
	end
	return table.concat(parts, ' + ')
end

function suui.close()
	smartSuState.anim.is_closing = true
	smartSuState.anim.is_opening = false
end

-- Выдать: /su по форме (ранг 5+)
function suui.do_issue()
	local id = smartSuState.targetId[0]
	local sex_a = setting.sex == 2 and 'а' or ''
	if send_smart_su_commands({
		'/me правой рукой снял' .. sex_a .. ' рацию с пояса, сообщил' .. sex_a .. ' диспетчеру приметы подозреваемого',
		string.format('/su %d %d %s', id, suui.issue_stars(), u1251:iconv(suui.reason())),
		'/do Преступник занесен в базу данных преступников.'
	}) then suui.close() end
end

-- Запросить: запрос в рацию (ранг 1-4)
function suui.do_request()
	local id = smartSuState.targetId[0]
	if send_smart_su_commands({
		string.format('/r Запрашиваю розыск на дело: "%d" степень розыска: "%d" с причиной: "%s"', id, suui.issue_stars(), u1251:iconv(suui.reason())),
		'/r Доказательства есть на боди-камере!'
	}) then suui.close() end
end

-- подгрузка базы статей, если файл появился уже после открытия окна
function suui.try_load()
	if os.clock() - suui.load_check < 1.0 then return end
	suui.load_check = os.clock()
	if s_na == nil or s_na == '' then return end
	local file_path = dir .. '/State Helper/Police/AutoSu/' .. s_na .. '.json'
	if not doesFileExist(file_path) then return end
	local file = io.open(file_path, 'r')
	if not file then return end
	local data = file:read('*a')
	file:close()
	local ok, decoded = pcall(decodeJson, data)
	if ok and type(decoded) == 'table' and #decoded > 0 then
		smartSuState.reasons = decoded
		smartSuState.chapterStates = {}
		smartSuState.chapterStates[1] = true
	end
end

-- ---------- примитивы ---------------------------------------------------------
-- Иконка в круглом/скруглённом квадрате. Возвращает true при клике.
function suui.icon_btn(id, x, y, w, h, icon, tip, accent)
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	local clicked = imgui.InvisibleButton(id, imgui.ImVec2(w, h))
	local hovered = imgui.IsItemHovered()
	local active = imgui.IsItemActive()
	local k = suui.approach(suui.hov, id, hovered and 1 or 0, 9)
	local bg = suui.mix(cl.bg, cl.bg2, k)
	if active then bg = cl.def end
	suui.box(x, y, w, h, bg, cl.line, 7)
	local col = suui.mix(suui.muted(1), accent or cl.def, k)
	if active then col = imgui.ImVec4(0.95, 0.95, 0.95, 1.00) end
	gui.FaText(x + (w / 2) - 7, y + (h / 2) - 8, icon, fa_font[3], col)
	if hovered and tip then
		imgui.SetTooltip('%s', u8(tip))
	end
	return clicked
end

-- Большая кнопка действия. Возвращает true при клике (только если enabled).
function suui.action_btn(id, x, y, w, h, icon, label, sub, primary, enabled, tip)
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	local clicked = imgui.InvisibleButton(id, imgui.ImVec2(w, h))
	local hovered = imgui.IsItemHovered()
	local active = imgui.IsItemActive()
	local k = suui.approach(suui.hov, id, (hovered and enabled) and 1 or 0, 8)
	local bg, fg, subc, bord
	if not enabled then
		bg = imgui.ImVec4(0.50, 0.50, 0.50, 0.30)
		fg = imgui.ImVec4(0.60, 0.60, 0.60, 0.80)
		subc = imgui.ImVec4(0.60, 0.60, 0.60, 0.70)
		bord = cl.line
	elseif primary then
		bg = suui.mix(cl.def, imgui.ImVec4(math.min(cl.def.x + 0.10, 1), math.min(cl.def.y + 0.10, 1), math.min(cl.def.z + 0.10, 1), 1), k)
		fg = imgui.ImVec4(1, 1, 1, 1)
		subc = imgui.ImVec4(1, 1, 1, 0.80)
		bord = bg
	else
		bg = suui.mix(cl.bg, cl.bg2, k)
		fg = suui.mix(cl.text, cl.def, k)
		subc = suui.muted(1)
		bord = suui.mix(cl.line, cl.def, k)
	end
	if active and enabled then
		bg = suui.mix(bg, imgui.ImVec4(0, 0, 0, 1), 0.18)
	end
	local lift = (enabled and not active) and (k * 1.5) or 0
	suui.box(x, y - lift, w, h, bg, bord, 9)
	-- иконка в круге
	local circ = primary and enabled and imgui.ImVec4(1, 1, 1, 0.20) or suui.alpha(cl.def, enabled and 0.16 or 0.10)
	gui.DrawCircle({x + 28, y - lift + (h / 2)}, 17, circ)
	local icol = (primary and enabled) and imgui.ImVec4(1, 1, 1, 1) or (enabled and cl.def or suui.muted(0.8))
	gui.FaText(x + 20, y - lift + (h / 2) - 9, icon, fa_font[4], icol)
	imgui.PushStyleColor(imgui.Col.Text, fg)
	gui.Text(x + 54, y - lift + 10, label, bold_font[1])
	imgui.PopStyleColor(1)
	imgui.PushStyleColor(imgui.Col.Text, subc)
	gui.Text(x + 54, y - lift + 31, sub)
	imgui.PopStyleColor(1)
	if hovered and tip then
		imgui.SetTooltip('%s', u8(tip))
	end
	if clicked and not enabled and tip then
		suui.notify(tip)
	end
	return clicked and enabled
end

-- ---------- главное окно ------------------------------------------------------
win.smart_su = imgui.OnFrame(
	function() return windows.smart_su[0] end,
	function(main)
		local W, H = 848, 448
		local st = smartSuState
		local dt = suui.dt()

		-- анимация открытия / закрытия: плавный выезд справа + проявление
		if st.anim.is_opening then
			suui.t = math.min(1, suui.t + dt * 3.2)
			if suui.t >= 1 then st.anim.is_opening = false end
		elseif st.anim.is_closing then
			suui.t = math.max(0, suui.t - dt * 4.0)
			if suui.t <= 0 then
				st.anim.is_closing = false
				windows.smart_su[0] = false
			end
		end
		local ez = suui.ease(suui.t)
		local win_x = suui.lerp(sx + (W / 2) + 20, sx / 2, ez)
		st.anim.win_x[0] = win_x

		suui.time = suui.time + dt

		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, suui.clamp(ez * 1.4, 0.0, 1.0))
		local pos_cond = (st.anim.is_opening or st.anim.is_closing) and imgui.Cond.Always or imgui.Cond.FirstUseEver
		imgui.SetNextWindowPos(imgui.ImVec2(win_x, st.anim.win_y[0]), pos_cond, imgui.ImVec2(0.5, 0.5))
		imgui.SetNextWindowSize(imgui.ImVec2(W, H))
		imgui.Begin('SmartSU', windows.smart_su, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoSavedSettings)
		bug_fix_input()

		-- если файл базы появился позже открытия окна
		if not st.reasons or #st.reasons == 0 then
			suui.try_load()
		elseif not suui.init_done then
			suui.init_done = true
			if st.chapterStates[1] == nil then st.chapterStates[1] = true end
		end

		local inner_w = W - 8

		-- фон окна
		gui.Draw({4, 4}, {inner_w, H - 8}, cl.main, 12, 15)
		winter.begin(W, H)

		-- ===== ШАПКА =====
		gui.DrawLine({4, 38}, {W - 4, 38}, cl.line)
		imgui.SetCursorPos(imgui.ImVec2(11, 11))
		if imgui.InvisibleButton(u8'##su_close', imgui.ImVec2(20, 20)) then
			suui.close()
		end
		if imgui.IsItemHovered() then
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.30, 0.38, 1.00))
		else
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.40, 0.38, 1.00))
		end

		imgui.PushFont(bold_font[1])
		local title_w = imgui.CalcTextSize(u8'Умный розыск').x
		imgui.PopFont()
		local title_x = (W - title_w) / 2
		gui.FaText(title_x - 26, 12, fa.SCALE_BALANCED, fa_font[4], cl.def)
		gui.Text(title_x, 10, 'Умный розыск', bold_font[1])
		winter.small_front('smart_su', W, H, title_w, 22)

		-- бейдж звёзд (справа в шапке)
		local total = st.totalStars
		local used = math.min(total, suui.LIMIT)
		local over = total > suui.LIMIT
		if total > suui.prev_total and over then suui.warn_t = 1 end
		suui.prev_total = total
		suui.warn_t = math.max(0, suui.warn_t - dt * 1.6)
		local badge_txt = tostring(used) .. ' / ' .. tostring(suui.LIMIT)
		local bw = imgui.CalcTextSize(u8(badge_txt)).x + 44
		local bx = W - 16 - bw
		local bcol = suui.mix(cl.bg, suui.warn(0.35), suui.warn_t)
		suui.box(bx, 8, bw, 24, bcol, over and suui.warn(0.9) or cl.line, 8)
		gui.FaText(bx + 10, 12, fa.STAR, fa_font[3], used > 0 and suui.gold() or suui.muted(0.8))
		gui.Text(bx + 32, 11, badge_txt, font[3])

		-- ===== РАСКЛАДКА: слева игрок/выбор/кнопки, справа поиск и статьи =====
		local LX, LW = 16, 254
		local RX, RWc = 286, 546
		local RED = imgui.ImVec4(0.98, 0.40, 0.38, 1.00)
		local function sev(n)
			if n >= 5 then return imgui.ImVec4(0.96, 0.40, 0.38, 1) end
			if n >= 3 then return imgui.ImVec4(0.97, 0.72, 0.28, 1) end
			return imgui.ImVec4(0.38, 0.80, 0.50, 1)
		end
		gui.DrawLine({278, 48}, {278, H - 14}, cl.line)

		-- ===== КАРТОЧКА ИГРОКА (компактная: иконка, справа ник и под ним ID) =====
		local tid = st.targetId[0]
		local connected = sampIsPlayerConnected(tid)
		local nick = connected and sampGetPlayerNickname(tid) or nil
		if not nick or nick == '' then nick = 'Игрок вышел' end
		suui.box(LX, 48, LW, 46, cl.tab, cl.line, 10)
		gui.Draw({LX, 48}, {4, 46}, connected and cl.def or suui.muted(0.8), 2, 15)
		gui.DrawCircle({LX + 30, 71}, 17, suui.alpha(cl.def, 0.18))
		gui.FaText(LX + 22, 63, fa.USER, fa_font[4], cl.def)
		gui.Text(LX + 56, 52, nick, bold_font[1])
		if connected then
			suui.mtext(LX + 56, 72, 'ID ' .. tostring(tid))
		else
			suui.mtext(LX + 56, 72, 'покинул сервер', suui.warn(1))
		end

		-- ===== ЗВЁЗДЫ К ВЫДАЧЕ (только шкала) =====
		local cnt = #st.selected
		local ty, th = 102, 46
		suui.box(LX, ty, LW, th, cl.tab, cl.line, 10)
		if used ~= suui.last_used then
			for i = 1, suui.LIMIT do
				if (i > suui.last_used and i <= used) or (i <= suui.last_used and i > used) then
					suui.pop[i] = 1
				end
			end
			suui.last_used = used
		end
		for i = 1, suui.LIMIT do
			local target = (i <= used) and 1 or 0
			local v = suui.approach(suui.stars, i, target, 7)
			suui.pop[i] = math.max(0, suui.pop[i] - dt * 3.5)
			local gold = suui.mix(suui.muted(0.55), suui.gold(1), v)
			if over and i == suui.LIMIT then
				gold = suui.mix(gold, suui.warn(1), suui.warn_t * 0.8 + 0.2)
			end
			local jump = math.sin(suui.pop[i] * math.pi) * 5
			gui.FaText(LX + 16 + (i - 1) * 28, ty + 12 - jump, fa.STAR, fa_font[5], gold)
		end
		if cnt > 0 then
			if suui.icon_btn(u8'##su_clearall', LX + LW - 40, ty + 11, 28, 24, fa.TRASH, 'Очистить выбор', RED) then
				st.selected = {}
				st.totalStars = 0
				suui.range_open = nil
			end
		end

		-- ===== ПРИЧИНА В КОМАНДЕ (занимает свободное место) =====
		local has_sel = cnt > 0
		local rank = setting.rank or 0
		local can_issue = rank >= 5
		local alive = connected
		local ry, rh = 156, 148
		suui.box(LX, ry, LW, rh, cl.tab, cl.line, 10)
		if has_sel then
			suui.mtext(LX + 14, ry + 9, 'Причина в команде')
			local wp0 = imgui.GetWindowPos()
			imgui.PushClipRect(imgui.ImVec2(wp0.x + LX + 4, wp0.y + ry + 28), imgui.ImVec2(wp0.x + LX + LW - 4, wp0.y + ry + rh - 6), true)
			imgui.SetCursorPos(imgui.ImVec2(LX + 14, ry + 30))
			imgui.PushTextWrapPos(LX + LW - 14)
			imgui.Text(suui.reason())
			imgui.PopTextWrapPos()
			imgui.PopClipRect()
		else
			gui.FaText(LX + 14, ry + 14, fa.LIST_CHECK, fa_font[3], suui.muted(0.7))
			suui.mtext(LX + 40, ry + 15, 'Выберите статьи справа')
			suui.mtext(LX + 14, ry + 42, 'Звёзды суммируются, максимум ' .. tostring(suui.LIMIT) .. '.')
		end

		local req_ok = has_sel and alive
		local give_ok = has_sel and alive and can_issue
		local req_tip = (not has_sel) and 'Выберите хотя бы одну статью' or (not alive and 'Игрок покинул сервер' or nil)
		local give_tip = (not can_issue) and 'Доступно с 5 ранга. Используйте запрос в рацию' or ((not has_sel) and 'Выберите хотя бы одну статью' or (not alive and 'Игрок покинул сервер' or nil))
		if suui.action_btn(u8'##su_req', LX, 312, LW, 56, fa.BULLHORN, 'Запросить', 'в рацию | ранг 1-4', not can_issue, req_ok, req_tip) then
			suui.do_request()
		end
		if suui.action_btn(u8'##su_give', LX, 376, LW, 56, can_issue and fa.CHECK or fa.LOCK, 'Выдать', can_issue and '/su | ранг 5+' or 'нужен 5 ранг', can_issue, give_ok, give_tip) then
			suui.do_issue()
		end

		-- ===== ПОИСК (правая колонка) =====
		suui.box(RX, 48, RWc, 34, cl.tab, cl.line, 10)
		gui.FaText(RX + 12, 57, fa.MAGNIFYING_GLASS, fa_font[3], cl.def)
		st.searchQuery = gui.InputText({RX + 40, 59}, RWc - 120, st.searchQuery, 'smartSuState.searchQuery', 256, u8'Поиск по номеру или названию статьи...')
		local has_query = (st.searchQuery or '') ~= ''
		if has_query then
			if suui.icon_btn(u8'##su_clear', RX + RWc - 72, 52, 28, 26, fa.XMARK, 'Очистить поиск', RED) then
				st.searchQuery = ''
			end
		end
		local any_open = false
		for i = 1, #(st.reasons or {}) do
			if st.chapterStates[i] then any_open = true break end
		end
		if suui.icon_btn(u8'##su_fold', RX + RWc - 38, 52, 28, 26, any_open and fa.CARET_DOWN or fa.CARET_RIGHT, any_open and 'Свернуть все главы' or 'Развернуть все главы') then
			for i = 1, #(st.reasons or {}) do
				st.chapterStates[i] = not any_open
			end
		end

		-- ===== СПИСОК СТАТЕЙ =====
		local list_y = 90
		local list_h = H - 18 - list_y
		imgui.SetCursorPos(imgui.ImVec2(RX, list_y))
		imgui.BeginChild(u8'##su_list', imgui.ImVec2(RWc, list_h), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
		imgui.Scroller(u8'##su_list', img_step[1][0], img_duration[1][0], imgui.HoveredFlags.AllowWhenBlockedByActiveItem)

		local query = suui.ulower(st.searchQuery or '')
		local drawn_any = false
		local ROW_H, ROW_GAP = 42, 4
		local HEAD_H = 42
		local LIST_W = imgui.GetContentRegionAvail().x - 2
		local RW = LIST_W - 12

		if st.reasons and #st.reasons > 0 then
			for index, chapterData in ipairs(st.reasons) do
				local articles = chapterData.chapter or {}
				local matches = {}
				for _, article in ipairs(articles) do
					local ok = true
					if query ~= '' then
						local hay = suui.ulower(tostring(article.code or '') .. ' ' .. tostring(article.text or ''))
						ok = hay:find(query, 1, true) ~= nil
					end
					if ok then matches[#matches + 1] = article end
				end
				if #matches > 0 then
					drawn_any = true
					if st.chapterStates[index] == nil then st.chapterStates[index] = false end
					local open = st.chapterStates[index] or query ~= ''
					local ck = suui.approach(suui.chap, index, open and 1 or 0, 5)

					-- заголовок главы: номер в круге, название, прогресс выбора
					local hp = imgui.GetCursorPos()
					imgui.SetCursorPos(hp)
					if imgui.InvisibleButton(u8'##su_ch' .. index, imgui.ImVec2(LIST_W, HEAD_H)) then
						if query == '' then
							st.chapterStates[index] = not st.chapterStates[index]
						end
					end
					local chov = imgui.IsItemHovered()
					local hk = suui.approach(suui.hov, 'ch' .. index, chov and 1 or 0, 9)
					local mn, mx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
					local dl = imgui.GetWindowDrawList()
					local picked = 0
					for _, article in ipairs(matches) do
						if suui.find_sel(article.code) then picked = picked + 1 end
					end
					local hbg = suui.mix(cl.tab, cl.bg, math.max(hk * 0.7, ck * 0.6))
					dl:AddRectFilled(mn, mx, suui.u32(hbg), 10)
					dl:AddRect(mn, mx, suui.u32(suui.mix(cl.line, cl.def, ck * 0.6)), 10, 15, 1.0)
					if picked > 0 then
						local frac = picked / #matches
						dl:AddRectFilled(imgui.ImVec2(mn.x + 12, mx.y - 5), imgui.ImVec2(mn.x + 12 + (LIST_W - 24) * frac, mx.y - 3), suui.u32(cl.def, 0.9), 2)
					end
					local bcx, bcy = mn.x + 26, (mn.y + mx.y) / 2 - 1
					dl:AddCircleFilled(imgui.ImVec2(bcx, bcy), 15, suui.u32(cl.def, 0.14 + 0.30 * ck), 28)
					imgui.PushFont(bold_font[1])
					local ns = tostring(index)
					local nsz = imgui.CalcTextSize(ns)
					dl:AddText(imgui.ImVec2(bcx - nsz.x / 2, bcy - nsz.y / 2), suui.u32(suui.mix(cl.def, imgui.ImVec4(1, 1, 1, 1), ck * 0.0)), ns)
					local right_txt = (picked > 0 and (tostring(picked) .. ' выбр.  |  ') or '') .. tostring(#matches) .. ' ст.'
					imgui.PopFont()
					local rw = imgui.CalcTextSize(u8(right_txt)).x
					local title_w = LIST_W - 52 - (rw + 16) - 44
					imgui.PushFont(bold_font[1])
					local head_txt = suui.fit(tostring(chapterData.headerText or ''), title_w)
					imgui.PushStyleColor(imgui.Col.Text, cl.text)
					imgui.SetCursorPos(imgui.ImVec2(hp.x + 52, hp.y + 11))
					imgui.Text(head_txt)
					imgui.PopStyleColor(1)
					imgui.PopFont()
					if chov and tostring(chapterData.headerText or '') ~= '' and select(2, suui.fit(tostring(chapterData.headerText or ''), title_w)) then
						imgui.SetTooltip('%s', tostring(chapterData.headerText))
					end
					local px = hp.x + LIST_W - 40 - rw - 16
					suui.box(px, hp.y + 9, rw + 16, 24, suui.alpha(cl.def, picked > 0 and 0.16 or 0.06), picked > 0 and cl.def or cl.line, 12)
					suui.mtext(px + 8, hp.y + 13, right_txt)
					gui.FaText(hp.x + LIST_W - 28, hp.y + 13, open and fa.CARET_DOWN or fa.CARET_RIGHT, fa_font[3], suui.mix(suui.muted(1), cl.def, ck))
					imgui.SetCursorPos(imgui.ImVec2(hp.x, hp.y + HEAD_H))
					imgui.Dummy(imgui.ImVec2(0, 5))

					-- статьи главы
					if ck > 0.02 then
						for ai, article in ipairs(matches) do
							local code = tostring(article.code or '')
							local lo, hi, is_range = suui.parse_pen(article.penalty)
							local selected_item = suui.find_sel(code)
							local sk = suui.approach(suui.selv, code, selected_item and 1 or 0, 8)
							local picker = (suui.range_open == code)
							local pk = suui.approach(suui.hov, 'pk' .. code, picker and 1 or 0, 9)
							local stagger = suui.clamp((ck * (#matches + 3) - ai * 0.5) / 2.5, 0, 1)
							local ra = suui.ease(stagger)
							if ra > 0.01 then
								local ap = imgui.GetCursorPos()
								local slide = (1 - ra) * 10
								imgui.SetCursorPos(imgui.ImVec2(ap.x + slide, ap.y))
								local disabled = hi < 1
								if imgui.InvisibleButton(u8'##su_art' .. index .. '_' .. ai .. code, imgui.ImVec2(RW, ROW_H)) and not disabled then
									if is_range then
										if suui.range_open == code then
											suui.range_open = nil
										else
											suui.range_open = code
										end
									else
										if selected_item then
											suui.remove_sel(code)
										else
											suui.set_sel(article, lo)
										end
										suui.range_open = nil
									end
								end
								local ahov = imgui.IsItemHovered()
								local hv = suui.approach(suui.hov, 'a' .. code, ahov and 1 or 0, 10)
								local amn, amx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
								local adl = imgui.GetWindowDrawList()
								local sevc = sev(math.max(hi, lo))
								local row_bg = suui.mix(cl.main, cl.tab, hv)
								row_bg = suui.mix(row_bg, suui.mix(cl.bg, cl.def, 0.14), sk)
								local bottom_y = amx.y + (46 * pk)
								adl:AddRectFilled(amn, imgui.ImVec2(amx.x, bottom_y), suui.u32(row_bg, ra), 10)
								adl:AddRect(amn, imgui.ImVec2(amx.x, bottom_y), suui.u32(suui.mix(cl.line, cl.def, math.max(sk, pk * 0.6)), ra), 10, 15, 1.2)
								-- полоса тяжести слева (зелёная / жёлтая / красная)
								adl:AddRectFilled(imgui.ImVec2(amn.x + 1, amn.y + 9), imgui.ImVec2(amn.x + 5, amn.y + ROW_H - 9), suui.u32(sevc, ra * (0.55 + 0.45 * math.max(sk, hv))), 2)

								local ico = selected_item and fa.CHECK or (disabled and fa.LOCK or (is_range and fa.ELLIPSIS or fa.PLUS))
								local ico_col = suui.mix(suui.muted(0.9), cl.def, math.max(sk, hv))
								gui.FaText(ap.x + slide + 16, ap.y + 13, ico, fa_font[3], suui.alpha(ico_col, ra))

								-- номер статьи в акцентной плашке
								local badge_w = 76
								suui.box(ap.x + slide + 42, ap.y + 8, badge_w, 26, suui.alpha(cl.def, ra * (0.10 + 0.12 * math.max(sk, hv))), suui.alpha(cl.def, ra * 0.40), 8)
								imgui.PushStyleColor(imgui.Col.Text, suui.alpha(cl.def, ra))
								local code_fit = suui.fit(code, badge_w - 10)
								local cw = imgui.CalcTextSize(code_fit).x
								imgui.SetCursorPos(imgui.ImVec2(ap.x + slide + 42 + (badge_w - cw) / 2, ap.y + 13))
								imgui.Text(code_fit)
								imgui.PopStyleColor(1)

								-- звёзды справа в плашке цвета тяжести
								local star_txt
								if selected_item then
									star_txt = tostring(selected_item.stars)
								elseif is_range then
									star_txt = tostring(lo) .. '-' .. tostring(hi)
								else
									star_txt = tostring(lo)
								end
								local stw = imgui.CalcTextSize(star_txt).x
								local pw = stw + 44
								local pxs = ap.x + slide + RW - 12 - pw
								suui.box(pxs, ap.y + 8, pw, 26, suui.alpha(sevc, ra * 0.14), suui.alpha(sevc, ra * 0.55), 13)
								gui.FaText(pxs + 11, ap.y + 13, fa.STAR, fa_font[2], suui.alpha(suui.mix(suui.muted(0.6), suui.gold(1), math.max(sk, 0.5 + hv * 0.5)), ra))
								imgui.PushStyleColor(imgui.Col.Text, suui.alpha(cl.text, ra))
								imgui.SetCursorPos(imgui.ImVec2(pxs + 31, ap.y + 13))
								imgui.Text(star_txt)
								imgui.PopStyleColor(1)

								-- название (с обрезкой) + подсказка с полным текстом
								local ttl = suui.title(article)
								local ttl_x = ap.x + slide + 128
								local ttl_w = pxs - ttl_x - 10
								local ttl_fit, cut = suui.fit(ttl, ttl_w)
								imgui.PushStyleColor(imgui.Col.Text, suui.alpha(cl.text, ra))
								imgui.SetCursorPos(imgui.ImVec2(ttl_x, ap.y + 13))
								imgui.Text(ttl_fit)
								imgui.PopStyleColor(1)
								if ahov and cut then
									imgui.SetTooltip('%s', tostring(article.text or ''))
								end

								-- панель выбора звёзд для диапазона
								if pk > 0.02 and is_range then
									local py = ap.y + ROW_H - 2
									local ph = 46 * pk
									if ph > 30 then
										suui.mtext(ap.x + slide + 16, py + 5, 'Сколько звёзд:')
										local bx0 = ap.x + slide + 120
										for v = lo, hi do
											local on = selected_item and selected_item.stars == v
											imgui.SetCursorPos(imgui.ImVec2(bx0, py))
											if imgui.InvisibleButton(u8'##su_pen' .. code .. '_' .. v, imgui.ImVec2(52, 28)) then
												suui.set_sel(article, v)
												suui.range_open = nil
											end
											local bh = imgui.IsItemHovered()
											local bk = suui.approach(suui.hov, 'pb' .. code .. v, bh and 1 or 0, 10)
											local fill = on and cl.def or suui.mix(cl.bg, cl.bg2, bk)
											suui.box(bx0, py, 52, 28, suui.alpha(fill, pk), suui.alpha(suui.mix(cl.line, cl.def, math.max(bk, on and 1 or 0)), pk), 14)
											gui.FaText(bx0 + 10, py + 6, fa.STAR, fa_font[2], suui.alpha(on and imgui.ImVec4(1, 1, 1, 1) or suui.gold(1), pk))
											imgui.PushStyleColor(imgui.Col.Text, suui.alpha(on and imgui.ImVec4(1, 1, 1, 1) or cl.text, pk))
											imgui.SetCursorPos(imgui.ImVec2(bx0 + 30, py + 5))
											imgui.Text(tostring(v))
											imgui.PopStyleColor(1)
											bx0 = bx0 + 58
										end
										if selected_item then
											imgui.SetCursorPos(imgui.ImVec2(bx0 + 6, py))
											if imgui.InvisibleButton(u8'##su_penrm' .. code, imgui.ImVec2(84, 28)) then
												suui.remove_sel(code)
												suui.range_open = nil
											end
											local rh = imgui.IsItemHovered()
											local rk = suui.approach(suui.hov, 'prm' .. code, rh and 1 or 0, 10)
											suui.box(bx0 + 6, py, 84, 28, suui.alpha(suui.mix(cl.bg, suui.alpha(RED, 0.3), rk), pk), suui.alpha(suui.mix(cl.line, RED, rk), pk), 14)
											gui.FaText(bx0 + 16, py + 6, fa.TRASH, fa_font[2], suui.alpha(RED, pk))
											imgui.PushStyleColor(imgui.Col.Text, suui.alpha(cl.text, pk))
											imgui.SetCursorPos(imgui.ImVec2(bx0 + 36, py + 5))
											imgui.Text(u8'Убрать')
											imgui.PopStyleColor(1)
										end
									end
								end

								imgui.SetCursorPos(imgui.ImVec2(ap.x, ap.y + ROW_H + (46 * pk)))
								imgui.Dummy(imgui.ImVec2(0, ROW_GAP))
							end
						end
					end
					imgui.Dummy(imgui.ImVec2(0, 6))
				end
			end
			if not drawn_any then
				local cx0 = (LIST_W - 220) / 2
				gui.FaText(LIST_W / 2 - 14, list_h / 2 - 40, fa.MAGNIFYING_GLASS, fa_font[6], suui.muted(0.6))
				gui.Text(cx0 + 38, list_h / 2 + 10, 'Ничего не найдено', bold_font[1])
				suui.mtext(cx0 + 20, list_h / 2 + 34, 'Попробуйте другой номер или слово')
				imgui.Dummy(imgui.ImVec2(0, list_h - 20))
			end
		else
			-- загрузка: три прыгающие точки
			local t = suui.time * 5
			for i = 0, 2 do
				local yy = list_h / 2 - 20 - math.max(0, math.sin(t - i * 0.7)) * 9
				gui.DrawCircle({LIST_W / 2 - 22 + i * 22, yy}, 5, suui.alpha(cl.def, 0.5 + 0.5 * math.max(0, math.sin(t - i * 0.7))))
			end
			gui.Text(LIST_W / 2 - 90, list_h / 2 + 4, 'Загружаю базу статей...', bold_font[1])
			suui.mtext(LIST_W / 2 - 150, list_h / 2 + 30, 'Если база не появляется, проверьте интернет и повторите /su')
			imgui.Dummy(imgui.ImVec2(0, list_h - 20))
		end
		imgui.EndChild()

		winter.finish()
		imgui.End()
		imgui.PopStyleVar(1)
	end
)
