local dep_fmt_names = {
	u8'[ЛСМЦ] - [ЛСПД]:',
	u8'[ЛСМЦ] to [ЛСПД]:',
	u8'к ЛСПД,',
	u8'[Больница ЛС] - [100,3] - [Полиция ЛС]:',
	u8'[Больница ЛС] з.к. [ФБР]:'
}

local dep_fmt_pos_dirty = false
win.dep_fmt = imgui.OnFrame(
	function()
		if not windows.dep_fmt[0] or not setting.dep_mini or scene_active then return false end
		return setting.dep_mini_always or sampIsChatInputActive()
	end,
	function(dep_fmt_win)
		dep_fmt_win.HideCursor = not sampIsChatInputActive()
		local format = setting.adress_format_dep
		if format == nil or format < 1 or format > #dep_fmt_names then format = 1 end
		local rows = 2
		if format == 3 then rows = 1 elseif format == 4 then rows = 3 end
		imgui.PushFont(bold_font[4])
		local calc_label = imgui.CalcTextSize(u8('Формат обращения')).x
		imgui.PopFont()
		imgui.PushFont(font[3])
		local calc_fmt = imgui.CalcTextSize(dep_fmt_names[format]).x
		imgui.PopFont()
		local same_row = 285 - calc_fmt >= 16 + calc_label + 8
		local fmt_y = same_row and 46 or 66
		local shift = same_row and 20 or 0
		local dep_h = 138 + rows * 36 - shift
		if not setting.dep_fmt_pos then
			setting.dep_fmt_pos = { x = 43, y = 334 }
		end
		setting.dep_fmt_pos.x = math.max(0, math.min(setting.dep_fmt_pos.x, sx - 320))
		setting.dep_fmt_pos.y = math.max(0, math.min(setting.dep_fmt_pos.y, sy - dep_h))
		imgui.SetNextWindowPos(imgui.ImVec2(setting.dep_fmt_pos.x, setting.dep_fmt_pos.y), imgui.Cond.FirstUseEver)
		imgui.SetNextWindowSize(imgui.ImVec2(320, dep_h))
		imgui.Begin('Department format', windows.dep_fmt, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
		local wpos = imgui.GetWindowPos()
		if math.abs(wpos.x - setting.dep_fmt_pos.x) > 1 or math.abs(wpos.y - setting.dep_fmt_pos.y) > 1 then
			setting.dep_fmt_pos = { x = wpos.x, y = wpos.y }
			dep_fmt_pos_dirty = true
		end
		if dep_fmt_pos_dirty and not imgui.IsMouseDown(0) then
			dep_fmt_pos_dirty = false
			save()
		end
		gui.Draw({4, 4}, {312, 130 + rows * 36 - shift}, cl.main, 12, 15)
		gui.DrawLine({4, 38}, {316, 38}, cl.line)

		imgui.SetCursorPos(imgui.ImVec2(11, 11))
		if imgui.InvisibleButton('##dep_fmt_close', imgui.ImVec2(20, 20)) then
			windows.dep_fmt[0] = false
		end
		if imgui.IsItemHovered() then
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.30, 0.38, 1.00))
		else
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.40, 0.38, 1.00))
		end

		imgui.SetCursorPos(imgui.ImVec2(288, 9))
		if imgui.InvisibleButton('##dep_fmt_settings', imgui.ImVec2(22, 22)) then
			tab = 'settings'
			name_tab = u8'Главное'
			tab_settings = 16
			if not windows.main[0] then
				open_main()
			end
		end
		gui.FaText(291, 12, fa.GEAR, fa_font[3], imgui.IsItemHovered() and cl.def or cl.text)

		imgui.PushFont(bold_font[1])
		local calc_title = imgui.CalcTextSize(u8('Формат рации'))
		imgui.PopFont()
		gui.Text(160 - (calc_title.x / 2), 21 - (calc_title.y / 2), 'Формат рации', bold_font[1])

		gui.Text(16, 46, 'Формат обращения', bold_font[4])
		local bool_dep_fmt = format
		local new_dep_fmt = gui.ListTableMove({285, fmt_y}, dep_fmt_names, format, 'Select Adress Format Departament Mini')
		if new_dep_fmt ~= bool_dep_fmt then
			setting.adress_format_dep = new_dep_fmt
			save()
			update_text_dep()
		end

		local y = 104 - shift
		if format ~= 3 then
			gui.Text(16, y, 'Ваш тег', bold_font[1])
			local before_my = setting.my_tag_dep
			setting.my_tag_dep = gui.InputText({110, y + 2}, 194, setting.my_tag_dep, u8'Мой тег в рации', 230, u8'Введите Ваш тег')
			if setting.my_tag_dep ~= before_my then
				save()
				update_text_dep()
			end
			y = y + 36
		end
		if format == 4 then
			gui.Text(16, y, 'Волна', bold_font[1])
			local before_wave = setting.wave_tag_dep
			setting.wave_tag_dep = gui.InputText({110, y + 2}, 194, setting.wave_tag_dep, u8'Волна в рации', 230, u8'Введите частоту')
			if setting.wave_tag_dep ~= before_wave then
				save()
				update_text_dep()
			end
			y = y + 36
		end
		gui.Text(16, y, 'Кому', bold_font[1])
		local before_alien = setting.alien_tag_dep
		setting.alien_tag_dep = gui.InputText({110, y + 2}, 194, setting.alien_tag_dep, u8'Тег к обращаемому в рации', 230, u8'Введите тег')
		if setting.alien_tag_dep ~= before_alien then
			save()
			update_text_dep()
		end
		y = y + 36

		gui.Text(16, y + 2, 'Пример:', bold_font[1])
		imgui.PushFont(bold_font[1])
		imgui.SetCursorPos(imgui.ImVec2(90, y + 2))
		imgui.Text(dep_text or '')
		imgui.PopFont()
		imgui.End()
	end
)

