			local seek_x = math.max(0.01, math.min(214.99, imgui.GetMousePos().x - imgui.GetWindowPos().x - 85))
			gui.Draw({85, 65}, {215, 4}, track_color, 20, 15)
			imgui.SetCursorPos(imgui.ImVec2(85, 60))
			imgui.InvisibleButton('##SeekMini', imgui.ImVec2(215, 14))
			if imgui.IsItemActive() then
				mini_seek_active = true
				gui.Draw({85, 65}, {seek_x, 4}, cl.def, 20, 15)
			elseif mini_seek_active then
				mini_seek_active = false
				rewind_song((play.len_time / 215) * seek_x)
				gui.Draw({85, 65}, {seek_x, 4}, cl.def, 20, 15)
			else
				gui.Draw({85, 65}, {(215 / play.len_time) * play.pos_time, 4}, cl.def, 20, 15)
			end
		end

		local name_record = {'Record Dance', 'Megamix', 'Party 24/7', 'Phonk', 'Гоп FM', 'Руки Вверх', 'Dupstep', 'Big Hits', 'Organic', 'Russian Hits'}
		local name_radio = {'Европа Плюс', 'DFM', 'Шансон', 'Радио Дача', 'Дорожное', 'Маяк', 'Наше', 'LoFi Hip-Hop', 'Максимум', '90s Eurodance'}
		imgui.PushFont(font[3])
		if play.tab == 'RECORD' then
			imgui.PushStyleColor(imgui.Col.Text, text_color)
			gui.Text(85, 27, name_record[play.i], font[3])
			imgui.PopStyleColor(1)
			imgui.SetCursorPos(imgui.ImVec2(85, 44))
			imgui.TextColored(secondary_color, u8('Record'))

		elseif play.tab == 'RADIO' then
			imgui.PushStyleColor(imgui.Col.Text, text_color)
			gui.Text(85, 27, name_radio[play.i], font[3])
			imgui.PopStyleColor(1)
			imgui.SetCursorPos(imgui.ImVec2(85, 44))
			imgui.TextColored(secondary_color, u8('Radio'))
		else
			if play.status ~= 'NULL' then
				local track_name, _ = wrapText(play.info.name or '', 30, 30)
				local track_artist, _ = wrapText(play.info.artist or '', 28, 28)
				imgui.PushStyleColor(imgui.Col.Text, text_color)
				gui.Text(85, 19, track_name, font[3])
				imgui.PopStyleColor(1)
				imgui.SetCursorPos(imgui.ImVec2(85, 37))
				imgui.TextColored(secondary_color, u8(track_artist))
			end
		end
		imgui.PopFont()
		do
			local y_pos_button = 75
			local y_pos_icon = 77
			local button_size = imgui.ImVec2(20, 20)
			local icon_offset_x = 2
			local gap_between_buttons = 10
			local slider_width = 80
			local slider_height = 6
			local knob_radius = 6
			local total_width = (button_size.x * 5) + (gap_between_buttons * 4) + slider_width
			local start_x = (318 / 2) - (total_width / 2)
			local current_x = start_x
			imgui.SetCursorPos(imgui.ImVec2(current_x, y_pos_button))
			if imgui.InvisibleButton('##StopTrackMini', button_size) then
				set_song_status('STOP')
			end
			gui.FaText(current_x + icon_offset_x, y_pos_icon, fa.STOP, fa_font[2], icon_color)
			current_x = current_x + button_size.x + gap_between_buttons
			imgui.SetCursorPos(imgui.ImVec2(current_x, y_pos_button))
			if play.tab ~= 'RECORD' and play.tab ~= 'RADIO' and play.i > 1 then
				if imgui.InvisibleButton('##PreviousTrackMini', button_size) then
					back_track()
				end
				gui.FaText(current_x + icon_offset_x, y_pos_icon, fa.BACKWARD_STEP, fa_font[2], icon_color)
			else
				gui.FaText(current_x + icon_offset_x, y_pos_icon, fa.BACKWARD_STEP, fa_font[2], disabled_color)
			end
			current_x = current_x + button_size.x + gap_between_buttons
			imgui.SetCursorPos(imgui.ImVec2(current_x, y_pos_button))
			if imgui.InvisibleButton('##PlayPauseMini', button_size) then
				set_song_status('PLAY_OR_PAUSE')
			end
			local play_icon = (play.status == 'PLAY') and fa.PAUSE or fa.PLAY
			gui.FaText(current_x + icon_offset_x, y_pos_icon, play_icon, fa_font[2], icon_color)
			current_x = current_x + button_size.x + gap_between_buttons
			imgui.SetCursorPos(imgui.ImVec2(current_x, y_pos_button))
			if play.tab ~= 'RECORD' and play.tab ~= 'RADIO' then
				if imgui.InvisibleButton('##NextTrackMini', button_size) then
					next_track(true)
				end
				gui.FaText(current_x + icon_offset_x, y_pos_icon, fa.FORWARD_STEP, fa_font[2], icon_color)
			else
				gui.FaText(current_x + icon_offset_x, y_pos_icon, fa.FORWARD_STEP, fa_font[2], disabled_color)
			end
			current_x = current_x + button_size.x + gap_between_buttons
			local vol_icon
			if play.volume >= 0.7 then
				vol_icon = fa.VOLUME_HIGH
			elseif play.volume >= 0.4 then
				vol_icon = fa.VOLUME
			elseif play.volume >= 0.03 then
				vol_icon = fa.VOLUME_LOW
			else
				vol_icon = fa.VOLUME_SLASH
			end
			imgui.SetCursorPos(imgui.ImVec2(current_x, y_pos_button))
			if imgui.InvisibleButton('##MuteButton', button_size) then
				if play.volume > 0 then
					play.last_volume_before_mute = play.volume
					play.volume = 0
				else
					play.volume = (play.last_volume_before_mute and play.last_volume_before_mute > 0) and play.last_volume_before_mute or 0.5
				end
				volume_song(play.volume)
			end
			gui.FaText(current_x + icon_offset_x, y_pos_icon, vol_icon, fa_font[2], icon_color)
			current_x = current_x + button_size.x
			
			gui.Draw({200, 81}, {slider_width, slider_height}, track_color, 20, 15)
			gui.Draw({200, 81}, {slider_width * play.volume, slider_height}, cl.def, 20, 15)
			gui.DrawCircle({200 + slider_width * play.volume, 81 + slider_height / 2}, knob_radius, text_color)

			imgui.SetCursorPos(imgui.ImVec2(200 - knob_radius, 81 - knob_radius))
			imgui.InvisibleButton('##volume_slider', imgui.ImVec2(slider_width + (knob_radius * 2), slider_height + (knob_radius * 2)))
			
			if imgui.IsItemActive() or (imgui.IsItemHovered() and imgui.IsMouseDown(0)) then
				local mouse_x = imgui.GetMousePos().x - (imgui.GetWindowPos().x + 200)
				local new_volume = math.max(0, math.min(1, mouse_x / slider_width))
				if play.volume ~= new_volume then
					play.volume = new_volume
					volume_song(play.volume)
				end
			end
		end
		winter.finish()
		imgui.End()
	end
)

FAST_MAX = 8
fast_edit = nil
fast_level = nil
fast_was_open = false
fast_aim_x = 0
fast_aim_y = 0
fast_mouse_on = false

local function fast_text(s)
	s = s or ''
	if s == '' then return '' end
	local ok, v = pcall(function() return u8:decode(s) end)
	if ok and type(v) == 'string' then return v end
	return s
end

local function fast_same_cmd(a, b)
	if a == nil or b == nil then return false end
	if a == b then return true end
	local da, db = fast_text(a), fast_text(b)
	return da == b or a == db or da == db
end

local function fast_cmd_entry(name, command, with_id, send_now)
	return {kind = 'cmd', name = name or u8'', cmd = command or u8'', id = with_id ~= false, send = send_now ~= false}
end

local function fast_pack_commands(list)
	return list
end

local function fast_lead_set()
	local set = {}
	for _, command in ipairs(cmd[1] or {}) do
		if command.folder == 5 and command.cmd then
			set[command.cmd] = true
			set[fast_text(command.cmd)] = true
		end
	end
	return set
end

function fast_migrate()
	if setting.fast.wheel_ready and type(setting.fast.wheel) == 'table' then return end
	local lead = fast_lead_set()
	local flat = {}
	for _, list in ipairs({setting.fast.one_win or {}, setting.fast.two_win or {}}) do
		for _, entry in ipairs(list) do
			if type(entry) == 'table' and not lead[entry.cmd] and not lead[fast_text(entry.cmd)] then
				flat[#flat + 1] = fast_cmd_entry(entry.name, entry.cmd, entry.id, entry.send)
			end
		end
	end
	setting.fast.wheel = fast_pack_commands(flat)
	setting.fast.wheel_ready = true
	save()
end

function fast_seed_org()
	fast_migrate()
	if type(setting.fast.wheel) ~= 'table' then setting.fast.wheel = {} end
	setting.fast.wheel_ready = true
end

function fast_editing()
	fast_migrate()
	if fast_edit ~= nil then
		local dir = setting.fast.wheel[fast_edit]
		if type(dir) ~= 'table' or dir.kind ~= 'dir' then
			fast_edit = nil
		else
			dir.items = dir.items or {}
			return dir.items, true, dir
		end
	end
	return setting.fast.wheel, false, nil
end

function fast_reveal_height()
	local list, in_dir = fast_editing()
	local y = in_dir and 186 or 148
	if #list == 0 then y = y + 28 else y = y + #list * 86 end
	return y - 53 + 18
end

function fast_draw_settings()
	local list, in_dir, dir = fast_editing()
	gui.Text(26, 96, 'Секции круга', bold_font[1])
	gui.TextInfo({26, 114}, {'Команда по ЛКМ пишется в чат.', 'Раздел открывает свой круг с командами.'})
	local y = 148
	if in_dir then
		if gui.Button(u8'Назад##fast_dir_back', {26, 148}, {72, 24}) then
			fast_edit = nil
			return
		end
		gui.Text(108, 152, 'Раздел', font[3])
		local prev = dir.name
		dir.name = gui.InputText({168, 152}, 240, dir.name or '', u8'fast-dir-title', 48, u8'Название раздела')
		if dir.name ~= prev then save() end
		y = 186
	end
	if #list == 0 then
		gui.Text(26, y, in_dir and 'В разделе пока нет команд' or 'Круг пуст. Добавьте команду или раздел', font[3])
		return
	end
	for i = 1, #list do
		local entry = list[i]
		if entry.kind ~= 'dir' then
			if entry.id == nil then entry.id = true end
			if entry.send == nil then entry.send = true end
		end
		gui.DrawBox({16, y}, {586, 78}, cl.tab, cl.line, 7, 15)
		gui.Text(26, y + 8, entry.kind == 'dir' and 'Раздел' or 'Команда', font[2])
		local idn = (in_dir and 'd' or 'r') .. i
		local prev_name = entry.name
		entry.name = gui.InputText({96, y + 10}, 200, entry.name or '', u8('fast-name-' .. idn), 48, u8'Название')
		if entry.name ~= prev_name then save() end
		if entry.kind == 'dir' then
			if gui.Button(u8('Открыть##' .. idn), {312, y + 6}, {90, 24}) then
				fast_edit = i
				return
			end
			gui.Text(412, y + 10, tostring(#(entry.items or {})) .. ' команд', font[3])
		else
			local prev_cmd = entry.cmd
			entry.cmd = gui.InputText({312, y + 10}, 260, entry.cmd or '', u8('fast-cmd-' .. idn), 96, u8'Команда, например /me')
			if entry.cmd ~= prev_cmd then save() end
			imgui.SetCursorPos(imgui.ImVec2(26, y + 44))
			if gui.Switch(u8('ID игрока##fast-id-' .. idn), entry.id) then
				entry.id = not entry.id
				save()
			end
			imgui.SetCursorPos(imgui.ImVec2(190, y + 44))
			if gui.Switch(u8('Сразу в чат##fast-send-' .. idn), entry.send) then
				entry.send = not entry.send
				save()
			end
		end
		if gui.Button(u8('Выше##' .. idn), {428, y + 44}, {52, 24}, (i == 1) and true or nil) then
			if i > 1 then
				list[i], list[i - 1] = list[i - 1], list[i]
				save()
			end
		end
		if gui.Button(u8('Ниже##' .. idn), {484, y + 44}, {52, 24}, (i == #list) and true or nil) then
			if i < #list then
				list[i], list[i + 1] = list[i + 1], list[i]
				save()
			end
		end
		if gui.Button(u8('X##' .. idn), {542, y + 44}, {40, 24}) then
			table.remove(list, i)
			save()
			break
		end
		y = y + 86
	end
end

local function fast_blocked(entry)
	if entry.lead then
		local command = entry.lead
		return command.enabled == false or (command.rank or 0) > (setting.rank or 0)
	end
	for c = 1, #(cmd[1] or {}) do
		local command = cmd[1][c]
		if fast_same_cmd(command.cmd, entry.cmd) and (command.rank or 0) > (setting.rank or 0) then
			return true
		end
	end
	return false
end

local function fast_run(entry)
	local player = tostring(fast_id)
	if entry.lead then
		local command = entry.lead
		if command.arg and #command.arg > 1 and command.cmd ~= '' then
			sampSetChatInputEnabled(true)
			sampSetChatInputText('/' .. command.cmd .. ' ' .. player .. ' ')
		else
			cmd_start(command.arg and #command.arg > 0 and player or '', tostring(command.UID) .. command.cmd)
		end
		return
	end
	local raw = entry.cmd or ''
	local plain = fast_text(raw)
	local tr_cmd, other_cmd, uid = false, false, 0
	for c = 1, #(cmd[1] or {}) do
		if fast_same_cmd(cmd[1][c].cmd, raw) or fast_same_cmd(cmd[1][c].cmd, plain) then
			tr_cmd = true
			uid = cmd[1][c].UID
			plain = cmd[1][c].cmd
			break
		end
	end
	if not tr_cmd and setting.command_tabs then
		for c = 1, #setting.command_tabs do
			if setting.command_tabs[c] ~= '' and (fast_same_cmd(setting.command_tabs[c], raw) or fast_same_cmd(setting.command_tabs[c], plain)) then
				other_cmd = true
				plain = setting.command_tabs[c]
				break
			end
		end
	end
	if tr_cmd then
		if entry.send ~= false then
			cmd_start(entry.id and player or '', tostring(uid) .. plain)
		else
			sampSetChatInputEnabled(true)
			sampSetChatInputText('/' .. plain .. ((entry.id and (' ' .. player)) or ''))
		end
	elseif other_cmd then
		start_other_cmd(plain, player)
	else
		local chat = plain
		if chat ~= '' and chat:sub(1, 1) ~= '/' then chat = '/' .. chat end
		if entry.id and tonumber(fast_id) and tonumber(fast_id) >= 0 then
			chat = chat .. ' ' .. player
		end
		if entry.send ~= false then
			sampSendChat(chat)
		else
			sampSetChatInputEnabled(true)
			sampSetChatInputText(chat)
		end
	end
end

local function fast_leadership_items()
	local items = {}
	for _, command in ipairs(cmd[1] or {}) do
		if command.folder == 5 then
			items[#items + 1] = {kind = 'cmd', name = fast_action_name(command.desc), cmd = command.cmd, lead = command}
		end
	end
	return items
end

local function fast_org_key()
	local o = setting.org or 0
	if o >= 1 and o <= 4 then return 'hospital' end
	if o == 5 then return 'driving_school' end
	if o == 6 then return 'government' end
	if o == 7 or o == 8 then return 'army' end
	if o == 9 then return 'fire_department' end
	if o == 10 then return 'jail' end
	if o >= 11 and o <= 15 then return 'police' end
	return 'all'
end

local function fast_allowed_cmds()
	local set = {}
	local function take(list)
		for _, command in ipairs(list or {}) do
			if type(command) == 'table' and type(command.cmd) == 'string' and command.cmd ~= '' then
				set[command.cmd:lower()] = true
			end
		end
	end
	if type(cmd_defoult) == 'table' then
		take(cmd_defoult.all)
		local key = fast_org_key()
		take(cmd_defoult[key])
		if key == 'police' then take(cmd_defoult.government) end
	end
	return set
end

local function fast_builtin_command(cmd_name, allowed)
	if not allowed[cmd_name:lower()] then return nil end
	for _, command in ipairs(cmd[1] or {}) do
		if type(command) == 'table' and command.folder ~= 1 and fast_same_cmd(command.cmd, cmd_name) then
			return command
		end
	end
	return nil
end

