		{id = 'lic', name = 'Лицензии', icon = 'card', cmds = {'licauto', 'licmoto', 'licfly', 'licswim', 'licfish', 'lichunt', 'licdig', 'licgun', 'licmec', 'lictaxi', 'liccrypto', 'licstocks', 'price'}},
