local function fast_menu_pref()
	if type(setting.fast.menu) ~= 'table' then setting.fast.menu = {} end
	local key = fast_org_key()
	local pref = setting.fast.menu[key]
	if type(pref) ~= 'table' then
		pref = {}
		setting.fast.menu[key] = pref
	end
	if type(pref.join) ~= 'table' then pref.join = {} end
	if type(pref.off) ~= 'table' then pref.off = {} end
	return pref, key
end

local function fast_join_target(pref, section_id, org_key)
	local saved = pref.join[section_id]
	if saved ~= nil then return saved end
	if section_id == 'med' and (org_key == 'government' or org_key == 'police') then
		return 'duty'
	end
	return ''
end

local function fast_section_commands(section, allowed)
	local list = {}
	for _, cmd_name in ipairs(section.cmds) do
		local command = fast_builtin_command(cmd_name, allowed)
		if command then
			list[#list + 1] = {cmd = cmd_name, name = fast_action_name(command.desc or command.cmd), lead = command}
		end
	end
	return list
end

local function fast_org_tree()
	local allowed = fast_allowed_cmds()
	local defs = fast_section_defs()
	local pref, org_key = fast_menu_pref()
	local buckets = {}
	for _, section in ipairs(defs) do
		local items = {}
		for _, entry in ipairs(fast_section_commands(section, allowed)) do
			if pref.off[entry.cmd] ~= true then
				items[#items + 1] = {kind = 'cmd', name = entry.name, cmd = entry.lead.cmd, lead = entry.lead}
			end
		end
		buckets[section.id] = items
	end
	local function host_of(id, seen)
		local target = fast_join_target(pref, id, org_key)
		if target == '' or target == 'hide' or target == id or buckets[target] == nil then
			return id, target
		end
		if seen[id] then return id, '' end
		seen[id] = true
		local host, mode = host_of(target, seen)
		if mode == 'hide' then return host, 'hide' end
		return host, 'join'
	end
	local grouped = {}
	for _, section in ipairs(defs) do
		local host, mode = host_of(section.id, {})
		if mode ~= 'hide' then
			if grouped[host] == nil then grouped[host] = {} end
			for _, item in ipairs(buckets[section.id]) do
				grouped[host][#grouped[host] + 1] = item
			end
		end
	end
	local tree = {}
	for _, section in ipairs(defs) do
		local items = grouped[section.id]
		if items and #items > 0 then
			tree[#tree + 1] = {kind = 'dir', name = u8(section.name), icon = section.icon, items = items}
		end
	end
	return tree
end

