	showpassrp = 'id', showmcrp = 'med', showlicrp = 'lic', showworkrp = 'doc', show = 'id', pass = 'id', mc = 'med', visa = 'doc', lic = 'lic', wed = 'users', givemilitary = 'gun', giveplate = 'car',
	cuff = 'cuff', uncuff = 'cuff', frisk = 'search', gotome = 'user', ungotome = 'user', incar = 'car', miranda = 'scale', unmask = 'eye',
	hl = 'med', hlactor = 'med', narko = 'syr', ant = 'syr', cur = 'syr', cure = 'syr', strah = 'lic', mt = 'hosp', osm = 'search', rec = 'doc', hme = 'med',
	z = 'chat', za = 'flag', cam = 'eye', mb = 'users', exp = 'search', agenda = 'doc', freely = 'ban', car = 'car', visit = 'key', uvalgos = 'ban',
	inv = 'user', rank = 'star', uval = 'ban', mutechat = 'ban', unmutechat = 'mega', warnorg = 'bell', unwarnorg = 'bell'
}

function FAST_UI.greeting_icon(entry)
	return entry.kind == 'cmd' and fast_same_cmd(entry.cmd, 'z')
		and (entry.icon == nil or entry.icon == 'flag' or entry.icon == 'chat')
end

function FAST_UI.glyph(entry)
	if FAST_UI.greeting_icon(entry) then return FAST_UI.MAP.chat end
	local key = entry.icon
	key = FAST_UI.LEGACY[key] or key
	if key == nil or FAST_UI.MAP[key] == nil then
		key = (entry.kind == 'dir' and 'dir') or (entry.kind == 'page' and 'next') or 'cmd'
	end
	return FAST_UI.MAP[key]
end

-- стартовый список: то, что раньше собиралось автоматически, теперь копируется и редактируется
function FAST_UI.seed()
	local out = {}
	for _, d in ipairs(fast_org_tree()) do
		local dir_icon = FAST_UI.LEGACY[d.icon] or d.icon or 'dir'
		local dir = {kind = 'dir', name = d.name, icon = dir_icon, items = {}}
		for _, it in ipairs(d.items or {}) do
			local c = it.lead or {}
			local plain = fast_text(it.cmd or '')
			dir.items[#dir.items + 1] = {
				kind = 'cmd', name = it.name, cmd = it.cmd,
				id = (c.arg ~= nil and #c.arg > 0) and true or false,
				send = not (c.arg ~= nil and #c.arg > 1),
				icon = FAST_UI.CMD_ICON[plain] or dir_icon
			}
		end
		out[#out + 1] = dir
	end
	return out
end

-- Upgrade saved wheels in memory, including settings written back by an older running script.
function FAST_UI.migrate_show(slot, key)
	local f = setting.fast
	if type(f.show_documents_split_version) ~= 'table' then f.show_documents_split_version = {} end
	if f.show_documents_split_version[key] == 2 then return false end
	local specs = {{'showpassrp','Паспорт','id'},{'showmcrp','Медкарта','med'},{'showlicrp','Лицензии','lic'},{'showworkrp','Трудовая книжка','doc'}}
	local available, seen = {}, {}
	for _, c in ipairs(cmd[1]) do available[c.cmd] = c.enabled ~= false end
	for _, spec in ipairs(specs) do if not available[spec[1]] then return false end end
	local function collect(list)
		for _, item in ipairs(list) do
			if item.kind == 'dir' and type(item.items) == 'table' then collect(item.items)
			elseif type(item.cmd) == 'string' then seen[item.cmd:gsub('^/','')] = true end
		end
	end
	collect(slot)
	local function walk(list)
		local i = 1
		while i <= #list do
			local item = list[i]
			if item.kind == 'dir' and type(item.items) == 'table' then walk(item.items)
			elseif type(item.cmd) == 'string' and item.cmd:gsub('^/','') == 'show' then
				table.remove(list,i)
				for _, spec in ipairs(specs) do if not seen[spec[1]] then
					local entry = deep_copy(item)
					entry.kind, entry.cmd, entry.name, entry.icon = 'cmd', spec[1], u8(spec[2]), spec[3]
					entry.id, entry.send = true, true
					table.insert(list,i,entry); i = i + 1; seen[spec[1]] = true
				end end
				i = i - 1
			end
			i = i + 1
		end
	end
	walk(slot)
	f.show_documents_split_version[key] = 2
	return true
end

function FAST_UI.tree()
	local f = setting.fast
	if type(f.by_org) ~= 'table' then f.by_org = {} end
	local key = fast_org_key()
	if FAST_UI.bound ~= key then
		FAST_UI.bound = key
		FAST_UI.edit = nil
		FAST_UI.pick = nil
	end
	local slot = f.by_org[key]
	if type(slot) ~= 'table' then
		if not f.wheel_imported and type(f.wheel) == 'table' and #f.wheel > 0 then
			slot = deep_copy(f.wheel)
			f.wheel_imported = true
		else
			slot = FAST_UI.seed()
		end
		if #slot == 0 then return slot end
		f.by_org[key] = slot
		save()
	end
	if FAST_UI.migrate_show(slot, key) then save() end
	-- Add new finance licenses once to an already customized CL wheel.
	if key == 'driving_school' and not f.finance_licenses_added then
		local licenses
		for _, entry in ipairs(slot) do
			if entry.kind == 'dir' and type(entry.items) == 'table' then
				if entry.name == u8'Лицензии' then licenses = entry end
				for _, item in ipairs(entry.items) do
					if item.cmd == 'licauto' or item.cmd == 'licmauto' or item.cmd == 'lictaxi' then licenses = entry end
				end
			end
		end
		if not licenses then
			licenses = {kind = 'dir', name = u8'Лицензии', icon = 'lic', items = {}}
			slot[#slot + 1] = licenses
		end
		for _, info in ipairs({{'liccrypto', u8'Криптовалюта'}, {'licstocks', u8'Торговля акциями'}}) do
			local exists = false
			for _, item in ipairs(licenses.items) do if item.cmd == info[1] then exists = true end end
			if not exists then
				local index = #licenses.items + 1
				for i, item in ipairs(licenses.items) do if item.cmd == 'price' then index = i; break end end
				table.insert(licenses.items, index, {kind = 'cmd', name = info[2], cmd = info[1], icon = 'id', id = true, send = true})
			end
		end
		f.finance_licenses_added = true
		save()
	end
	f.custom = slot
	f.custom_ready = true
	return slot
end

function fast_draw_menu_settings(top)
	local tree = FAST_UI.tree()
	local cur = FAST_UI.edit
	local dir = cur and tree[cur] or nil
	if cur and (type(dir) ~= 'table' or dir.kind ~= 'dir') then
		FAST_UI.edit = nil
		cur = nil
		dir = nil
	end
	if dir and type(dir.items) ~= 'table' then dir.items = {} end
	local list = dir and dir.items or tree
	local now = os.clock()
	if FAST_UI.page_list ~= list then
		FAST_UI.page_started = FAST_UI.page_list and now or nil
		FAST_UI.page_list = list
	end
	FAST_UI.appear = FAST_UI.appear or {}
	for entry, started in pairs(FAST_UI.appear) do
		if now - started >= 0.22 then FAST_UI.appear[entry] = nil end
	end
	local function appear_progress(started)
		local t = started and math.max(0, math.min(1, (now - started) / 0.22)) or 1
		return 1 - (1 - t) ^ 3
	end
	local page_progress = appear_progress(FAST_UI.page_started)
	if FAST_UI.delete and (FAST_UI.delete.list ~= list or os.clock() - FAST_UI.delete.time >= 3) then
		FAST_UI.delete = nil
	end
	local left, right = 26, 592
	local row_h = 78
	local list_top = top + 78
	local list_block = (#list == 0) and 36 or (#list * (row_h + 6) + 8)
	local box_h = (list_top - top) + list_block + 14
	local function fast_btn(label, pos, size, kind, disabled)
		imgui.SetCursorPos(imgui.ImVec2(pos[1], pos[2]))
		local hit = imgui.InvisibleButton(label, imgui.ImVec2(size[1], size[2])) and not disabled
		local hot = imgui.IsItemHovered() and not disabled
		local down = imgui.IsItemActive() and not disabled
		local fill, textc, border
		if disabled then
			fill = imgui.ImVec4(cl.bg.x, cl.bg.y, cl.bg.z, 0.4)
			textc = imgui.ImVec4(cl.text.x, cl.text.y, cl.text.z, 0.35)
			border = imgui.ImVec4(cl.line.x, cl.line.y, cl.line.z, 0.45)
		elseif kind == 'go' then
			fill = cl.def
			textc = imgui.ImVec4(0.98, 0.98, 0.98, 1)
			border = nil
		elseif kind == 'danger' then
			fill = imgui.ImVec4(0.42, 0.14, 0.16, down and 1 or (hot and 1 or 0.92))
			textc = imgui.ImVec4(1, 0.9, 0.9, 1)
			border = imgui.ImVec4(0.82, 0.28, 0.32, 1)
		else
			fill = down and cl.def or cl.bg
			textc = down and imgui.ImVec4(0.98, 0.98, 0.98, 1) or cl.text
			border = (hot or down) and cl.def or cl.line
		end
		imgui.SetCursorPos(imgui.ImVec2(0, 0))
		local p = imgui.GetCursorScreenPos()
		local bdl = imgui.GetWindowDrawList()
		local x1, y1 = p.x + pos[1], p.y + pos[2]
		bdl:AddRectFilled(imgui.ImVec2(x1, y1), imgui.ImVec2(x1 + size[1], y1 + size[2]), imgui.GetColorU32Vec4(fill), 5, 15)
		if border then
			bdl:AddRect(imgui.ImVec2(x1, y1), imgui.ImVec2(x1 + size[1], y1 + size[2]), imgui.GetColorU32Vec4(border), 5, 15, 1)
		end
		local shown = label
		local mark = shown:find('##', 1, true)
		if mark then shown = shown:sub(1, mark - 1) end
		imgui.PushStyleColor(imgui.Col.Text, textc)
		imgui.PushFont(font[3])
		local calc = imgui.CalcTextSize(shown)
		imgui.SetCursorPos(imgui.ImVec2(pos[1] + (size[1] - calc.x) / 2, pos[2] + (size[2] - calc.y) / 2))
		imgui.Text(shown)
		imgui.PopFont()
		imgui.PopStyleColor()
		return hit
	end
	new_draw(top, box_h)
	local btn_y = top + 12
	local x_reset, w_reset = right - 96, 96
	local x_sec, w_sec = x_reset - 8 - 108, 108
	local x_cmd, w_cmd = (dir and (x_reset - 8 - 116) or (x_sec - 8 - 116)), 116
	if dir then
		if fast_btn(u8'Назад##fastc_back', {left, btn_y}, {72, 25}, 'soft') then
			FAST_UI.edit = nil
			return
		end
		local title = fast_text(dir.name)
		local title_max = x_cmd - (left + 82) - 12
		imgui.PushFont(bold_font[1])
		local cut = false
		while #title > 1 and imgui.CalcTextSize(u8(title) .. (cut and u8'...' or '')).x > title_max do
			title = title:sub(1, -2)
			cut = true
		end
		imgui.PopFont()
		if cut then title = title .. '...' end
		gui.Text(left + 82, btn_y + 4, title, bold_font[1])
	else
		gui.Text(left, btn_y + 4, 'Круговое меню', bold_font[1])
	end
	if #list < FAST_UI.CAP then
		if fast_btn(u8'+ Команда##fastc_addc', {x_cmd, btn_y}, {w_cmd, 25}, 'go') then
			list[#list + 1] = {kind = 'cmd', name = u8'Новая команда', cmd = u8'', id = true, send = true, icon = dir and dir.icon or 'cmd'}
			FAST_UI.appear[list[#list]] = now
			save()
		end
		if not dir and fast_btn(u8'+ Раздел##fastc_addd', {x_sec, btn_y}, {w_sec, 25}, 'go') then
			list[#list + 1] = {kind = 'dir', name = u8'Новый раздел', icon = 'dir', items = {}}
			FAST_UI.appear[list[#list]] = now
			save()
		end
	end
	local asking = FAST_UI.ask and os.clock() - FAST_UI.ask < 3
	if fast_btn((asking and u8'Точно?' or u8'Сбросить') .. u8'##fastc_reset', {x_reset, btn_y}, {w_reset, 25}, asking and 'danger' or 'soft') then
		if asking then
			local fresh = FAST_UI.seed()
			local key = fast_org_key()
			if type(setting.fast.by_org) ~= 'table' then setting.fast.by_org = {} end
			setting.fast.by_org[key] = fresh
			setting.fast.custom = fresh
			setting.fast.custom_ready = true
			FAST_UI.edit = nil
			FAST_UI.ask = nil
			save()
			return
		end
		FAST_UI.ask = os.clock()
	end
	gui.Text(left, top + 50, 'Размер круга', font[3])
	local size_now = setting.fast.size or 100
	local size_new = gui.SliderBar('##fastc_size', size_now, 60, 140, 370, {156, top + 47})
	if math.abs(size_new - size_now) >= 1 then
		setting.fast.size = math.floor(size_new + 0.5)
		FAST_UI.size_text = tostring(setting.fast.size)
		FAST_UI.dirty = true
	end
	if not FAST_UI.size_text then FAST_UI.size_text = tostring(setting.fast.size or 100) end
	local entered
	FAST_UI.size_text, entered = gui.InputText({right - 70, top + 50}, 42, FAST_UI.size_text, u8'fastc_size_input', 4, nil, 'num')
	if entered or imgui.IsItemDeactivatedAfterEdit() then
		setting.fast.size = math.max(60, math.min(140, tonumber(FAST_UI.size_text) or size_now))
		FAST_UI.size_text = tostring(setting.fast.size)
		FAST_UI.dirty = true
	end
	gui.Text(right - 12, top + 50, '%', font[3])
	if FAST_UI.dirty and not imgui.IsMouseDown(0) then
		FAST_UI.dirty = nil
		save()
	end
	local dl = imgui.GetWindowDrawList()
	local row_w = right - left
	if #list == 0 then
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, imgui.GetStyle().Alpha * page_progress)
		gui.Text(left, list_top + 8 + (1 - page_progress) * 12, dir and 'В разделе пока нет команд' or 'Круг пуст. Добавьте команду или раздел', font[3])
		imgui.PopStyleVar()
	end
	local open_at = nil
	local y = 0
	local card_w = row_w
	local col2, edge = 282, card_w - 18
	local x_up, x_down, x_del = col2, 346, edge - 128
	local plate = imgui.ImVec4(cl.def.x, cl.def.y, cl.def.z, 0.28)
	gui.ActionMoveFrame(list)
	local offsets = {}
	for i, entry in ipairs(list) do
		offsets[i] = gui.ActionMoveOffset(entry, (i - 1) * (row_h + 6))
	end
	for i = 1, #list do
		local entry = list[i]
		local is_dir = entry.kind == 'dir'
		local idn = (cur or 0) .. '_' .. i
		local progress = page_progress * appear_progress(FAST_UI.appear[entry])
		local oy = list_top + y + offsets[i] + (1 - progress) * 12
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, imgui.GetStyle().Alpha * progress)
		imgui.SetCursorPos(imgui.ImVec2(left, oy))
		local p0 = imgui.GetCursorScreenPos()
		dl:AddRectFilled(p0, imgui.ImVec2(p0.x + card_w, p0.y + row_h), imgui.GetColorU32Vec4(cl.main), 6)
		dl:AddRect(p0, imgui.ImVec2(p0.x + card_w, p0.y + row_h), imgui.GetColorU32Vec4(cl.line), 6)
		local icon_y = oy + 12
		imgui.SetCursorPos(imgui.ImVec2(left + 16, icon_y))
		local icon_p = imgui.GetCursorScreenPos()
		local icon_hit = imgui.InvisibleButton(u8'##fi' .. idn, imgui.ImVec2(28, 26))
		dl:AddRectFilled(icon_p, imgui.ImVec2(icon_p.x + 28, icon_p.y + 26), imgui.GetColorU32Vec4(plate), 5)
		imgui.PushFont(fa_font[4])
		local glyph = FAST_UI.glyph(entry)
		local gs = imgui.CalcTextSize(glyph)
		dl:AddText(imgui.ImVec2(icon_p.x + (28 - gs.x) / 2, icon_p.y + (26 - gs.y) / 2), imgui.GetColorU32Vec4(cl.text), glyph)
		imgui.PopFont()
		if icon_hit then
			FAST_UI.pick = entry
			imgui.OpenPopup(u8'##fast_icon_pick')
		end
		local prev = entry.name
		entry.name = gui.InputText({left + 61, oy + 19}, 200, entry.name or '', u8('fastc-n-' .. idn), 48, u8'Название')
		if entry.name ~= prev then save() end
		local act_y = oy + 44
		if is_dir then
			if fast_btn(u8('Открыть раздел##fastc-o' .. idn), {left + col2, icon_y}, {edge - col2, 26}, 'go') then
				open_at = i
			end
		else
			if entry.id == nil then entry.id = true end
			if entry.send == nil then entry.send = true end
			local prev_cmd = entry.cmd
			entry.cmd = gui.InputText({left + 287, oy + 19}, 252, entry.cmd or '', u8('fastc-c-' .. idn), 96, u8'Команда')
			if entry.cmd ~= prev_cmd then save() end
			imgui.SetCursorPos(imgui.ImVec2(left + 16, act_y))
			if gui.Switch(u8('ID##fastc-id-' .. idn), entry.id) then
				entry.id = not entry.id
				save()
			end
			imgui.SetCursorPos(imgui.ImVec2(left + 96, act_y))
			if gui.Switch(u8('В чат##fastc-s-' .. idn), entry.send) then
				entry.send = not entry.send
				save()
			end
		end
		if fast_btn(u8('Выше##fastc-u' .. idn), {left + x_up, act_y}, {58, 26}, 'soft', i == 1) then
			gui.StartActionMove()
			list[i], list[i - 1] = list[i - 1], list[i]
			save()
			imgui.PopStyleVar()
			break
		end
		if fast_btn(u8('Ниже##fastc-d' .. idn), {left + x_down, act_y}, {58, 26}, 'soft', i == #list) then
			gui.StartActionMove()
			list[i], list[i + 1] = list[i + 1], list[i]
			save()
			imgui.PopStyleVar()
			break
		end
		local deleting = FAST_UI.delete and FAST_UI.delete.entry == entry
		if fast_btn((deleting and u8'Точно?' or u8'Удалить') .. '##fastc-x' .. idn, {left + x_del, act_y}, {128, 26}, 'danger') then
			if deleting then
				table.remove(list, i)
				FAST_UI.delete = nil
				save()
				imgui.PopStyleVar()
				break
			end
			FAST_UI.delete = {list = list, entry = entry, time = os.clock()}
		end
		imgui.PopStyleVar()
		y = y + row_h + 6
	end
	if imgui.BeginPopup(u8'##fast_icon_pick') then
		local target = FAST_UI.pick
		for n, item in ipairs(FAST_UI.ICONS) do
			imgui.PushFont(fa_font[4])
			local chosen = imgui.Button(item[2] .. '##ip' .. item[1], imgui.ImVec2(34, 30))
			imgui.PopFont()
			if chosen then
				if target then target.icon = item[1] save() end
				imgui.CloseCurrentPopup()
			end
			if n % 9 ~= 0 and n < #FAST_UI.ICONS then imgui.SameLine() end
		end
		imgui.EndPopup()
	end
	imgui.SetCursorPos(imgui.ImVec2(0, top + box_h + 8))
	imgui.Dummy(imgui.ImVec2(1, 1))
	if open_at then FAST_UI.edit = open_at end
end

local function fast_menu_slots()
	local tree = FAST_UI.tree()
	fast_tree = tree
	local list = tree
	if fast_level ~= nil then
		local dir = tree[fast_level]
		if type(dir) ~= 'table' or dir.kind ~= 'dir' then
			fast_level = nil
			return fast_menu_slots()
		end
		list = dir.items or {}
	end
	local slots = {}
	local room = 8
	local pages = 1
	if #list > 8 then
		room = 7
		pages = math.ceil(#list / room)
	end
	local page = fast_page or 0
	if page < 0 then page = 0 end
	if page > pages - 1 then page = pages - 1 end
	fast_page = page
	fast_pages = pages
	local from = page * room + 1
	local to = math.min(#list, from + room - 1)
	for i = from, to do
		slots[#slots + 1] = {ref = list[i], index = i}
	end
	if pages > 1 then
		slots[#slots + 1] = {ref = {kind = 'page', name = u8('Ещё ' .. (page + 1) .. '/' .. pages), icon = 'next'}, index = 'page'}
	end
	return slots
end

local fast_short_rules = {
	{'[Пп]родать лицензию на ', 'Лиц. '},
	{'[Вв]ыдать лицензию на ', 'Лиц. '},
	{'[Пп]родать лицензию ', 'Лиц. '},
	{'[Лл]ицензию на ', 'Лиц. '},
	{'[Лл]ицензия на ', 'Лиц. '},
	{'вождение автомобиля', 'авто'},
	{'вождение мотоцикла', 'мото'},
	{'вождение', 'вожд.'},
	{'рыболовство', 'рыбалку'},
	{'[Пп]оказать игроку свои ', 'Показать '},
	{'[Пп]оказать игроку ', 'Показать '},
	{'[Пп]редложить игроку ', 'Предл. '},
	{'[Пп]редложить ', 'Предл. '},
	{'документы', 'докум.'},
	{'[Нн]а территории ', ''},
	{'организации', 'орг.'},
	{'пользоваться ', 'польз. '},
	{'автомобиля', 'авто'},
	{'мотоцикла', 'мото'}
}
local function fast_short(value)
	for i = 1, #fast_short_rules do
		value = value:gsub(fast_short_rules[i][1], fast_short_rules[i][2])
	end
	return value
end

local function fast_fit(raw, max_w, used_font, short)
	local value = fast_text(raw)
	if short then value = fast_short(value) end
	value = (value:match('^%s*(.-)%s*$')) or ''
	if value == '' then value = '...' end
	imgui.PushFont(used_font)
	local cut = false
	while #value > 1 and imgui.CalcTextSize(u8(value) .. (cut and u8'...' or '')).x > max_w do
		value = value:sub(1, -2)
		cut = true
	end
	imgui.PopFont()
	if cut then return u8(value) .. u8'...' end
	return u8(value)
end

local function fast_annulus(dl, cx, cy, r0, r1, a0, a1, col)
	local segs = math.max(8, math.floor((a1 - a0) * 16))
	dl:PathClear()
	dl:PathArcTo(imgui.ImVec2(cx, cy), r1, a0, a1, segs)
	dl:PathArcTo(imgui.ImVec2(cx, cy), r0, a1, a0, segs)
	dl:PathFillConvex(col)
end

local function fast_u32(v)
	return imgui.GetColorU32Vec4(v)
end

win.fast = imgui.OnFrame(
	function()
		if not windows.fast[0] then
			fast_was_open = false
			FAST_UI.closing = nil
			FAST_UI.pending = nil
			fast_level = nil
		end
		return windows.fast[0] and not scene_active
	end,
	function(fast)
		fast.HideCursor = false
		fast.LockPlayer = false
		if FAST_UI.closing then
			-- ждём отпускания кнопок мыши, только потом прячем курсор и запускаем команду
			if (not imgui.IsMouseDown(0) and not imgui.IsMouseDown(1)) or os.clock() - FAST_UI.closing > 0.6 then
				FAST_UI.closing = nil
				windows.fast[0] = false
				local picked = FAST_UI.pending
				FAST_UI.pending = nil
				if picked then
					lua_thread.create(function()
						wait(150)
						local now_run = os.clock()
						if not FAST_UI.last_run or now_run - FAST_UI.last_run > 0.35 then
							FAST_UI.last_run = now_run
							local ok_run, err_run = pcall(fast_run, picked)
							if not ok_run then print('[SH] fast_run: ' .. tostring(err_run)) end
						end
					end)
				end
			end
			return
		end
		local cx, cy = sx / 2, sy / 2
		if not fast_was_open then
			FAST_UI.closing = nil
			FAST_UI.pending = nil
			fast_was_open = true
			fast_level = nil
			fast_page = 0
			fast_pop = 0
			fast_weights = {}
			fast_skip_lmb = imgui.IsMouseDown(0)
			fast_skip_rmb = imgui.IsMouseDown(1)
		end
		local mouse = imgui.GetIO().MousePos
		local aim_x = mouse.x - cx
		local aim_y = mouse.y - cy
		local aim_len = math.sqrt(aim_x * aim_x + aim_y * aim_y)
		local slots = fast_menu_slots()
		local count = #slots
		local scale_k = math.max(0.6, math.min(1.4, (setting.fast.size or 100) / 100))
		local radius = math.min(214, sx * 0.2, sy * 0.27) * scale_k
		local hub = 62 * math.max(0.9, scale_k)
		local hover = 0
		if count > 0 and aim_len >= 38 then
			local drag_angle = math.atan2(aim_y, aim_x)
			local ang = drag_angle + math.pi / 2
			while ang < 0 do ang = ang + math.pi * 2 end
			while ang >= math.pi * 2 do ang = ang - math.pi * 2 end
			hover = math.floor(ang / (math.pi * 2 / count)) + 1
			if hover < 1 or hover > count then hover = 0 end
		end
		imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
		imgui.SetNextWindowSize(imgui.ImVec2(sx, sy), imgui.Cond.Always)
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, 1.0)
		imgui.Begin('Fast win 1', windows.fast, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoSavedSettings + imgui.WindowFlags.NoBackground + imgui.WindowFlags.NoMove)
		local dl = imgui.GetWindowDrawList()
		local now = os.clock()
		local dt = math.min(0.05, now - (fast_clock or now))
		fast_clock = now
		fast_pop = math.min(1, (fast_pop or 0) + dt * 6.5)
		local pop = fast_pop * fast_pop * (3 - 2 * fast_pop)
		local wheel = radius * (0.92 + 0.08 * pop)
		local function tint(col, a)
			return imgui.ImVec4(col.x, col.y, col.z, a)
		end
		local function mixc(a, b, t)
			return imgui.ImVec4(a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t, a.z + (b.z - a.z) * t, a.w + (b.w - a.w) * t)
		end
		local white = imgui.ImVec4(0.98, 0.98, 0.98, 1)
		local function arc(r, a0, a1, col, thick)
			dl:PathClear()
			dl:PathArcTo(imgui.ImVec2(cx, cy), r, a0, a1, math.max(10, math.floor(math.abs(a1 - a0) * 30)))
			dl:PathStroke(fast_u32(col), false, thick)
			dl:PathClear()
		end
		fast_weights = fast_weights or {}
		for i = 1, count do
			local target = (i == hover) and 1 or 0
			local w = fast_weights[i] or 0
			fast_weights[i] = w + (target - w) * math.min(1, dt * 16)
		end
		for i = count + 1, #fast_weights do fast_weights[i] = nil end
		local span = (count > 0) and (math.pi * 2 / count) or 0
		local center = imgui.ImVec2(cx, cy)
		local r_out = wheel
		local rmid = (hub + r_out) / 2
		local half = 1.5
		local function sector(a0, a1, ro, col)
			local sp = a1 - a0
			local mid = (a0 + a1) / 2
			local apex = half / math.sin(sp / 2)
			local d = math.asin(math.min(1, half / ro))
			local s0, s1 = a0 + d, a1 - d
			local n = math.max(8, math.floor((s1 - s0) * 26))
			dl:PathClear()
			dl:PathLineTo(imgui.ImVec2(cx + math.cos(mid) * apex, cy + math.sin(mid) * apex))
			for k = 0, n do
				local t = s0 + (s1 - s0) * k / n
				dl:PathLineTo(imgui.ImVec2(cx + math.cos(t) * ro, cy + math.sin(t) * ro))
			end
			dl:PathFillConvex(fast_u32(col))
			dl:PathClear()
		end
		for i = 1, count do
			local entry = slots[i].ref
			local blocked = entry.kind ~= 'dir' and entry.kind ~= 'page' and fast_blocked(entry)
			local w = fast_weights[i] or 0
			local col = tint(cl.bg, 0.68)
			if not blocked and w > 0.01 then col = mixc(col, tint(cl.def, 0.68), w) end
			local ro = r_out + 7 * w
			if count == 1 then
				dl:AddCircleFilled(center, ro, fast_u32(col), 96)
			else
				local a0 = -math.pi / 2 + (i - 1) * span
				sector(a0, a0 + span, ro, col)
			end
		end
		for i = 1, count do
			local entry = slots[i].ref
			local mid = (count == 1) and -math.pi / 2 or (-math.pi / 2 + (i - 0.5) * span)
			local w = fast_weights[i] or 0
			local selected = w > 0.45
			local blocked = entry.kind ~= 'dir' and entry.kind ~= 'page' and fast_blocked(entry)
			local rr = rmid + 3 * w
			local px = cx + math.cos(mid) * rr
			local py = cy + math.sin(mid) * rr
			local max_w = math.max(64, math.min(150, 2 * math.sin(math.max(span, 0.45) * 0.42) * rr))
			local used_font = selected and bold_font[1] or font[3]
			local label = fast_fit(entry.name, max_w, used_font, true)
			local text_col = blocked and tint(cl.text, 0.52) or (selected and white or cl.text)
			local icon_col = blocked and tint(cl.text, 0.52) or (selected and white or tint(cl.text, 0.92))
			local glyph = FAST_UI.glyph(entry)
			local icy = py - 10 - 2 * w
			imgui.PushFont(fa_font[5])
			local gs = imgui.CalcTextSize(glyph)
			dl:AddText(imgui.ImVec2(px - gs.x / 2, icy - gs.y / 2), fast_u32(icon_col), glyph)
			imgui.PopFont()
			imgui.PushFont(used_font)
			local size = imgui.CalcTextSize(label)
			local lx = px - size.x / 2
			local ly = py + 9
			dl:AddText(imgui.ImVec2(lx, ly), fast_u32(text_col), label)
			imgui.PopFont()
			if entry.kind == 'dir' then
				imgui.PushFont(fa_font[2])
				dl:AddText(imgui.ImVec2(lx + size.x + 3, ly + 1), fast_u32(tint(text_col, 0.75)), fa.ANGLE_RIGHT)
				imgui.PopFont()
			end
		end
		for i = 1, count do
			local w = fast_weights[i] or 0
			if w > 0.02 and count > 1 then
				local a0 = -math.pi / 2 + (i - 1) * span
				arc(r_out + 7 * w + 3, a0 + 0.03, a0 + span - 0.03, tint(cl.def, w), 2.2)
			end
		end
		dl:AddCircleFilled(center, hub, fast_u32(cl.tab), 64)
		dl:AddCircle(center, hub, fast_u32(tint(cl.line, 0.9)), 64, 1.5)
		if hover > 0 then
			local mid = (count == 1) and -math.pi / 2 or (-math.pi / 2 + (hover - 0.5) * span)
			local sweep = math.max(0.35, span * 0.42)
			arc(hub - 3, mid - sweep, mid + sweep, cl.def, 2.6)
		end
		local title, subtitle = 'Быстрый доступ', ''
		if count == 0 then
			title = 'Пусто'
			subtitle = 'добавьте в настройках'
		elseif hover > 0 then
			local entry = slots[hover].ref
			title = fast_text(entry.name)
			if title == '' then title = 'Без названия' end
			if entry.kind == 'page' then
				subtitle = 'следующая страница'
			elseif entry.kind == 'dir' then
				subtitle = tostring(#(entry.items or {})) .. ' команд'
			elseif fast_blocked(entry) then
				subtitle = 'недоступно'
			else
				local preview = fast_text(entry.cmd or '')
				if preview ~= '' and preview:sub(1, 1) ~= '/' and not entry.lead then preview = '/' .. preview end
				subtitle = preview
			end
		elseif fast_level ~= nil then
			local dir = fast_tree and fast_tree[fast_level]
			title = dir and fast_text(dir.name) or 'Раздел'
			if title == '' then title = 'Раздел' end
			subtitle = 'назад'
		end
		imgui.PushFont(bold_font[1])
		local title_u = fast_fit(u8(title), hub * 1.7, bold_font[1])
		local title_size = imgui.CalcTextSize(title_u)
		dl:AddText(imgui.ImVec2(cx - title_size.x / 2, cy - (subtitle ~= '' and title_size.y or title_size.y / 2)), fast_u32(cl.text), title_u)
		imgui.PopFont()
		if subtitle ~= '' then
			imgui.PushFont(font[2])
			local sub_u = fast_fit(u8(subtitle), hub * 1.85, font[2])
			local sub_size = imgui.CalcTextSize(sub_u)
			dl:AddText(imgui.ImVec2(cx - sub_size.x / 2, cy + 2), fast_u32(imgui.ImVec4(cl.text.x, cl.text.y, cl.text.z, 0.62)), sub_u)
			imgui.PopFont()
		end
		local player_id = tonumber(fast_id)
		local player_selected = player_id and player_id >= 0 and sampIsPlayerConnected(player_id)
		local player_text = player_selected and (fast_nick .. '  ' .. player_id) or 'игрок не выбран'
		imgui.PushFont(font[2])
		local player_u = u8(player_text)
		local player_size = imgui.CalcTextSize(player_u)
		local chip_w = player_size.x + 18
		local chip_h = player_size.y + 8
		local chip_y = cy - wheel - chip_h - 16
		dl:AddRectFilled(imgui.ImVec2(cx - chip_w / 2, chip_y), imgui.ImVec2(cx + chip_w / 2, chip_y + chip_h), fast_u32(player_selected and cl.def or tint(cl.bg, 0.88)), chip_h / 2)
		dl:AddText(imgui.ImVec2(cx - player_size.x / 2, chip_y + 4), fast_u32(player_selected and imgui.ImVec4(0.98, 0.98, 0.98, 1) or cl.text), player_u)
		local hint = u8'ЛКМ выбрать     ПКМ назад'
		local hint_size = imgui.CalcTextSize(hint)
		dl:AddText(imgui.ImVec2(cx - hint_size.x / 2, cy + wheel + 16), fast_u32(tint(cl.text, 0.72)), hint)
		imgui.PopFont()
		local lmb = imgui.IsMouseClicked(0) and not fast_skip_lmb
		local rmb = imgui.IsMouseClicked(1) and not fast_skip_rmb
		if not imgui.IsMouseDown(0) then fast_skip_lmb = false end
		if not imgui.IsMouseDown(1) then fast_skip_rmb = false end
		local function go_back()
			if fast_level ~= nil then
				fast_level = nil
				fast_page = 0
				fast_pop = 0
				fast_weights = {}
			else
				FAST_UI.closing = os.clock()
			end
		end
		if close_win.fast then
			FAST_UI.closing = os.clock()
			close_win.fast = false
		elseif rmb then
			go_back()
		elseif lmb then
			if hover == 0 then
				if fast_level ~= nil then go_back() end
			else
				local entry = slots[hover] and slots[hover].ref
				if entry == nil then
					--> slot disappeared (command list changed)
				elseif entry.kind == 'page' then
					fast_page = (fast_page or 0) + 1
					if fast_page >= (fast_pages or 1) then fast_page = 0 end
					fast_pop = 0
					fast_weights = {}
				elseif entry.kind == 'dir' then
					fast_level = slots[hover].index
					fast_page = 0
					fast_pop = 0
					fast_weights = {}
				elseif not fast_blocked(entry) then
					FAST_UI.pending = entry
					FAST_UI.closing = os.clock()
				end
			end
		end
		imgui.End()
		imgui.PopStyleVar(1)
	end
)

local action_input_disabled = false
win.action = imgui.OnFrame(
	function()
		local active = windows.action[0] and not scene_active
		if active ~= action_input_disabled then
			action_input_disabled = active
			-- shortcut: all mimgui windows ignore input while the action hint is visible, split the overlay if simultaneous UI input is needed
			imgui.DisableInput = active
		end
		return active
	end,
	function(action)
		action.HideCursor = true
		local size_win = {x = 300, y = 25 + (#dialog_act.info * 24)}
		if dialog_act.enter then
			size_win = {x = 300, y = 39}
		end
		local x_pos = sx - (size_win.x / 2) - 20
		if dialog_act.status then
			if x_act_dialog > x_pos then
				x_act_dialog = x_act_dialog - (anim * 1400)
			elseif x_act_dialog <= x_pos then
				x_act_dialog = x_pos
			end
		else
			if x_act_dialog < (sx + 200) then
				x_act_dialog = x_act_dialog + (anim * 1200)
			else
				windows.action[0] = false
			end
		end
		
		imgui.SetNextWindowPos(imgui.ImVec2(x_act_dialog, sy - (size_win.y / 2) - 20), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
		imgui.SetNextWindowSize(imgui.ImVec2(size_win.x, size_win.y))
		imgui.Begin('Action reminder', windows.action,  imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoSavedSettings + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoInputs + imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoBringToFrontOnFocus)
		gui.Draw({4, 4}, {size_win.x - 4, size_win.y - 4}, imgui.ImVec4(0.10, 0.10, 0.10, 0.70), 12, 15)
		winter.begin(size_win.x, size_win.y, {dark = true})
		winter.mini_front(size_win.x, size_win.y, {dark = true})
		
		imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.96, 0.96, 0.96, 1.00))
		if dialog_act.enter then
			gui.Text(20, 11, 'Нажмите ' .. setting.enter_key[2] .. ', чтобы продолжить', bold_font[1])
		else 
			if dialog_act.info ~= 0 then
				for i = 1, #dialog_act.info do
					if i ~= 10 then
						gui.Text(20, 17 + ((i - 1) * 24), 'NUM ' .. i .. ' - ' .. u8:decode(dialog_act.info[i]), bold_font[1])
					else
						gui.Text(20, 17 + ((i - 1) * 24), 'NUM 0 - ' .. u8:decode(dialog_act.info[i]), bold_font[1])
					end
				end
			end
		end
		imgui.PopStyleColor(1)
		
		winter.finish()
		imgui.End()
	end
)

win.stat = imgui.OnFrame(
	function() return windows.stat[0] and not scene_active end,
	function(stat)
		stat.HideCursor = true
		local size_y_stat = 38
		size_y_stat = size_y_stat + (setting.stat_on_screen.current_time and 21 or 0)
		size_y_stat = size_y_stat + (setting.stat_on_screen.current_date and setting.stat_on_screen.current_time and 24 or setting.stat_on_screen.current_date and 8 or 0)
		local num_stat = 0
		size_y_stat = size_y_stat + (setting.stat_on_screen.day and 7 or 0) + (setting.stat_on_screen.afk and 7 or 0) + (setting.stat_on_screen.all and 7 or 0) + (setting.stat_on_screen.ses_day and 7 or 0) + (setting.stat_on_screen.ses_afk and 7 or 0) + (setting.stat_on_screen.ses_all and 7 or 0)
		num_stat = num_stat  + (setting.stat_on_screen.day and 1 or 0) + (setting.stat_on_screen.afk and 1 or 0) + (setting.stat_on_screen.all and 1 or 0) + (setting.stat_on_screen.ses_day and 1 or 0) + (setting.stat_on_screen.ses_afk and 1 or 0) + (setting.stat_on_screen.ses_all and 1 or 0)
		if num_stat > 0 then
			size_y_stat = size_y_stat + ((num_stat - 1) * 13)
			size_y_stat = size_y_stat + (setting.stat_on_screen.current_time and 17 or setting.stat_on_screen.current_date and 17 or 0)
		end
		
		--[[if setting.stat_on_screen.current_time then
			size_y_stat = size_y_stat + 21
		end]]
		local function format_custom_date()
			local weekdays = {'Воскресенье', 'Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота'}
			local months = {'января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'}

			local current_time = os.date('*t')
			local weekday = weekdays[current_time.wday]
			local month = months[current_time.month]
			local day = current_time.day

			return weekday .. ', ' .. day .. ' ' .. month
		end
		local function format_time(seconds)
			local days = math.floor(seconds / 86400)
			local hours = math.floor((seconds % 86400) / 3600)
			local minutes = math.floor((seconds % 3600) / 60)
			local secs = seconds % 60

			if days > 0 then
				return string.format('%02d д. %02d ч. %02d мин. %02d сек.', days, hours, minutes, secs)
			else
				return string.format('%02d ч. %02d мин. %02d сек.', hours, minutes, secs)
			end
		end
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, (setting.stat_on_screen.visible > 15) and setting.stat_on_screen.visible / 100 or 0.15)
		imgui.SetNextWindowPos(imgui.ImVec2(setting.position_stat.x, setting.position_stat.y), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
		imgui.SetNextWindowSize(imgui.ImVec2(298, size_y_stat + 8))
		imgui.Begin('Stat Online', windows.stat,  imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoBringToFrontOnFocus + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoMove)
		gui.Draw({4, 4}, {290, size_y_stat}, imgui.ImVec4(0.05, 0.05, 0.05, 1.00), 12, 15)
		
		if imgui.IsMouseClicked(0) and change_pos_onstat then
			change_pos_onstat = false 
		end
		
		local pos_pl_stat = 0
		if setting.stat_on_screen.current_time then
			local time_format = os.date('%H:%M:%S')
			imgui.PushFont(bold_font[3])
			local calc_time = imgui.CalcTextSize(time_format)
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(149 - (calc_time.x / 2), 16 + pos_pl_stat, time_format, bold_font[3])
			imgui.PopStyleColor(1)
			imgui.PopFont()
			pos_pl_stat = 38
		end
		if setting.stat_on_screen.current_date then
			local time_format = format_custom_date()
			imgui.PushFont(bold_font[1])
			local calc_date = imgui.CalcTextSize(u8(time_format))
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(149 - (calc_date.x / 2), 16 + pos_pl_stat, time_format, bold_font[1])
			imgui.PopStyleColor(1)
			imgui.PopFont()
			pos_pl_stat = pos_pl_stat + 26
		end
		if setting.stat_on_screen.day then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'Чистый за день: ' .. format_time(setting.stat.cl[1]), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		if setting.stat_on_screen.afk then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'АФК за день: ' .. format_time(setting.stat.afk[1]), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		if setting.stat_on_screen.all then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'Всего за день: ' .. format_time(setting.stat.cl[1] + setting.stat.afk[1]), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		if setting.stat_on_screen.ses_day then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'Чистый за сессию: ' .. format_time(stat_ses.cl), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		if setting.stat_on_screen.ses_afk then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'АФК за сессию: ' .. format_time(stat_ses.afk), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		if setting.stat_on_screen.ses_all then
			imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.00, 1.00, 1.00, 1.00))
			gui.Text(20, 16 + pos_pl_stat, 'Всего за сессию: ' .. format_time(stat_ses.all), font[3])
			imgui.PopStyleColor(1)
			pos_pl_stat = pos_pl_stat + 20
		end
		
		imgui.PopStyleVar(1)
		imgui.End()
	end
)

