--> Прочие функции
function start_other_cmd(cmd_func, arguments)
	if cmd_func == setting.cmd_open_win then
		open_main()
	else
		local tab_open = {'cmd', 'shpora', 'dep', 'sob', 'reminder', 'stat', 'music', 'rp_zona', 'actions', 'help'}
		local tab_name_open = {u8'Команды', u8'Шпаргалки', u8'Департамент', u8'Собеседование', u8'Напоминания', u8'Статистика онлайна', u8'Музыка', u8'РП зона', u8'Действия', u8'Браузер'}
		for i = 1, #setting.command_tabs do
			if setting.command_tabs[i] == cmd_func then
				tab = tab_open[i]
				name_tab = tab_name_open[i]
				if not windows.main[0] then
					open_main()
				end
				if i == 4 and arguments:find('(%d+)') and setting.sob_id_arg then
					local arg_id = arguments:match('(%d+)')
					arg_id = tonumber(arg_id)
					if arg_id ~= nil and (setting.sob.min_exp ~= '' or not setting.sob.auto_exp)
					and (setting.sob.min_law ~= '' or not setting.sob.auto_law)
					and (setting.sob.min_narko ~= '' or not setting.sob.auto_narko) then
						if not sampIsPlayerConnected(arg_id) then
							if not setting.cef_notif then
								sampAddChatMessage("[SH] {FFFFFF}Игрок с таким ID не найден, либо это Вы", 0xFF5345)
							else
								cefnotig("{FF5345}[SH] {FFFFFF}Игрок с таким ID не найден, либо это Вы", 3000)
							end
							windows.main[0] = false
							return
						end
						run_sob = true
						sob_info = {
							exp = -1,
							law = -1,
							narko = -1,
							org = -1,
							med = -1,
							blacklist = -1,
							ticket = -1,
							bilet = -1,
							car = -1,
							moto = -1,
							gun = -1,
							warn = -1,
							bl_info = {},
							org_info = '',
							id = arg_id,
							nick = sampGetPlayerNickname(arg_id),
							history = {}
						}
					end
				end
			end
		end
	end
end

function filter_word_rus(data)
	local code = data.EventChar
	if (code >= 1040 and code <= 1103) or code == 1025 or code == 1105 or code == 32 then
		return 0
	else
		return true
	end
end

function filter_word_en(data)
	if (data.EventChar >= 97 and data.EventChar <= 122) then
	
		return 0
	else
		return true
	end
end

function filter_word_en_num(data)
	if (data.EventChar >= 65 and data.EventChar <= 90) or
		(data.EventChar >= 97 and data.EventChar <= 122) or
		(data.EventChar >= 48 and data.EventChar <= 57) then
	
		return 0
	else
		return true
	end
end

function filter_word_en_rus_num(data)
	local char_code = data.EventChar
	if (char_code >= 1040 and char_code <= 1103) or
		char_code == 1025 or char_code == 1105 or
		(char_code >= 65 and char_code <= 90) or
		(char_code >= 97 and char_code <= 122) or
		(char_code == 32) or
		(char_code >= 48 and char_code <= 57) then

		return 0
	else
		return true
	end
end

function filter_word_en_rus_num_h(data)
	local char_code = data.EventChar
	if (char_code >= 1040 and char_code <= 1103) or
		char_code == 1025 or char_code == 1105 or
		(char_code >= 65 and char_code <= 90) or
		(char_code >= 97 and char_code <= 122) or
		(char_code == 32) or
		(char_code >= 48 and char_code <= 57) or
		(char_code == 45) then
		return 0
	else
		return true
	end
end

TextCallbackEnRusNumH = ffi.cast('int (*)(ImGuiInputTextCallbackData* data)', filter_word_en_rus_num_h)
TextCallbackRus = ffi.cast('int (*)(ImGuiInputTextCallbackData* data)', filter_word_rus)
TextCallbackEn = ffi.cast('int (*)(ImGuiInputTextCallbackData* data)', filter_word_en)
TextCallbackEnNum = ffi.cast('int (*)(ImGuiInputTextCallbackData* data)', filter_word_en_num)
TextCallbackEnRusNum = ffi.cast('int (*)(ImGuiInputTextCallbackData* data)', filter_word_en_rus_num)

function remove_old_org_commands(selected_org, unregister_commands)
	local groups = {
		cmd_defoult.hospital,
		cmd_defoult.driving_school,
		cmd_defoult.government,
		cmd_defoult.army,
		cmd_defoult.fire_department,
		cmd_defoult.jail,
		cmd_defoult.police
	}
	local selected = selected_org <= 4 and cmd_defoult.hospital
		or selected_org == 5 and cmd_defoult.driving_school
		or selected_org == 6 and cmd_defoult.government
		or (selected_org == 7 or selected_org == 8) and cmd_defoult.army
		or selected_org == 9 and cmd_defoult.fire_department
		or selected_org == 10 and cmd_defoult.jail
		or cmd_defoult.police
	local org_names, selected_names, common_names = {}, {}, {}
	local org_labels = {}
	for _, group in ipairs(groups) do
		for _, command in ipairs(group) do
			org_names[command.cmd] = true
			org_labels[command.cmd] = org_labels[command.cmd] or {}
			org_labels[command.cmd][fast_action_name(command.desc)] = true
		end
	end
	for _, command in ipairs(selected) do selected_names[command.cmd] = command end
	for _, command in ipairs(cmd_defoult.all) do common_names[command.cmd] = true end

	local changed = false
	for i = #cmd[1], 1, -1 do
		local command = cmd[1][i]
		if org_names[command.cmd] and not selected_names[command.cmd] and not common_names[command.cmd] then
			if unregister_commands then
				if command.cmd ~= '' then sampUnregisterChatCommand(command.cmd) end
				if command.key and command.key[2] and #command.key[2] ~= 0 then
					rkeys.unRegisterHotKey(command.key[2])
					for key_i = #all_keys, 1, -1 do
						if table.concat(all_keys[key_i], ' ') == table.concat(command.key[2], ' ') then
							table.remove(all_keys, key_i)
							break
						end
					end
				end
			end
			table.remove(cmd[1], i)
			changed = true
		end
	end
	if unregister_commands and not setting.first_start_fast then
		local fast_names = {}
		for _, list in ipairs({setting.fast.one_win, setting.fast.two_win}) do
			for i = #list, 1, -1 do
				local name = list[i].cmd
				if org_names[name] and not selected_names[name] and not common_names[name] then
					table.remove(list, i)
				else
					if selected_names[name] and org_labels[name][list[i].name] then
						list[i].name = fast_action_name(selected_names[name].desc)
					end
					fast_names[name] = true
				end
			end
		end
		for _, command in ipairs(selected) do
			if command.cmd ~= '' and not fast_names[command.cmd] then
				local list = #setting.fast.one_win < 16 and setting.fast.one_win or setting.fast.two_win
				table.insert(list, {name = fast_action_name(command.desc), cmd = command.cmd, send = true, id = true})
				fast_names[command.cmd] = true
			end
		end
	end
	return changed
end

function add_cmd_in_all_cmd()
	all_cmd = {'ts', 'r', 'd', 'go', 's', 'f'}
	if #cmd[1] ~= 0 then
		for i = 1, #cmd[1] do
			table.insert(all_cmd, cmd[1][i].cmd)
