					rp_sob[i] = rp_sob[i]:gsub('%{id_sob%}', sob_info.id)
				end
				if rp_sob[i]:find('%{myid%}') then
					rp_sob[i] = rp_sob[i]:gsub('%{myid%}', my.id)
				end
				if rp_sob[i]:find('%{mynickrus%}') then
					rp_sob[i] = rp_sob[i]:gsub('%{mynickrus%}', setting.name_rus)
				end
