				else
					fast_nick = 'No_Name'
					fast_id = -1
				end
				windows.fast[0] = true
				win.fast.HideCursor = false
				win.fast.LockPlayer = false
			elseif targ_id == -1 or targ_id == nil then
				fast_nick = 'No_Name'
				fast_id = -1
				windows.fast[0] = true
				win.fast.HideCursor = false
				win.fast.LockPlayer = false
			end
		end
		if pressed_key == tostring(table.concat(setting.win_key[2], ' ')) and not edit_key then
			open_main()
		end
		local music_bind = setting.music_keys
		if #music_bind.pause[2] ~= 0 and pressed_key == tostring(table.concat(music_bind.pause[2], ' ')) and not edit_key then
			set_song_status('PLAY_OR_PAUSE')
		elseif #music_bind.next[2] ~= 0 and pressed_key == tostring(table.concat(music_bind.next[2], ' ')) and not edit_key then
			if play.tab ~= 'RECORD' and play.tab ~= 'RADIO' then
				next_track(true)
			end
		elseif #music_bind.prev[2] ~= 0 and pressed_key == tostring(table.concat(music_bind.prev[2], ' ')) and not edit_key then
			if play.tab ~= 'RECORD' and play.tab ~= 'RADIO' then
				back_track()
			end
		elseif #music_bind.vol_up[2] ~= 0 and pressed_key == tostring(table.concat(music_bind.vol_up[2], ' ')) and not edit_key then
			play.volume = math.min(1, play.volume + 0.05)
			volume_song(play.volume)
		elseif #music_bind.vol_down[2] ~= 0 and pressed_key == tostring(table.concat(music_bind.vol_down[2], ' ')) and not edit_key then
			play.volume = math.max(0, play.volume - 0.05)
			volume_song(play.volume)
		end
		
		if pressed_key == tostring(table.concat(setting.act_key[1], ' ')) and not edit_key and thread:status() ~= 'dead'
		and not sampIsChatInputActive() and not sampIsDialogActive() and not isGamePaused() then
			sh_license.cancel(); thread:terminate()
			dialog_act.status = false
		end
		
		if #cmd[1] ~= 0 then
			for j = 1, #cmd[1] do
				if #cmd[1][j].key[2] ~= 0 then
