		help = 17
	}
	local name_tabs = {
		settings = u8'Главное',
		cmd = u8'Команды',
		shpora = u8'Шпаргалки',
		dep = u8'Департамент',
		sob = u8'Собеседование',
		reminder = u8'Напоминания',
		stat = u8'Статистика онлайна',
		music = u8'Музыка',
		rp_zona = u8'РП зона',
