sh_license = {pending = nil}
function sh_license.trace(event, request)
    local path=sh_audit.private_root..'/license-trace.log'
    local file=io.open(path,'rb')
    if file then local size=file:seek('end');file:close();if size and size>65536 then os.remove(path..'.old');os.rename(path,path..'.old') end end
    file=io.open(path,'ab')
    if file then file:write(os.date('[%Y-%m-%d %H:%M:%S] '),tostring(event):gsub('[\r\n]',' '),request and (' id='..request.id..' license='..request.license..' term='..request.term..' phase='..request.phase) or '', '\r\n');file:close() end
end
function sh_license.cancel(reason)
    local request=sh_license.pending
    if request and reason then
        sh_license.trace('cancel: '..reason,request)
        sampAddChatMessage('[SH]{FFFFFF} Выдача лицензии остановлена: '..reason,0xFF5345)
    end
	sh_license.pending = nil
	num_give_lic, num_give_lic_term, num_give_gov = -1, 0, -1
	if sh_auto_license and sh_auto_license.pending then sh_auto_license.pending.cancelled = true; sh_auto_license.pending = nil end
end
function sh_license.valid(request)
	return request and os.clock() < request.deadline and sampIsLocalPlayerSpawned()
		and tonumber(setting.org) == 5 and table.concat({sampGetCurrentServerAddress()}, ':') == request.server
		and sampIsPlayerConnected(request.id) and sampGetPlayerNickname(request.id) == request.nick
end
function sh_license.begin(id, license, term)
	sh_license.cancel()
	id, license, term = tonumber(id), tonumber(license), tonumber(term)
	if not id or id ~= math.floor(id) or id < 0 or id > 1003 or not sampIsPlayerConnected(id) then return false end
	if not license or license < 0 or license > 11 or license ~= math.floor(license) or not term or term < 0 or term > 2 or term ~= math.floor(term) then return false end
	sh_license.pending = {id = id, nick = sampGetPlayerNickname(id), license = license, term = term, phase = 'sale', expected_command = '/givelicense '..id, server = table.concat({sampGetCurrentServerAddress()}, ':'), deadline = os.clock() + 30}
	return true
end
-- Keep the existing template IDs, but resolve the actual row from the current server list.
sh_license.names = {
    [0] = {'авто'}, {'мото'}, {'полёт', 'полет'}, {'рыбал'}, {'водн'}, {'оруж'},
    {'охот'}, {'раскоп'}, {'такси'}, {'механ'}, {'криптовалют'}, {'акци'}
}

function sh_license.find_row(style, text, matches, check_details)
    if (style ~= 2 and style ~= 4 and style ~= 5) or type(text) ~= 'string' then return nil end
    local index, found = style == 5 and -2 or -1, nil
    for line in (text:gsub('\r\n', '\n'):gsub('\r', '\n') .. '\n'):gmatch('(.-)\n') do
        index = index + 1
        if index >= 0 then
            local label = to_lowercase((line:match('^[^	]*') or ''):gsub('{%x+}', ''))
            if matches(label) then
                local clean = check_details and to_lowercase(line:gsub('{%x+}', '')) or label
                if found or clean:find('недоступ', 1, true) then return nil end
                found = index
            end
        end
    end
    return found
end

function sh_license.dialog(id, style, title, text)
    local request = sh_license.pending
    if not request then return end
    if not sh_license.valid(request) then sh_license.cancel('истекло время ожидания или изменился игрок/подключение'); return end
    sh_license.trace('dialog '..tostring(id)..': '..title,request)
    local name = to_lowercase(title:gsub('{%x+}', '')):match('^%s*(.-)%s*$')
    local row
    if name == 'продажа лицензии' and request.phase == 'sale' then
        row = sh_license.find_row(style, text, function(label)
            if not label:match('^%s*%d+%.') then return false end
            -- Test the more specific names before the generic "авто".
            for offset = 1, 12 do
                local kind = offset % 12
                for _, alias in ipairs(sh_license.names[kind]) do
                    if label:find(alias, 1, true) then return kind == request.license end
                end
            end
            return false
        end, false)
        if row == nil then sh_license.cancel('лицензия не найдена или недоступна. Выберите её вручную'); return end
        request.phase, request.deadline = 'term', os.clock() + 30
    elseif name == 'выбор срока лицензий' and request.phase == 'term' then
        local short = request.license == 10 or request.license == 11
        row = sh_license.find_row(style, text, function(label)
            if short then return label:match('5%s*дн') ~= nil end
            return tonumber(label:match('(%d+)%s*месяц')) == request.term + 1
        end, true)
        if row == nil then sh_license.cancel('срок не найден или недоступен. Выберите его вручную'); return end
        sh_license.cancel()
    else
        sh_license.cancel('открылся другой диалог: '..name)
        return
    end
    sampSendDialogResponse(id, 1, row, '')
    return false
end
function sh_license.send(text)
	local request = sh_license.pending
	if request then request.sending = true;sh_license.trace('sending license command',request) end
	local ok, err = pcall(sampSendChat, text)
	if request then request.sending = false end
	if not ok then sh_license.cancel(); error(err) end
end
function sh_license.tick()
	if sh_license.pending and not sh_license.valid(sh_license.pending) then sh_license.cancel('истекло время ожидания или изменился игрок/подключение') end
	local request = sh_auto_license and sh_auto_license.pending
	if request and (request.cancelled or os.clock() >= request.deadline or not sh_auto_license.valid(request)) then
		request.cancelled = true; sh_auto_license.pending = nil
	end
end

-- Auto-license newcomer check: /id replies are matched to both ID and nickname.
sh_auto_license = {pending = nil}
function sh_auto_license.valid(request)
	return sampIsLocalPlayerSpawned() and tonumber(setting.org) == 5
		and table.concat({sampGetCurrentServerAddress()}, ':') == request.server
		and sampIsPlayerConnected(request.id) and sampGetPlayerNickname(request.id) == request.nick
end
function sh_auto_license.message(text)
	local request = sh_auto_license.pending
	if not request or request.cancelled or os.clock() > request.deadline or not sh_auto_license.valid(request) then return end
	local plain = tostring(text or ''):gsub('{%x+}', '')
	local id, nick, level = plain:match('^%s*%[(%d+)%]%s+([A-Za-z0-9_]+)%s*|%s*Уровень:%s*(%d+)%s*|')
	if tonumber(id) == request.id and nick == request.nick then
		level = tonumber(level)
		if level and level <= 10000 then
			request.level = level
			return true
		end
	end
end
function sh_auto_license.prepare(command, args)
	local id = tonumber(args[1])
	if not id or id < 0 or id > 1003 or id ~= math.floor(id) or not sampIsPlayerConnected(id) then return nil, nil, 'Игрок с таким ID не найден.' end
	local request = {id = id, nick = sampGetPlayerNickname(id), server = table.concat({sampGetCurrentServerAddress()}, ':'), deadline = os.clock() + 8, sending = true}
	sh_auto_license.pending = request
	sampSendChat('/id ' .. id)
	request.sending = false
	while request.level == nil and not request.cancelled and os.clock() < request.deadline and sh_auto_license.valid(request) do wait(50) end
	if sh_auto_license.pending == request then sh_auto_license.pending = nil end
	if request.cancelled then return nil, nil, 'Проверка уровня отменена.' end
	if not sh_auto_license.valid(request) then return nil, nil, 'Выдача отменена: игрок или подключение изменились.' end
	if request.level == nil then return nil, nil, 'Не удалось определить уровень через /id. Повторите команду.' end
	if request.level > 5 then
		if command.newbie_license_template then return nil, nil, 'Этот шаблон предназначен для игроков до 5 уровня включительно.' end
		return command, request
	end
	if command.newbie_license_template then return command, request end
	for _, variant in ipairs(cmd[1]) do
		if variant.newbie_license_template and variant.enabled ~= false then
			if (tonumber(setting.rank) or 0) < variant.rank then return nil, nil, 'Недостаточный ранг для новичкового шаблона.' end
			local copy = deep_copy(variant)
			local ok = sh_audit.command(copy)
			if ok and #copy.arg == #args then return copy, request end
		end
	end
	return nil, nil, 'Не найден корректный шаблон выдачи новичку. Добавьте стандартные команды ЦЛ.'
end
function cmd_start(argument, cmd_name) --> Запуск команды
	for c = 1, #cmd[1] do
		local command = cmd[1][c]
		local name = command.cmd or ''
		local lecture = name:match('^lekmz%d*$') or name:match('^lekcl%d*$') or name:match('^lekgov%d*$') or name:match('^lekarmy%d*$') or name:match('^lekfd%d*$') or name:match('^lekzeks%d*$') or name:match('^lektsr%d*$')
		if lecture and tostring(command.UID) .. name == cmd_name and (tonumber(setting.rank) or 0) < 5 then
			if setting.cef_notif then
				cefnotig('{FF5345}[SH]{FFFFFF} Лекции доступны с 5 ранга.', 3000)
			else
				sampAddChatMessage('[SH]{FFFFFF} Лекции доступны с 5 ранга.', 0xFF5345)
			end
			return
		end
		if tostring(cmd[1][c].UID) .. cmd[1][c].cmd == cmd_name and cmd[1][c].enabled == false then
			return
		end
	end
	if setting.blockl then
		if not setting.cef_notif then
			sampAddChatMessage('[SH]{FFFFFF} Доступ к StateHelper был заблокирован разработчиком.', 0xFF5345)
		end
		return
	end
	if afind_run and not afind_bypass then
		afind_take_cmd(argument, cmd_name)
		return
	end
	if thread:status() ~= 'dead' then --> Если какая-то команда уже запущена, то эту команду не запускаем
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}У Вас уже запущена отыгровка! Используйте {ED95A8}' .. setting.act_key[2] .. '{FFFFFF}, чтобы остановить её.', 0xFF5345)
		else
			cefnotig('{FF5345}[SH] {FFFFFF}У Вас уже запущена отыгровка! Используйте {ED95A8}' .. setting.act_key[2] .. '{FFFFFF}, чтобы остановить её.', 3000)
		end
		return
	end
	
	local CMD --> Вся команда
	local ARG = {} --> Для аргументов
	for c = 1, #cmd[1] do --> Ищем какую команду нам запустить
		if tostring(cmd[1][c].UID) .. cmd[1][c].cmd == cmd_name then
			CMD = cmd[1][c]
		end
	end
	if CMD == nil then --> Если команда почему-то не найдена, то информируем пользователя и останавливаем проигровку
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}ОШИБКА! Команда не найдена... Видимо, файл с командами уничтожен.', 0xFF5345)
		else
			cefnotig("{FF5345}[SH] {FFFFFF}ОШИБКА! Команда не найдена... Видимо, файл с командами уничтожен.", 3000)
		end
		return
	end
	
	local valid, problem = sh_audit.command(CMD)
	if not valid then sampAddChatMessage('[SH]{FFFFFF} Команда повреждена: ' .. tostring(problem), 0xFF5345); return end
	if (tonumber(setting.rank) or 0) < CMD.rank then sampAddChatMessage('[SH]{FFFFFF} Эта команда доступна с ' .. CMD.rank .. ' ранга.', 0xFF5345); return end
	CMD = deep_copy(CMD) -- runtime variables must not modify the saved command
	if #CMD.arg ~= 0 then --> Если команда с аргументами, то делаем проверку, вписываем аргументы и так далее
		local function invalid_arguments() --> Для случая, если аргументы не ожидаемые
			local tbl_ar = {}
			for ar = 1, #CMD.arg do
				table.insert(tbl_ar, '[' .. u8:decode(CMD.arg[ar].desc) .. ']')
			end
			if not setting.cef_notif then
				sampAddChatMessage('[SH] {FFFFFF}Используйте {a8a8a8}/' .. CMD.cmd .. ' ' .. table.concat(tbl_ar, ' '), 0xFF5345)
			else
				cefnotig('{FF5345}[SH] {FFFFFF}Используйте {a8a8a8}/' .. CMD.cmd .. ' ' .. table.concat(tbl_ar, ' '), 5000)
			end
		end
		
		if argument:gsub('%s+', '') ~= '' then
			for word in argument:gmatch('%S+') do --> Выписываем все полученные аргументы в переменную
				table.insert(ARG, word)
			end
			
			if #ARG > #CMD.arg then --> Если аргументов дали больше, чем их должно быть, то всё лишнее вписываем в последний аргумент
				local bool_args = table.concat(ARG, ' ', #CMD.arg, #ARG)
				ARG[#CMD.arg] = bool_args
				for c = #ARG, #CMD.arg + 1, -1 do
					table.remove(ARG, c)
				end
			end
		end
		
		for num, type_arg in ipairs(CMD.arg) do --> Если аргументы дали не те, какие должны быть, то сообщаем как надо и говорим до свидания
			if type_arg.type == 1 then
				if ARG[num] ~= nil then
					if not ARG[num]:find('(.+)') then invalid_arguments() return end
				else
					invalid_arguments() return
				end
			elseif type_arg.type == 2 then
				if ARG[num] ~= nil then
					if not ARG[num]:find('^(%d+)$') then invalid_arguments() return end
				else
					invalid_arguments() return
				end
			end
		end
	end
	local function escape_pattern(text_esc)
		return text_esc:gsub('([%^%$%(%)%%%.%[%]%*%+%-%?])', '%%%1')
	end

	local model, speed, square
	local function vehicle_values()
		if model == nil then model, speed = sh_audit.nearest_vehicle() end
	end

	local function tag_converter(text) --> Преобразовать теги в тексте, если они имеются
		text = u8:decode(text)
		if text:find('%b{}') then
			local week = {'Воскресенье', 'Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота'}
			local month = {'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'}
			local extracted_str = {}
			local stop_send_chat = false
			
			for tag in text:gmatch('%b{}') do
				table.insert(extracted_str, {tag, tag})
			end
			
			for i = 1, #extracted_str do
				local val = extracted_str[i][1]
				if val == '{mynick}' then
					extracted_str[i][2] = my.nick:gsub('_', ' ')
				elseif val == '{mynickrus}' then
