function swanted_ok()
	local sw = setting.police_settings and setting.police_settings.swanted
	return sw and sw.func and setting.org >= 11 and setting.org <= 15
end

function swanted_bind()
	if swanted_bound and swanted_bound ~= '' then
		sampUnregisterChatCommand(swanted_bound)
		swanted_bound = nil
	end
	local sw = setting.police_settings and setting.police_settings.swanted
	if not sw then return end
	if sw.func and sw.cmd ~= '' and setting.org >= 11 and setting.org <= 15 then
		sampRegisterChatCommand(sw.cmd, swanted_toggle)
		swanted_bound = sw.cmd
	end
end

function swanted_toggle()
	if not swanted_ok() then return end
	windows.swanted[0] = not windows.swanted[0]
	if windows.swanted[0] then swanted_last = 0 end
end

function swanted_refresh()
	if wanted_wait.checking then return end
	swanted_last = os.clock()
	wanted_wait.checking = true
	wanted_wait.page = 1
	emp_wanted_players = {}
	sampSendChat('/wanted 1')
	wanted_wait.timeout = os.clock() + 5
end

function swanted_tick()
	if not windows.swanted[0] then return end
	if not swanted_ok() then windows.swanted[0] = false return end
	if wanted_wait.checking or sampIsDialogActive() or sampIsChatInputActive() or isGamePaused() then return end
	if os.clock() - swanted_last >= (setting.police_settings.swanted.interval or 30) then swanted_refresh() end
end

AUTOMASK_INTERVAL = 300 -- проверка маски раз в 5 минут (не настраивается)
automask = {skin = nil, wait_until = 0, pending = false, death_at = -1000, next_check = 0, heal_at = 0, dress_at = 0}

function automask_ok()
	local am = setting.police_settings and setting.police_settings.automask
	return am and am.func and setting.org >= 11 and setting.org <= 15
end

local function automask_say(text)
	if not setting.cef_notif then
		sampAddChatMessage('[SH] {FFFFFF}' .. text, 0xFF5345)
	else
		cefnotig('{FF5345}[SH] {FFFFFF}' .. text, 6000)
	end
end

-- маска определяется по цвету ника: под маской сервер делает его чёрным
function automask_masked()
	local ok, color = pcall(sampGetPlayerColor, my.id)
	if not ok or not color then return nil, nil end
	color = bit.band(color, 0xFFFFFF)
	local r, g, b = bit.band(bit.rshift(color, 16), 255), bit.band(bit.rshift(color, 8), 255), bit.band(color, 255)
	local black = (r <= 16 and g <= 16 and b <= 16)
	-- серо-коричневый цвет ника под маской 665E5E (с небольшим допуском)
	local grey = math.abs(r - 0x66) <= 8 and math.abs(g - 0x5E) <= 8 and math.abs(b - 0x5E) <= 8
	return grey, color
end

function automask_log(text)
	sampAddChatMessage('[SH] {A8A8A8}Auto Mask: ' .. text, 0xFF5345)
end

function automask_check(reason)
	local masked, color = automask_masked()
	if masked == nil then return end
	if masked then return end
	-- в чат: напоминание; в уведомление: подсказка про Enter (без CEF-уведомлений уйдёт в чат)
	sampAddChatMessage('[SH] {FFFFFF}Вы в форме SWAT!', 0xFF5345)
	sampAddChatMessage('[SH] {FFFFFF}Не забудьте надеть маску!', 0xFF5345)
	automask_say('Нажмите {ED95A8}Enter{FFFFFF}, чтобы надеть маску.')
	automask.wait_until = os.clock() + 20
end

function automask_enter()
	automask.wait_until = 0
	local masked = automask_masked()
	if masked then
		-- маска уже надета: ничего не отправляем
	else
		sampSendChat('/mask')
	end
end

function automask_tick()
	if not automask_ok() then
		automask.skin = nil
		automask.pending = false
		automask.wait_until = 0
		automask.next_check = 0
		automask.heal_at = 0
		automask.dress_at = 0
		return
	end
	local now = os.clock()
	if isCharDead(PLAYER_PED) then
		-- мёртв или лечится в больнице: маску надеть нельзя
		automask.death_at = now
		automask.wait_until = 0
		return
	end
	local skin = getCharModel(PLAYER_PED)
	if automask.skin ~= nil and skin ~= automask.skin then
		if skin == 285 then
			-- переоделись в SWAT: проверяем маску через пару секунд, когда обновится цвет ника
			automask.dress_at = now + 2
		else
			automask.wait_until = 0
			automask.dress_at = 0
		end
	end
	automask.skin = skin
	if skin ~= 285 then
		automask.next_check = 0
		if now > automask.heal_at + 5 then automask.heal_at = 0 end
		return
	end
	if automask.next_check == 0 then automask.next_check = now + AUTOMASK_INTERVAL end
	if sampIsChatInputActive() or sampIsDialogActive() or isGamePaused() or (now - automask.death_at < 120) then return end
	if automask.heal_at > 0 and now >= automask.heal_at then
		automask.heal_at = 0
		automask.next_check = now + AUTOMASK_INTERVAL
		automask_check('после лечения')
	elseif automask.dress_at > 0 and now >= automask.dress_at then
		automask.dress_at = 0
		automask.next_check = now + AUTOMASK_INTERVAL
		automask_check('смена формы')
	elseif now >= automask.next_check then
		automask.next_check = now + AUTOMASK_INTERVAL
		automask_check('проверка')
	end
end

autoheal = {queue = {}, cur = nil, wait_until = 0, running = false, cool = 0}
autoheal_prefix = {'лек', 'хил', 'вылечи', 'излечи', 'таблетк'}

function autoheal_ok()
	return setting.autoheal and setting.autoheal.func and setting.org >= 1 and setting.org <= 4
end

local function autoheal_lower(str)
	return (str:gsub('[\192-\223\168]', function(ch)
		local b = ch:byte()
		if b == 168 then return string.char(184) end
		return string.char(b + 32)
	end):lower())
end

-- сообщение вида: Nick_Name[12] говорит: текст
function autoheal_scan(mes)
	local nick, id, text = mes:match('^%s*([%w_]+)%[(%d+)%]%s+говорит:%s*(.+)$')
	if not nick then return end
	id = tonumber(id)
	if id == my.id then return end
	local hit = false
	for word in autoheal_lower(text):gmatch('[^%s%p]+') do
		for _, pref in ipairs(autoheal_prefix) do
			if word:sub(1, #pref) == pref then hit = true break end
		end
		if hit then break end
	end
	if not hit then return end
	if autoheal.cur and autoheal.cur.id == id then return end
	for _, q in ipairs(autoheal.queue) do
		if q.id == id then return end
	end
	table.insert(autoheal.queue, {id = id, nick = nick})
end

function autoheal_go()
	if thread:status() ~= 'dead' then return end
	local p = autoheal.cur
	autoheal.cur = nil
	autoheal.wait_until = 0
	if not p or not sampIsPlayerConnected(p.id) then return end
	autoheal.running = true
	autoheal.cool = os.clock() + 1.5
	for c = 1, #cmd[1] do
		if cmd[1][c].cmd == 'hl' and cmd[1][c].enabled ~= false then
			cmd_start(tostring(p.id), tostring(cmd[1][c].UID) .. cmd[1][c].cmd)
			return
		end
	end
	sampSendChat('/heal ' .. p.id)
end

function autoheal_tick()
	if not autoheal_ok() then
		autoheal.queue = {}
		autoheal.cur = nil
		autoheal.wait_until = 0
		autoheal.running = false
		return
	end
	local now = os.clock()
	if autoheal.running then
		-- ждём конца отыгровки, потом предлагаем следующего
		if now > autoheal.cool and thread:status() == 'dead' then autoheal.running = false end
		return
	end
	if autoheal.cur then
		if now > autoheal.wait_until then autoheal.cur = nil end
		return
	end
	if #autoheal.queue == 0 or thread:status() ~= 'dead' then return end
	if sampIsChatInputActive() or sampIsDialogActive() or isGamePaused() then return end
	local p = table.remove(autoheal.queue, 1)
	while p and not sampIsPlayerConnected(p.id) do
		p = table.remove(autoheal.queue, 1)
	end
	if not p then return end
	autoheal.cur = p
	autoheal.wait_until = now + 20
	automask_say('Игрок {ED95A8}' .. p.nick:gsub('_', ' ') .. '[' .. p.id .. ']{FFFFFF} просит лечение. Нажмите {ED95A8}Enter{FFFFFF}, чтобы вылечить (/heal ' .. p.id .. ').' .. (#autoheal.queue > 0 and (' В очереди ещё: ' .. #autoheal.queue) or ''))
end

function swanted_position()
	lua_thread.create(function()
		local sw = setting.police_settings.swanted
		local bk = {x = sw.pos.x, y = sw.pos.y}
		local was = windows.swanted[0]
		windows.main[0] = false
		windows.swanted[0] = true
		swanted_placing = true
		sampSetCursorMode(4)
		sampAddChatMessage('[SH]{FFFFFF} Нажмите {FF6060}ЛКМ{FFFFFF}, чтобы применить или {FF6060}ESC{FFFFFF} для отмены.', 0xFF5345)
		while isKeyDown(VK_LBUTTON) do
			wait(0)
			if isKeyJustPressed(VK_ESCAPE) then
				sw.pos.x, sw.pos.y = bk.x, bk.y
				swanted_placing = false
				sampSetCursorMode(0)
				windows.swanted[0] = was
				windows.main[0] = true
				imgui.ShowCursor = true
				return
			end
		end
		while true do
			wait(0)
			local cx, cy = getCursorPos()
			sw.pos.x = cx
			sw.pos.y = cy
			if isKeyJustPressed(VK_LBUTTON) then save() break
			elseif isKeyJustPressed(VK_ESCAPE) then
				sw.pos.x, sw.pos.y = bk.x, bk.y
				break
			end
		end
		swanted_placing = false
		sampSetCursorMode(0)
		windows.swanted[0] = was
		windows.main[0] = true
		imgui.ShowCursor = true
	end)
end

win.swanted = imgui.OnFrame(
	function() return windows.swanted[0] and swanted_ok() and not scene_active end,
	function(self)
		self.HideCursor = true
		local sw = setting.police_settings.swanted
		local k = math.max(0.7, math.min(1.5, (sw.size or 100) / 100))
		local fnt = k < 0.9 and font[2] or (k < 1.25 and font[3] or bold_font[1])
		local rows = {}
		for _, p in ipairs(wanted_players or {}) do
			local ins = tostring(p.dist):find('интер', 1, true)
			if not (sw.hide_int and ins) then rows[#rows + 1] = p end
		end
		local cols, width = {}, 20 * k
		for _, key in ipairs(sw.cols or {}) do
			local c = swanted_cols[key]
			if c then cols[#cols + 1] = {key = key, c = c} width = width + c.w * k end
		end
		width = math.max(width, 150 * k)
		local rh, head = 22 * k, 56 * k
		local shown = math.min(#rows, 15)
		local h = head + math.max(shown, 1) * rh + (#rows > shown and rh or 0) + 12 * k

		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, math.max(0.2, math.min(1, (sw.alpha or 90) / 100)))
		imgui.SetNextWindowPos(imgui.ImVec2(sw.pos.x, sw.pos.y), imgui.Cond.Always)
		imgui.SetNextWindowSize(imgui.ImVec2(width, h))
		imgui.Begin('Smart Wanted', windows.swanted, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoSavedSettings + imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoBringToFrontOnFocus + imgui.WindowFlags.NoMove + (swanted_placing and imgui.WindowFlags.NoMouseInputs or 0))
		gui.Draw({0, 0}, {width, h}, cl.main, 10, 15)
		gui.DrawEmp({0, 0}, {width, h}, cl.line, 10, 15, 1)

		local function cell(text, x, y, w, left, col)
			imgui.PushFont(fnt)
			local tw = imgui.CalcTextSize(u8(tostring(text))).x
			imgui.PopFont()
			if col then imgui.PushStyleColor(imgui.Col.Text, col) end
			gui.Text(left and x or (x + (w - tw) / 2), y, tostring(text), fnt)
			if col then imgui.PopStyleColor(1) end
		end
		local gray = imgui.ImVec4(0.55, 0.55, 0.55, 1)

		gui.Text(10 * k, 7 * k, 'Розыск: ' .. #rows, bold_font[4])
		local bx, by = width - 18 * k, 17 * k
		imgui.SetCursorPos(imgui.ImVec2(bx - 10 * k, by - 10 * k))
		if imgui.InvisibleButton('##sw_refresh', imgui.ImVec2(20 * k, 20 * k)) and os.clock() - swanted_manual_t > 3 then
			swanted_manual_t = os.clock()
			swanted_refresh()
		end
		local hov = imgui.IsItemHovered()
		gui.DrawCircle({bx, by}, 10 * k, wanted_wait.checking and cl.def or (hov and cl.bg2 or cl.bg))
		local ico = fa.ARROWS_ROTATE
		imgui.PushFont(fa_font[1])
		local isz = imgui.CalcTextSize(ico)
		imgui.PopFont()
		gui.FaText(bx - isz.x / 2, by - isz.y / 2, ico, fa_font[1], wanted_wait.checking and imgui.ImVec4(1, 1, 1, 1) or cl.text)
		gui.DrawLine({8, 30 * k}, {width - 8, 30 * k}, cl.line)

		local x = 10 * k
		for _, cc in ipairs(cols) do
			cell(cc.c.name, x, 34 * k, cc.c.w * k, cc.key == 'nick', gray)
			x = x + cc.c.w * k
		end

		if #rows == 0 then
			cell(wanted_wait.checking and 'Обновление...' or 'Никого нет в розыске', 10 * k, head + 2 * k, width - 20 * k, false, gray)
		end
		for i = 1, shown do
			local p, y = rows[i], head + (i - 1) * rh
			local ins = tostring(p.dist):find('интер', 1, true)
			local lv = tonumber(p.level) or 0
			local lcol
			if setting.cl == 'White' then
				lcol = lv >= 5 and imgui.ImVec4(0.82, 0.12, 0.12, 1) or (lv >= 3 and imgui.ImVec4(0.85, 0.40, 0.00, 1) or imgui.ImVec4(0.62, 0.42, 0.00, 1))
			else
				lcol = lv >= 5 and imgui.ImVec4(1, 0.35, 0.35, 1) or (lv >= 3 and imgui.ImVec4(1, 0.62, 0.2, 1) or imgui.ImVec4(1, 0.85, 0.3, 1))
			end
			x = 10 * k
			for _, cc in ipairs(cols) do
				local key, w = cc.key, cc.c.w * k
				if key == 'nick' then cell(p.nick, x, y, w, true)
				elseif key == 'id' then cell(tostring(p.id), x, y, w, false, gray)
				elseif key == 'level' then cell(tostring(p.level), x, y, w, false, lcol)
				else cell(ins and 'в инте' or tostring(p.dist), x, y, w, false, ins and gray or nil) end
				x = x + w
			end
		end
		if #rows > shown then cell('+' .. (#rows - shown) .. ' ещё', 10 * k, head + shown * rh, width - 20 * k, false, gray) end

		imgui.End()
		imgui.PopStyleVar(1)
	end
)

function wanted_check()
	if not wanted_wait.checking then return end
	wanted_wait.page = wanted_wait.page + 1
	wanted_wait.clean = (wanted_wait.clean or 0) + 1
	if wanted_wait.clean >= 6 and (wanted_wait.gap or 300) > 250 then
		wanted_wait.gap = wanted_wait.gap - 50
		wanted_wait.clean = 0
	end
	if wanted_wait.page <= (setting.org == 15 and 7 or 6) then
		lua_thread.create(function()
			wait(wanted_wait.gap or 300)
			while thread:status() ~= 'dead' do
				wait(100)
			end
			if wanted_wait.checking then
				while sampIsDialogActive() do
					wait(100)
				end
				if wanted_wait.checking then
					sampSendChat('/wanted ' .. wanted_wait.page)
					wanted_wait.timeout = os.clock() + 5
				end
			end
		end)
	else
		wanted_update = true
		wanted_wait.checking = false
	end
end

function render_members()
	local X, Y = setting.mb.pos.x, setting.mb.pos.y
	local title = string.format('%s | Онлайн: %s%s', org.name, org.online, (setting.mb.afk and (' (%s в АФК)'):format(org.afk) or ''))
	local col_title = changeColorAlpha(setting.mb.color.title, (setting.mb.vis * 2))
	if setting.mb.invers then
		if renderFontDrawClickableText(script_cursor, fontes, title, X, Y - setting.mb.dist - 5, col_title, col_title, 4, false) then
			sampSendChat('/members')
		end
	else
		if renderFontDrawClickableText(script_cursor, fontes, title, X, Y - setting.mb.dist - 5, col_title, col_title, 3, false) then
			sampSendChat('/members')
		end
	end
	if org.name == 'Гражданин' then
		local col_non = changeColorAlpha(setting.mb.color.default, (setting.mb.vis * 2))
		if setting.mb.invers then
			renderFontDrawClickableText(script_cursor, fontes, 'Вы не состоите в организации', X, Y, col_non, col_non,  4, false)
		else
			renderFontDrawClickableText(script_cursor, fontes, 'Вы не состоите в организации', X, Y, col_non, col_non,  3, false)
		end
	elseif #members > 0 then
		for i, member in ipairs(members) do
			if i <= tonumber(org.online) then
				if setting.rank_members[tonumber(member.rank.count)] then
					local color = changeColorAlpha(setting.mb.form and (member.uniform and setting.mb.color.work or setting.mb.color.default) or setting.mb.color.default, (setting.mb.vis * 2))
					local rank = setting.mb.rank and string.format('[%s]', member.rank.count) or nil
					local nick = member.nick .. (setting.mb.id and string.format('(%s)', member.id) or '')
					local afk = setting.mb.afk and string.format(' (AFK: %s)', member.afk) or ''
					local warns = setting.mb.warn and string.format(' (W: %s)', member.warns) or ''
					local out_string
					if setting.mb.invers then
						out_string = ('%s%s%s%s'):format(rank and rank .. ' ' or '', nick, afk, warns)
						renderFontDrawClickableText(script_cursor, fontes, out_string, X, Y, color, color, 4, true)
					else
						out_string = ('%s%s%s%s'):format(rank and rank .. ' ' or '', nick, afk, warns)
						renderFontDrawClickableText(script_cursor, fontes, out_string, X, Y, color, color, 3, true)
					end
					Y = Y + setting.mb.dist
				end
			end
		end
	else
		local col_non = changeColorAlpha(setting.mb.color.default, (setting.mb.vis * 2))
		if setting.mb.invers then
			renderFontDrawClickableText(script_cursor, fontes, 'Мемберс обновится через ' .. wait_mb .. ' сек.', X, Y, col_non, col_non,  4, false)
		else
			renderFontDrawClickableText(script_cursor, fontes, 'Мемберс обновится через ' .. wait_mb .. ' сек.', X, Y, col_non, col_non,  3, false)
		end
	end
end

function isCursorAvailable()
	return (not sampIsChatInputActive() and not sampIsDialogActive() and not sampIsScoreboardOpen())
end

function renderFontDrawClickableText(active, font, text, posX, posY, color, color_hovered, align, b_symbol)
	local cursorX, cursorY = getCursorPos()
	local lenght = renderGetFontDrawTextLength(font, text)
	local height = renderGetFontDrawHeight(font)
	local symb_len = renderGetFontDrawTextLength(font, '>')
	local hovered = false
	local result = false
	b_symbol = b_symbol == nil and false or b_symbol
	align = align or 1

	if align == 2 then
		posX = posX - (lenght / 2)
	elseif align == 3 then
		posX = posX - lenght
	end

	if active and cursorX > posX and cursorY > posY and cursorX < posX + lenght and cursorY < posY + height then
		hovered = true
		if isKeyJustPressed(0x01) then
			result = true 
		end
	end

	local anim = math.floor(math.sin(os.clock() * 10) * 3 + 5)
 	if hovered and b_symbol and (align == 2 or align == 1) then
		renderFontDrawText(font, '>', posX - symb_len - anim, posY, 0x90FFFFFF)
	end 
	renderFontDrawText(font, text, posX, posY, hovered and color_hovered or color)
	if hovered and b_symbol and (align == 2 or align == 3) then
		renderFontDrawText(font, '<', posX + lenght + anim, posY, 0x90FFFFFF)
	end 

	return result
end

function changePosition()
	if setting.mb.func then
		pos_new_memb = lua_thread.create(function()
			local backup = {
				['x'] = setting.mb.pos.x,
				['y'] = setting.mb.pos.y
			}
			local ChangePos = true
			sampSetCursorMode(4)
			windows.main[0] = false
			if not setting.cef_notif then
				sampAddChatMessage('[SH]{FFFFFF} Нажмите {FF6060}ЛКМ{FFFFFF}, чтобы применить или {FF6060}ESC{FFFFFF} для отмены.', 0xFF5345)
			else
				cefnotig('{FF5345}[SH]{FFFFFF} Нажмите {FF6060}ЛКМ{FFFFFF}, чтобы применить или {FF6060}ESC{FFFFFF} для отмены.', 3000)
			end
			if not sampIsChatInputActive() then
				while not sampIsChatInputActive() and ChangePos do
					wait(0)
					local cX, cY = getCursorPos()
					setting.mb.pos.x = cX
					setting.mb.pos.y = cY
					if isKeyDown(0x01) then
						while isKeyDown(0x01) do wait(0) end
						ChangePos = false
						save()
						if not setting.cef_notif then
							sampAddChatMessage('[SH]{FFFFFF} Позиция сохранена.', 0xFF5345)
						else
							cefnotig('[SH]{FFFFFF} Позиция сохранена.', 3000)
						end
					elseif isKeyJustPressed(VK_ESCAPE) then
						ChangePos = false
						setting.mb.pos.x = backup['x']
						setting.mb.pos.y = backup['y']
						if not setting.cef_notif then
							sampAddChatMessage('[SH]{FFFFFF} Вы отменили изменение позиции.', 0xFF5345)
						else
							cefnotig('{FF5345}[SH]{FFFFFF} Вы отменили изменение позиции.', 3000)
						end
					end
				end
			end
			sampSetCursorMode(0)
			windows.main[0] = true
			imgui.ShowCursor = true
			ChangePos = false
		end)
	end
end

function update_lists()
    local toggle_updater = false
    while true do
        wait(1000)
        if sampIsLocalPlayerSpawned() and not sampIsDialogActive() and not sampIsChatInputActive() and wait_mb == 0 and not isGamePaused() and not isPauseMenuActive() then
            local check_started = false
            
            local need_members = setting.mb.func
            local need_wanted = setting.police_settings.wanted_list.func and (setting.org >= 11 and setting.org <= 15)

            if need_members and need_wanted then
                if toggle_updater then
                    sampSendChat('/members')
                    members_wait.members = true
                    check_started = true
                    toggle_updater = false
                else
                    wanted_wait.checking = true
                    wanted_wait.page = 1
                    emp_wanted_players = {}
                    sampSendChat('/wanted 1')
                    wanted_wait.timeout = os.clock() + 5
                    check_started = true
                    toggle_updater = true
                end
            elseif need_members then
                sampSendChat('/members')
                members_wait.members = true
                check_started = true
            elseif need_wanted then
                wanted_wait.checking = true
                wanted_wait.page = 1
                emp_wanted_players = {}
                sampSendChat('/wanted 1')
                wanted_wait.timeout = os.clock() + 5
                check_started = true
            end
            
            if check_started then
                wait_mb = 15
            end
        end
    end
end

function check_all_wanted_pages() -- посл.проверки
	if wanted_wait.checking then return end
		wanted_wait.checking = true
		lua_thread.create(function()
		temp_wanted_players = {} 
		for page = 1, 6 do
			while windows.main[0] do
				wait(200)
			end
			if not wanted_wait.checking then break end
			wanted_wait.dialog_opened = false
			sampSendChat('/wanted ' .. page)
			local timeout = os.clock() + 1.5 
			while os.clock() < timeout and not wanted_wait.dialog_opened do
				wait(0)
			end
			wait(700)
		end

		wanted_update = true
		wanted_wait.checking = false
	end)
end

