http_pending = {}

function asyncHttpRequest(method, url, args, resolve, reject)
	debug_log('async > %s %s', tostring(method), tostring(url))
	local request_thread = effil.thread(function (method, url, args)
		local requests = require 'requests'
		local result, response = pcall(requests.request, method, url, args)
		if result then
			response.json, response.xml = nil, nil
			return true, response
		else
			return false, response
		end
	end)(method, url, args)

	if not resolve then resolve = function() end end
	if not reject then reject = function() end end

	table.insert(http_pending, {runner = request_thread, resolve = resolve, reject = reject, url = url})
end

function http_poll()
 local finished = {}
 for i = #http_pending, 1, -1 do
  local req = http_pending[i]
  local ok, status, status_error = pcall(function() return req.runner:status() end)
  local done, success, response = false, false, nil
  if not ok or status_error then
   done, response = true, status_error or status
  elseif status == 'completed' then
   done = true
   local got, result, value = pcall(function() return req.runner:get() end)
   success, response = got and result, got and value or result
  elseif status == 'canceled' or status == 'failed' then
   done, response = true, status
  end
  if done then
   table.remove(http_pending, i)
   finished[#finished + 1] = {req = req, success = success, response = response}
  end
 end
 for _, item in ipairs(finished) do
  local callback = item.success and item.req.resolve or item.req.reject
  if callback then
   local ok, err = xpcall(function() callback(item.response) end, debug.traceback)
   if not ok then print('[SH HTTP] Callback failed: ' .. tostring(err)) end
  end
 end
end

local function last_color(text, pos)
	local before = text:sub(1, math.max((pos or 1) - 1, 0))
	local last = before:match(".*({%x%x%x%x%x%x})")
	return last
end

--> Hook
-- Match server loot announcements without relying on item icons or chat colors.
local function sh_is_loot_message(message)
 local text = tostring(message or ''):gsub('{%x+}', ''):match('^%s*(.-)%s*$')
 local function loot_container(name)
  name = to_lowercase(name):lower()
  for _, word in ipairs({'тайник', 'рулет', 'ларец', 'ларц', 'сундук', 'ящик'}) do
   if name:find(word, 1, true) then return true end
  end
  return false
 end
 local function after_header(header)
  local at = text:find(header, 1, true)
  if not at then return nil end
  local prefix = text:sub(1, at - 1):gsub('%s', '')
  -- Permit a leading gift/item icon, but reject quoted player chat prefixes.
  if #prefix > 16 or prefix:find('[%w_:%[%]]') then return nil end
  return text:sub(at + #header):match('^%s*(.-)%s*$')
 end
 if text:match('^[%w_]+%s+открыл%s+Тайник%s+.+%s+и получил супер%-приз:%s*.+$') then return true end
 local luck = after_header('[Удача]')
 if luck then
  if luck:match('^Игрок%s+[%w_]+%s+использовал%s+.+%s+и выиграл%s+.+$') then return true end
  local container = luck:match('^Игрок%s+[%w_]+%s+открыл%s+(.+)%s+и получил:%s*.+$')
  if container and loot_container(container) then return true end
 end
 local info = after_header('[Информация]')
 if info then
  local container = info:match('^Вы использовали%s+(.+)%s+и получили%s+.+$')
  if container and loot_container(container) then return true end
 end
 local draw = after_header('[Чёрный жребий]') or after_header('[Черный жребий]')
 if draw and draw:match('^Игрок%s+[%w_]+%s+испытал судьбу и получил%s+.+$') then return true end
 return false
end

function chat_hook_server_message(color_mes, mes)
	local mescol = mes:gsub('{%x+}', '')
	local mes_col = (bit.tohex(bit.rshift(color_mes, 8), 6))

	if autoheal and autoheal_ok() then autoheal_scan(mescol) end

	if automask and automask_ok() and mescol:find('Вы закончили свое лечение', 1, true) then
		-- вышли из больницы: снимаем запрет на напоминание и проверяем маску через секунду
		automask.death_at = -1000
		automask.heal_at = os.clock() + 1.5
	end

	if mescol:find('Вы успешно пометили игрока') and mes_col == '9acd32' and setting.org >= 11 and setting.org <= 15 then
		local mark_minutes = mescol:match('в течение (%d+) минут')
		if mark_minutes then
			z_timer.active = true
			z_timer.until_time = os.clock() + tonumber(mark_minutes) * 60
		end
	end

	if mescol:find('Вы успешно получили бодикамеру') and setting.police_settings.auto_bodycam and setting.org >= 11 and setting.org <= 15 then
		close_ammo_menu = true
	end

		if mescol:find('Запрашиваю розыск на дело:') and mes_col == '2db043' and (setting.police_settings.su_accept.func or setting.rank > 4) and setting.org >= 11 and setting.org <= 15 then
		local su_nick = mescol:match('(%S+)%[%d+%]:')
		local su_case = mescol:match('на дело:%D-(%d+)')
		local su_degree = mescol:match('степень розыска:%D-(%d+)')
		local su_reason = mescol:match('с причиной:%s*"?(.-)"?%s*$')
		if su_nick and su_case and su_degree and su_reason then
			local su_short_tag = su_nick:sub(1, 1) .. '.' .. (su_nick:match('_(.+)$') or su_nick)
			su_accept = { active = true, case = su_case, degree = su_degree, reason = su_reason, tag = su_short_tag }
			local su_notify_text = '[SH] {FFFFFF}' .. su_nick .. ' запрашивает выдачу розыска. Для подтверждения введите команду {FF6060}/' .. setting.police_settings.su_accept.cmd
			if setting.police_settings.su_accept.key[1] ~= '' then
				su_notify_text = su_notify_text .. '{FFFFFF} или нажмите {FF6060}' .. setting.police_settings.su_accept.key[1]
			end
			sampAddChatMessage(su_notify_text, 0xFF5345)
			lua_thread.create(function()
				wait(20000)
				su_accept.active = false
			end)
		end
	end

	if mescol:find('Вы не полицейский!') and wanted_wait.checking and mes_col == 'ff6347' then
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}Вы не полицейский, функция wanted на экране выключена.', 0xFF5345)
		else
			cefnotig('{FF5345}[SH] {FFFFFF}Вы не полицейский, функция wanted на экране выключена.', 3500)
		end
		setting.police_settings.wanted_list.func = false
		save()
		return false
	end

	if mescol:find('Вы не состоите во фракции') and setting.mb.func and mes_col == 'ff6347' then
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}Вы не состоите в организации, мемберс на экране выключен.', 0xFF5345)
		else
			cefnotig('{FF5345}[SH] {FFFFFF}Вы не состоите в организации, мемберс на экране выключен.', 3500)
		end
		setting.mb.func = false
		save()
		return false
	end

	if mescol:find('Не флуди!') and wanted_wait.checking and mes_col == 'ff6347' then --> для вантед
		wanted_wait.gap = math.min(1100, (wanted_wait.gap or 300) + 150)
		wanted_wait.clean = 0
		lua_thread.create(function()
			wait(wanted_wait.gap)
			if wanted_wait.checking then
				sampSendChat('/wanted ' .. wanted_wait.page)
				wanted_wait.timeout = os.clock() + 5
			end
		end)
		return false
	end

	if mescol:find('Игроков с таким уровнем розыска нету!') and wanted_wait.checking and mes_col == 'ff6347' then
		wanted_wait.timeout = 0
		wanted_check()
		return false
	end

	if setting.police_settings.ten_code and (setting.org >= 11 and setting.org <= 15) and next(tenCodes) then
		for pattern, addon in pairs(tenCodes) do
			local s, e = mes:find(pattern, 1, true)
			local prev_ch = s and s > 1 and mes:sub(s-1, s-1) or ""
			if s and (prev_ch == "" or prev_ch:match("[%s%p]")) then
				local next_ch = mes:sub(e+1, e+1)
				if next_ch == "" or next_ch:match("[%s%p]") or next_ch == "{" then
					local mes_col = "{" .. bit.tohex(bit.rshift(color_mes, 8), 6) .. "}"
					local restore_hex = last_color(mes, s)
					if not restore_hex then
						restore_hex = mes_col
					end
					local insert = " {FFFF00}(" .. addon .. ")" .. restore_hex
					local new_text = mes:sub(1, e) .. insert .. mes:sub(e + 1)
					return { color_mes, new_text }
				end
			end
		end
	end

	if setting.put_mes[2] and setting.hide_chat then
		local icon_23b = string.char(0xEF, 0x88, 0xBB)
		local icon_23c = string.char(0xEF, 0x88, 0xBC)
		-- вип-объявления приходят другим цветом и с иконкой uf23c, поэтому цвет не проверяем
		if mescol:find(icon_23b, 1, true) == 1 or mescol:find(icon_23c, 1, true) == 1 or mescol:lower():find('^:uf23%x:', 1)
		or mescol:find('Отредактировал') or mescol:find('^%s*Объявление:') then
			return false
		end
	end
	
	if mescol:find('на территории штата бушует торнадо') and setting.put_mes[11] and setting.hide_chat then
		return false
	end
	
	if setting.put_mes[3] and setting.hide_chat then
		if mescol:find('News LS') or mescol:find('News SF') or mescol:find('News LV') then
			return false
		end
		if mescol:find('Гость') or mescol:find('Репортёр') then
			if mes_col == '9acd32' then
				return false
			end
		end
	end

	if mescol:find('Преследование за (.-) было приостановлено, причина:') and setting.org >= 11 and setting.org <= 15 then
		poltarget = nil
		auto_z_state.range = false
		auto_z_state.id = nil
		z_timer.active = false
	end

	if mescol:find('Вы успешно начали погоню за игроком') and setting.org >= 11 and setting.org <= 15 then
		local id = mes:match("Вы успешно начали погоню за игроком .- %[ID: (%d+)%]")
		if id then
			poltarget = tonumber(id)
			z_timer.active = false
		end
	end

	if mescol:find('Вы не можете продавать лицензии на такой срок') then
		sh_license.cancel()
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}Ваш ранг не позволяет выдать эту лицензию!', 0xFF5345)
		else
			cefnotig('{FF5345}[SH] {FFFFFF}Ваш ранг не позволяет выдать эту лицензию!', 3000)
		end
		return false
	end
	
	if setting.put_mes[1] and setting.hide_chat then
		if mescol:find('~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~') or mescol:find('- Основные команды сервера: /menu /help /gps /settings') 
		or mescol:find('Пригласи друга и получи бонус в размере') or mescol:find('- Донат и получение дополнительных средств arizona-rp.com/donate') 
		or mescol:find('Подробнее об обновлениях сервера') or mescol:find('(Личный кабинет/Донат)') or mescol:find('С помощью телефона можно заказать') 
		or mescol:find('В нашем магазине ты можешь') or mescol:find('их на желаемый тобой бизнес') or mescol:find('Игроки со статусом (.+)имеют больше возможностей') 
		or mescol:find('можно приобрести редкие автомобили, аксессуары, воздушные') or mescol:find('предметы, которые выделят тебя из толпы! Наш сайт:') 
