local license_copy = {}

local sign_pick = {}

local function sign_pick_rows(text)
	local rows, index = {}, -1
	for line in (tostring(text or ''):gsub('\r', ''):gsub('\n+$', '') .. '\n'):gmatch('(.-)\n') do
		local plain = line:gsub('{%x+}', '')
		local num, name, distance, wear, status = plain:match('^%s*%[(%d+)%]%s+([^\t]+)\t([^\t]+)\t([^\t]*)\t(.+)$')
		if num then
			local meters = distance:gsub('%s', ''):match('^(%d+[.,]?%d*)')
			meters = meters and tonumber((meters:gsub(',', '.')))
			if meters then rows[#rows + 1] = {index = index, name = name, distance = meters, status = status} end
		end
		index = index + 1
	end
	return rows
end

local function sign_pick_cities(text)
	local cities, index = {}, -1
	for line in (tostring(text or ''):gsub('\r', ''):gsub('\n+$', '') .. '\n'):gmatch('(.-)\n') do
		local plain = line:gsub('{%x+}', '')
		local name, installed = plain:match('^%s*([^\t]+)\t%s*(%d+)%s+из%s+%d+')
		if installed then
			local key = to_lowercase(name):lower():gsub('[%s%-]', '')
			local center
			if key == 'sanfierro' or key == 'санфиерро' then center = {x = -1980, y = 150, name = 'San Fierro'}
			elseif key == 'lossantos' or key == 'лоссантос' then center = {x = 1480, y = -1720, name = 'Los Santos'}
			elseif key == 'lasventuras' or key == 'ласвентурас' then center = {x = 1690, y = 1440, name = 'Las Venturas'} end
			if center then cities[#cities + 1] = {index = index, installed = tonumber(installed), center = center} end
		end
		index = index + 1
	end
	return cities
end

-- One-shot installation reminder, bound to the marker created by selecting a missing sign.
sh_sign_arrival = {pending = nil, radius = 30}
function sh_sign_arrival.server()
	return table.concat({sampGetCurrentServerAddress()}, ':')
end
function sh_sign_arrival.position(value)
	if not value then return end
	local x, y, z = tonumber(value.x), tonumber(value.y), tonumber(value.z)
	if x and y and z and x == x and y == y and z == z and math.abs(x) < 50000 and math.abs(y) < 50000 and math.abs(z) < 10000 then return {x = x, y = y, z = z} end
end
function sh_sign_arrival.distance(a, b)
	return math.sqrt((a.x - b.x)^2 + (a.y - b.y)^2 + (a.z - b.z)^2)
end
function sh_sign_arrival.arm(row)
	sh_sign_arrival.pending = nil
	if not row or not to_lowercase(row.status):find('отсутствует', 1, true) then return end
	local x, y, z = getCharCoordinates(PLAYER_PED)
	local old
	local ok, found, mx, my_, mz = pcall(getTargetServerCoordinates)
	if ok and found then old = sh_sign_arrival.position({x = mx, y = my_, z = mz}) end
	sh_sign_arrival.pending = {name = row.name, expected = row.distance, origin = {x = x, y = y, z = z}, previous = old, server = sh_sign_arrival.server(), created = os.clock(), last_poll = -1}
	sampAddChatMessage('[SH]{FFFFFF} Знак выбран. Напомню, какой установить, когда подъедете.', 0xFF5345)
end
function sh_sign_arrival.marker(position, kind, id)
	local request = sh_sign_arrival.pending
	if not request then return end
	local point = sh_sign_arrival.position(position)
	if not point then return end
	if request.server ~= sh_sign_arrival.server() then sh_sign_arrival.pending = nil return end
	if request.target then
		local difference = sh_sign_arrival.distance(point, request.target)
		if difference <= 3 and request.kind == 'memory' and kind ~= 'memory' then
			request.kind, request.marker_id = kind, id
		elseif difference > 3 and (kind == 'checkpoint' or kind == 'race' or (request.kind == kind and request.marker_id == id)) then
			sh_sign_arrival.pending = nil
		end
		return
	end
	if os.clock() - request.created > 8 then return end
	local distance = sh_sign_arrival.distance(request.origin, point)
	if math.abs(distance - request.expected) > math.max(60, request.expected * 0.12) then return end
	if kind == 'memory' and request.previous and sh_sign_arrival.distance(point, request.previous) < 1 then return end
	request.target, request.kind, request.marker_id, request.captured = point, kind, id, os.clock()
end
function sh_sign_arrival.notify(request)
	local x, y, z = getCharCoordinates(PLAYER_PED)
	if request.target and sh_sign_arrival.distance({x = x, y = y, z = z}, request.target) <= sh_sign_arrival.radius then
		sh_sign_arrival.pending = nil
		sampAddChatMessage('[SH]{FFFFFF} Требуется установить знак: ' .. request.name .. '.', 0xFF5345)
		return true
	end
end
function sh_sign_arrival.clear(kind, id)
	local request = sh_sign_arrival.pending
	if request and request.target and request.kind == kind and request.marker_id == id then
		sh_sign_arrival.notify(request)
		sh_sign_arrival.pending = nil
	end
end
function sh_sign_arrival.tick()
	local request = sh_sign_arrival.pending
	if not request then return end
	local now = os.clock()
	if now - request.last_poll < 0.2 then return end
	request.last_poll = now
	if not sampIsLocalPlayerSpawned() or request.server ~= sh_sign_arrival.server() or now - request.created > 1800 then sh_sign_arrival.pending = nil return end
	if not request.target then
		local ok, found, x, y, z = pcall(getTargetServerCoordinates)
		if ok and found then sh_sign_arrival.marker({x = x, y = y, z = z}, 'memory') end
		if not request.target and now - request.created > 8 then
			sh_sign_arrival.pending = nil
			sampAddChatMessage('[SH]{FFFFFF} Не удалось определить метку знака. Повторите выбор.', 0xFF5345)
		end
	else
		if request.kind == 'memory' then
			local ok, found, x, y, z = pcall(getTargetServerCoordinates)
			local current = ok and found and sh_sign_arrival.position({x = x, y = y, z = z})
			if not current or sh_sign_arrival.distance(current, request.target) > 3 then sh_sign_arrival.pending = nil return end
		end
		sh_sign_arrival.notify(request)
	end
end
function hook.onSetCheckpoint(position, radius)
	sh_sign_arrival.marker(position, 'checkpoint')
end
function hook.onDisableCheckpoint()
	sh_sign_arrival.clear('checkpoint')
end
function hook.onSetRaceCheckpoint(kind, position, next_position, radius)
	sh_sign_arrival.marker(position, 'race')
end
function hook.onDisableRaceCheckpoint()
	sh_sign_arrival.clear('race')
end
function hook.onSetMapIcon(id, position, kind, color, style)
	sh_sign_arrival.marker(position, 'icon', id)
end
function hook.onRemoveMapIcon(id)
	sh_sign_arrival.clear('icon', id)
end

local function sign_pick_nearest()
	local best, best_distance
	for _, row in ipairs(sign_pick.rows or {}) do
		if (to_lowercase(row.status):find('требует ремонта', 1, true) or to_lowercase(row.status):find('отсутствует', 1, true)) and (best_distance == nil or row.distance < best_distance) then
			best, best_distance = row, row.distance
		end
	end
	if not best then
		sampAddChatMessage('[SH]{FFFFFF} В списке нет отсутствующих знаков или знаков, требующих ремонта.', 0xFF5345)
		return
	end
	local id = sign_pick.id
	if not id then return end
	sh_sign_arrival.arm(best)
	sign_pick.id = nil
	sampSendDialogResponse(id, 1, best.index, '')
	sign_pick.closing_id = id
	sampCloseCurrentDialogWithButton(0)
	sign_pick.closing_id = nil

end

local function sign_pick_candidate(rows)
	local best
	for _, row in ipairs(rows or {}) do
		local status = to_lowercase(row.status)
		if (status:find('требует ремонта', 1, true) or status:find('отсутствует', 1, true)) and (not best or row.distance < best.distance) then best = row end
	end
	return best
end

local function sign_pick_open_city()
	if sign_pick.scan then return end
	sh_sign_arrival.pending = nil
	local cities = sign_pick.cities
	if not sign_pick.id or not cities or #cities == 0 then return end
	local x, y = getCharCoordinates(PLAYER_PED)
	local queue = {}
	for _, city in ipairs(cities) do queue[#queue + 1] = city end
	table.sort(queue, function(a, b)
		return (x - a.center.x)^2 + (y - a.center.y)^2 < (x - b.center.x)^2 + (y - b.center.y)^2
	end)
	local op = {cancel = false, server = table.concat({sampGetCurrentServerAddress()}, ':')}
	sign_pick.scan = op
	sampAddChatMessage('[SH]{FFFFFF} Проверяю знаки: сначала ваш город, затем ближайшие остальные.', 0xFF5345)
	lua_thread.create(function()
		local function alive()
			return sign_pick.scan == op and not op.cancel and sampIsLocalPlayerSpawned() and table.concat({sampGetCurrentServerAddress()}, ':') == op.server
		end
		local function send(button, row)
			if not alive() or not sign_pick.id then error('Поиск отменён.') end
			local id, serial = sign_pick.id, sign_pick.serial or 0
			sign_pick.id, sign_pick.rows, sign_pick.cities, sign_pick.indices = nil, nil, nil, nil
			op.internal = true
			local ok, err = pcall(sampSendDialogResponse, id, button, row or 0, '')
			op.internal = false
			if not ok then error(err) end
			return serial
		end
		local function await_screen(kind, serial)
			local deadline = os.clock() + 6
			while alive() and os.clock() < deadline do
				if sign_pick.id and (sign_pick.serial or 0) > serial and type(sign_pick[kind]) == 'table' then
					local snapshot = sign_pick[kind]
					local dialog_id = sign_pick.id
					wait(250)
					if not alive() then error('Поиск отменён.') end
					if sign_pick.id ~= dialog_id or type(sign_pick[kind]) ~= 'table' then
						error('Диалог знаков изменился во время поиска. Повторите выбор.')
					end
					return snapshot
				end
				wait(50)
			end
			if not alive() then error('Поиск отменён.') end
			error('Сервер не открыл список знаков вовремя. Повторите поиск.')
		end
		local function open_city(city)
			local current
			for _, row in ipairs(sign_pick.cities or {}) do if row.center.name == city.center.name then current = row break end end
			if not current then error('Список городов изменился. Повторите поиск.') end
			return await_screen('rows', send(1, current.index))
		end
		local ok, err = pcall(function()
			for _, city in ipairs(queue) do
				local rows = open_city(city)
				if #rows == 0 then error('Не удалось прочитать список знаков. Повторите поиск.') end
				local candidate = sign_pick_candidate(rows)
				if candidate then
					local nx, ny = getCharCoordinates(PLAYER_PED)
					if (nx - x)^2 + (ny - y)^2 > 2500 then error('Вы переместились во время поиска. Повторите его для точного выбора.') end
					-- Stop at the first city with work; do not inspect more distant cities.
					sign_pick.scan = nil
					if not to_lowercase(candidate.status):find('отсутствует', 1, true) then
						sampAddChatMessage('[SH]{FFFFFF} Ближайший знак: ' .. city.center.name .. ', ' .. candidate.name .. ' (' .. candidate.distance .. ' м).', 0xFF5345)
					end
					sign_pick_nearest()
					return
				end
				await_screen('cities', send(0, 0))
			end
			sampAddChatMessage('[SH]{FFFFFF} Во всех городах нет отсутствующих знаков или знаков, требующих ремонта.', 0xFF5345)
		end)
		if sign_pick.scan == op then sign_pick.scan = nil end
		if not ok and not op.cancel then
			local message = tostring(err):gsub('^.-:%d+:%s*', '')
			sampAddChatMessage('[SH]{FFFFFF} ' .. message, 0xFF5345)
		end
	end)
end
function hook.onShowDialog(id, style, title, but_1, but_2, text, payload)
	if sh_license.pending and sh_license.dialog(id, style, title, text) == false then return false end
	do
		local ok, hide = pcall(function()
			local result = stroi.members_dialog(id, style, title, text)
			if result == false then return false end
			return phone_mb_on_dialog(id, style, title, text)
		end)
		if ok and hide == false then return false end
		if not ok then
			phone_mb_stop()
			stroi.want = false
			stroi.say('Ошибка чтения состава. Повторите обновление.')
			print('[SH][roster] ' .. tostring(hide))
		end
	end
	if take_keep.active then
		-- shortcut: первый список после /take определяет ID, при параллельных ответах нужен серверный ID.
		if (take_keep.wait_until or 0) > os.clock() and (take_keep.last_id == nil or id == take_keep.last_id) and (style == 2 or style == 4 or style == 5) then
			take_keep.last_id, take_keep.wait_until = id, 0
		elseif id ~= take_keep.last_id then
			take_keep.active, take_keep.arg, take_keep.wait_until = false, nil, 0
		end
	end
	if id == sign_pick.id and text == sign_pick.display_text then text = sign_pick.source_text end
	sign_pick.id, sign_pick.rows, sign_pick.cities, sign_pick.action_row, sign_pick.indices = nil, nil, nil, nil, nil
	license_copy.id, license_copy.row = nil, nil
	if sign_trace_active then
		sign_trace_write('DIALOG', tostring(id) .. ' | ' .. tostring(title) .. ' | ' .. tostring(text))
	end
	last_dialog_title = title
	last_dialog_text = text
	local plain_title = to_lowercase(title:gsub('{%x+}', '')):match('^%s*(.-)%s*$')
	if style == 5 then
		if (id == 27077 or plain_title == 'выберите город') and text:find('Установлено знаков', 1, true) then
			sign_pick.cities = sign_pick_cities(text)
		elseif (id == 27078 or plain_title:find('дорожные знаки', 1, true) == 1) and text:find('Название знака', 1, true) then
			sign_pick.rows = sign_pick_rows(text)
		end
		if sign_pick.rows or sign_pick.cities then sign_pick.serial = (sign_pick.serial or 0) + 1 end
		if sign_pick.rows then
			sign_pick.id = id
		elseif sign_pick.cities then
			local columns = sign_pick.cities and '\t \t ' or '\t \t \t '
			local action = '{FF5345}[SH] {FFFFFF}Выбрать ближайший знак' .. columns
			local lines, indices, source_row = {}, {}, -1
			for line in (text:gsub('\r', ''):gsub('\n+$', '') .. '\n'):gmatch('(.-)\n') do
				local plain = line:gsub('{%x+}', '')
				if not plain:find('Выбрать ближайший знак', 1, true) then
					if sign_pick.cities and plain:find('Информация', 1, true) and not sign_pick.action_row then
						sign_pick.action_row = #lines - 1
						lines[#lines + 1] = action
					end
					if not sign_pick.cities or plain:find('%S') then
						indices[#lines - 1] = source_row
						lines[#lines + 1] = line
					end
					source_row = source_row + 1
				end
			end
			if not sign_pick.action_row then
				sign_pick.action_row = #lines - 1
				lines[#lines + 1] = action
			end
			local body = table.concat(lines, '\n')
			sign_pick.id, sign_pick.indices = id, indices
			sign_pick.source_text, sign_pick.display_text = text, body
			return {id, style, title, but_1, but_2, body, payload or ''}
		end
	end

	if id == 1780 and wanted_wait.checking then
		wanted_wait.timeout = 0
		local got_row = false
		for line in text:gmatch('[^\r\n]+') do
			local nick, player_id, wanted_level, distance = string.match(line, '{FFFFFF}(.-)%({21FF11}(%d+){FFFFFF}%)%s+(%d+)%s+уровень%s+%[%s*(.-)%s*%]')
			if nick then
				table.insert(emp_wanted_players, { nick = nick, id = player_id, level = wanted_level, dist = distance })
				got_row = true
			end
		end
		if got_row then closeDialog(1780, 0) end
		wanted_check()
		return false
	end

	if id == 0 and unprison then
		if text:find("Тюремные наказания") then
			if (s_na == 'Chandler' or s_na == 'RedRock' or s_na == 'Gilbert' or s_na == 'ShowLow' or s_na == 'CasaGrande' or s_na == 'SunCity' or s_na == 'Holiday' or s_na == 'Christmas' or s_na == 'Scottdale') then
				local values = {}
				for value in text:gmatch("{5CDC59}(%d+)") do
					table.insert(values, value)
				end
				if #values >= 5 then
					local total_sum = 0
					if setting.price[3] then
						total_sum = total_sum + (tonumber(values[1]) * tonumber(setting.price[3].box))
						total_sum = total_sum + (tonumber(values[2]) * tonumber(setting.price[3].eat))
						total_sum = total_sum + (tonumber(values[3]) * tonumber(setting.price[3].cloth))
						total_sum = total_sum + (tonumber(values[4]) * tonumber(setting.price[3].trash))
						total_sum = total_sum + (tonumber(values[5]) * tonumber(setting.price[3].min))
						local function format_number(n)
							n = tonumber(n)
							if not n then return "0" end
							return tostring(math.floor(n))
						end
						if unprison_id then
							sampAddChatMessage("/unpunish " .. unprison_id .. " " .. format_number(total_sum), -1	)
							sampSendChat("/unpunish " .. unprison_id .. " " .. format_number(total_sum))
							unprison_id = nil
						end
					end
				end
			elseif (s_na == 'Tucson') then
				sampSendChat("/unpunish " .. unprison_id .. " " .. '2500000')
				unprison = false
			elseif (s_na == 'Mesa') then
				sampSendChat("/unpunish " .. unprison_id .. " " .. '2000000')
				unprison = false
			elseif (s_na == 'Page') then
				sampSendChat("/unpunish " .. unprison_id .. " " .. '10000000')
				unprison = false
			elseif (s_na == 'Sedona') then
				sampSendChat("/unpunish " .. unprison_id .. " " .. '15000000')
				unprison = false
			end
		end	
	end

	if id == 1214 then
		if lspawncar then
