function reply_from_choice_fires_dialog(list_id)
	level_fire = 1
	local text_dialog = dialog_fire.text[list_id + 1]
	if text_dialog:find('В данный момент все спокойно') then
		return false
	end
	local function count_stars(text_star)
		local count = 0
		if text_star ~= nil and text_star ~= '' then
			for _ in string.gmatch(text_star, '%*') do
				count = count + 1
			end
			
			return count
		else
			return 1
		end
	end
	
	local function tags_sub(text_sub)
		if text_sub:find('%{mynickrus%}') then
			text_sub = text_sub:gsub('%{mynickrus%}', setting.name_rus)
		end
		if text_sub:find('%{myid%}') then
			text_sub = text_sub:gsub('%{myid%}', tostring(my.id))
		end
		if text_sub:find('%{mynick%}') then
			text_sub = text_sub:gsub('%{mynick%}', my.nick)
		end
		if text_sub:find('%{level%}') then
			text_sub = text_sub:gsub('%{level%}', tostring(level_fire))
		end
		if text_sub:find('%{rank%}') then
			text_sub = text_sub:gsub('%{rank%}', setting.job_title)
		end
		if text_sub:find('%{myrank%}') then
			text_sub = text_sub:gsub('%{myrank%}', setting.job_title)
		end
		
		return text_sub
	end
	
	if text_dialog ~= '' then
		level_fire = count_stars(text_dialog)
	end
	local text_fire = u8:decode(setting.text_fires)
	
	if setting.fire.auto_send and thread:status() == 'dead' then
		thread = lua_thread.create(function()
		wait(600)
			sampSendChat(tags_sub(text_fire))
		end)
	end
end

--> Убрать все знаки, оставив только число, преобразовав его в num type
function process_string(input_text)
	local cleaned = input_text:gsub('[^%d]', '')
	local number = tonumber(cleaned)
	
	return number
end

-- Chat messages are CP1251: byte limits are also character limits here.
local sh_sending_split = false
local function sh_send_chat_part(text)
 sh_sending_split = true
 local ok, err = pcall(sampSendChat, text)
 sh_sending_split = false
 if not ok then print('[SH Chat] ' .. tostring(err)) end
end
function split_text_message(input, max_length)
 input = tostring(input or '')
 max_length = math.floor(tonumber(max_length) or 0)
 if max_length < 1 or #input <= max_length then return false, input end
 local result, rest = {}, input
 local markers = max_length >= 9
 while #rest > 0 do
  local prefix = markers and #result > 0 and '... ' or ''
  local room = max_length - #prefix
  if #rest <= room then result[#result + 1] = prefix .. rest; break end
  local suffix = markers and ' ...' or ''
  room = room - #suffix
  local cut = room
  -- Prefer a word boundary, but split an overlong word to guarantee progress.
  if rest:sub(room + 1, room + 1):match('%S') then
   local space = rest:sub(1, room):match('.*()%s')
   if space and space > 1 then cut = space - 1 end
  end
  local part = rest:sub(1, cut):gsub('%s+$', '')
  if part == '' then part, cut = rest:sub(1, room), room end
  result[#result + 1] = prefix .. part .. suffix
  rest = rest:sub(cut + 1):gsub('^%s+', '')
 end
 return true, result
end

function hook.onSendDialogResponse(id, button_id, list_id, input)
	if sign_pick.scan and not sign_pick.scan.internal then sign_pick.scan.cancel = true; sign_pick.scan = nil end
	if id == sign_pick.closing_id then return false end
	if sign_trace_active then
		sign_trace_write('DIALOG_RESPONSE', 'id=' .. tostring(id) .. ' button=' .. tostring(button_id) .. ' row=' .. tostring(list_id) .. ' expected_id=' .. tostring(sign_pick.id) .. ' action_row=' .. tostring(sign_pick.action_row) .. ' input=' .. tostring(input))
	end
	if id == sign_pick.id then
		if button_id == 1 and list_id == sign_pick.action_row then
			local cities = sign_pick.cities ~= nil
			lua_thread.create(function()
				wait(0)
				if sign_trace_active then sign_trace_write('SIGN_ACTION', cities and 'cities' or 'signs') end
				if cities then sign_pick_open_city() else sign_pick_nearest() end
			end)
			return false
		end
		if button_id == 1 and sign_pick.rows then
			for _, row in ipairs(sign_pick.rows) do if row.index == list_id then sh_sign_arrival.arm(row) break end end
		end
		local server_row = sign_pick.indices and sign_pick.indices[list_id]
		sign_pick.id = nil
		if server_row ~= nil and server_row ~= list_id then return {id, button_id, server_row, input} end
	end
	if id == license_copy.id then
		if button_id == 1 and list_id == license_copy.row then
			license_copy.handling = true
			local ok, err = pcall(copy_license_policy)
			license_copy.handling = false
			if not ok then print('[SH][prices] ' .. tostring(err)) end
			return false
		end
		license_copy.id, license_copy.row = nil, nil
	end
	if id == dialog_fire.id and button_id == 1 and setting.godeath.func then
		reply_from_choice_fires_dialog(list_id)
	end
	if id == take_keep.last_id and setting.police_settings.keep_take_open and take_keep.active and take_keep.arg and not take_keep.reopening then
		if button_id == 1 then
			local take_id, take_arg = id, take_keep.arg
			take_keep.reopening = true
			lua_thread.create(function()
				wait(250)
				if setting.police_settings.keep_take_open and take_keep.active and take_keep.last_id == take_id and take_keep.arg == take_arg and not sampIsDialogActive() then
					take_keep.wait_until = os.clock() + 5
					sampSendChat('/take ' .. take_arg)
				end
				take_keep.reopening = false
			end)
		else
			take_keep.active, take_keep.arg, take_keep.wait_until = false, nil, 0
		end
	end
end

function hook.onSendChat(message)
	if sh_sending_split then return end
	local message_end = ''
	if setting.accent.func then
		if message == ')' or message == '(' or message ==  '))' or message == '((' or message == 'xD' or message == ':D' or message == ':d' or message == 'XD' or message == ':)' or message == ':(' then return {message} end
		
		if setting.accent.text ~= '' then
			message_end = '[' .. u8:decode(setting.accent.text) .. ' акцент]: ' .. message
		end
	end
	
	if setting.chat_corrector and message:sub(1,1) ~= '/' then
		local text_correct = (message_end == '') and message or message_end
		local corrected_text = correct_chat(text_correct)
		message_end = corrected_text
	end
	if setting.wrap_text_chat.func then
		local char_num = process_string(setting.wrap_text_chat.num_char)
		
		if char_num then
			local exceeded, result = split_text_message(message_end ~= '' and message_end or message, char_num)
			
			if exceeded then
				lua_thread.create(function()
					for i = 2, #result do
						wait(2200)
						sh_send_chat_part(result[i])
					end
				end)
				message_end = result[1]
			end
		end
	end
	
	if message_end ~= '' then
		return {message_end}
	end
end

function extractCommandArgument(text)
	local command, argument = text:match('^/(%S+)%s+(.*)$')
	return argument
end

function hook.onSendCommand(cmd)
	local lookup = sh_auto_license.pending
	if lookup and not lookup.sending and cmd:match('^/?id%s+%d+%s*$') then lookup.cancelled = true; sh_auto_license.pending = nil end
	if sh_license.pending then
        local request=sh_license.pending
        local normalized=tostring(cmd):match('^/?(.-)%s*$')
        if request.expected_command and '/'..normalized==request.expected_command then
            request.expected_command=nil;sh_license.trace('own command accepted',request)
        elseif not request.sending then sh_license.cancel('отправлена другая команда') end
    end
	if sh_sending_split then return end
	local message_array = {}
	local message_end = ''
	do
		local take_arg = cmd:match('^/?take%s+(%d+)%s*$')
		if take_arg then
			take_keep.active = setting.police_settings.keep_take_open
			take_keep.arg = take_keep.active and take_arg or nil
			if not take_keep.reopening then take_keep.last_id = nil end
			take_keep.wait_until = take_keep.active and (os.clock() + 5) or 0
		end
	end
	-- авто-формат рации: /d текст -> /d [тег] - [кому]: текст
	local dep_body = u8:decode(dep_text):sub(4)
	if dep_body ~= '' then
		local dep_rest = cmd:match('^/d (.*)$')
		if dep_rest and dep_rest:sub(1, #dep_body) ~= dep_body then
			message_end = '/d ' .. dep_body .. dep_rest
		end
	end
	if cmd:find('^/r%s') then
		if setting.auto_cmd_r ~= '' and setting.auto_cmd_r ~= ' ' then
			table.insert(message_array, u8:decode(setting.auto_cmd_r))
		end
	end
	if cmd:find('^/time%s*$') then
		if setting.auto_cmd_time ~= '' and setting.auto_cmd_time ~= ' ' then
			table.insert(message_array, u8:decode(setting.auto_cmd_time))
		end
	end
		
	if setting.chat_corrector then
		local command_ch = {r=true, s=true, c=true, b=true, rb=true, vr=true, fam=true}
		local command, argument = cmd:match('/(%S+)%s*(.*)')

		if command and command_ch[command] and argument ~= '' then
			local corrected_arg = correct_chat(argument)
			if corrected_arg ~= argument then
				message_end = '/' .. command .. ' ' .. corrected_arg
			end
		end
	end

	if setting.auto_edit then
		if cmd:find('/do (.+)') or cmd:find('/me (.+)') or cmd:find('/todo (.+)') then
			local result_cmd = cmd:gsub('^([\\/])(.*)', function(first_slash, rest)
				return first_slash .. rest:gsub('[\\/]', '')
			end)
			message_end = check_and_correct(result_cmd)
		end
	end
	
	if setting.wrap_text_chat.func then
		local char_num = process_string(setting.wrap_text_chat.num_char)
		
		if char_num then
			local outgoing = message_end ~= '' and message_end or cmd
			local prefix, body = outgoing:match('^(%S+)%s+(.*)$')
			if prefix and char_num > #prefix + 1 then
				local exceeded, result = split_text_message(body, char_num - #prefix - 1)
				if exceeded then
					for i = 2, #result do message_array[#message_array + 1] = prefix .. ' ' .. result[i] end
					message_end = prefix .. ' ' .. result[1]
				end
			end
		end
	end
	
	if #message_array ~= 0 then
		lua_thread.create(function()
			for i = 1, #message_array do
				wait(2000)
				sh_send_chat_part(message_array[i])
			end
		end)
	end
	
	if message_end ~= '' then
		return {message_end}
	end
end

--> Из верхнего регистра в нижний
function to_lowercase(str)
	return (str:gsub('[А-ЯЁ]', function(c)
		if c == 'Ё' then
			return 'ё'
		else
			return string.char(c:byte() + 32)
		end
	end))
end

function check_and_correct(variable)
	local function to_upper(char)
		local map = {
			['а']='А', ['б']='Б', ['в']='В', ['г']='Г', ['д']='Д', ['е']='Е', ['ё']='Ё', ['ж']='Ж', ['з']='З', ['и']='И',
			['й']='Й', ['к']='К', ['л']='Л', ['м']='М', ['н']='Н', ['о']='О', ['п']='П', ['р']='Р', ['с']='С', ['т']='Т',
			['у']='У', ['ф']='Ф', ['х']='Х', ['ц']='Ц', ['ч']='Ч', ['ш']='Ш', ['щ']='Щ', ['ъ']='Ъ', ['ы']='Ы', ['ь']='Ь',
			['э']='Э', ['ю']='Ю', ['я']='Я'
		}
		return map[char] or char:upper()
	end

	local function to_lower(char)
		local map = {
			['А']='а', ['Б']='б', ['В']='в', ['Г']='г', ['Д']='д', ['Е']='е', ['Ё']='ё', ['Ж']='ж', ['З']='з', ['И']='и',
			['Й']='й', ['К']='к', ['Л']='л', ['М']='м', ['Н']='н', ['О']='о', ['П']='п', ['Р']='р', ['С']='с', ['Т']='т',
			['У']='у', ['Ф']='ф', ['Х']='х', ['Ц']='ц', ['Ч']='ч', ['Ш']='ш', ['Щ']='щ', ['Ъ']='ъ', ['Ы']='ы', ['Ь']='ь',
			['Э']='э', ['Ю']='ю', ['Я']='я'
		}
		
		return map[char] or char:lower()
	end
	if type(variable) ~= 'string' then
		return variable
	end
	
	if variable:match('^/do (.+)%/') then
		variable = string.sub(variable, 1, -2)
	end
	
	if variable:match('^/me (.+)') then
		local text = variable:sub(5)
		text = text:gsub('^.', to_lower)
		text = text:gsub('%.$', '')
		
		return '/me ' .. text
	elseif variable:match('^/do (.+)') then
		local text = variable:sub(5)
		text = text:gsub('^.', to_upper)
		if not text:find('%.$') and not text:find('[!?]$') then
			text = text .. '.'
		end
		
		return '/do ' .. text
	 elseif variable:match('^/todo (.+)%*(.+)') then
		local text = variable:sub(7)
		text = text:gsub('^.', to_upper)
		local text2 = text:gsub('(.+)*', '')
		text2 = text2:gsub('^.', to_lower)
		text = text:gsub('%*(.+)', '')
		
		return '/todo ' .. text .. '*' .. text2
	end

	return variable
end

function onWindowMessage(msg, wparam, lparam)
    local browser_state = sh_browser_manager and sh_browser_manager.state
    if sh_browser_input.close_pressed and (msg == 0x201 or msg == 0x202 or msg == 0x203) then
        consumeWindowMessage(true, true, true)
        if msg == 0x202 then sh_browser_input.finish_close() end
        return
    end
    if msg == 0x0008 then
        sh_browser_input.swallow_key = nil
        if sh_browser_input.enabled and browser_state then sh_browser_input.disable(browser_state) end
    end
    local key_down, key_up = msg == 0x100 or msg == 0x104, msg == 0x101 or msg == 0x105
    if (key_down or key_up) and sh_browser_input.swallow_key == wparam then
        if key_up then sh_browser_input.swallow_key = nil end
        consumeWindowMessage(true, false)
        return
    end
    if key_down and sh_browser_input.choosing_key and windows.main[0] and tab_settings == 24
        and not sampIsChatInputActive() and not sampIsDialogActive() then
        if bit.band(lparam, 0x40000000) ~= 0 then return end
        if wparam == 0x1B or sh_browser_input.valid_key(wparam) then
            sh_browser_input.swallow_key = wparam
            consumeWindowMessage(true, false)
            if wparam == 0x1B then
                sh_browser_input.choosing_key = false
            else
                sh_browser_input.pending_key = wparam
                sh_browser_input.pending_modifiers = sh_browser_input.modifiers()
            end
            return
        end
    end
    if key_down and wparam == 0x1B and sh_browser_input.enabled and sh_browser_input.available(browser_state) then
        sh_browser_input.swallow_key = wparam
        consumeWindowMessage(true, true, true)
        sh_browser_input.disable(browser_state)
        return
    end
    if sh_browser_input.enabled and sh_browser_input.available(browser_state) and browser_state.web_keyboard
        and (key_down or key_up or msg == 0x102 or msg == 0x106) then
        consumeWindowMessage(true, true, true)
        if msg == 0x102 or msg == 0x106 then
            sh_browser_input.web_text(browser_state, wparam)
        else
            sh_browser_manager.pointer(key_down and 'rawKeyDown' or 'keyUp', wparam,
                bit.band(bit.rshift(lparam, 16), 0x1FF), sh_browser_input.web_modifiers(),
                key_down and bit.band(lparam, 0x40000000) ~= 0)
        end
        return
    end
    if key_down and wparam == sh_browser_input.key() and sh_browser_input.available(browser_state)
        and not browser_state.address_edit and sh_browser_input.modifiers() == setting.browser_cursor_modifiers then
        consumeWindowMessage(true, false)
        if bit.band(lparam, 0x40000000) == 0 then
            sh_browser_input.swallow_key = wparam
            if sh_browser_input.enabled then sh_browser_input.disable(browser_state)
            else sh_browser_input.enabled = true end
        end
        return
    end
    if sh_browser_manager and sh_browser_manager.state.address_edit and (msg==0x100 or msg==0x101) and wparam==0x1B then
        sh_browser_manager.state.address_edit=false;consumeWindowMessage(true,false);return
    end
    if sh_browser_input.enabled and sh_browser_input.available(browser_state) then
        local state=sh_browser_manager.state;local r=state.overlay_rect
        if r and (msg==0x200 or msg==0x201 or msg==0x202 or msg==0x203 or msg==0x20A) then
            local x,y=getCursorPos()
            local inside=x>=r.x and x<r.x+r.w and y>=r.y and y<r.y+r.h
            local page=inside and y>=r.y+78 and y<r.y+r.h-12
            local captured=state.web_mouse_down==true
            if (msg == 0x201 or msg == 0x203) and not captured and sh_browser_input.close_hit(r, x, y) then
                sh_browser_input.close_pressed = true
                consumeWindowMessage(true, true, true)
                return
            end
            if msg==0x201 then
                state.web_keyboard=page
                state.web_surrogate=nil
            end
            if msg == 0x200 and captured then
                sh_browser_input.drag_to(state, x, y)
            elseif (msg == 0x202 and captured) or (page and msg ~= 0x203 and msg ~= 0x202) then
                local action = msg == 0x201 and 'mousePressed' or msg == 0x202 and 'mouseReleased'
                    or msg == 0x20A and 'mouseWheel' or 'mouseMoved'
                local delta = bit.rshift(wparam, 16)
                if delta >= 32768 then delta = delta - 65536 end
                if msg == 0x201 then
                    state.web_mouse_down = true
                    state.web_drag_x, state.web_drag_y = x, y
                elseif msg == 0x202 then
                    sh_browser_input.drag_to(state, x, y)
                    state.web_mouse_down = false
                end
                sh_browser_manager.pointer(action, x - r.x, y - r.y - 78, msg == 0x20A and -delta or 0, state.web_mouse_down == true)
            end
            if msg~=0x200 and (inside or (msg==0x202 and captured)) then consumeWindowMessage(true,false);return end
        end
    end

	if stroi.run.active and stroi.run.phase == 'wait' and (msg == 0x100 or msg == 0x101) and stroi.can_confirm() then
		local keys = setting.enter_key[1]
		if #keys == 0 and wparam == vkeys.VK_RETURN then consumeWindowMessage(true, false) end
		for _, key in ipairs(keys) do if dec_to_key(key) == wparam then consumeWindowMessage(true, false); break end end
	end
	if wparam == vkeys.VK_RETURN and (msg == 0x100 or msg == 0x101) and autoheal and autoheal.cur and autoheal.wait_until > os.clock() and not sampIsChatInputActive() and not sampIsDialogActive() then
		consumeWindowMessage(true, false)
		if msg == 0x100 then autoheal_go() end
		return
	end
	if wparam == vkeys.VK_RETURN and (msg == 0x100 or msg == 0x101) and automask and automask.wait_until > os.clock() and not sampIsChatInputActive() and not sampIsDialogActive() then
		consumeWindowMessage(true, false)
		if msg == 0x100 then
			automask_enter()
		end
		return
	end
	if dialog_act.status and dialog_act.enter and not sampIsChatInputActive() and not sampIsDialogActive() and wparam == vkeys.VK_RETURN and (msg == 0x100 or msg == 0x101) then
		consumeWindowMessage(true, false)
	end
	if msg == 0x100 and wparam == 0x1B and not isPauseMenuActive() then
		if off_scene or scene_active then
			consumeWindowMessage(true, false)
			windows.main[0] = true
			off_scene = false
		elseif not isPlayerControlLocked() then
			if windows.fast[0] then
				consumeWindowMessage(true, false)
				close_win.fast = true
			end
			if windows.smart_su[0] then
				consumeWindowMessage(true, false)
				smartSuState.anim.is_closing = true
				smartSuState.anim.is_opening = false
			end
			if windows.stroi[0] and not stroi.moving then
				consumeWindowMessage(true, false)
				stroi.close()
			end
			if windows.shpora[0] then
				consumeWindowMessage(true, false)
				windows.shpora[0] = false
			elseif windows.main[0] then
				consumeWindowMessage(true, false)
				if not sh_modal_open then
					close_win.main = true
				end
			end
		end
	end
end

function draw_wrapped_text(text, x, y, wrap_width, line_spacing) --> Перенос текста по его длине в пикселях (текст, позиция, длина x, интервал y)
	local words = {}
	for word in text:gmatch('%S+') do
		table.insert(words, word)
	end
	
	local currentLine = ''
	local currentY = y
	
	for _, word in ipairs(words) do
		local nextLine = currentLine .. (currentLine ~= '' and ' ' or '') .. word
		local textWidth = imgui.CalcTextSize(nextLine).x
		if textWidth > wrap_width then
			imgui.SetCursorPos(imgui.ImVec2(x, currentY))
			imgui.Text(currentLine)
			currentLine = word
			currentY = currentY + line_spacing
		else
			currentLine = nextLine
		end
	end
	
	if currentLine ~= '' then
		imgui.SetCursorPos(imgui.ImVec2(x, currentY))
		imgui.Text(currentLine)
	end
	
	return currentY
end

function imgui.TextColoredRGB(string, max_float)
	local style = imgui.GetStyle()
	local colors = style.Colors
	local clr = imgui.Col
	local u8 = require 'encoding'.UTF8

	local function color_imvec4(color)
		if color:upper():sub(1, 6) == 'SSSSSS' then return imgui.ImVec4(colors[clr.Text].x, colors[clr.Text].y, colors[clr.Text].z, tonumber(color:sub(7, 8), 16) and tonumber(color:sub(7, 8), 16)/255 or colors[clr.Text].w) end
		local color = type(color) == 'number' and ('%X'):format(color):upper() or color:upper()
		local rgb = {}
		for i = 1, #color/2 do rgb[#rgb+1] = tonumber(color:sub(2*i-1, 2*i), 16) end
		return imgui.ImVec4(rgb[1]/255, rgb[2]/255, rgb[3]/255, rgb[4] and rgb[4]/255 or colors[clr.Text].w)
	end

	local function render_text(string)
		for w in string:gmatch('[^\r\n]+') do
			local text, color = {}, {}
			local render_text = 1
			local m = 1
			if w:sub(1, 8) == '[center]' then
				render_text = 2
				w = w:sub(9)
			elseif w:sub(1, 7) == '[right]' then
				render_text = 3
				w = w:sub(8)
			end
			w = w:gsub('{(......)}', '{%1FF}')
			while w:find('{........}') do
				local n, k = w:find('{........}')
				if tonumber(w:sub(n+1, k-1), 16) or (w:sub(n+1, k-3):upper() == 'SSSSSS' and tonumber(w:sub(k-2, k-1), 16) or w:sub(k-2, k-1):upper() == 'SS') then
					text[#text], text[#text+1] = w:sub(m, n-1), w:sub(k+1, #w)
					color[#color+1] = color_imvec4(w:sub(n+1, k-1))
					w = w:sub(1, n-1)..w:sub(k+1, #w)
					m = n
				else w = w:sub(1, n-1)..w:sub(n, k-3)..'}'..w:sub(k+1, #w) end
			end
			local length = imgui.CalcTextSize(u8(w))
			if render_text == 2 then
				imgui.NewLine()
				imgui.SameLine(max_float / 2 - ( length.x / 2 ))
			elseif render_text == 3 then
				imgui.NewLine()
				imgui.SameLine(max_float - length.x - 5 )
			end
			if text[0] then
				for i, k in pairs(text) do
					imgui.TextColored(color[i] or colors[clr.Text], u8(k))
					imgui.SameLine(nil, 0)
				end
				imgui.NewLine()
			else 
				imgui.Text(u8(w))
			end
		end
	end
	render_text(string)
end

--> Фукция анимации с использованием математической линейной интерполяции
function animate(start_x, start_y, x_end, y_end, target_x, target_y, duration, ease_factor)
	local elapsed_time = 0
	local current_x, current_y = start_x, start_y
	local delta_x, delta_y = x_end - start_x, y_end - start_y
	
	return function()
		if elapsed_time < duration then
			elapsed_time = elapsed_time + anim
			local t = math.min(elapsed_time / duration, 1)
			local easedT = 1 - (1 - t) ^ ease_factor
			
			current_x = start_x + delta_x * easedT
			current_y = start_y + delta_y * easedT
			
			_G[target_x] = current_x
			_G[target_y] = current_y
			
			return current_x, current_y
		else
			_G[target_x] = x_end
			_G[target_y] = y_end
			
			return x_end, y_end
		end
	end
end

