--> ---------- настройки и данные ----------
function stroi.cfg()
	if type(setting.stroi) ~= 'table' then setting.stroi = {} end
	local s = setting.stroi
	if type(s.func) ~= 'boolean' then s.func = false end
	if type(s.cmd) ~= 'string' then s.cmd = 'str' end
	if type(s.key) ~= 'table' or type(s.key[2]) ~= 'table' then s.key = {'', {}} end
	if type(s.list) ~= 'table' then s.list = {} end
	if type(s.pos) ~= 'table' or type(s.pos.x) ~= 'number' or type(s.pos.y) ~= 'number' then
		s.pos = {x = math.floor(sx - 130), y = math.floor(sy * 0.28)}
	end
	return s
end

function stroi.new_id()
	local m = 0
	for _, f in ipairs(setting.stroi.list) do
		if type(f.id) == 'number' and f.id > m then m = f.id end
	end
	return m + 1
end

function stroi.fix(f) --> приводит строй к корректному виду
	if type(f.id) ~= 'number' then f.id = stroi.new_id() end
	if type(f.name) ~= 'string' then f.name = '' end
	if type(f.cmd) ~= 'string' then f.cmd = '' end
	if type(f.key) ~= 'table' or type(f.key[2]) ~= 'table' then f.key = {'', {}} end
	if type(f.actions) ~= 'table' or #f.actions == 0 then f.actions = {{text = ''}, {text = ''}} end
	for i = 1, #f.actions do
		if type(f.actions[i]) ~= 'table' or type(f.actions[i].text) ~= 'string' then f.actions[i] = {text = ''} end
	end
	if type(f.timers) ~= 'table' then f.timers = {} end
	for i = 1, #f.actions - 1 do
		local v = tonumber(f.timers[i]) or 0
		f.timers[i] = math.max(0, math.min(5999, math.floor(v)))
	end
	for i = #f.timers, #f.actions, -1 do f.timers[i] = nil end
	if type(f.orgs) ~= 'table' then f.orgs = {} end
	local selected, seen = {}, {}
	for _, v in ipairs(f.orgs) do
		local id = tonumber(v)
		if id and id == math.floor(id) and id >= 1 and id <= #stroi.org_names and not seen[id] then selected[#selected + 1] = id; seen[id] = true end
	end
	f.orgs = selected
	if type(f.warn_reason) ~= 'string' then f.warn_reason = u8('Неявка на строй') end
	if f.ask_mode ~= 'nick' then f.ask_mode = 'id' end
	return f
end

function stroi.find(id)
	for _, f in ipairs(stroi.cfg().list) do
		if f.id == id then return stroi.fix(f) end
	end
end

function stroi.title(f, idx) --> название (UTF-8)
	if f.name ~= '' then return f.name end
	return u8('Строй ') .. tostring(idx or '')
end

function stroi.fmt(sec)
	sec = math.max(0, math.floor(sec))
	return string.format('%02d:%02d', math.floor(sec / 60), sec % 60)
end

function stroi.lines(text) --> UTF-8 текст -> массив непустых строк
	local res = {}
	for line in (text .. '\n'):gmatch('(.-)\r?\n') do
		line = line:gsub('^%s+', '')
		line = line:gsub('%s+$', '')
		if line ~= '' then table.insert(res, line) end
	end
	return res
end

function stroi.summary(f) --> строка для карточки (CP1251)
	local total = 0
	for _, t in ipairs(f.timers) do total = total + t end
	return 'Действий: ' .. #f.actions .. '   ·   Таймеров: ' .. #f.timers .. '   ·   Общее время: ' .. stroi.fmt(total)
end

function stroi.is_blank(f)
	if type(f.orgs) == 'table' and #f.orgs > 0 then return false end
	if f.name ~= '' or f.cmd ~= '' or #f.key[2] > 0 then return false end
	for _, a in ipairs(f.actions) do
		if a.text:match('%S') then return false end
	end
	for _, t in ipairs(f.timers) do
		if t > 0 then return false end
	end
	return true
end

function stroi.touch() --> отложенное сохранение
	stroi.ui.dirty = true
	stroi.ui.dirty_t = os.clock()
end

function stroi.flush(force)
	local ui = stroi.ui
	if ui.dirty and (force or os.clock() - ui.dirty_t > 1.2) then
		ui.dirty = false
		save()
	end
end

function stroi.say(text) --> сообщение игроку (текст в CP1251)
	if not setting.cef_notif then
		sampAddChatMessage('[SH]{FFFFFF} ' .. text, 0xFF5345)
	else
		cefnotig('{FF5345}[SH]{FFFFFF} ' .. text, 3500)
	end
end

function stroi.ord(n) --> "ко второму действию"
	local o = {'первому', 'второму', 'третьему', 'четвертому', 'пятому', 'шестому', 'седьмому', 'восьмому', 'девятому', 'десятому'}
	if n == 2 then return 'ко второму действию' end
	if o[n] then return 'к ' .. o[n] .. ' действию' end
	return 'к действию №' .. n
end

--> ---------- команды и клавиши ----------
stroi.org_names = {'Больница Лос-Сантос', 'Больница Сан-Фиерро', 'Больница Лас-Вентурас', 'Больница Джефферсон', 'Центр Лицензирования', 'Правительство', 'Армия Лос-Сантос', 'Армия Сан-Фиерро', 'Пожарный департамент', 'Тюрьма строгого режима', 'Полиция Лос-Сантос', 'Полиция Лас-Вентурас', 'Полиция Сан-Фиерро', 'Полиция Рэд-Каунти', 'ФБР'}
stroi.org_short = {'ЛСМЦ', 'СФМЦ', 'ЛВМЦ', 'Джефферсон', 'ЦЛ', 'Правительство', 'Армия ЛС', 'Армия СФ', 'Пожарные', 'Тюрьма', 'ЛСПД', 'ЛВПД', 'СФПД', 'РКПД', 'ФБР'}

function stroi.leader() return (tonumber(setting.rank) or 0) >= 9 end

function stroi.has_org(f, o)
	for _, v in ipairs(f.orgs) do
		if v == o then return true end
	end
	return false
end

function stroi.org_label(f) --> короткая подпись выбранных фракций (CP1251)
	if #f.orgs == 0 then return 'не выбрана' end
	local t = {}
	for i = 1, math.min(3, #f.orgs) do t[i] = stroi.org_short[f.orgs[i]] end
	local lbl = table.concat(t, ', ')
	if #f.orgs > 3 then lbl = lbl .. ' +' .. (#f.orgs - 3) end
	return lbl
end

function stroi.toggle_org(f, o)
	if stroi.ui.fetching then return end
	stroi.ui.confirm = nil
	for i, v in ipairs(f.orgs) do
		if v == o then
			table.remove(f.orgs, i)
			stroi.touch()
			return
		end
	end
	table.insert(f.orgs, o)
	table.sort(f.orgs)
	stroi.touch()
end

function stroi.mark(f, key, v) --> повторное нажатие снимает отметку
	stroi.ui.confirm = nil
	local m = stroi.marks[f.id]
	if not m then
		m = {}
		stroi.marks[f.id] = m
	end
	if m[key] == v then m[key] = nil else m[key] = v end
end

function stroi.roster(f)
	local list, seen = {}, {}
	local _, myid = sampGetPlayerIdByCharHandle(PLAYER_PED)
	local oid = tonumber(setting.org)
	local function add(m, org_id, own)
		local nick = tostring(m.nick or ''):match('([A-Za-z][A-Za-z0-9_]+)')
		local e = {key = nick, nick = nick, id = tonumber(m.id), rank = 0, afk = tonumber(m.afk) or 0, own = own, org_id = org_id, phone = m.phone, status = m.status}
		if own then e.rank = (type(m.rank) == 'table' and tonumber(m.rank.count)) or 0 end
		if nick and e.id ~= myid and not seen[nick] and stroi.valid_player(e) then seen[nick] = true; list[#list + 1] = e end
	end
	if stroi.has_org(f, oid) and stroi.own_org == oid and stroi.own_updated > 0 then
		for _, m in ipairs(stroi.own_members) do add(m, oid, true) end
	end
	for _, id in ipairs(f.orgs) do
		if id ~= oid then
			for _, m in ipairs(phone_mb.by_org[id] or {}) do add(m, id, false) end
		end
	end
	for _, m in ipairs(stroi.ext[f.id] or {}) do add(m, nil, false) end
	table.sort(list, function(a, b) if a.rank ~= b.rank then return a.rank > b.rank end return a.nick < b.nick end)
	return list
end

function stroi.add_ext(f, id)
	id = tonumber(id)
	if not id or id < 0 or id > 1003 or id ~= math.floor(id) or not sampIsPlayerConnected(id) then
		stroi.say('Игрок с таким ID не найден.')
		return
	end
	local nick = sampGetPlayerNickname(id)
	if not stroi.ext[f.id] then stroi.ext[f.id] = {} end
	for _, e in ipairs(stroi.ext[f.id]) do
		if e.nick == nick then return end
	end
	table.insert(stroi.ext[f.id], {nick = nick, id = id})
end

function stroi.auto_mark(f, list) --> присутствующими отмечаются те, кто стоит рядом (до 40 м)
	local near = {}
	local mx, my_, mz = getCharCoordinates(PLAYER_PED)
	for _, ped in ipairs(getAllChars()) do
		if doesCharExist(ped) and ped ~= PLAYER_PED then
			local ok, id = sampGetPlayerIdByCharHandle(ped)
			if ok then
				local x, y, z = getCharCoordinates(ped)
				if getDistanceBetweenCoords3d(mx, my_, mz, x, y, z) <= 40 then near[id] = true end
			end
		end
	end
	local m = stroi.marks[f.id]
	if not m then
		m = {}
		stroi.marks[f.id] = m
	end
	local n = 0
	for _, e in ipairs(list) do
		if near[e.id] and m[e.key] ~= 'p' then
			m[e.key] = 'p'
			n = n + 1
		end
	end
	return n
end

function stroi.valid_player(e)
	local id = tonumber(e.id)
	return id and id >= 0 and id <= 1003 and id == math.floor(id) and type(e.nick) == 'string'
		and sampIsPlayerConnected(id) and sampGetPlayerNickname(id) == e.nick
end

function stroi.members_dialog(id, style, title, text)
	if not stroi.want or id ~= 2015 then return end
	local read = stroi.read_members
	if not read then return end
	local lines = phone_mb_lines(text)
	local next_row, page = nil, phone_mb_plain(text)
	if read.server ~= table.concat({sampGetCurrentServerAddress()}, ':') then read.error = 'Подключение изменилось.'; stroi.want = false; return false end
	if read.pages[page] then read.error = 'Сервер повторил страницу состава.'; stroi.want = false; return false end
	read.pages[page] = true
	read.page_count = read.page_count + 1
	if read.page_count > 30 then read.error = 'Слишком много страниц состава.'; stroi.want = false; return false end
	for i, line in ipairs(lines) do
		local plain = phone_mb_plain(line)
		local nick, pid = plain:match('([A-Za-z][A-Za-z0-9_]+)%s*%((%d+)%)')
		if nick then
			local rank = tonumber(plain:match('\t[^\t]- %((%d+)%)')) or tonumber(plain:match('\t[^\t]-%((%d+)%)'))
			if not rank or rank < 1 then read.error = 'Не распознан ранг сотрудника.' else
				if not read.seen[nick] then
					read.seen[nick] = true
					read.list[#read.list + 1] = {nick = nick, id = tonumber(pid), rank = {count = rank}, afk = 0}
				end
			end
		end
		if plain:find('Следующая страница', 1, true) then next_row = i - 1 - (style == 5 and 1 or 0) end
	end
	if read.error then
		stroi.want = false
		sampSendDialogResponse(id, 0, 0, '')
	elseif next_row and next_row >= 0 then
		sampSendDialogResponse(id, 1, next_row, '')
	else
		local total = tonumber(phone_mb_plain(title):match('В сети:%s*(%d+)'))
		if #read.list == 0 and total ~= 0 then read.error = 'Не удалось распознать состав /members.' end
		stroi.want = false
		sampSendDialogResponse(id, 0, 0, '')
		if not read.error then
			stroi.own_members, stroi.own_updated, stroi.own_org = read.list, os.clock(), tonumber(setting.org)
			stroi.own_server = read.server
		end
	end
	return false
end

function phone_mb_async(task)
	local token = phone_mb.token
	lua_thread.create(function()
		local ok, err = pcall(task)
		if not ok and token == phone_mb.token then
			print('[SH][phone_mb] ' .. tostring(err))
			phone_mb_stop('Ошибка сбора состава через телефон.')
		end
	end)
end

function stroi.fetch_own(token)
	stroi.own_updated = 0
	stroi.read_members = {server = table.concat({sampGetCurrentServerAddress()}, ':'), list = {}, seen = {}, pages = {}, page_count = 0}
	stroi.want = true
	sampSendChat('/members')
	local deadline = os.clock() + 15
	while stroi.want and os.clock() < deadline and token == stroi.refresh_token do wait(50) end
	if token ~= stroi.refresh_token then return false end
	if stroi.want then stroi.want = false; stroi.say('Не получен ответ /members. Наказания недоступны.'); return false end
	if stroi.read_members.error then stroi.say(stroi.read_members.error); return false end
	return stroi.own_updated > 0
end
function stroi.run_valid(run)
	return not run.cancel and sampIsLocalPlayerSpawned() and stroi.cfg().func
		and (not run.server or run.server == table.concat({sampGetCurrentServerAddress()}, ':'))
		and (not run.org_id or run.org_id == tonumber(setting.org))
end
function stroi.can_confirm()
	return not sampIsChatInputActive() and not sampIsDialogActive() and not isGamePaused() and not edit_key and not edit_cmd and not windows.main[0]
end

function stroi.refresh()
	local ui = stroi.ui
	if ui.fetching or sampIsChatInputActive() or phone_mb.active or members_wait.members then return end
	if not stroi.cfg().func or not sampIsLocalPlayerSpawned() then return end
	local f = stroi.find(ui.id)
	if not f or #f.orgs == 0 then return end
	stroi.refresh_token = (stroi.refresh_token or 0) + 1
	local token, oid, orgs = stroi.refresh_token, tonumber(setting.org), {}
	for _, id in ipairs(f.orgs) do orgs[#orgs + 1] = id end
	ui.fetching, ui.confirm = true, nil
	stroi.job_stop()
	lua_thread.create(function()
		local ok, err = pcall(function()
			if stroi.has_org(f, oid) then stroi.fetch_own(token) end
			if token ~= stroi.refresh_token or not stroi.cfg().func then return end
			local need = {}
			for _, id in ipairs(orgs) do if id ~= oid then need[#need + 1] = id end end
			if #need > 0 and phone_mb_start_for_orgs(need) then
				local scan_token = phone_mb.token
				local deadline = os.clock() + 25 + #need * 25
				while phone_mb.active and phone_mb.token == scan_token and token == stroi.refresh_token and os.clock() < deadline do wait(80) end
				if token ~= stroi.refresh_token then return end
				if phone_mb.active then phone_mb_stop('Превышено время сбора состава.') end
			end
			if stroi.has_org(f, oid) and os.clock() - stroi.own_updated > 60 then stroi.fetch_own(token) end
			if oid ~= tonumber(setting.org) then stroi.own_updated = 0 end
			ui.updated = os.time()
		end)
		if token == stroi.refresh_token then
			stroi.want, ui.fetching = false, false
			if not ok then
				phone_mb_stop()
				stroi.say('Не удалось обновить состав. Повторите попытку.')
				print('[SH][stroi.refresh] ' .. tostring(err))
			end
		end
	end)
end

function stroi.open_roster(f)
	local ui = stroi.ui
	ui.screen, ui.id, ui.filter, ui.confirm = 'roster', f.id, 'all', nil
	if not ui.fetching then stroi.refresh() end
end

function stroi.people(f) --> кнопка с человечком на карточке
	if #f.orgs == 0 then
		stroi.ui.screen, stroi.ui.id = 'orgs', f.id
	else
		stroi.open_roster(f)
	end
end

function stroi.punish_targets(f, list)
	local result, marks = {}, stroi.marks[f.id] or {}
	local rank = tonumber(setting.rank) or 0
	if stroi.own_server ~= table.concat({sampGetCurrentServerAddress()}, ':') or not stroi.leader() or stroi.ui.fetching or stroi.own_org ~= tonumber(setting.org) or stroi.own_updated <= 0 or os.clock() - stroi.own_updated > 120 then return result end
	for _, e in ipairs(list) do
		if marks[e.key] == 'a' and e.own and e.org_id == tonumber(setting.org) and e.rank > 0 and e.rank < rank and stroi.valid_player(e) then result[#result + 1] = e end
	end
	return result
end

function stroi.ask_targets(f, list) --> кого спрашивать: отсутствующие, а если их нет - неотмеченные
	local m, a, n = stroi.marks[f.id] or {}, {}, {}
	for _, e in ipairs(list) do
		if m[e.key] == 'a' then a[#a + 1] = e elseif not m[e.key] then n[#n + 1] = e end
	end
	if #a > 0 then return a end
	return n
end

function stroi.punish_msgs(cmd, targets, reason)
	local out = {targets = {}, command = cmd, org_id = tonumber(setting.org), snapshot = stroi.own_updated}
	if cmd ~= 'fwarn' and cmd ~= 'uninvite' then return out end
	local r = u8:decode(reason or ''):gsub('[\r\n\t]', ' '):gsub('{%x+}', ''):match('^%s*(.-)%s*$')
	if r == '' then r = 'Неявка на строй' end
	for _, e in ipairs(targets) do
		local prefix = string.format('/%s %d ', cmd, e.id)
		out[#out + 1] = prefix .. r:sub(1, math.max(0, 140 - #prefix))
		out.targets[#out] = {id = e.id, nick = e.nick, rank = e.rank, own = e.own, org_id = e.org_id}
	end
	return out
end

function stroi.ask_msgs(targets, mode)
	local out, group = {groups = {}}, {}
	local nick = mode == 'nick'
	local header, tail = nick and '/r Где вы? ' or '/r ', nick and '' or ' где вы?'
	local text = header
	local function flush()
		if #group > 0 then out[#out + 1] = text .. tail; out.groups[#out] = group end
		group, text = {}, header
	end
	for _, e in ipairs(targets) do
		if stroi.valid_player(e) then
			local token = nick and e.nick or ('@' .. e.id)
			local sep = #group == 0 and '' or (nick and ', ' or ' ')
			if #text + #sep + #token + #tail > 96 then flush(); sep = '' end
			text = text .. sep .. token
			group[#group + 1] = {id = e.id, nick = e.nick}
		end
	end
	flush()
	return out
end

function stroi.job_start(kind, msgs)
	if stroi.job.active or #msgs == 0 or not stroi.leader() or not stroi.cfg().func or stroi.ui.fetching then return end
	if kind ~= 'warn' and kind ~= 'fire' and kind ~= 'ask' then return end
	local job = {server = table.concat({sampGetCurrentServerAddress()}, ':'), active = true, cancel = false, kind = kind, total = #msgs, done = 0, org_id = tonumber(setting.org)}
	stroi.job = job
	lua_thread.create(function()
		local ok, err = pcall(function()
			for i, msg in ipairs(msgs) do
				if table.concat({sampGetCurrentServerAddress()}, ':') ~= job.server or job.cancel or not stroi.leader() or not stroi.cfg().func or not sampIsLocalPlayerSpawned() or tonumber(setting.org) ~= job.org_id then break end
				local can_send = true
				if kind == 'warn' or kind == 'fire' then
					local e = msgs.targets and msgs.targets[i]
					can_send = e and e.own and e.org_id == job.org_id and e.rank > 0 and e.rank < (tonumber(setting.rank) or 0)
						and stroi.own_org == job.org_id and msgs.snapshot == stroi.own_updated and os.clock() - stroi.own_updated <= 120 and stroi.valid_player(e)
				end
				if kind == 'ask' then
					can_send = msgs.groups and msgs.groups[i] ~= nil
					for _, e in ipairs((msgs.groups and msgs.groups[i]) or {}) do if not stroi.valid_player(e) then can_send = false break end end
				end
				if can_send then sampSendChat(msg); job.done = job.done + 1 end
				job.processed = i
				if i < #msgs and not stroi.sleep(job, stroi.delay) then break end
			end
		end)
		job.active = false
		job.skipped = job.total - job.done
		stroi.say(('Очередь завершена. Отправлено: %d. Не отправлено: %d.'):format(job.done, job.skipped))
		if not ok then print('[SH][stroi.job] ' .. tostring(err)); stroi.say('Отправка команд остановлена из-за ошибки.') end
	end)
end

function stroi.job_stop()
	stroi.job.cancel, stroi.job.active = true, false
end

function stroi.confirm_click(kind)
	local ui, f = stroi.ui, stroi.find(stroi.ui.id)
	if not f then return false end
	local parts = {kind, tostring(f.id), f.warn_reason}
	for _, e in ipairs(stroi.punish_targets(f, stroi.roster(f))) do parts[#parts + 1] = e.nick .. ':' .. e.id end
	local signature = table.concat(parts, '|')
	if ui.confirm == kind and ui.confirm_signature == signature and os.clock() - ui.confirm_t < 4 then
		ui.confirm, ui.confirm_signature = nil, nil
		return true
	end
	ui.confirm, ui.confirm_t, ui.confirm_signature = kind, os.clock(), signature
	return false
end

--> ---------- команды и клавиши ----------
function stroi.reg_cmd(f)
	if f.cmd ~= '' and stroi.cfg().func then
		local id = f.id
		sampRegisterChatCommand(f.cmd, function() stroi.start(id) end)
		local exist = false
		for _, c in ipairs(all_cmd) do
			if c == f.cmd then exist = true break end
		end
		if not exist then table.insert(all_cmd, f.cmd) end
	end
end

function stroi.unreg_cmd(f)
	if f.cmd ~= '' then
		sampUnregisterChatCommand(f.cmd)
		for i, c in ipairs(all_cmd) do
			if c == f.cmd then table.remove(all_cmd, i) break end
		end
	end
end

function stroi.reg_all()
	local s = stroi.cfg()
	if s.cmd ~= '' then
		sampRegisterChatCommand(s.cmd, stroi.cmd)
		local exist = false
		for _, c in ipairs(all_cmd) do
			if c == s.cmd then exist = true break end
		end
		if not exist then table.insert(all_cmd, s.cmd) end
	end
	for _, f in ipairs(s.list) do
		stroi.fix(f)
		stroi.reg_cmd(f)
	end
end

function stroi.unreg_all()
	stroi.job_stop()
	phone_mb_stop()
	stroi.refresh_token = (stroi.refresh_token or 0) + 1
	stroi.want, stroi.ui.fetching = false, false
	stroi.stop(true)
	local s = stroi.cfg()
	if s.cmd ~= '' then
		sampUnregisterChatCommand(s.cmd)
		for i, c in ipairs(all_cmd) do
			if c == s.cmd then table.remove(all_cmd, i) break end
		end
	end
	if #s.key[2] > 0 then
		rkeys.unRegisterHotKey(s.key[2])
		for i, key in ipairs(all_keys) do
			if compare_array_disable_order(key, s.key[2]) then table.remove(all_keys, i) break end
		end
	end
	for _, f in ipairs(s.list) do
		stroi.unreg_cmd(f)
		if #f.key[2] > 0 then
			rkeys.unRegisterHotKey(f.key[2])
			for i, key in ipairs(all_keys) do
				if compare_array_disable_order(key, f.key[2]) then table.remove(all_keys, i) break end
			end
		end
	end
	if windows.stroi[0] then stroi.close() end
end

function stroi.reg_keys() --> горячие клавиши строёв (при запуске скрипта)
	local s = stroi.cfg()
	if #s.key[2] > 0 and not rkeys.isHotKeyDefined(s.key[2]) then
		rkeys.registerHotKey(s.key[2], 3, true, function() on_hot_key(s.key[2]) end)
		table.insert(all_keys, s.key[2])
	end
	for _, f in ipairs(s.list) do
		stroi.fix(f)
		if #f.key[2] > 0 and not rkeys.isHotKeyDefined(f.key[2]) then
			local key = f.key
			rkeys.registerHotKey(key[2], 3, true, function() on_hot_key(key[2]) end)
			table.insert(all_keys, key[2])
		end
	end
end

function stroi.on_key(pressed) --> вызывается из on_hot_key
	local s = setting.stroi
	if type(s) ~= 'table' or not s.func or edit_key then return end
	if type(s.key) == 'table' and type(s.key[2]) == 'table' and #s.key[2] > 0 and pressed == table.concat(s.key[2], ' ') then
		stroi.cmd('')
		return
	end
	for _, f in ipairs(s.list) do
		if type(f.key) == 'table' and type(f.key[2]) == 'table' and #f.key[2] > 0 and pressed == table.concat(f.key[2], ' ') then
			stroi.start(f.id)
			return
		end
	end
end

function stroi.cmd(arg) --> /stroi
	if arg and arg:lower():find('stop') then
		if stroi.run.active then stroi.stop() else stroi.say('Сейчас строй не запущен.') end
		return
	end
	if windows.stroi[0] and not stroi.ui.closing then stroi.close() else stroi.open() end
end

--> ---------- запуск строя ----------
function stroi.start(id)
	local s = stroi.cfg()
	if not s.func then return end
	local f = stroi.find(id)
	if not f then return end
	if stroi.run.active then
		local stop_hint = s.cmd ~= '' and ('{FF8FA2}/' .. s.cmd .. ' stop{FFFFFF}') or '{FF8FA2}Строй без стопа{FFFFFF}'
		stroi.say('Строй уже запущен. Остановить: ' .. stop_hint .. '.')
		return
	end
	local acts, timers = {}, {}
	for i, a in ipairs(f.actions) do acts[i] = stroi.lines(a.text) end
	for i, t in ipairs(f.timers) do timers[i] = t end
	if #acts[1] == 0 then
		local open_hint = s.cmd ~= '' and ('{FF8FA2}/' .. s.cmd .. '{FFFFFF}') or '{FF8FA2}Меню строя{FFFFFF}'
		stroi.say('В первом действии строя нет текста. Откройте ' .. open_hint .. ' и заполните его.')
		return
	end
	local run = {active = true, cancel = false, id = f.id, acts = acts, timers = timers, step = 1, total = #acts, phase = 'send', line = 0, lines = #acts[1], timer_len = timers[1] or 0, timer_end = 0, expired = false}
	run.server, run.org_id = table.concat({sampGetCurrentServerAddress()}, ':'), tonumber(setting.org)
	stroi.marks[f.id] = {}
	stroi.ui.confirm = nil
	stroi.job_stop()
	stroi.say('Начат новый строй. Предыдущие отметки посещаемости сброшены.')
	stroi.run = run
	lua_thread.create(function() stroi.worker(run) end)
end

function stroi.stop(silent)
	local run = stroi.run
	if run.active then
		run.cancel = true
		run.active = false
		if not silent then stroi.say('Строй остановлен.') end
	end
end

function stroi.sleep(run, ms) --> пауза, которую можно прервать
	local t = os.clock() + ms / 1000
	while os.clock() < t do
		if not stroi.run_valid(run) then run.cancel = true; return false end
		wait(50)
	end
	return not run.cancel
end

function stroi.worker_body(run)
	for step = 1, run.total do
		run.step = step
		run.phase = 'send'
		local lines = run.acts[step]
		run.lines = #lines
		run.line = 0
		for i, line in ipairs(lines) do
			if not stroi.run_valid(run) then run.cancel = true; return end
			if i > 1 and not stroi.sleep(run, stroi.delay) then return end
			run.line = i
			sampSendChat(u8:decode(line))
		end
		if step >= run.total then break end
		--> таймер между действиями
		local sec = run.timers[step] or 0
		run.timer_len = sec
		run.expired = false
		if sec > 0 then
			run.phase = 'timer'
			run.timer_end = os.clock() + sec
			while os.clock() < run.timer_end do
				if not stroi.run_valid(run) then run.cancel = true; return end
				wait(50)
			end
			run.expired = true
		end
		--> ждём подтверждения
		run.phase = 'wait'
		local nxt = stroi.ord(step + 1)
		if sec > 0 then
			stroi.say('Таймер истек, приступить ' .. nxt .. '?')
		else
			stroi.say('Приступить ' .. nxt .. '?')
		end
		stroi.say('Нажмите {23E64A}' .. u8:decode(setting.enter_key[2]) .. '{FFFFFF}, чтобы подтвердить.')
		play_beep()
		local keys = {}
		for k = 1, #setting.enter_key[1] do
			local v = dec_to_key(setting.enter_key[1][k])
			if v then table.insert(keys, v) end
		end
		if #keys == 0 then keys = {13} end
		local function pressed()
			for _, v in ipairs(keys) do
				if not isKeyDown(v) then return false end
			end
			return true
		end
		wait(300)
		while true do
			wait(0)
			if not stroi.run_valid(run) then run.cancel = true; return end
			if stroi.can_confirm() and pressed() then break end
		end
		while pressed() do
			wait(0)
			if not stroi.run_valid(run) then run.cancel = true; return end
		end
	end
	run.phase = 'done'
	stroi.sleep(run, 2500)
	if stroi.run == run then run.active = false end
end

function stroi.worker(run)
	local ok, err = pcall(stroi.worker_body, run)
	if stroi.run == run then run.active = false end
	if not ok then stroi.say('Строй остановлен из-за ошибки.'); print('[SH][stroi] ' .. tostring(err)) end
end

--> перемещение мини-меню курсором (как у мини-плеера)
function stroi.move_mode()
	if stroi.moving then return end
	lua_thread.create(function()
		stroi.moving = true
		local s = stroi.cfg()
		local backup = {x = s.pos.x, y = s.pos.y}
		local was_open = windows.stroi[0]
		windows.stroi[0] = false
		sampSetCursorMode(4)
		stroi.say('Нажмите {FF6060}ЛКМ{FFFFFF}, чтобы применить или {FF6060}ESC{FFFFFF} для отмены.')
		wait(250)
		while true do
			wait(0)
			local cx, cy = getCursorPos()
			s.pos.x, s.pos.y = cx, cy
			if isKeyJustPressed(VK_LBUTTON) then
				save()
				stroi.say('Позиция мини-меню сохранена.')
				break
			elseif isKeyJustPressed(VK_ESCAPE) then
				s.pos.x, s.pos.y = backup.x, backup.y
				stroi.say('Изменение позиции отменено.')
				break
			end
		end
		sampSetCursorMode(0)
		stroi.moving = false
		windows.stroi[0] = was_open
	end)
end

--> ---------- открытие / редактирование ----------
function stroi.open()
	local ui = stroi.ui
	ui.screen, ui.id, ui.t, ui.closing, ui.del = 'list', nil, 0, false, nil
	windows.stroi[0] = true
end

function stroi.close()
	if windows.stroi[0] then stroi.ui.closing = true end
end

function stroi.edit(id)
	local ui = stroi.ui
	ui.screen, ui.id, ui.bufs[id], ui.scroll_end = 'edit', id, nil, false
end

function stroi.back()
	local ui = stroi.ui
	if ui.screen == 'edit' then
		stroi.leave_editor()
	elseif ui.screen == 'orgs' then
		local f = stroi.find(ui.id)
		ui.screen = (f and #f.orgs > 0) and 'roster' or 'list'
		stroi.flush(true)
	else
		ui.screen = 'list'
		stroi.flush(true)
	end
end

function stroi.leave_editor()
	local ui = stroi.ui
	if ui.screen == 'edit' and ui.id then
		local f = stroi.find(ui.id)
		if f and stroi.is_blank(f) then stroi.remove(ui.id) end
	end
	ui.screen, ui.id = 'list', nil
	stroi.flush(true)
end

function stroi.create()
	local s = stroi.cfg()
	local f = stroi.fix({id = stroi.new_id(), name = '', cmd = '', key = {'', {}}, actions = {{text = ''}, {text = ''}}, timers = {0}})
	table.insert(s.list, f)
	stroi.touch()
	stroi.edit(f.id)
end

function stroi.remove(id)
	stroi.job_stop()
	stroi.marks[id], stroi.ext[id] = nil, nil
	local s = stroi.cfg()
	for i, f in ipairs(s.list) do
		if f.id == id then
			stroi.unreg_cmd(f)
			if #f.key[2] > 0 then
				rkeys.unRegisterHotKey(f.key[2])
				for k, v in ipairs(all_keys) do
					if compare_array_disable_order(v, f.key[2]) then table.remove(all_keys, k) break end
				end
			end
			if stroi.run.active and stroi.run.id == id then stroi.stop(true) end
			table.remove(s.list, i)
			stroi.ui.bufs[id] = nil
			save()
			return
		end
	end
end

function stroi.buf(f, i) --> буфер ввода текста действия
	local ui = stroi.ui
	if not ui.bufs[f.id] then ui.bufs[f.id] = {} end
	local b = ui.bufs[f.id][i]
	if not b then
		b = ffi.new('char[?]', 2048)
		ffi.copy(b, f.actions[i].text, math.min(#f.actions[i].text, 2046))
		ui.bufs[f.id][i] = b
	end
	return b
end

--> ---------- цвета и мелкие помощники отрисовки ----------
function stroi.lum(c) return 0.299 * c.x + 0.587 * c.y + 0.114 * c.z end
function stroi.mix(a, b, k) return imgui.ImVec4(a.x + (b.x - a.x) * k, a.y + (b.y - a.y) * k, a.z + (b.z - a.z) * k, a.w + (b.w - a.w) * k) end
function stroi.alpha(c, a) return imgui.ImVec4(c.x, c.y, c.z, a) end
function stroi.on_acc() --> цвет текста поверх акцентной заливки
	if stroi.lum(cl.def) > 0.62 then return imgui.ImVec4(0.08, 0.08, 0.09, 1.00) end
	return imgui.ImVec4(1.00, 1.00, 1.00, 1.00)
end
function stroi.acc_text() --> акцент для текста на фоне окна
	local dark_theme = stroi.lum(cl.main) < 0.5
	if not dark_theme and stroi.lum(cl.def) > 0.55 then
		return stroi.mix(cl.def, imgui.ImVec4(0, 0, 0, 1), 0.35)
	end
	if dark_theme and stroi.lum(cl.def) < 0.38 then
		return stroi.mix(cl.def, imgui.ImVec4(1, 1, 1, 1), 0.40)
	end
	return cl.def
end

function stroi.tu(x, y, s, f, col) --> текст UTF-8
	if col then imgui.PushStyleColor(imgui.Col.Text, col) end
	if f then imgui.PushFont(f) end
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	imgui.Text(s)
	if f then imgui.PopFont() end
	if col then imgui.PopStyleColor(1) end
end

function stroi.tw(s, f)
	if f then imgui.PushFont(f) end
	local w = imgui.CalcTextSize(s).x
	if f then imgui.PopFont() end
	return w
end

function stroi.ctext(cx, y, s, f, col) --> текст по центру
	stroi.tu(cx - stroi.tw(s, f) / 2, y, s, f, col)
end

function stroi.fit(s, f, maxw) --> обрезка UTF-8 строки по ширине
	if stroi.tw(s, f) <= maxw then return s end
	local out = s
	while #out > 0 do
		local i = #out
		while i > 1 and out:byte(i) >= 0x80 and out:byte(i) < 0xC0 do i = i - 1 end
		out = out:sub(1, i - 1)
		if stroi.tw(out .. '...', f) <= maxw then return out .. '...' end
	end
	return '...'
end

function stroi.ico(cx, cy, glyph, fidx, col) --> иконка по центру точки
	imgui.PushFont(fa_font[fidx])
	local sz = imgui.CalcTextSize(glyph)
	imgui.SetCursorPos(imgui.ImVec2(cx - sz.x / 2, cy - sz.y / 2))
	if col then imgui.TextColored(col, glyph) else imgui.Text(glyph) end
	imgui.PopFont()
end

--> кнопка: kind = accent | soft | danger | ghost. Возвращает: нажата, наведена
function stroi.btn(id, x, y, w, h, label, glyph, kind, disabled)
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	local clicked = imgui.InvisibleButton(u8'##stroi_' .. id, imgui.ImVec2(w, h))
	local hov, act = imgui.IsItemHovered(), imgui.IsItemActive()
	if disabled then clicked, hov, act = false, false, false end
	local black = imgui.ImVec4(0, 0, 0, 1)
	local bg, fg
	if kind == 'accent' then
		bg = stroi.mix(cl.def, black, act and 0.20 or (hov and 0.08 or 0))
		fg = stroi.on_acc()
	elseif kind == 'danger' then
		bg = imgui.ImVec4(0.90, 0.28, 0.30, act and 0.85 or 1.00)
		fg = imgui.ImVec4(1, 1, 1, 1)
	elseif kind == 'ghost' then
		bg = (hov or act) and cl.bg or stroi.alpha(cl.bg, 0)
		fg = hov and stroi.acc_text() or cl.text
	else
		bg = act and stroi.mix(cl.bg, cl.def, 0.25) or (hov and stroi.mix(cl.bg, cl.def, 0.12) or cl.bg)
		fg = cl.text
	end
	if disabled then bg, fg = stroi.alpha(bg, 0.5), stroi.alpha(fg, 0.5) end
	if bg.w > 0.01 then gui.Draw({x, y}, {w, h}, bg, 8, 15) end
	local cy = y + h / 2
	if label and glyph then
		local gw = stroi.tw(glyph, fa_font[3])
		local lw = stroi.tw(u8(label), nil)
		local sx0 = x + (w - (gw + 8 + lw)) / 2
		stroi.ico(sx0 + gw / 2, cy, glyph, 3, fg)
		stroi.tu(sx0 + gw + 8, cy - 9, u8(label), nil, fg)
	elseif label then
		stroi.ctext(x + w / 2, cy - 9, u8(label), nil, fg)
	elseif glyph then
		stroi.ico(x + w / 2, cy, glyph, 3, fg)
	end
	return clicked, hov
end

function stroi.chip(xr, y, text, glyph) --> плашка (выравнивание по правому краю), возвращает новый xr
	local tw = stroi.tw(text, bold_font[4])
	local w = tw + 18 + (glyph and 16 or 0)
	local x0 = xr - w
	gui.Draw({x0, y}, {w, 22}, cl.bg, 6, 15)
	local tx = x0 + 9
	if glyph then
		stroi.ico(x0 + 15, y + 11, glyph, 2, stroi.acc_text())
		tx = x0 + 25
	end
	stroi.tu(tx, y + 4, text, bold_font[4])
	return x0 - 8
end

--> счётчик с кнопками: возвращает true, если нужно сделать шаг (с автоповтором при удержании)
function stroi.spin(id, x, y, w, h, glyph)
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	imgui.InvisibleButton(u8'##stroi_sp_' .. id, imgui.ImVec2(w, h))
	local hov, act = imgui.IsItemHovered(), imgui.IsItemActive()
	local ui, fire = stroi.ui, false
	if act then
		local h0 = ui.hold[id]
		local now = os.clock()
		if not h0 then
			ui.hold[id] = {t = now, n = now}
			fire = true
		else
			local gap = (now - h0.t > 1.4) and 0.03 or 0.08
			if now - h0.t > 0.45 and now - h0.n > gap then h0.n = now fire = true end
		end
	else
		ui.hold[id] = nil
	end
	gui.Draw({x, y}, {w, h}, act and stroi.mix(cl.bg, cl.def, 0.30) or (hov and stroi.mix(cl.bg, cl.def, 0.14) or cl.bg), 6, 15)
	stroi.ico(x + w / 2, y + h / 2, glyph, 3, hov and stroi.acc_text() or cl.text)
	return fire
end

--> ---------- экран: список строёв ----------
function stroi.card(idx, f, y, W) --> карточка строя; true - строй удалён
	stroi.fix(f) --> строи, созданные до обновления, получают новые поля
	local ui, run = stroi.ui, stroi.run
	local x, cw, ch = 12, W - 8 - 24, 74
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	local is_run = run.active and run.id == f.id
	gui.DrawBox({x, y}, {cw, ch}, cl.tab, is_run and stroi.alpha(cl.def, 0.75) or cl.line, 8, 15)
	gui.Draw({x, y + 14}, {4, ch - 28}, cl.def, 2, 15)
	gui.DrawCircle({x + 38, y + ch / 2}, 19, stroi.alpha(cl.def, 0.16))
	stroi.ico(x + 38, y + ch / 2, fa.USERS, 4, stroi.acc_text())
	stroi.tu(x + 70, y + 14, stroi.fit(stroi.title(f, idx), bold_font[1], 210), bold_font[1])
	stroi.tu(x + 70, y + 42, u8(stroi.summary(f)), bold_font[4], muted)
	local by = y + (ch - 34) / 2
	local bx3 = x + cw - 14 - 34
	local bx2 = bx3 - 8 - 34
	local bxp = bx2 - 8 - 34
	local bx1 = bxp - 8 - 112
	--> удалить (двойное нажатие)
	local confirming = ui.del == f.id and os.clock() - ui.del_t < 3
	local c3, h3 = stroi.btn('del' .. f.id, bx3, by, 34, 34, nil, fa.TRASH, confirming and 'danger' or 'soft')
	if h3 then imgui.SetTooltip(confirming and u8'Нажмите ещё раз для удаления' or u8'Удалить строй') end
	if c3 then
		if confirming then
			stroi.remove(f.id)
			return true
		end
		ui.del, ui.del_t = f.id, os.clock()
	end
	--> изменить
	local c2, h2 = stroi.btn('edit' .. f.id, bx2, by, 34, 34, nil, fa.PEN, 'soft')
	if h2 then imgui.SetTooltip(u8'Настроить строй') end
	if c2 then stroi.edit(f.id) end
	--> состав строя (человечек)
	local cp, hp = stroi.btn('ppl' .. f.id, bxp, by, 34, 34, nil, fa.USER, 'soft')
	if #f.orgs > 0 then gui.DrawCircle({bxp + 29, by + 5}, 4, cl.def) end
	if hp then imgui.SetTooltip(#f.orgs > 0 and (u8'Состав строя: ' .. u8(stroi.org_label(f))) or u8'Выбрать фракцию и открыть состав') end
	if cp then stroi.people(f) end
	--> запуск / стоп
	if is_run then
		if stroi.btn('run' .. f.id, bx1, by, 112, 34, 'Стоп', fa.STOP, 'soft') then stroi.stop() end
	else
		if stroi.btn('run' .. f.id, bx1, by, 112, 34, 'Запуск', fa.PLAY, 'accent', run.active) then stroi.start(f.id) end
	end
	--> команда и клавиша
	local xr = bx1 - 14
	if f.key[1] ~= '' then xr = stroi.chip(xr, y + 14, f.key[1], fa.KEYBOARD) end
	if f.cmd ~= '' then xr = stroi.chip(xr, y + 14, '/' .. f.cmd, fa.TERMINAL) end
	return false
end

function stroi.draw_list(W, H)
	local s, ui = stroi.cfg(), stroi.ui
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	if #s.list == 0 then
		local cx, cy = W / 2, H / 2 - 10
		imgui.SetCursorPos(imgui.ImVec2(cx - 38, cy - 98))
		local clicked = imgui.InvisibleButton(u8'##stroi_empty_add', imgui.ImVec2(76, 76))
		local hov = imgui.IsItemHovered()
		gui.DrawCircle({cx, cy - 60}, 38, stroi.alpha(cl.def, hov and 0.26 or 0.16))
		stroi.ico(cx, cy - 60, fa.PLUS, 6, stroi.acc_text())
		if clicked then stroi.create() end
		stroi.ctext(cx, cy - 4, u8'Тут пока пусто', bold_font[3])
		stroi.ctext(cx, cy + 44, u8'Нажмите + чтобы создать новые настройки', nil, muted)
		return
	end
	imgui.SetCursorPos(imgui.ImVec2(4, 46))
	imgui.BeginChild(u8'##stroi_list', imgui.ImVec2(W - 8, H - 58), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller(u8'Список строёв', img_step[1][0], img_duration[1][0])
	local y = 12
	for idx, f in ipairs(s.list) do
		if stroi.card(idx, f, y, W) then break end
		y = y + 84
	end
	imgui.SetCursorPos(imgui.ImVec2(0, y))
	imgui.Dummy(imgui.ImVec2(0, 4))
	imgui.EndChild()
end

--> ---------- экран: настройка строя ----------
function stroi.draw_edit(W, H)
	local s, ui = stroi.cfg(), stroi.ui
	local f = stroi.find(ui.id)
	if not f then ui.screen = 'list' return end
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	local PH = H - 52 - 62
	--> левая панель
	gui.DrawBox({16, 52}, {240, PH}, cl.tab, cl.line, 8, 15)
	stroi.tu(30, 64, u8'Название', bold_font[4], muted)
	local nm = gui.InputText({30, 92}, 206, f.name, u8'stroi_name' .. f.id, 40, u8'Например: Тренировка')
	if nm ~= f.name then f.name = nm stroi.touch() end
	gui.DrawLine({30, 120}, {242, 120}, cl.line)
	stroi.tu(30, 130, u8'Команда запуска', bold_font[4], muted)
	stroi.tu(30, 152, f.cmd ~= '' and ('/' .. f.cmd) or u8'Не назначена', nil, (f.cmd == '') and muted or nil)
	if stroi.btn('cmd', 150, 146, 92, 28, 'Изменить...', nil, 'soft') then
		lockPlayerControl(true)
		edit_cmd = true
		cur_cmd = f.cmd
		new_cmd = f.cmd
		imgui.OpenPopup(u8'Строй: команда')
	end
	gui.DrawLine({30, 184}, {242, 184}, cl.line)
	stroi.tu(30, 194, u8'Клавиша запуска', bold_font[4], muted)
	stroi.tu(30, 216, f.key[1] ~= '' and stroi.fit(f.key[1], nil, 112) or u8'Не назначена', nil, (f.key[1] == '') and muted or nil)
	if stroi.btn('key', 150, 210, 92, 28, 'Изменить...', nil, 'soft') then
		current_key = {'', {}}
		key_bool_cur = f.key[2]
		lockPlayerControl(true)
		edit_key = true
		imgui.OpenPopup(u8'Строй: клавиша')
	end
	gui.DrawLine({30, 248}, {242, 248}, cl.line)
	stroi.tu(30, 258, u8'Мини-меню на экране', bold_font[4], muted)
	if stroi.btn('move', 30, 280, 212, 30, 'Переместить...', fa.UP_DOWN_LEFT_RIGHT, 'soft') then stroi.move_mode() end
	local kn = stroi.fit(setting.enter_key[2], bold_font[4], 60)
	local hint = {u8'Каждая строка - отдельное', u8'сообщение, пауза 2 сек.', u8'После таймера нажмите ' .. kn .. ',', u8'чтобы перейти дальше.'}
	for i, h in ipairs(hint) do stroi.tu(30, 324 + (i - 1) * 16, h, bold_font[4], muted) end
	--> окна назначения команды / клавиши
	if edit_cmd then
		local r = cmd_edit(u8'Строй: команда', cur_cmd)
		if r ~= nil then
			f.cmd = r
			if r ~= '' then stroi.reg_cmd(f) end
			save()
		end
	end
	local kr = key_edit(u8'Строй: клавиша', f.key)
	if kr[1] then
		f.key = kr[2]
		save()
	end
	--> правая часть: цепочка действий и таймеров
	local AH, TH = 144, 82
	local n = #f.actions
	imgui.SetCursorPos(imgui.ImVec2(268, 52))
	imgui.BeginChild(u8'##stroi_timeline', imgui.ImVec2(436, PH), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller(u8'Действия строя', img_step[1][0], img_duration[1][0])
	local y0 = 2
	if n > 1 then
		gui.DrawLine({24, y0 + 22}, {24, y0 + (n - 1) * (AH + TH + 16) + 22}, stroi.alpha(cl.def, 0.35), 2)
	end
	local del_action = nil
	for i = 1, n do
		local y = y0 + (i - 1) * (AH + TH + 16)
		gui.DrawBox({44, y}, {372, AH}, cl.tab, cl.line, 8, 15)
		gui.DrawCircle({24, y + 22}, 12, cl.def)
		stroi.ctext(24, y + 14, tostring(i), bold_font[4], stroi.on_acc())
		stroi.tu(62, y + 12, u8('Действие ') .. i)
		if n > 1 then
			local cd, hd = stroi.btn('delact' .. i, 44 + 372 - 34, y + 6, 26, 26, nil, fa.XMARK, 'ghost')
			if hd then imgui.SetTooltip(u8'Удалить действие') end
			if cd then del_action = i end
		end
		gui.Draw({56, y + 40}, {348, 78}, cl.bg, 6, 15)
		local buf = stroi.buf(f, i)
		imgui.PushStyleColor(imgui.Col.FrameBg, imgui.ImVec4(0, 0, 0, 0))
		imgui.PushStyleVarVec2(imgui.StyleVar.FramePadding, imgui.ImVec2(8, 6))
		imgui.PushFont(font[3])
		imgui.SetCursorPos(imgui.ImVec2(56, y + 40))
		local changed = imgui.InputTextMultiline(u8'##stroi_act' .. f.id .. '_' .. i, buf, ffi.sizeof(buf), imgui.ImVec2(348, 78))
		local active = imgui.IsItemActive()
		imgui.PopFont()
		imgui.PopStyleVar(1)
		imgui.PopStyleColor(1)
		if changed then
			f.actions[i].text = ffi.string(buf)
			stroi.touch()
		end
		if f.actions[i].text == '' and not active then
			stroi.tu(66, y + 46, u8'/r Сбор на парковке!', bold_font[4], stroi.alpha(muted, 0.55))
			stroi.tu(66, y + 64, u8'/r У вас 5 минут!', bold_font[4], stroi.alpha(muted, 0.55))
		end
		local cnt = #stroi.lines(f.actions[i].text)
		stroi.tu(62, y + 122, u8(string.format('Сообщений: %d   ·   пауза %d сек между ними', cnt, stroi.delay / 1000)), bold_font[4], muted)
		--> плашка таймера после действия
		if i < n then
			local py = y + AH + 8
			local t = f.timers[i] or 0
			gui.DrawBox({44, py}, {372, TH}, stroi.mix(cl.tab, cl.def, 0.07), stroi.alpha(cl.def, 0.40), 8, 15)
			stroi.ico(66, py + 24, fa.CLOCK, 4, stroi.acc_text())
			stroi.tu(82, py + 15, u8'Таймер')
			local sx0 = 170
			local m, sc = math.floor(t / 60), t % 60
			local d = 0
			if stroi.spin('m_dec' .. i, sx0, py + 12, 22, 34, fa.ANGLE_LEFT) then d = -60 end
			stroi.ctext(sx0 + 22 + 23, py + 8, string.format('%02d', m), bold_font[3])
			if stroi.spin('m_inc' .. i, sx0 + 68, py + 12, 22, 34, fa.ANGLE_RIGHT) then d = 60 end
			stroi.ctext(sx0 + 100, py + 8, ':', bold_font[3], stroi.alpha(cl.text, 0.6))
			if stroi.spin('s_dec' .. i, sx0 + 112, py + 12, 22, 34, fa.ANGLE_LEFT) then d = -1 end
			stroi.ctext(sx0 + 134 + 23, py + 8, string.format('%02d', sc), bold_font[3])
			if stroi.spin('s_inc' .. i, sx0 + 180, py + 12, 22, 34, fa.ANGLE_RIGHT) then d = 1 end
			if d ~= 0 then
				f.timers[i] = math.max(0, math.min(5999, t + d))
				stroi.touch()
			end
			local presets = {30, 60, 120, 300, 600}
			for k, v in ipairs(presets) do
				local px = 60 + (k - 1) * 64
				local sel = (t == v)
				imgui.SetCursorPos(imgui.ImVec2(px, py + 54))
				local cp = imgui.InvisibleButton(u8'##stroi_pr' .. i .. '_' .. k, imgui.ImVec2(56, 20))
				local hp = imgui.IsItemHovered()
				gui.Draw({px, py + 54}, {56, 20}, sel and cl.def or (hp and stroi.mix(cl.bg, cl.def, 0.14) or cl.bg), 6, 15)
				stroi.ctext(px + 28, py + 56, stroi.fmt(v), bold_font[4], sel and stroi.on_acc() or nil)
				if cp then
					f.timers[i] = v
					stroi.touch()
				end
			end
		end
	end
	local y_end = y0 + (n - 1) * (AH + TH + 16) + AH + 12
	if stroi.btn('add_act', 44, y_end, 372, 40, 'Добавить действие', fa.PLUS, 'soft') then
		table.insert(f.timers, 0)
		table.insert(f.actions, {text = ''})
		ui.bufs[f.id] = nil
		ui.scroll_end = true
		stroi.touch()
	end
	if del_action then
		table.remove(f.actions, del_action)
		if del_action <= #f.timers then table.remove(f.timers, del_action) else table.remove(f.timers, #f.timers) end
		stroi.fix(f)
		ui.bufs[f.id] = nil
		stroi.touch()
	end
	imgui.SetCursorPos(imgui.ImVec2(0, y_end + 52))
	imgui.Dummy(imgui.ImVec2(0, 6))
	if ui.scroll_end then
		imgui.SetScrollY(imgui.GetScrollMaxY())
		ui.scroll_end = false
	end
	imgui.EndChild()
	--> нижняя панель
	gui.DrawLine({4, H - 56}, {W - 4, H - 56}, cl.line)
	if stroi.btn('test', 16, H - 46, 170, 34, 'Запустить строй', fa.PLAY, 'soft', stroi.run.active) then stroi.start(f.id) end
	stroi.tu(200, H - 37, u8'Изменения сохраняются автоматически', bold_font[4], muted)
	if stroi.btn('done', W - 16 - 140, H - 46, 140, 34, 'Готово', fa.CHECK, 'accent') then stroi.leave_editor() end
end

function stroi.draw_orgs(W, H)
	local ui = stroi.ui
	local f = stroi.find(ui.id)
	if not f then ui.screen = 'list' return end
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	stroi.ctext(W / 2, 52, u8'Выберите фракцию для этого строя', bold_font[1])
	stroi.ctext(W / 2, 80, u8'Можно выбрать несколько. Обновление: ваша фракция через /members,', bold_font[4], muted)
	stroi.ctext(W / 2, 96, u8'остальные — скрыто через телефон. Можно добавить вручную по ID.', bold_font[4], muted)
	local cw, ch, gx, gy = 220, 46, 14, 10
	for i = 1, #stroi.org_names do
		local x, y = 16 + ((i - 1) % 3) * (cw + gx), 124 + math.floor((i - 1) / 3) * (ch + gy)
		local sel = stroi.has_org(f, i)
		imgui.SetCursorPos(imgui.ImVec2(x, y))
		local clicked = imgui.InvisibleButton(u8'##stroi_org' .. i, imgui.ImVec2(cw, ch))
		local hov = imgui.IsItemHovered()
		gui.DrawBox({x, y}, {cw, ch}, sel and stroi.mix(cl.tab, cl.def, 0.14) or (hov and stroi.mix(cl.tab, cl.def, 0.06) or cl.tab), sel and cl.def or cl.line, 8, 15)
		gui.Draw({x + 12, y + 13}, {20, 20}, sel and cl.def or cl.bg, 6, 15)
		if sel then stroi.ico(x + 22, y + 23, fa.CHECK, 2, stroi.on_acc()) end
		stroi.tu(x + 44, y + 6, stroi.fit(u8(stroi.org_short[i]), nil, cw - 100))
		stroi.tu(x + 44, y + 26, stroi.fit(u8(stroi.org_names[i]), bold_font[4], cw - 54), bold_font[4], muted)
		if i == setting.org then stroi.tu(x + cw - 12 - stroi.tw(u8'ваша', bold_font[4]), y + 8, u8'ваша', bold_font[4], stroi.acc_text()) end
		if clicked then stroi.toggle_org(f, i) end
	end
	gui.DrawLine({4, H - 56}, {W - 4, H - 56}, cl.line)
	stroi.tu(16, H - 37, u8('Выбрано фракций: ') .. #f.orgs, bold_font[4], muted)
	if stroi.btn('orgs_done', W - 16 - 140, H - 46, 140, 34, 'Готово', fa.CHECK, 'accent') then
		stroi.flush(true)
		if #f.orgs > 0 then stroi.open_roster(f) else ui.screen = 'list' end
	end
end

--> ---------- экран: состав строя ----------
function stroi.mark_btn(id, x, y, glyph, active, kind) --> кнопка отметки (галочка / крестик)
	imgui.SetCursorPos(imgui.ImVec2(x, y))
	local clicked = imgui.InvisibleButton(u8'##stroi_mk' .. id, imgui.ImVec2(28, 28))
	local hov = imgui.IsItemHovered()
	local bg, fg
	if active then
		if kind == 'p' then bg, fg = cl.def, stroi.on_acc() else bg, fg = imgui.ImVec4(0.90, 0.28, 0.30, 1), imgui.ImVec4(1, 1, 1, 1) end
	else
		bg = hov and stroi.mix(cl.bg, kind == 'p' and cl.def or imgui.ImVec4(0.90, 0.28, 0.30, 1), 0.25) or cl.bg
		fg = imgui.ImVec4(0.50, 0.50, 0.50, 0.95)
	end
	gui.Draw({x, y}, {28, 28}, bg, 7, 15)
	stroi.ico(x + 14, y + 14, glyph, 3, fg)
	return clicked
end

function stroi.member_row(f, e, v, y)
	local x, w = 0, 456
	local tint = cl.tab
	if v == 'p' then tint = stroi.mix(cl.tab, cl.def, 0.14) elseif v == 'a' then tint = stroi.mix(cl.tab, imgui.ImVec4(0.90, 0.28, 0.30, 1), 0.14) end
	gui.DrawBox({x, y}, {w, 38}, tint, cl.line, 8, 15)
	if stroi.mark_btn('p' .. e.key, x + 6, y + 5, fa.CHECK, v == 'p', 'p') then stroi.mark(f, e.key, 'p') end
	if stroi.mark_btn('a' .. e.key, x + 40, y + 5, fa.XMARK, v == 'a', 'a') then stroi.mark(f, e.key, 'a') end
	stroi.tu(x + 80, y + 10, stroi.fit(e.nick, nil, 196))
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	if e.rank > 0 then
		gui.Draw({x + 284, y + 9}, {24, 20}, cl.bg, 6, 15)
		stroi.ctext(x + 296, y + 11, tostring(e.rank), bold_font[4])
	end
	stroi.tu(x + 318, y + 12, u8('ID ') .. e.id, bold_font[4], muted)
	if e.afk > 0 then stroi.tu(x + 376, y + 12, 'AFK ' .. e.afk, bold_font[4], imgui.ImVec4(0.95, 0.65, 0.20, 1)) end
end

function stroi.draw_roster(W, H)
	local ui = stroi.ui
	local f = stroi.find(ui.id)
	if not f then ui.screen = 'list' return end
	if #f.orgs == 0 then ui.screen = 'orgs' return end
	local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
	local own, leader = stroi.has_org(f, setting.org), stroi.leader()
	local list = stroi.roster(f)
	local marks = stroi.marks[f.id] or {}
	local cp, ca, cn = 0, 0, 0
	for _, e in ipairs(list) do
		local v = marks[e.key]
		if v == 'p' then cp = cp + 1 elseif v == 'a' then ca = ca + 1 else cn = cn + 1 end
	end
	--> фракции (мелко) и состояние данных
	stroi.tu(16, 56, u8'Фракции:', bold_font[4], muted)
	local cx = 84
	for i = 1, math.min(2, #f.orgs) do
		local txt = u8(stroi.org_short[f.orgs[i]])
		local cw = stroi.tw(txt, bold_font[4]) + 18
		gui.Draw({cx, 52}, {cw, 22}, cl.bg, 6, 15)
		stroi.tu(cx + 9, 56, txt, bold_font[4])
		cx = cx + cw + 6
	end
	if #f.orgs > 2 then
		stroi.tu(cx + 2, 56, '+' .. (#f.orgs - 2), bold_font[4], muted)
		cx = cx + 28
	end
	local ce, he = stroi.btn('orgs_edit', cx, 50, 26, 26, nil, fa.PEN, 'ghost')
	if he then imgui.SetTooltip(u8'Изменить фракции') end
	if ce then ui.screen = 'orgs' return end
	local info = ui.fetching and 'Загрузка...' or (own and (stroi.own_updated > 0 and ('Ваш состав: ' .. math.floor(os.clock() - stroi.own_updated) .. ' сек') or 'Ваш состав не получен') or (ui.updated > 0 and ('Обновлено ' .. (os.time() - ui.updated) .. ' сек назад') or 'Нажмите обновить'))
	stroi.tu(W - 16 - stroi.tw(u8(info), bold_font[4]), 56, u8(info), bold_font[4], muted)
	--> фильтр
	local segs = {{'all', 'Все', 'Все', #list}, {'p', 'Присутствуют', 'Присутств.', cp}, {'a', 'Отсутствуют', 'Отсутств.', ca}, {'n', 'Не отмечены', 'Не отмеч.', cn}}
	local total = 0
	for _, sg in ipairs(segs) do total = total + stroi.tw(u8(sg[2]) .. ' (' .. sg[4] .. ')', bold_font[4]) + 28 end
	local short = total > 468
	local sx0 = 16
	for _, sg in ipairs(segs) do
		local label = u8(short and sg[3] or sg[2]) .. ' (' .. sg[4] .. ')'
		local w = stroi.tw(label, bold_font[4]) + 22
		imgui.SetCursorPos(imgui.ImVec2(sx0, 84))
		local c = imgui.InvisibleButton(u8'##stroi_flt' .. sg[1], imgui.ImVec2(w, 28))
		local hv = imgui.IsItemHovered()
		local sel = ui.filter == sg[1]
		gui.Draw({sx0, 84}, {w, 28}, sel and cl.def or (hv and stroi.mix(cl.bg, cl.def, 0.14) or cl.bg), 8, 15)
		stroi.tu(sx0 + 11, 91, label, bold_font[4], sel and stroi.on_acc() or nil)
		if c then ui.filter = sg[1] end
		sx0 = sx0 + w + 6
	end
	--> список сотрудников
	imgui.SetCursorPos(imgui.ImVec2(16, 122))
	imgui.BeginChild(u8'##stroi_roster', imgui.ImVec2(470, H - 122 - 62), false, imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollWithMouse)
	imgui.Scroller(u8'Состав строя', img_step[1][0], img_duration[1][0])
	local y, shown = 0, 0
	for _, e in ipairs(list) do
		local v = marks[e.key]
		if ui.filter == 'all' or (ui.filter == 'p' and v == 'p') or (ui.filter == 'a' and v == 'a') or (ui.filter == 'n' and not v) then
			shown = shown + 1
			stroi.member_row(f, e, v, y)
			y = y + 42
		end
	end
	if shown == 0 then
		local msg = u8'В этом фильтре никого нет'
		if #list == 0 then
			msg = ui.fetching and u8'Загружаю состав...' or u8'Список пуст. Нажмите обновить в углу'
		end
		stroi.ctext(228, 90, msg, nil, muted)
	end
	imgui.SetCursorPos(imgui.ImVec2(0, y))
	imgui.Dummy(imgui.ImVec2(0, 4))
	imgui.EndChild()
	--> панель действий
	gui.DrawBox({498, 84}, {206, H - 84 - 62}, cl.tab, cl.line, 8, 15)
	if stroi.btn('auto', 510, 96, 87, 32, 'Рядом', fa.CHECK_DOUBLE, 'soft') then stroi.auto_mark(f, list) end
	if imgui.IsItemHovered() then imgui.SetTooltip(u8'Отметить присутствующими тех, кто рядом (до 40 м)') end
	if stroi.btn('reset', 605, 96, 87, 32, 'Сброс', fa.ROTATE_LEFT, 'soft') then stroi.marks[f.id] = {} end
	if imgui.IsItemHovered() then imgui.SetTooltip(u8'Сбросить все отметки') end
	stroi.tu(510, 140, u8'Добавить игрока по ID', bold_font[4], muted)
	local nid = gui.InputText({512, 164}, 110, ui.add_id, u8'stroi_addid', 4, u8'ID')
	ui.add_id = nid:gsub('%D', '')
	if stroi.btn('addid', 640, 158, 52, 30, nil, fa.PLUS, 'soft') then
		stroi.add_ext(f, ui.add_id)
		ui.add_id = ''
	end
	gui.DrawLine({510, 196}, {692, 196}, cl.line)
	if leader then
		stroi.tu(510, 204, u8'Причина / статья', bold_font[4], muted)
		local rs = gui.InputText({512, 228}, 170, f.warn_reason, u8'stroi_reason' .. f.id, 60, u8'Неявка на строй')
		if rs ~= f.warn_reason then
			f.warn_reason = rs
			stroi.touch()
		end
		local pt, at = stroi.punish_targets(f, list), stroi.ask_targets(f, list)
		local busy = stroi.job.active
		local cw_on = ui.confirm == 'warn' and os.clock() - ui.confirm_t < 4
		local cf_on = ui.confirm == 'fire' and os.clock() - ui.confirm_t < 4
		local wl = cw_on and ('Точно? (' .. #pt .. ')') or ('Выговор всем (' .. #pt .. ')')
		local c1, h1 = stroi.btn('warn', 510, 254, 182, 34, wl, fa.CIRCLE_EXCLAMATION, cw_on and 'danger' or 'soft', busy or #pt == 0)
		if h1 then imgui.SetTooltip(u8'Выдать выговор всем не явившимся (по очереди, /fwarn)') end
		if c1 and stroi.confirm_click('warn') then stroi.job_start('warn', stroi.punish_msgs('fwarn', pt, f.warn_reason)) end
		local fl = cf_on and ('Точно? (' .. #pt .. ')') or ('Уволить всех (' .. #pt .. ')')
		local c2, h2 = stroi.btn('fire', 510, 294, 182, 34, fl, fa.USER_XMARK, cf_on and 'danger' or 'soft', busy or #pt == 0)
		if h2 then imgui.SetTooltip(u8'Уволить всех неявившихся (по очереди, /uninvite)') end
		if c2 and stroi.confirm_click('fire') then stroi.job_start('fire', stroi.punish_msgs('uninvite', pt, f.warn_reason)) end
		local c3, h3 = stroi.btn('ask', 510, 334, 182, 34, 'Где они? (' .. #at .. ')', fa.WALKIE_TALKIE, 'soft', busy or #at == 0)
		if h3 then imgui.SetTooltip(u8'Спросить в рации, где они (отсутствующие, а если их нет - неотмеченные)') end
		if c3 then stroi.job_start('ask', stroi.ask_msgs(at, f.ask_mode)) end
		if busy then
			stroi.tu(510, 380, u8('Отправка ') .. stroi.job.done .. '/' .. stroi.job.total, bold_font[4], muted)
			if stroi.btn('jobstop', 620, 374, 72, 26, 'Стоп', nil, 'soft') then stroi.job_stop() end
		else
			for k, md in ipairs({{'id', '@ID'}, {'nick', 'Ники'}}) do
				local bx = 510 + (k - 1) * 94
				imgui.SetCursorPos(imgui.ImVec2(bx, 374))
				local cm = imgui.InvisibleButton(u8'##stroi_md' .. md[1], imgui.ImVec2(88, 26))
				local sel = f.ask_mode == md[1]
				gui.Draw({bx, 374}, {88, 26}, sel and cl.def or cl.bg, 7, 15)
				stroi.ctext(bx + 44, 379, md[2], bold_font[4], sel and stroi.on_acc() or nil)
				if cm and not sel then
					f.ask_mode = md[1]
					stroi.touch()
				end
			end
		end
	else
		local hint = {u8'Выговоры и увольнение', u8'доступны с 9 ранга.', u8'Вы можете отмечать, кто', u8'пришёл, а кого нет.'}
		for i, h in ipairs(hint) do stroi.tu(510, 208 + (i - 1) * 18, h, bold_font[4], muted) end
	end
	--> нижняя панель
	gui.DrawLine({4, H - 56}, {W - 4, H - 56}, cl.line)
	if stroi.btn('test2', 16, H - 46, 170, 34, 'Запустить строй', fa.PLAY, 'soft', stroi.run.active) then stroi.start(f.id) end
	if stroi.btn('done2', W - 16 - 140, H - 46, 140, 34, 'Готово', fa.CHECK, 'accent') then stroi.back() end
end

--> ---------- главное окно /stroi ----------
win.stroi = imgui.OnFrame(
	function() return windows.stroi[0] end,
	function(self)
		local W, H = 720, (stroi.ui.screen == 'roster' or stroi.ui.screen == 'orgs') and 520 or 468
		local ui = stroi.ui
		local dt = imgui.GetIO().DeltaTime
		if ui.closing then
			ui.t = ui.t - dt * 6
			if ui.t <= 0 then
				ui.t, ui.closing = 0, false
				windows.stroi[0] = false
				stroi.leave_editor()
				return
			end
		else
			ui.t = math.min(1, ui.t + dt * 6)
		end
		stroi.flush(false)
		imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, math.max(0.001, ui.t))
		imgui.SetNextWindowPos(imgui.ImVec2(sx / 2, sy / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
		imgui.SetNextWindowSize(imgui.ImVec2(W, H))
		imgui.Begin('StroiMenu', windows.stroi, imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoSavedSettings)
		bug_fix_input()
		gui.Draw({4, 4}, {W - 8, H - 8}, cl.main, 12, 15)
		if winter then winter.begin(W, H) end
		--> шапка
		gui.DrawLine({4, 38}, {W - 4, 38}, cl.line)
		imgui.SetCursorPos(imgui.ImVec2(11, 11))
		if imgui.InvisibleButton(u8'##stroi_close', imgui.ImVec2(20, 20)) then stroi.close() end
		if imgui.IsItemHovered() then
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.30, 0.38, 1.00))
		else
			gui.DrawCircle({21, 21}, 7, imgui.ImVec4(0.98, 0.40, 0.38, 1.00))
		end
		if ui.screen ~= 'list' then
			imgui.SetCursorPos(imgui.ImVec2(40, 5))
			if imgui.InvisibleButton(u8'##stroi_exit', imgui.ImVec2(48, 32)) then stroi.back() end
			if imgui.IsItemActive() or imgui.IsItemHovered() then
				if an[35] < 0.45 then an[35] = an[35] + (anim * 1) end
			elseif an[35] > 0 then
				an[35] = an[35] - (anim * 1)
			end
			if setting.cl == 'White' then
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 - an[35], 0.50 - an[35], 0.50 - an[35], 1.00))
			else
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 + an[35], 0.50 + an[35], 0.50 + an[35], 1.00))
			end
			gui.FaText(55, 6, fa.ARROW_RIGHT_TO_BRACKET, fa_font[4])
			gui.Text(45, 22, 'Выйти')
			imgui.PopStyleColor(1)
		end
		local titles = {edit = 'Настройка строя', orgs = 'Выбор фракций', roster = 'Состав строя', list = 'Умный строй'}
		local title = u8(titles[ui.screen] or titles.list)
		local tw = stroi.tw(title, bold_font[1])
		stroi.tu(W / 2 - tw / 2, 11, title, bold_font[1])
		if ui.screen == 'list' then
			imgui.SetCursorPos(imgui.ImVec2(W - 148, 5))
			if imgui.InvisibleButton(u8'##stroi_add', imgui.ImVec2(65, 32)) then stroi.create() end
			if imgui.IsItemActive() or imgui.IsItemHovered() then
				if an[33] < 0.45 then an[33] = an[33] + (anim * 1) end
			elseif an[33] > 0 then
				an[33] = an[33] - (anim * 1)
			end
			if setting.cl == 'White' then
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 - an[33], 0.50 - an[33], 0.50 - an[33], 1.00))
			else
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 + an[33], 0.50 + an[33], 0.50 + an[33], 1.00))
			end
			command_toolbar_label(W - 148, fa.PLUS, 'Добавить')
			imgui.PopStyleColor(1)

			imgui.SetCursorPos(imgui.ImVec2(W - 78, 5))
			if imgui.InvisibleButton(u8'##stroi_settings', imgui.ImVec2(65, 32)) then
				stroi.close()
				windows.main[0] = true
				tab = 'settings'
				name_tab = u8'Главное'
				tab_settings = 23
			end
			if imgui.IsItemActive() or imgui.IsItemHovered() then
				if an[34] < 0.45 then an[34] = an[34] + (anim * 1) end
			elseif an[34] > 0 then
				an[34] = an[34] - (anim * 1)
			end
			if setting.cl == 'White' then
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 - an[34], 0.50 - an[34], 0.50 - an[34], 1.00))
			else
				imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.50 + an[34], 0.50 + an[34], 0.50 + an[34], 1.00))
			end
			command_toolbar_label(W - 78, fa.GEAR, 'Настройки')
			imgui.PopStyleColor(1)
		end
		if winter then winter.small_front('stroi_win', W, H, tw, 21) end
		if ui.screen == 'roster' then
			if stroi.btn('refresh', W - 116, 7, 100, 26, 'Обновить', fa.ARROWS_ROTATE, 'soft', ui.fetching) then stroi.refresh() end
		end
		if ui.screen == 'edit' then stroi.draw_edit(W, H) elseif ui.screen == 'orgs' then stroi.draw_orgs(W, H) elseif ui.screen == 'roster' then stroi.draw_roster(W, H) else stroi.draw_list(W, H) end
		if winter then winter.finish() end
		imgui.End()
		imgui.PopStyleVar(1)
	end
)

--> ---------- мини-меню с таймером ----------
function stroi.timer_visible()
	local s = setting.stroi
	if stroi.run.active or stroi.moving then return true end
	return type(s) == 'table' and s.func == true and windows.stroi[0]
end

win.stroi_timer = imgui.OnFrame(
	function() return stroi.timer_visible() end,
	function(self)
		self.HideCursor = true
		local s, run = stroi.cfg(), stroi.run
		local W, H = 212, 104
		local muted = imgui.ImVec4(0.50, 0.50, 0.50, 0.90)
		imgui.SetNextWindowPos(imgui.ImVec2(s.pos.x, s.pos.y), stroi.moving and imgui.Cond.Always or imgui.Cond.Appearing, imgui.ImVec2(0.5, 0.5))
		imgui.SetNextWindowSize(imgui.ImVec2(W, H))
		local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoSavedSettings + imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoBringToFrontOnFocus
		if stroi.moving then flags = flags + imgui.WindowFlags.NoMouseInputs end
		imgui.Begin('StroiTimer', nil, flags)
		gui.DrawBox({4, 4}, {W - 8, H - 8}, cl.main, cl.line, 12, 15)
		--> заголовок
		gui.DrawCircle({26, 24}, 12, stroi.alpha(cl.def, 0.18))
		stroi.ico(26, 24, fa.USERS, 3, stroi.acc_text())
		stroi.tu(46, 15, u8'Строй', bold_font[1])
		local big, cap, prog = '', '', 0
		local col, pulse = nil, stroi.mix(stroi.acc_text(), cl.text, 0.30 + 0.30 * math.sin(os.clock() * 5))
		if not run.active then --> предпросмотр (меню можно перетаскивать, когда включён курсор)
			big, cap, prog, col = '05:00', '', 1, muted
		else
			stroi.tu(W - 16 - stroi.tw(run.step .. '/' .. run.total, bold_font[4]), 18, run.step .. '/' .. run.total, bold_font[4], muted)
			if run.phase == 'send' then
				big = (run.step < run.total) and stroi.fmt(run.timers[run.step] or 0) or '--:--'
				cap = 'Отправка ' .. run.line .. '/' .. run.lines
				prog = (run.lines > 0) and (run.line / run.lines) or 0
				col = muted
			elseif run.phase == 'timer' then
				local left = math.max(0, run.timer_end - os.clock())
				big = stroi.fmt(math.ceil(left))
				cap = 'До следующего действия'
				prog = (run.timer_len > 0) and (left / run.timer_len) or 0
				if left <= 10 then col = pulse end
			elseif run.phase == 'wait' then
				big = run.expired and 'Время истекло!' or 'Подтвердите'
				cap = u8:decode(setting.enter_key[2]) .. ' - продолжить'
				prog, col = 1, pulse
			else
				big, cap, prog = 'Готово', 'Строй выполнен', 1
			end
		end
		local bigf = (#big > 6 and not big:find(':')) and bold_font[1] or bold_font[3]
		local bigu = u8(big)
		stroi.ctext(W / 2, (bigf == bold_font[3]) and 40 or 50, bigu, bigf, col)
		stroi.ctext(W / 2, 77, u8(cap), bold_font[4], muted)
		--> полоса прогресса
		gui.Draw({16, H - 12}, {W - 32, 4}, cl.bg, 4, 15)
		if prog > 0.003 then gui.Draw({16, H - 12}, {(W - 32) * math.min(1, prog), 4}, cl.def, 4, 15) end
		imgui.End()
	end
)

