local server_marker_positions = ffi.cast('const float*', 0xC7F168)

function getTargetServerCoordinates()
	local target_server, x, y, z = false, 0.0, 0.0, 0.0
	for id = 0, 31 do
		local index = id * 14 -- прежний шаг 56 байт / sizeof(float)
		local px, py, pz = server_marker_positions[index], server_marker_positions[index + 1], server_marker_positions[index + 2]
		if px ~= 0.0 or py ~= 0.0 or pz ~= 0.0 then
			x, y, z = px, py, pz
			target_server = true
		end
	end
	
	return target_server, x, y, z
end

