function download_admin_list()
	local url = 'https://raw.githubusercontent.com/kysteno4ek/StateHelper/main/data/nicks.json'
	local save_path = dir .. '/config/Admins.json'
	
	sh_resource.download(url, save_path, function(id, status)
	end)
end
download_admin_list()

function get_last_lines(log, n)
	local function split_text(input, length)
		local parts = {}
		while #input > length do
			local part = input:sub(1, length)
			table.insert(parts, part)
			input = input:sub(length + 1)
		end
		
		if #input > 0 then
			table.insert(parts, input)
		end
		
		return parts
	end
	
	local lines = {}
	for line in log:gmatch("[^\n]+") do
		table.insert(lines, line)
	end
	
	local start_index = #lines - n + 1
	if start_index < 1 then start_index = 1 end

	local last_lines = {}
	local num_str = 1
	for i = start_index, #lines do
		local name_script_error, line_error, error_text, error_path
		
		if lines[i]:find("%(error%)") then
			name_script_error, error_path, line_error, error_text = lines[i]:match("%(error%)%s*(.-):%s*(.-%.lua):(%d+):%s*(.+)")
			if not line_error then
				name_script_error, error_text = lines[i]:match("%(error%)%s*(.-):%s*(.+)")
				line_error = "???"
			end

			if name_script_error and error_text then
				local formatted_line = string.format("[%d] [Лог Краша] {FFFFFF}ОШИБКА В СКРИПТЕ %s[%s], ЛИНИЯ %s: %s", num_str, name_script_error, scr.version, line_error, error_text)
				local parts = split_text(formatted_line, 120)
				for j, part in ipairs(parts) do
					table.insert(last_lines, (j == 1 and "" or "{FFFFFF}") .. part)
				end
				num_str = num_str + 1
			end
		elseif lines[i]:find('in function') and not lines[i]:find('>$') then
			name_script_error, line_error, error_text = lines[i]:match("stack traceback:%s*(.-%.lua):(%d+):%s*(.+)")
			if not line_error then
				line_error = "???"
				name_script_error = "script"
				error_text = lines[i]:match("stack traceback:%s*(.+)") or lines[i]
			end
			
			if error_text then
				local formatted_line = string.format("[%d] [Лог краша] {FFFFFF}Ошибка функции в скрипте %s[%s], строка %s: %s", num_str, name_script_error or "?", scr.version, line_error or "?", error_text or "?")
				local parts = split_text(formatted_line, 120)
				for j, part in ipairs(parts) do
					table.insert(last_lines, (j == 1 and "" or "{FFFFFF}") .. part)
				end
				num_str = num_str + 1
			end
		end
	end

	return last_lines
end

function reset_state()
	scene_active = false
	scene_edit_pos = false
	new_scene = false
	off_scene = false
	change_pos_onstat = false
	is_mini_player_pos = false
	camhack_active = false
	if isPlayerControlLocked() then
		lockPlayerControl(false)
	end
	displayRadar(true)
	displayHud(true)
	restoreCameraJumpcut()
	setCameraBehindPlayer()
	sampSetCursorMode(0)
	imgui.ShowCursor = true
	setVirtualKeyDown(0x79, false)
	evalanon("document.body.style.display = 'block'")
end
 
function onScriptTerminate(script, game_quit)
	if script ~= thisScript() then return end
	sh_browser_close()
	if game_quit then return end  -- нормальный выход / перезагрузка игры
	pcall(save)
	if play and play.stream then
		pcall(bass.BASS_ChannelStop, play.stream)
		pcall(bass.BASS_StreamFree, play.stream)
		play.stream = nil
	end
	pcall(cover_flush)
	if camhack_active then
		pcall(displayRadar, true)
		pcall(displayHud, true)
		pcall(lockPlayerControl, false)
		pcall(restoreCameraJumpcut)
		pcall(setCameraBehindPlayer)
	end
	debug_log('terminate quit=%s', tostring(game_quit))
	local f = io.open(dir .. '/moonloader.log', 'rb')
	if not f then return end
	local length = f:seek('end') or 0
	f:seek('set', length >= sh_log_start and sh_log_start or 0)
	local crash_log = f:read('*a') or ''
	f:close()

 local script_name = (thisScript().filename or 'StateHelper.lua'):lower()
 local relevant, active = {}, false
 for line in crash_log:gmatch('[^\r\n]+') do
  if line:find('%(error%)') then
   local lower = line:lower()
   local owner = lower:match('%(error%)%s*(.-):%s*')
   active = owner == 'state helper' or owner == 'statehelper' or owner == script_name
   if not active and owner and owner:match('statehelper%.lua$') then active = true end
  elseif line:match('^%[.-%]%s*%([%w_]+%)') then
   active = false
  end
  if active then relevant[#relevant + 1] = line end
 end
 if #relevant == 0 then return end
 local log_array = get_last_lines(table.concat(relevant, '\n'), math.max(10, #relevant))
	local clipboard = {}
	if #log_array == 0 then return end

	if setting and setting.show_logs then
		sampAddChatMessage('[SH] Скрипт неожиданно завершил работу со следующими ошибками:', 0xFF5345)
		for i = 1, #log_array do
			sampAddChatMessage(log_array[i], 0xFF5345)
			table.insert(clipboard, u8(log_array[i]))
		end
	else
		for i = 1, #log_array do
			table.insert(clipboard, u8(log_array[i]))
		end
	end
	-- при выгрузке скрипта контекста mimgui может уже не быть, и вызов роняет игру
	if imgui.GetCurrentContext() ~= nil then
		pcall(imgui.SetClipboardText, table.concat(clipboard, '\n'))
	end
	local fw = io.open(sh_audit.private_root .. '/crashlog.log', 'w')
	if fw then
		fw:write(table.concat(clipboard, '\n'))
		fw:flush()
		fw:close()
	end

	if setting and setting.show_logs then
		sampAddChatMessage('[SH] Лог краша сохранён в файлах скрипта, а также скопирован в буфер обмена.', 0xFF5345)
	else
		sampAddChatMessage('[SH] Скрипт неожиданно завершил работу. Лог сохранён в файлах скрипта, а также скопирован в буфер обмена.', 0xFF5345)
	end
end
