function correct_chat(text) --> Исправление чата
	if not text or text:match("^%s*$") then return text end
	text = text:gsub("^%s*(.-)%s*$", "%1")
	text = text:gsub(",(%S)", ", %1")
	local first_char = text:sub(1, 1)
	local rest_of_text = text:sub(2)
	local lower = 'абвгґдеєжзиіїйклмнопрстуфхцчшщъыьэюяё'
	local upper = 'АБВГҐДЕЄЖЗИІЇЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯЁ'
	local pos = lower:find(first_char, 1, true)
	if pos then
		first_char = upper:sub(pos, pos)
	else
		first_char = first_char:upper()
	end
	text = first_char .. rest_of_text
	text = text:gsub("([.?!]%s*)([абвгґдеєжзиіїйклмнопрстуфхцчшщъыьэюяёa-z])", function(punctuation_and_space, letter)
		local pos_cyr = lower:find(letter, 1, true)
		if pos_cyr then
			return punctuation_and_space .. upper:sub(pos_cyr, pos_cyr)
		else
			return punctuation_and_space .. letter:upper()
		end
	end)
	if not text:match('[%.%!%?%,%/%\\%)%(%:]$') then
		text = text .. '.'
	end
	return text
end

function remove(path)
	if lfs.attributes(path, "mode") == "directory" then
		for file in lfs.dir(path) do
			if file ~= "." and file ~= ".." then
				remove(path .. "/" .. file)
			end
		end
		lfs.rmdir(path)
	else
		os.remove(path)
	end
end

function AddMoveButtons(i, pxl)
 local actions = bl_cmd.act
 local current = actions[i]
 if not current or current[1] == 'ELSE' or current[1] == 'END' then return false end
 local function block_end(first)
  if actions[first][1] ~= 'IF' then return first end
  local depth = 0
  for k = first, #actions do
   local kind = actions[k][1]
   if kind == 'IF' then depth = depth + 1 end
   if kind == 'END' then
    depth = depth - 1
    if depth == 0 then
     if actions[k][2] ~= actions[first][4] then return nil end
     return k
    end
   end
  end
 end
 local last = block_end(i)
 if not last then return false end
 local previous = i - 1
 if previous > 0 and actions[previous][1] == 'END' then
  local depth = 1
  for k = previous - 1, 1, -1 do
   if actions[k][1] == 'END' then depth = depth + 1 end
   if actions[k][1] == 'IF' then
    depth = depth - 1
    if depth == 0 then previous = k; break end
   end
  end
  if block_end(previous) ~= i - 1 then previous = 0 end
 elseif previous > 0 and (actions[previous][1] == 'IF' or actions[previous][1] == 'ELSE') then
  previous = 0
 end
 local next_first, next_last = last + 1, nil
 if actions[next_first] and actions[next_first][1] ~= 'ELSE' and actions[next_first][1] ~= 'END' then
  next_last = block_end(next_first)
 end
 local function rotate(first, middle, finish)
  gui.StartActionMove()
  local ordered = {}
  for k = middle, finish do ordered[#ordered + 1] = actions[k] end
  for k = first, middle - 1 do ordered[#ordered + 1] = actions[k] end
  for k, action in ipairs(ordered) do actions[first + k - 1] = action end
 end
 if previous > 0 then
  imgui.SetCursorPos(imgui.ImVec2(770, 293 + pxl))
  if imgui.InvisibleButton('##UP' .. i, imgui.ImVec2(21, 22)) then
   rotate(previous, i, last)
   return true
  end
  local hovered = imgui.IsItemHovered()
  if hovered then imgui.PushStyleColor(imgui.Col.Text, cl.def) end
  gui.FaText(772, 295 + pxl, fa.ARROW_UP, fa_font[4])
  if hovered then imgui.PopStyleColor() end
 end
 if next_last then
  imgui.SetCursorPos(imgui.ImVec2(740, 293 + pxl))
  if imgui.InvisibleButton('##DOWN' .. i, imgui.ImVec2(21, 22)) then
   rotate(i, next_first, next_last)
   return true
  end
  local hovered = imgui.IsItemHovered()
  if hovered then imgui.PushStyleColor(imgui.Col.Text, cl.def) end
  gui.FaText(742, 295 + pxl, fa.ARROW_DOWN, fa_font[4])
  if hovered then imgui.PopStyleColor() end
 end
 return false
end

--> Функции для полиции
function checkVehicleData()
	local vehicle_data_url = 'https://raw.githubusercontent.com/kysteno4ek/StateHelper/main/data/vehicle.json'
	local local_path = dir .. '/State Helper/Police/vehicle.json'

	local function loadVehicleNames()
		local f = io.open(local_path, 'r')
		if f then
			local data = f:read('*a')
			f:close()
			local res, decoded_data = pcall(decodeJson, data)
			if res and type(decoded_data) == 'table' then
				vehicleNames = {}
				if decoded_data[1] and decoded_data[1].version then
					localVehicleVersion = decoded_data[1].version
				end
				for _, vehicle in ipairs(decoded_data) do
					if vehicle.model_id and vehicle.name then
						vehicleNames[vehicle.model_id] = u8:decode(vehicle.name)
					end
				end
				print('[SH] Файл vehicle.json успешно загружен. Версия: ' .. localVehicleVersion)
			else
				print('[SH] Ошибка чтения vehicle.json.')
			end
		end
	end
	
	if not doesFileExist(local_path) then
		print('[SH] Файл vehicle.json не найден. Скачиваю...')
		sh_resource.download(vehicle_data_url, local_path, function(id, status)
			if status == dlstatus.STATUS_ENDDOWNLOADDATA then
				loadVehicleNames()
			end
		end)
	else
		loadVehicleNames()
	end
end

function sh_audit.nearest_vehicle()
	local nearest, distance = nil, 150
	local x, y, z = getCharCoordinates(PLAYER_PED)
	local own = isCharInAnyCar(PLAYER_PED) and getCarCharIsUsing(PLAYER_PED) or nil
	for _, car in ipairs(getAllVehicles()) do
		if car ~= own and doesCharExist(getDriverOfCar(car)) then
			local cx, cy, cz = getCarCoordinates(car)
			local d = getDistanceBetweenCoords3d(x, y, z, cx, cy, cz)
			if d < distance then nearest, distance = car, d end
		end
	end
	if not nearest then return 'Неизвестно', '0' end
	local model = getCarModel(nearest)
	return (vehicleNames and vehicleNames[model]) or ('Модель ' .. model), tostring(math.floor(getCarSpeed(nearest) * 3.6))
end
function getNearestVehicleModel()
	local model = sh_audit.nearest_vehicle(); return model
end
function getNearestVehicleSpeed()
	local _, speed = sh_audit.nearest_vehicle(); return speed
end
function getCurrentMapSquare()
	local alphabet = 'АБВГДЖЗИКЛМНОПРСТУФХЦЧШЯ'
	local x, y = getCharCoordinates(PLAYER_PED)
	local gridX = math.ceil((x + 3000) / 250)
	local gridY = math.ceil((y * -1 + 3000) / 250)
	if gridX >= 1 and gridX <= 24 and gridY >= 1 and gridY <= 24 then
		local yLetter = string.sub(alphabet, gridY, gridY)
		return yLetter .. '-' .. gridX
	else
		return 'Вне карты'
	end
end

--> ===================== ЦЕНОВАЯ ПОЛИТИКА ЛИЦЕНЗИЙ =====================
local function license_cell_price(cell)
	if type(cell) ~= 'string' then return nil end
	local plain = cell:gsub('{%x+}', ''):match('^%s*(.-)%s*$')
	local lower = to_lowercase(plain):lower()
	if lower:find('недоступ', 1, true) then return '0' end
	plain = plain:gsub(':?[Cc][Aa][Ss][Hh]:', ''):gsub('^%s*%$', '')
	local amount = plain:match('^%s*(%d[%d%. ,]*)')
	if not amount then return nil end
	amount = amount:gsub('[%. ,]', '')
	local number = tonumber(amount)
	if not number or number < 0 or number > 1000000000 or number ~= math.floor(number) then return nil end
	return amount
end
local function license_policy_rows(text)
	local aliases = {
		{'moto','мото'}, {'swim','водн'}, {'fly','полёт','полет'}, {'fish','рыбал'}, {'gun','оруж'},
		{'hunt','охот'}, {'exc','раскоп'}, {'taxi','такси'}, {'meh','механ'}, {'crypto','криптовалют'}, {'stocks','акци'}, {'auto','авто'}
	}
	local result, count = {}, 0
	for line in tostring(text or ''):gmatch('[^\r\n]+') do
		local cells = {}
		for cell in (line .. '\t'):gmatch('(.-)\t') do cells[#cells + 1] = cell end
		local name = to_lowercase((cells[1] or ''):gsub('{%x+}', ''))
		if name:match('^%s*%d+%.') then
			local key
			for _, rule in ipairs(aliases) do
				for i = 2, #rule do if name:find(rule[i], 1, true) then key = rule[1]; break end end
				if key then break end
			end
			if not key or result[key] then return nil, 'Не удалось однозначно распознать лицензии.' end
			local prices = {}
			for month = 1, 3 do prices[month] = license_cell_price(cells[month + 1]); if not prices[month] then return nil, 'Не удалось прочитать все цены. Старые значения сохранены.' end end
			result[key], count = prices, count + 1
		end
	end
	if count ~= 12 then return nil, 'Получен неполный список лицензий. Старые цены сохранены.' end
	return result
end
function copy_license_policy()
	local active = license_copy.id and (license_copy.handling or (sampIsDialogActive() and sampGetCurrentDialogId() == license_copy.id))
	if not active or not license_copy.received or os.clock() - license_copy.received > 60 then sampAddChatMessage('[SH]{FFFFFF} Откройте актуальный диалог продажи лицензии.', 0xFF5345); return end
	local prices, problem = license_policy_rows(license_copy.text)
	if not prices then sampAddChatMessage('[SH]{FFFFFF} ' .. problem, 0xFF5345); return end
	local previous = deep_copy(setting.price[2])
	for key, value in pairs(prices) do setting.price[2][key] = value end
	if not save() then setting.price[2] = previous; return end
	sampAddChatMessage('[SH]{FFFFFF} Цены всех 12 лицензий обновлены.', 0x23E64A)
end

