function parsePenaltyRangeOrTake(penaltyStr)
	local result = { type = 'unknown' }
	if penaltyStr:lower() == 'take' then
		result.type = 'take'
	elseif penaltyStr:match('^(%d+)$') then
		result.type = 'number'
		result.value = tonumber(penaltyStr)
	elseif penaltyStr:match('^(%d+)%s*-%s*(%d+)$') then
		local minVal, maxVal = penaltyStr:match('^(%d+)%s*-%s*(%d+)$')
		result.type = 'range'
		result.min = tonumber(minVal)
		result.max = tonumber(maxVal)
		if result.min > result.max then
			result.min, result.max = result.max, result.min
		end
	elseif penaltyStr:match('^(%d+)%s*-%s*take$') then
		result.type = 'number-take'
		result.value = tonumber(penaltyStr:match('^(%d+)'))
	end
	return result
end

function send_smart_su_commands(commands)
	if thread:status() ~= 'dead' then
		if not setting.cef_notif then
			sampAddChatMessage('[SH] {FFFFFF}Дождитесь завершения предыдущей отыгровки.', 0xFF5345)
		else
			cefnotig('{FF5345}[SH] {FFFFFF}Дождитесь завершения предыдущей отыгровки.', 2000)
		end
		return false
	end
	thread = lua_thread.create(function(cmd_table)
		for _, text in ipairs(cmd_table) do
			sampSendChat(text)
			wait(1300)
		end
	end, commands)
	return true
end

function get_pursuit_target_distance(target_id)
	local chars = getAllChars()
	local mx, my, mz = getCharCoordinates(PLAYER_PED)
	for i, v in ipairs(chars) do
		if doesCharExist(v) and v ~= PLAYER_PED then
			local r, id = sampGetPlayerIdByCharHandle(v)
			if r and id == target_id then
				local vx, vy, vz = getCharCoordinates(v)
				return getDistanceBetweenCoords3d(mx, my, mz, vx, vy, vz)
			end
		end
	end
	return nil
end

function su_accept_reg()
	local should_work = setting.police_settings.su_accept.func or setting.rank > 4
	if should_work and not su_accept_is_on then
		if setting.police_settings.su_accept.cmd ~= '' then
			sampRegisterChatCommand(setting.police_settings.su_accept.cmd, su_accept_confirm)
		end
		if #setting.police_settings.su_accept.key[2] ~= 0 then
			rkeys.registerHotKey(setting.police_settings.su_accept.key[2], 3, true, su_accept_confirm)
			table.insert(all_keys, setting.police_settings.su_accept.key[2])
		end
		su_accept_is_on = true
	elseif not should_work and su_accept_is_on then
		if setting.police_settings.su_accept.cmd ~= '' then
			sampUnregisterChatCommand(setting.police_settings.su_accept.cmd)
		end
		if #setting.police_settings.su_accept.key[2] ~= 0 then
			rkeys.unRegisterHotKey(setting.police_settings.su_accept.key[2])
			for i, key in ipairs(all_keys) do
				if compare_array_disable_order(key, setting.police_settings.su_accept.key[2]) then
					table.remove(all_keys, i)
					break
				end
			end
		end
		su_accept_is_on = false
	end
end

function su_accept_confirm(arg)
	if not (setting.org >= 11 and setting.org <= 15) then return end
	if not (setting.police_settings.su_accept.func or setting.rank > 4) then return end
	if not su_accept.active then return end
	local su_cmd_send = '/su ' .. su_accept.case .. ' ' .. su_accept.degree .. ' ' .. su_accept.reason
	if setting.police_settings.su_accept.tag then
		su_cmd_send = su_cmd_send .. ' // ' .. su_accept.tag
	end
	sampSendChat(su_cmd_send)
	su_accept.active = false
end

function send_z()
	if not (setting.org >= 11 and setting.org <= 15) then return end
	if not setting.police_settings.auto_zm.func then return end
	if not poltarget then return end
	if not auto_z_state.range then return end
	sampSendChat('/z ' .. poltarget)
end

function auto_z()
	if not (setting.org >= 11 and setting.org <= 15) or not setting.police_settings.auto_zm.func then
		auto_z_state.range = false
		auto_z_state.id = nil
		return
	end

	if not poltarget then
		auto_z_state.range = false
		auto_z_state.id = nil
		return
	end

	if auto_z_state.id ~= poltarget then
		auto_z_state.id = poltarget
		auto_z_state.range = false
		auto_z_state.notify = -9999
	end

	local dist = get_pursuit_target_distance(poltarget)
	local in_range = dist ~= nil and dist <= 30.0

	if z_timer.active and os.clock() >= z_timer.until_time then
		z_timer.active = false
		auto_z_state.range = false
	end

	if in_range and not auto_z_state.range and not z_timer.active then
		if setting.police_settings.auto_zm.ask then
			if os.clock() - auto_z_state.notify >= 20 then
				local key_name = (setting.police_settings.auto_zm.key[1] ~= '' and setting.police_settings.auto_zm.key[1] or 'Не назначена')
				if not setting.cef_notif then
					sampAddChatMessage('[SH] {FFFFFF}Чтобы пометить преступника (/z) нажмите: {FF6060}' .. key_name, 0xFF5345)
				else
					cefnotig('{FF5345}[SH] {FFFFFF}Чтобы пометить преступника (/z) нажмите: {FF6060}' .. key_name, 3000)
				end
				auto_z_state.notify = os.clock()
			end
		else
			sampSendChat('/z ' .. poltarget)
		end
	end

	auto_z_state.range = in_range
end

function parsePenaltyRange(rangeStr)
	local startNum, endNum = rangeStr:match("(%d+)%s*-%s*(%d+)")
	if startNum and endNum then
		local penalties = {}
		for i = tonumber(startNum), tonumber(endNum) do
			table.insert(penalties, i)
		end
		return penalties
	end
	return nil
end

local ghetto_notify_in_zone = false

local function is_car_upside_down(car)
	if not car or not doesVehicleExist(car) then return false end
	local cx, cy, cz = getCarCoordinates(car)
	local ox, oy, oz = getOffsetFromCarInWorldCoords(car, 0.0, 0.0, 1.0)
	return oz < (cz - 0.25)
end

function autojack_tick()
	if not setting.auto_jack then
		jack_state.notified = false
		return
	end
	if not isCharInAnyCar(PLAYER_PED) then
		jack_state.notified = false
		return
	end
	if sampIsChatInputActive() or sampIsDialogActive() then return end
	if isSampfuncsConsoleActive and isSampfuncsConsoleActive() then return end
	local car = storeCarCharIsInNoSave(PLAYER_PED)
	if not is_car_upside_down(car) then
		jack_state.notified = false
		return
	end
	local now = os.clock()
	-- уведомление один раз, пока машина перевернута
	if not jack_state.notified then
		jack_state.notified = true
		if not setting.cef_notif then
			sampAddChatMessage('[SH]{FFFFFF} Авто перевернуто. Нажмите {FF6060}E{FFFFFF}, чтобы использовать домкрат.', 0xFF5345)
		else
			cefnotig('{FF5345}[SH]{FFFFFF} Нажмите {FF6060}E{FFFFFF}, чтобы использовать домкрат.', 4000)
		end
	end
	-- /domkrat только по E + кулдаун
	if now < (jack_state.cooldown_until or 0) then return end
	if isKeyJustPressed(0x45) then -- VK_E
		sampSendChat('/domkrat')
		jack_state.cooldown_until = now + 3.0
		jack_state.last_t = now
		if not setting.cef_notif then
			sampAddChatMessage('[SH]{FFFFFF} Команда {a8a8a8}/domkrat{FFFFFF} отправлена.', 0xFF5345)
		end
	end
end

function ghetto_notify_func()
	if setting.police_settings and setting.police_settings.ghetto_notify then
		local zona = isCharInArea2d(PLAYER_PED, 1646.65, -2180.01, 2917.80, -864.09, false)
		
		if zona and not ghetto_notify_in_zone then
			if not setting.cef_notif then
				sampAddChatMessage("[SH] {FFFFFF}Вы заехали в Гетто!", 0xFF5345)
			else
				cefnotig("{FF5345}[SH] {FFFFFF}Вы заехали в Гетто!", 2000)
			end
			ghetto_notify_in_zone = true
		elseif not zona and ghetto_notify_in_zone then
			ghetto_notify_in_zone = false
		end
	end
end

function smart_su_func(arg)
	local id = tonumber(arg)
	if id == nil or not sampIsPlayerConnected(id) then
		if not setting.cef_notif then
			sampAddChatMessage('[SH]{FFFFFF} Используйте {a8a8a8}/su [id игрока]', 0xFF5345)
		else
			cefnotig('{FF5345}[SH]{FFFFFF} Используйте {a8a8a8}/su [id игрока]', 2000)
		end
		return
	end
	smartSuState.reasons = {}
	local auto_su_dir = dir .. '/State Helper/Police/AutoSu/'
	if not doesDirectoryExist(auto_su_dir) then
		createDirectory(auto_su_dir)
	end
	local file_path = auto_su_dir .. s_na .. '.json'
	if doesFileExist(file_path) then
		local file = io.open(file_path, 'r')
		if file then
			local data = file:read('*a')
			file:close()
			local success, decoded_data = pcall(decodeJson, data)
			if success and type(decoded_data) == 'table' then
				smartSuState.reasons = decoded_data
			else
				if not setting.cef_notif then
					sampAddChatMessage('[SH]{FFFFFF} Ошибка чтения файла ' .. s_na .. '.json. Файл может быть поврежден.', 0xFF5345)
				else
					cefnotig('{FF5345}[SH]{FFFFFF} Ошибка чтения файла ' .. s_na .. '.json. Файл может быть поврежден.', 2000)
				end
				smartSuState.reasons = {}
			end
		end
	else
		if not setting.cef_notif then
			sampAddChatMessage('[SH]{FFFFFF} Файл розыска ' .. s_na .. '.json не найден. Скачивание...', 0xFF5345)
		else
			cefnotig('{FF5345}[SH]{FFFFFF} Файл розыска ' .. s_na .. '.json не найден. Скачивание...', 2000)
		end
		download_wanted_reasons()
		smartSuState.reasons = {}
	end
	smartSuState.targetId[0] = id
	smartSuState.selected = {}
	smartSuState.totalStars = 0
	smartSuState.selectedArticle = nil
	smartSuState.pendingRangeArticle = nil
	smartSuState.searchQuery = ''
	smartSuState.chapterStates = {}
	suui.reset()
	windows.smart_su[0] = true
	smartSuState.anim.is_opening = true
	smartSuState.anim.is_closing = false
end
